    #region 公共方法
    /// <summary>
    /// 参数设置
    /// </summary>
    /// <param name="item"></param>
    public bool? SetParameters(dynamic item)
    {
        ParameterSettingWindowViewModel cvm = new ParameterSettingWindowViewModel();
        cvm.Parameters = item.Parameters;
        bool? key = item.Parent.VM.OpenParameterSettingWindow(cvm);
        if (key == true)
        {
            item.Parameters = cvm.Parameters;
        }
        return key;
    }

    #region 测试准备
    public dynamic TestReady(dynamic item)
    {
        Result<List<TextData>> result  = new Result<List<TextData>>(true);
        string outmsg1 = "";
        string outmsg2 = "";
        try
        {
            item.GetDevice("P21").GetRS1(item.Root.DUT.DeviceCode, out outmsg1);
            item.GetDevice("P21").GetRS2(item.Root.DUT.DeviceCode, out outmsg2);
        }
        catch (Exception)
        {

        }
        if (!string.IsNullOrWhiteSpace(outmsg1) && !string.IsNullOrWhiteSpace(outmsg2))
        {
            bool? isPass = ScriptHelper.OpenInfoImgConfirmWindow($"测试前准备确认:\r\n1、接入4根电测线，2个外接航插线，1根电源线。\r\n2、接入USB通讯线，网线，U盘。3、拧上设备侧边的堵头。\r\n4、{outmsg1}。\r\n5、{outmsg2}\r\n\r\n点击【确认】或【取消】，都会停止测试。", "");
            if (isPass == true)
            {
                return result;
            }
            return result.AddTestErrMsgs(new ErrMsg(20003,"测试前检测没有通过,请检查错误信息"));
        }
        else if (!string.IsNullOrWhiteSpace(outmsg1))
        {
            bool? isPass = ScriptHelper.OpenInfoImgConfirmWindow($"测试前准备确认:\r\n1、接入4根电测线，2个外接航插线，1根电源线。\r\n2、接入USB通讯线，网线，U盘。3、拧上设备侧边的堵头。\r\n4、{outmsg1}。\r\n\r\n点击【确认】或【取消】，都会停止测试。", "");
            if (isPass == true)
            {
                return result;
            }
            return result.AddTestErrMsgs(new ErrMsg(20003,"测试前检测没有通过,请检查错误信息"));
        }
        else if (!string.IsNullOrWhiteSpace(outmsg2))
        {
            bool? isPass = ScriptHelper.OpenInfoImgConfirmWindow($"测试前准备确认:\r\n1、接入4根电测线，2个外接航插线，1根电源线。\r\n2、接入USB通讯线，网线，U盘。3、拧上设备侧边的堵头。\r\n4、{outmsg2}。\r\n\r\n点击【确认】或【取消】，都会停止测试。", "", "");
            if (isPass == true)
            {
                return result;
            }
            return result.AddTestErrMsgs(new ErrMsg(20003,"测试前检测没有通过,请检查错误信息"));
        }
        else
        {
            bool? isPass = ScriptHelper.OpenInfoImgConfirmWindow($"测试前准备确认:\r\n1、接入4根电测线，2个外接航插线，1根电源线。\r\n2、接入USB通讯线，网线，U盘。\r\n3、拧上设备侧边的堵头。\r\n\r\n完成后，没有问题点击【确认】进行下一步。\r\n点击【取消】，停止测试。", "", "");
            if (isPass != true)
            {
                return result.SetConclusion("人为取消测试",ErrMsg._09998).Completed();
            }
            else
            {
                return result;
            }
        }
    }

    /// <summary>
    /// CPS测试
    /// </summary>
    /// <returns></returns>
    public dynamic TestCPS(dynamic item)
    {
        Result<List<DataBase>> result = new Result<List<DataBase>>(true);
        string sn = item.GetDevice("P21").GetDUTSN();

        //老版本直接通过
        if
          (
            !sn.StartsWith("811AGC") &&
            !sn.StartsWith("811ADC") &&
            !sn.StartsWith("811ALC")
          )
        {
            return result;
        }
        else
        {
            bool? key = ScriptHelper.OpenInfoConfirmWindow(item, "1.将设备与连接台接好后，查看设备CPS图标，正常显示为通过。 \r\n2.上行控压，达到目标点进行下行控压，确定排气正常从C104出气。 气压版：上行7MPa，下行100kPa, 差压版：上行250kPa,下行50kPa，微差压版：上行10kPa，下行2kPa。 \r\n3.手动排空。");

            if (key != true)
            {
                result.SetConclusion("人工判断不通过", ErrMsg._09997);
            }
        }

        return result;
    }
