    #region 气路测试
    /// <summary>
    /// 表压、绝压配气模块测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestInterfaceModule_G_A(dynamic item)
    {
        //数据采集定时器
        //System.Timers.Timer timer1 = new System.Timers.Timer();

        //定义返回类型
        Result<List<DataBase>> result = new Result<List<DataBase>>(true);
        List<DataBase> rData = new List<DataBase>() { };
        result.Data = rData;

        ValueData sensor2 = item.DataBase["sensor2"];
        ValueData sensor3 = item.DataBase["sensor3"];

        //ListValueData sensor2Data = new ListValueData("sensor2Data");
        ValueData time1_sensor2 = new ValueData("time1_sensor2");
        ValueData time2_sensor2 = new ValueData("time2_sensor2");
        ValueData time3_sensor2 = new ValueData("time3_sensor2");
        ValueData time4_sensor2 = new ValueData("time4_sensor2");
        ValueData time5_sensor2 = new ValueData("time5_sensor2");


        time1_sensor2.Unit = sensor2.Unit;
        time2_sensor2.Unit = sensor2.Unit;
        time3_sensor2.Unit = sensor2.Unit;
        time4_sensor2.Unit = sensor2.Unit;
        time5_sensor2.Unit = sensor2.Unit;


        //rData.Add(sensor2Data);
        rData.Add(time1_sensor2);
        rData.Add(time2_sensor2);
        rData.Add(time3_sensor2);
        rData.Add(time4_sensor2);
        rData.Add(time5_sensor2);


        //清空实时信息
        item.ClearRealTimeMsgs();

        //获取条件参数
        ValueParameter parameter0;
        ValueParameter parameter1;
        ValueParameter parameter2;
        try
        {
            parameter0 = item.Parameters[0] as ValueParameter;
            parameter1 = item.Parameters[1] as ValueParameter;
            parameter2 = item.Parameters[2] as ValueParameter;
        }
        catch
        {
            result.AddTestErrMsgs(ErrMsg._10001);//添加错误信息
            return result;
        }

        //获取条件
        ValueCondition condition0;
        ValueCondition condition1;
        ValueCondition condition2;
        ValueCondition condition3;
        RangeCondition condition4;
        try
        {
            condition0 = item.Conditions[0] as ValueCondition;
            condition1 = item.Conditions[1] as ValueCondition;
            condition2 = item.Conditions[2] as ValueCondition;
            condition3 = item.Conditions[3] as ValueCondition;
            condition4 = item.Conditions[4] as RangeCondition;

        }
        catch
        {
            result.AddTestErrMsgs(ErrMsg._10002);//添加错误信息
            return result;
        }

        try
        {
            //数据采集
            //timer1.Elapsed += (s, e) =>
            //{
            //    sensor2Data.Values.Add(sensor2.WithDateTime());
            //};
            //timer1.Interval = 1000;
            //timer1.Start();

            System.Diagnostics.Stopwatch watch = new System.Diagnostics.Stopwatch();

            #region 进气压力判断

            //进气压力判断
            RealTimeMsg msg0 = new RealTimeMsg("判断进气压力");
            item.AddRealTimeMsgs(msg0);
            bool isOK = false;
            //判断5次（每秒一次）
            for (int i = 0; i < 5; i++)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg0.ContentRunning();
                System.Threading.Thread.Sleep(1000);
                if (condition0.IsTrue(sensor3.Value))
                {
                    isOK = true;
                    msg0.Name = "进气压力";
                    msg0.Content = string.Format("{0}({1})合格", sensor3.Value, sensor3.Unit);
                    break;
                }
            }
            if (!isOK)
            {
                msg0.Name = "进气压力";
                msg0.Content = string.Format("{0}({1})不合格,请调整气源压力!", sensor3.Value, sensor3.Unit);
                result.AddTestErrMsgs(new ErrMsg(30005, "气源压力不合格"));
                return result;
            }

            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region 预压

            RealTimeMsg msg001 = new RealTimeMsg("气路");
            item.AddRealTimeMsgs(msg001);
            msg001.Content = "预压";

            //V11打开
            item.GetDevice("P21_GR_T").SetV11On();

            //V5、V4预压
            for (int i = 0; i < 1; i++)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                //V5预压
                System.Threading.Thread.Sleep(1000);
                item.GetDevice("P21_GR_T").SetCha2On();
                System.Threading.Thread.Sleep(1000);
                item.GetDevice("P21_GR_T").SetCha2Off();

                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                //V4预压
                System.Threading.Thread.Sleep(1000);
                item.GetDevice("P21_GR_T").SetCha1On();
                System.Threading.Thread.Sleep(1000);
                item.GetDevice("P21_GR_T").SetCha1Off();

            }
            //V11关闭
            item.GetDevice("P21_GR_T").SetV11Off();

            //V5打开
            System.Threading.Thread.Sleep(1000);
            item.GetDevice("P21_GR_T").SetCha2On();
            //V4打开
            item.GetDevice("P21_GR_T").SetCha1On();
            //V12打开
            item.GetDevice("P21_GR_T").SetV12On();

            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                if (condition4.IsTrue(sensor2.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > 5)
                {
                    break;
                }
            }
            watch.Stop();
            //V5关闭
            item.GetDevice("P21_GR_T").SetCha2Off();
            //V4关闭
            item.GetDevice("P21_GR_T").SetCha1Off();
            //V12关闭
            item.GetDevice("P21_GR_T").SetV12Off();

            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region

            //V11通电
            RealTimeMsg msg2 = new RealTimeMsg("V11");
            item.AddRealTimeMsgs(msg2);
            msg2.Content = "通电";

            if (!item.GetDevice("P21_GR_T").SetV11On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V11通电失败！"));
                return result;
            }

            RealTimeMsg msg3 = new RealTimeMsg("计时");
            item.AddRealTimeMsgs(msg3);
            msg3.ReStart();
            //延时5秒
            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                msg3.Tick();
                if (condition1.IsTrue(sensor2.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > parameter0.Value)
                {
                    break;
                }
            }
            watch.Stop();

            if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > parameter0.Value)
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "压力输入超时！"));
                return result;
            }

            msg3.Name = "V11";
            msg3.Content = "断电";
            //V11断电
            if (!item.GetDevice("P21_GR_T").SetV11Off())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V11断电失败！"));
                return result;
            }

            RealTimeMsg msg4 = new RealTimeMsg("计时");
            item.AddRealTimeMsgs(msg4);
            //延时10秒
            for (int i = 0; i <= parameter1.Value; i++)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg4.Content = i + "秒";
                System.Threading.Thread.Sleep(1000);
            }
            //读取气压传传感器2的值

            time1_sensor2.Value = sensor2.Value;

            msg4.Name = "气压传感器2(time1)";
            msg4.Content = string.Format("{0}({1})", time1_sensor2.Value, time1_sensor2.Unit);

            RealTimeMsg msg5 = new RealTimeMsg("计时");
            item.AddRealTimeMsgs(msg5);
            //延时30秒
            for (int i = 0; i <= parameter2.Value; i++)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg5.Content = i + "秒";
                System.Threading.Thread.Sleep(1000);
            }
            //再次读取气压传感器2的值
            time2_sensor2.Value = sensor2.Value;

            msg5.Name = "气压传感器2(time2)";
            msg5.Content = string.Format("{0}({1})", time2_sensor2.Value, time2_sensor2.Unit);
            //计算气压传感器绝对值变化

            double r2 = Math.Abs(Math.Round((time2_sensor2.Value - time1_sensor2.Value) / time1_sensor2.Value, 4));

            RealTimeMsg msg6 = new RealTimeMsg("气压传感器2变化");
            item.AddRealTimeMsgs(msg6);
            msg6.Content = r2.ToString();


            RealTimeMsg msg7 = new RealTimeMsg("V4、V5的2口密封");
            item.AddRealTimeMsgs(msg7);
            if (condition2.IsTrue(r2))
            {
                msg7.Content = "合格";
            }
            else
            {
                msg7.Content = "不合格";
                result.AddTestErrMsgs(new ErrMsg(30003, "V4、V5的2口密封不合格,气路泄露"));
                return result;
            }

            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region
            //V5通电
            RealTimeMsg msg8 = new RealTimeMsg("V5");
            item.AddRealTimeMsgs(msg8);
            msg8.Content = "通电";

            if (!item.GetDevice("P21_GR_T").SetCha2On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V5通电失败！"));
                return result;
            }

            RealTimeMsg msg9 = new RealTimeMsg("计时");
            item.AddRealTimeMsgs(msg9);
            //延时10秒
            for (int i = 0; i <= parameter1.Value; i++)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg9.Content = i + "秒";
                System.Threading.Thread.Sleep(1000);

            }
            time3_sensor2.Value = sensor2.Value;

            msg9.Name = "气压传感器2(time3)";
            msg9.Content = string.Format("{0}({1})", time3_sensor2.Value, time3_sensor2.Unit);

            //计算气压传感器绝对值变化
            r2 = Math.Abs(Math.Round((time3_sensor2.Value - time2_sensor2.Value) / time2_sensor2.Value, 4));

            RealTimeMsg msg10 = new RealTimeMsg("气压传感器2变化");
            item.AddRealTimeMsgs(msg10);
            msg10.Content = r2.ToString();

            RealTimeMsg msg11 = new RealTimeMsg("V5");
            item.AddRealTimeMsgs(msg11);
            if (condition3.IsTrue(r2))
            {
                msg11.Content = "功能正常";
            }
            else
            {
                msg11.Content = "功能不正常";
                result.AddTestErrMsgs(new ErrMsg(30003, "V5功能不正常！"));
                return result;
            }

            RealTimeMsg msg101 = new RealTimeMsg("V11");
            item.AddRealTimeMsgs(msg101);
            msg101.Content = "通电";
            //V11通电，补气后断电
            if (!item.GetDevice("P21_GR_T").SetV11On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V11通电失败！"));
                return result;
            }

            RealTimeMsg msg102 = new RealTimeMsg("计时");
            item.AddRealTimeMsgs(msg102);

            msg102.Name = "计时";
            msg102.ReStart();
            //延时5秒
            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                msg102.Tick();
                if (condition1.IsTrue(sensor2.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > parameter0.Value)
                {
                    break;
                }
            }
            watch.Stop();

            if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > parameter0.Value)
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "压力输入超时！"));
                return result;
            }

            msg102.Name = "V11";
            msg102.Content = "断电";
            //V13断电
            if (!item.GetDevice("P21_GR_T").SetV11Off())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V11断电失败！"));
                return result;
            }



            RealTimeMsg msg103 = new RealTimeMsg("计时");
            item.AddRealTimeMsgs(msg103);
            //延时10秒
            for (int i = 0; i <= parameter1.Value; i++)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg103.Content = i + "秒";
                System.Threading.Thread.Sleep(1000);

            }

            //读取气压传传感器2的值
            time4_sensor2.Value = sensor2.Value;

            msg103.Name = "气压传感器2(time4)";
            msg103.Content = string.Format("{0}({1})", time4_sensor2.Value, time4_sensor2.Unit);

            RealTimeMsg msg104 = new RealTimeMsg("计时");
            item.AddRealTimeMsgs(msg104);
            //延时30秒
            for (int i = 0; i <= parameter2.Value; i++)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg104.Content = i + "秒";
                System.Threading.Thread.Sleep(1000);
            }
            //再次读取气压传感器2的值
            time5_sensor2.Value = sensor2.Value;

            msg104.Name = "气压传感器2(time5)";
            msg104.Content = string.Format("{0}({1})", time5_sensor2.Value, time5_sensor2.Unit);
            //计算气压传感器绝对值变化

            r2 = Math.Abs(Math.Round((time5_sensor2.Value - time4_sensor2.Value) / time4_sensor2.Value, 4));

            RealTimeMsg msg105 = new RealTimeMsg("气压传感器2变化");
            item.AddRealTimeMsgs(msg105);
            msg105.Content = r2.ToString();


            RealTimeMsg msg106 = new RealTimeMsg("V5密封");
            item.AddRealTimeMsgs(msg106);
            if (condition2.IsTrue(r2))
            {
                msg106.Content = "合格";
            }
            else
            {
                msg106.Content = "不合格";
                result.AddTestErrMsgs(new ErrMsg(30003, "V5密封密封不合格,气路泄露"));
                return result;
            }

            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region

            //V4通电
            RealTimeMsg msg12 = new RealTimeMsg("V4");
            item.AddRealTimeMsgs(msg12);
            msg12.Content = "通电";
            if (!item.GetDevice("P21_GR_T").SetCha1On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V4通电失败！"));
                return result;
            }
            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                if (condition4.IsTrue(sensor2.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > 5)
                {
                    break;
                }
            }
            watch.Stop();
            RealTimeMsg msg13 = new RealTimeMsg("V4");
            item.AddRealTimeMsgs(msg13);
            if (!condition4.IsTrue(sensor2.Value))
            {
                msg13.Content = "不合格";
                result.AddTestErrMsgs(new ErrMsg(30003, "Vout不合格,功能不正常"));
                return result;
            }
            else
            {
                msg13.Content = "合格";
            }

            System.Threading.Thread.Sleep(1000);
            //V4断电         
            RealTimeMsg msg14 = new RealTimeMsg("V4");
            item.AddRealTimeMsgs(msg14);
            msg14.Content = "断电";
            item.GetDevice("P21_GR_T").SetCha1Off();

            #endregion


            return result;
        }
        finally
        {
            item.GetDevice("P21_GR_T").SafeExit();
            //timer1.Stop();
            //timer1.Dispose();

        }
    }
    /// <summary>
    ///高精度接口模块测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestInterfaceModule_H(dynamic item)
    {
        //数据采集定时器
        //System.Timers.Timer timer1 = new System.Timers.Timer();

        //定义返回类型
        Result<List<DataBase>> result = new Result<List<DataBase>>(true);
        List<DataBase> rData = new List<DataBase>() { };
        result.Data = rData;

        ValueData sensor2 = item.DataBase["sensor2"];
        ValueData sensor3 = item.DataBase["sensor3"];

        //ListValueData sensor2Data = new ListValueData("sensor2Data");
        ValueData time1_sensor2 = new ValueData("time1_sensor2");
        ValueData time2_sensor2 = new ValueData("time2_sensor2");

        time1_sensor2.Unit = sensor2.Unit;
        time2_sensor2.Unit = sensor2.Unit;

        //rData.Add(sensor2Data);
        rData.Add(time1_sensor2);
        rData.Add(time2_sensor2);

        //清空实时信息
        item.ClearRealTimeMsgs();

        //获取条件参数
        ValueParameter parameter0;
        ValueParameter parameter1;
        ValueParameter parameter2;
        try
        {
            parameter0 = item.Parameters[0] as ValueParameter;
            parameter1 = item.Parameters[1] as ValueParameter;
            parameter2 = item.Parameters[2] as ValueParameter;
        }
        catch
        {
            result.AddTestErrMsgs(ErrMsg._10001);//添加错误信息
            return result;
        }

        //获取条件
        ValueCondition condition0;
        ValueCondition condition1;
        RangeCondition condition2;
        try
        {
            condition0 = item.Conditions[0] as ValueCondition;
            condition1 = item.Conditions[1] as ValueCondition;
            condition2 = item.Conditions[2] as RangeCondition;

        }
        catch
        {
            result.AddTestErrMsgs(ErrMsg._10002);//添加错误信息
            return result;
        }
        try
        {
            ////数据采集
            //timer1.Elapsed += (s, e) =>
            //{
            //    sensor2Data.Values.Add(sensor2.WithDateTime());
            //};
            //timer1.Interval = 1000;
            //timer1.Start();

            System.Diagnostics.Stopwatch watch = new System.Diagnostics.Stopwatch();

            #region 进气压力判断

            //进气压力判断
            RealTimeMsg msg0 = new RealTimeMsg("判断进气压力");
            item.AddRealTimeMsgs(msg0);
            bool isOK = false;
            //判断5次（每秒一次）
            for (int i = 0; i < 5; i++)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg0.ContentRunning();
                System.Threading.Thread.Sleep(1000);
                if (condition0.IsTrue(sensor3.Value))
                {
                    isOK = true;
                    msg0.Name = "进气压力";
                    msg0.Content = string.Format("{0}({1})合格", sensor3.Value, sensor3.Unit);
                    break;
                }
            }
            if (!isOK)
            {
                msg0.Name = "进气压力";
                msg0.Content = string.Format("{0}({1})不合格,请调整气源压力!", sensor3.Value, sensor3.Unit);
                result.AddTestErrMsgs(new ErrMsg(30005, "气源压力不合格"));
                return result;
            }

            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region 预压

            RealTimeMsg msg001 = new RealTimeMsg("气路");
            item.AddRealTimeMsgs(msg001);
            msg001.Content = "预压";

            //V11打开
            item.GetDevice("P21_GR_T").SetV11On();

            //V4预压
            for (int i = 0; i < 1; i++)
            {

                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                //V4预压
                System.Threading.Thread.Sleep(1000);
                item.GetDevice("P21_GR_T").SetCha1On();
                System.Threading.Thread.Sleep(1000);
                item.GetDevice("P21_GR_T").SetCha1Off();
            }

            //V11关闭
            item.GetDevice("P21_GR_T").SetV11Off();
            //V4打开
            System.Threading.Thread.Sleep(1000);
            item.GetDevice("P21_GR_T").SetCha1On();
            //V12打开
            item.GetDevice("P21_GR_T").SetV12On();
            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                if (condition2.IsTrue(sensor2.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > 5)
                {
                    break;
                }
            }
            watch.Stop();
            //V4关闭
            item.GetDevice("P21_GR_T").SetCha1Off();
            //V12关闭
            item.GetDevice("P21_GR_T").SetV12Off();
            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region

            //V11通电
            RealTimeMsg msg2 = new RealTimeMsg("V11");
            item.AddRealTimeMsgs(msg2);
            msg2.Content = "通电";

            if (!item.GetDevice("P21_GR_T").SetV11On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V11通电失败！"));
                return result;
            }

            RealTimeMsg msg3 = new RealTimeMsg("计时");
            item.AddRealTimeMsgs(msg3);
            msg3.ReStart();
            //延时5秒
            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                msg3.Tick();
                if (condition1.IsTrue(sensor2.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > parameter0.Value)
                {
                    break;
                }
            }
            watch.Stop();

            if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > parameter0.Value)
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "压力输入超时！"));
                return result;
            }

            msg3.Name = "V11";
            msg3.Content = "断电";
            //V11断电
            if (!item.GetDevice("P21_GR_T").SetV11Off())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V11断电失败！"));
                return result;
            }
            RealTimeMsg msg4 = new RealTimeMsg("计时");
            item.AddRealTimeMsgs(msg4);
            //延时10秒
            for (int i = 0; i <= parameter1.Value; i++)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg4.Content = i + "秒";
                System.Threading.Thread.Sleep(1000);
            }
            //读取气压传传感器2的值

            time1_sensor2.Value = sensor2.Value;

            msg4.Name = "气压传感器2(time1)";
            msg4.Content = string.Format("{0}({1})", time1_sensor2.Value, time1_sensor2.Unit);

            RealTimeMsg msg5 = new RealTimeMsg("计时");
            item.AddRealTimeMsgs(msg5);
            //延时30秒
            for (int i = 0; i <= parameter2.Value; i++)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg5.Content = i + "秒";
                System.Threading.Thread.Sleep(1000);
            }
            //再次读取气压传感器2的值
            time2_sensor2.Value = sensor2.Value;

            msg5.Name = "气压传感器2(time2)";
            msg5.Content = string.Format("{0}({1})", time2_sensor2.Value, time2_sensor2.Unit);
            //计算气压传感器绝对值变化

            double r2 = Math.Abs(Math.Round((time2_sensor2.Value - time1_sensor2.Value) / time1_sensor2.Value, 4));

            RealTimeMsg msg6 = new RealTimeMsg("气压传感器2变化");
            item.AddRealTimeMsgs(msg6);
            msg6.Content = r2.ToString();


            RealTimeMsg msg7 = new RealTimeMsg("V4的2口和高精度传感器的密封");
            item.AddRealTimeMsgs(msg7);
            if (condition1.IsTrue(r2))
            {
                msg7.Content = "合格";
            }
            else
            {
                msg7.Content = "不合格";
                result.AddTestErrMsgs(new ErrMsg(30003, "V4的2口和高精度传感器的密封不合格,气路泄露"));
                return result;
            }

            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region

            //V4通电
            RealTimeMsg msg8 = new RealTimeMsg("V4");
            item.AddRealTimeMsgs(msg8);
            msg8.Content = "通电";
            if (!item.GetDevice("P21_GR_T").SetCha1On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V4通电失败！"));
                return result;
            }
            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                if (condition2.IsTrue(sensor2.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > 5)
                {
                    break;
                }
            }
            watch.Stop();
            RealTimeMsg msg9 = new RealTimeMsg("V4");
            item.AddRealTimeMsgs(msg9);
            if (!condition2.IsTrue(sensor2.Value))
            {
                msg9.Content = "不合格";
                result.AddTestErrMsgs(new ErrMsg(30003, "V4不合格,功能不正常"));
                return result;
            }
            else
            {
                msg9.Content = "合格";
            }

            System.Threading.Thread.Sleep(1000);
            //V4断电         
            RealTimeMsg msg10 = new RealTimeMsg("V4");
            item.AddRealTimeMsgs(msg10);
            msg10.Content = "断电";
            item.GetDevice("P21_GR_T").SetCha1Off();

            #endregion

            return result;
        }
        finally
        {
            item.GetDevice("P21_GR_T").SafeExit();
            //timer1.Stop();
            //timer1.Dispose();
        }
    }
