            }

            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region
            //V6断电
            RealTimeMsg msg37 = new RealTimeMsg("V6");
            item.AddRealTimeMsgs(msg37);
            msg37.Content = "通电";
            if (!item.GetDevice("P21_GR_T").SetCha4On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V6通电失败！"));
                return result;
            }

            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                if (condition6.IsTrue(sensor2.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > 10)
                {
                    break;
                }
            }
            watch.Stop();
            RealTimeMsg msg38 = new RealTimeMsg("V6");
            item.AddRealTimeMsgs(msg38);
            System.Threading.Thread.Sleep(2000);
            if (condition6.IsTrue(sensor2.Value))
            {
                msg38.Content = "功能正常";
            }
            else
            {
                msg38.Content = "功能不正常";
                result.AddTestErrMsgs(new ErrMsg(30003, "V6功能不正常！"));
                return result;
            }
            #endregion

            return result;
        }
        finally
        {
            item.GetDevice("P21_GR_T").SafeExit();
            //timer1.Stop();
            //timer1.Dispose();
        }
    }
