            item.AddRealTimeMsgs(msg0);
            bool isOK = false;
            //判断5次（每秒一次）
            for (int i = 0; i < 5; i++)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg0.ContentRunning();
                System.Threading.Thread.Sleep(1000);
                if (condition0.IsTrue(sensor3.Value))
                {
                    isOK = true;
                    msg0.Name = "进气压力";
                    msg0.Content = string.Format("{0}({1})合格", sensor3.Value, sensor3.Unit);
                    break;
                }
            }
            if (!isOK)
            {
                msg0.Content = "气源压力不足！";
                result.AddTestErrMsgs(new ErrMsg(30005, "气源压力不足！"));
