            if (!item.GetDevice("P21_GR_T").SetV13On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V13通电失败！"));
                return result;
            }
            RealTimeMsg msg2 = new RealTimeMsg("计时");
            item.AddRealTimeMsgs(msg2);
            msg2.ReStart();
            //延时5秒
            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                msg2.Tick();
                if (condition1.IsTrue(sensor1.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > parameter0.Value)
                {
                    break;
                }
            }
            watch.Stop();

            if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > parameter0.Value)
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "压力输入超时！"));
                return result;
            }

            msg2.Name = "V13";
            msg2.Content = "断电";
            //V13断电
            if (!item.GetDevice("P21_GR_T").SetV13Off())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V13断电失败！"));
                return result;
            }

            RealTimeMsg msg3 = new RealTimeMsg("计时");
            item.AddRealTimeMsgs(msg3);
            //延时10秒
            for (int i = 0; i <= parameter1.Value; i++)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg3.Content = i + "秒";
                System.Threading.Thread.Sleep(1000);
            }
            //读取气压传感器1、气压传传感器2的值

            time1_sensor1.Value = sensor1.Value;


            msg3.Name = "气压传感器1(time1)";
            msg3.Content = string.Format("{0}({1})", time1_sensor1.Value, time1_sensor1.Unit);



            RealTimeMsg msg4 = new RealTimeMsg("计时");
            item.AddRealTimeMsgs(msg4);
            //延时30秒
            for (int i = 0; i <= parameter2.Value; i++)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg4.Content = i + "秒";
                System.Threading.Thread.Sleep(1000);
            }
            //再次读取气压传感器1、气压传感器2的值
            time2_sensor1.Value = sensor1.Value;


            msg4.Name = "气压传感器1(time2)";
            msg4.Content = string.Format("{0}({1})", time2_sensor1.Value, time2_sensor1.Unit);


            //计算气压传感器绝对值变化
            double r1 = Math.Abs(Math.Round((time2_sensor1.Value - time1_sensor1.Value) / time1_sensor1.Value, 4));


            RealTimeMsg msg5 = new RealTimeMsg("气压传感器1变化");
            item.AddRealTimeMsgs(msg5);
            msg5.Content = r1.ToString();

            RealTimeMsg msg10 = new RealTimeMsg("大气压接口密封");
            item.AddRealTimeMsgs(msg10);
            if (condition1.IsTrue(r1))
            {
                msg10.Content = "合格";
            }
            else
            {
                msg10.Content = "不合格";
                result.AddTestErrMsgs(new ErrMsg(30003, "大气压接口密封密封不合格,气路泄露"));
                return result;
            }

            #endregion

            return result;
        }
        finally
        {
            item.GetDevice("P21_GR_T").SafeExit();
            //timer1.Stop();
            //timer1.Dispose();
        }
    }

