    public struct DataCollectorItem
    {
        /// <summary>
        /// 构造函数
        /// </summary>
        /// <param name="value"></param>
        /// <param name="time"></param>
        public DataCollectorItem(double value, DateTime time)
        {
            _value = value;
            _time = time;
        }

        double _value;
        /// <summary>
        /// 值
        /// </summary>
        public double Value
        {
            get
            {
                return this._value < 1e-5 ? 0 : Math.Round(this._value, 4);
            }
            set
            {
                this._value = value;
            }
        }

        DateTime _time;
        /// <summary>
        /// 时间戳
        /// </summary>
        public DateTime Time
        {
            get
            {
                return this._time;
            }
            set
            {
                this._time = value;
            }
        }
    }

    public class DataCollector
    {
        #region 创建采集器
        public DataCollector()
        {
        }
        public DataCollector(TimeSpan limitTimeCapacity)
        {
            _limitTimeCapacity = limitTimeCapacity;
        }

        #endregion

        #region 采集器属性


        object _async = new object();

        List<DataCollectorItem> _dataList = new List<DataCollectorItem>();
        /// <summary>
        /// 采集器数据集合
        /// </summary>
        public List<DataCollectorItem> DataList
        {
            get
            {
                return _dataList;
            }
            set
            {
                _dataList = value;
            }
        }

        TimeSpan _limitTimeCapacity = TimeSpan.FromSeconds(1);
        /// <summary>
        /// 采集器容量
        /// </summary>
        public TimeSpan LimitTimeCapacity
        {
            get
            {
                return _limitTimeCapacity;
            }
            set
            {
                _limitTimeCapacity = value;
            }
        }

        double _average = 0;
        /// <summary>
        /// 平均值
        /// </summary>
        public double Average
        {
            get
            {
                return Math.Round(_average, 2);
            }
            set
            {
                _average = value;
            }
        }


        #endregion

        #region 采集器方法

        #region 公共方法
        /// <summary>
        /// 增加数据
        /// </summary>
        /// <param name="item"></param>
        public void Add(DataCollectorItem item)
        {

            //非数字不响应
            if (double.IsNaN(item.Value))
                return;

            lock (_async)
            {
                //数据溢出，删除队首元素
                while (DataList.Count > 0 && (DateTime.Now - DataList[0].Time) > LimitTimeCapacity)
                {
                    DataList.RemoveAt(0);
                }
                //添加新数据
                DataList.Add(item);
            }
            //计算平均值
            Average = GetAverage();
        }

        #endregion

        #region 私有方法

        /// <summary>
        /// 获取平均值
        /// </summary>
        /// <returns></returns>
        private double GetAverage()
        {
            lock (_async)
            {
                //克隆数据集合
                List<DataCollectorItem> tmpList = new List<DataCollectorItem>();
                tmpList.AddRange(DataList);
                if (tmpList.Count > 0)
                {
                    if (tmpList.Count > 1)
                    {
                        int n = tmpList.Count;
                        Double totalValue = 0;
                        for (int i = 1; i < n; i++)
                        {
                            totalValue += (tmpList[i].Value + tmpList[i - 1].Value) * (tmpList[i].Time - tmpList[i - 1].Time).TotalSeconds / 2;
                        }
                        return totalValue / (tmpList[n - 1].Time - tmpList[0].Time).TotalSeconds;

                    }
                    else
                    {
                        return DataList[0].Value;
                    }
                }
                else
                {
                    return 0;
                }
            }
        }

        /// <summary>
        /// 清除当前容器中的所有数据
        /// </summary>
        public void Clear()
        {
            lock (_async)
            {
                DataList.Clear();
            }
            Average = 0;
        }

        #endregion

        #endregion
    }

    /// <summary>
    /// 电源采集器
    /// </summary>
    public class PowerCollector
    {   //集合最大数量
        private int maxCount = 1800;
        //集合数据时间间隔
        private TimeSpan interval = TimeSpan.FromMilliseconds(200);

        //集合上次时间
        private DateTime cLastTime = DateTime.MinValue;
        //集合数量
        private int cCount = 0;

        //开始时间
        private DateTime startTime = DateTime.MinValue;
        //上次时间
        private DateTime lastTime = DateTime.MinValue;
        //上次值
        private double lastValue = 0;
        //总数
        private long totalCount = 0;

        //平均电流
        private double averageCurrent = 0;

        //电流积分
        private double integralCurrent = 0;

        //是否统计
        private bool isTotal = false;

        //测试对象
        PumpTest test;

        DataCollector currentDataCollector;

        DataCollector voltageDataCollector;

        public PowerCollector(PumpTest pumpTest)
        {
            test = pumpTest;
            currentDataCollector = new DataCollector();
            voltageDataCollector = new DataCollector();
        }

        private void CurrentChanged(object s, ValueChangeEventArgs e)
        {
            currentDataCollector.Add(new DataCollectorItem(Math.Round(Convert.ToDouble(e.Value), 4), e.TimeStamp));
            double current = currentDataCollector.Average;
            test.testItem.DataBase["Current"].Value = current;

            if (isTotal)
            {
                if (totalCount == 0)
                {
                    startTime = e.TimeStamp;
                }

                integralCurrent = totalCount <= 0 ? 0 : integralCurrent + (e.TimeStamp - lastTime).TotalSeconds * ((lastValue + current) / 2);
                test.testItem.DataBase["IntCurrent"].Value = integralCurrent;

                averageCurrent = totalCount <= 0 ? current : Math.Round(integralCurrent / (e.TimeStamp - startTime).TotalSeconds, 4);
                test.testItem.DataBase["AvgCurrent"].Value = averageCurrent;

                lastValue = current;
                lastTime = e.TimeStamp;
                totalCount++;

                if ((e.TimeStamp - cLastTime) > interval)
                {

                    if (cCount > maxCount)
                    {
                        test.testItem.DataBase["CurrentCollection"].RemoveFirst();
                        test.testItem.DataBase["AvgCurrentCollection"].RemoveFirst();
                    }
                    test.testItem.DataBase["CurrentCollection"].Append(test.testItem.DataBase["Current"].WithDateTime(e.TimeStamp));
                    test.testItem.DataBase["AvgCurrentCollection"].Append(test.testItem.DataBase["AvgCurrent"].WithDateTime(e.TimeStamp));
                    cCount++;
                    cLastTime = e.TimeStamp;
                }
            }
        }
        private void VoltageChanged(object s, ValueChangeEventArgs e)
        {
            double voltage = Math.Round(Convert.ToDouble(e.Value), 4);
            voltageDataCollector.Add(new DataCollectorItem(voltage, e.TimeStamp));
            test.testItem.DataBase["Voltage"].Value = voltageDataCollector.Average;
        }

        /// <summary>
        /// 开始
        /// </summary>
        public void Start(bool isTotal = true)
        {
            this.isTotal = isTotal;
            var tool = test.testItem.GetDevice("P01_Pump") as P21PumpTestTool;
            if (test.IsLeft)
            {

                tool.OnLeftCurrentChanged += CurrentChanged;
                tool.OnLeftVoltageChanged += VoltageChanged;
                tool.SetLeftPoweSourceStartRead();
            }
            else
            {
                tool.OnRightCurrentChanged += CurrentChanged;
                tool.OnRightVoltageChanged += VoltageChanged;
                tool.SetRightPoweSourceStartRead();
            }
        }

        /// <summary>
        /// 设置画图
        /// </summary>
        public void SetIsTotal(bool isTotal = true)
        {
            this.isTotal = isTotal;
        }
        /// <summary>
        /// 重新开始
        /// </summary>
        public void ReStart(bool isTotal = true)
        {
            Clear();
            SetIsTotal(isTotal);
        }
        /// <summary>
        /// 停止
        /// </summary>
        public void Stop()
        {
            var tool = test.testItem.GetDevice("P01_Pump") as P21PumpTestTool;
            if (test.IsLeft)
            {
                tool.SetLeftPoweSourceStopRead();
                tool.OnLeftCurrentChanged -= CurrentChanged;
                tool.OnLeftVoltageChanged -= VoltageChanged;

            }
            else
            {
                tool.SetRightPoweSourceStopRead();
                tool.OnRightCurrentChanged -= CurrentChanged;
                tool.OnRightVoltageChanged -= VoltageChanged;
            }
        }
        /// <summary>
        /// 清空
        /// </summary>
        public void Clear()
        {
            test.testItem.DataBase["Current"].Value = 0;
            test.testItem.DataBase["Voltage"].Value = 0;
            test.testItem.DataBase["AvgCurrent"].Value = 0;
            test.testItem.DataBase["IntCurrent"].Value = 0;
            test.testItem.DataBase["CurrentCollection"].Clear();
            test.testItem.DataBase["AvgCurrentCollection"].Clear();

            cLastTime = DateTime.MinValue;
            cCount = 0;

            startTime = DateTime.MinValue;
            lastTime = DateTime.MinValue;
            lastValue = 0;
            totalCount = 0;
            averageCurrent = 0;
            integralCurrent = 0;

            currentDataCollector.Clear();
            voltageDataCollector.Clear();
            isTotal = false;
        }
    }
    /// <summary>
    /// 压力采集器
    /// </summary>
    public class PressurerCollector
    {
        //集合最大数量
        private int maxCount = 1800;
        //集合数据时间间隔
        private TimeSpan interval = TimeSpan.FromMilliseconds(300);

        //正压上次采集时间
        private DateTime pLastTime = DateTime.MinValue;
        //正压集合数量
        private int pCount = 0;

        //负压上次采集时间
        private DateTime nLastTime = DateTime.MinValue;
        //负压集合数量
        private int nCount = 0;

        //显示正压图
        private bool isShowPositive = false;
        //显示负压图
        private bool isShowNegative = false;

        //测试对象
        PumpTest test;
        public PressurerCollector(PumpTest pumpTest)
        {
            test = pumpTest;
        }

        private void PositivePressureValueChanged(object s, ValueChangeEventArgs e)
        {
            try
            {
                test.testItem.DataBase["PositivePressure"].Value = Convert.ToDouble(e.Value);
                if (isShowPositive)
                {
                    if ((e.TimeStamp - pLastTime) > interval)
                    {
                        if (pCount > maxCount)
                        {
                            test.testItem.DataBase["PositivePressureCollection"].RemoveFirst();
                        }
                        test.testItem.DataBase["PositivePressureCollection"].Append(test.testItem.DataBase["PositivePressure"].WithDateTime(e.TimeStamp));
                        pLastTime = e.TimeStamp;
                        pCount++;
                    }
                }
            }
            catch (Exception ex)
            {
                LogHelper.Fatal(ex);
                LogHelper.Debug(string.Format("{0}\r\n,集合{1}", test.testItem.DataBase["PositivePressure"].Value.ToString(), test.testItem.DataBase["PositivePressureCollection"].ToString()));

            }

        }
        private void PositivePressureUnitChanged(object s, ValueChangeEventArgs e)
        {
            try
            {
                test.testItem.DataBase["PositivePressure"].Unit = e.Value.ToString();

            }
            catch (Exception ex)
            {
                LogHelper.Fatal(ex);
            }
        }
        private void NegativePressureValueChanged(object s, ValueChangeEventArgs e)
        {
            try
            {
                test.testItem.DataBase["NegativePressure"].Value = Convert.ToDouble(e.Value);
                if (isShowNegative)
                {
                    if ((e.TimeStamp - nLastTime) > interval)
                    {
                        if (nCount > maxCount)
                        {
                            test.testItem.DataBase["NegativePressureCollection"].RemoveFirst();
                        }
                        test.testItem.DataBase["NegativePressureCollection"].Append(test.testItem.DataBase["NegativePressure"].WithDateTime(e.TimeStamp));
                        nLastTime = e.TimeStamp;
                        nCount++;
                    }
                }
            }
            catch (Exception ex)
            {
                LogHelper.Fatal(ex);
                LogHelper.Debug(string.Format("{0}\r\n,集合{1}", test.testItem.DataBase["NegativePressure"].Value.ToString(), test.testItem.DataBase["NegativePressureCollection"].ToString()));
            }


        }
        private void NegativePressureUnitChanged(object s, ValueChangeEventArgs e)
        {
            try
            {
                test.testItem.DataBase["NegativePressure"].Unit = e.Value.ToString();

            }
            catch (Exception ex)
            {
                LogHelper.Fatal(ex);
            }
        }
        /// <summary>
        /// 开始
        /// </summary>
        public void Start(bool positiveShow = true, bool negativeShow = true)
        {
            var tool = test.testItem.GetDevice("P01_Pump") as P21PumpTestTool;
            isShowPositive = positiveShow;
            isShowNegative = negativeShow;
            if (test.IsLeft)
            {
                tool.OnLeftPositivePressureValueChanged += PositivePressureValueChanged;
                tool.OnLeftPositivePressureUnitChanged += PositivePressureUnitChanged;

                tool.OnLeftNegativePressureValueChanged += NegativePressureValueChanged;
                tool.OnLeftNegativePressureUnitChanged += NegativePressureUnitChanged;

                tool.SetLeftPositivePressureStartRead();
                tool.SetLeftNegativePressureStartRead();
            }
            else
            {
                tool.OnRightPositivePressureValueChanged += PositivePressureValueChanged;
                tool.OnRightPositivePressureUnitChanged += PositivePressureUnitChanged;

                tool.OnRightNegativePressureValueChanged += NegativePressureValueChanged;
                tool.OnRightNegativePressureUnitChanged += NegativePressureUnitChanged;

                tool.SetRightPositivePressureStartRead();
                tool.SetRightNegativePressureStartRead();
            }
        }

        /// <summary>
        /// 设置画图
        /// </summary>
        public void SetShowChart(bool positiveShow = true, bool negativeShow = true)
        {
            isShowPositive = positiveShow;
            isShowNegative = negativeShow;
        }
        /// <summary>
        /// 重新开始
        /// </summary>
        public void ReStart(bool positiveShow = true, bool negativeShow = true)
        {
            Clear();
            SetShowChart(positiveShow, negativeShow);
        }
        /// <summary>
        /// 停止
        /// </summary>
        public void Stop()
        {
            var tool = test.testItem.GetDevice("P01_Pump") as P21PumpTestTool;
            if (test.IsLeft)
            {
                tool.SetLeftPositivePressureStopRead();
                tool.SetLeftNegativePressureStopRead();
                tool.OnLeftPositivePressureValueChanged -= PositivePressureValueChanged;
                tool.OnLeftPositivePressureUnitChanged -= PositivePressureUnitChanged;

                tool.OnLeftNegativePressureValueChanged -= NegativePressureValueChanged;
                tool.OnLeftNegativePressureUnitChanged -= NegativePressureUnitChanged;
            }
            else
            {
                tool.SetRightPositivePressureStopRead();
                tool.SetRightNegativePressureStopRead();
                tool.OnRightPositivePressureValueChanged -= PositivePressureValueChanged;
                tool.OnRightPositivePressureUnitChanged -= PositivePressureUnitChanged;

                tool.OnRightNegativePressureValueChanged -= NegativePressureValueChanged;
                tool.OnRightNegativePressureUnitChanged -= NegativePressureUnitChanged;

            }
        }
        /// <summary>
        /// 清空
        /// </summary>
        public void Clear()
        {
            test.testItem.DataBase["PositivePressure"].Value = 0;
            test.testItem.DataBase["NegativePressure"].Value = 0;

            test.testItem.DataBase["PositivePressureCollection"].Clear();
            test.testItem.DataBase["NegativePressureCollection"].Clear();

            pLastTime = DateTime.MinValue;
            pCount = 0;

            nLastTime = DateTime.MinValue;
            nCount = 0;
        }

    }
    /// <summary>
    /// 气泵测试
    /// </summary>
    public class PumpTest
    {
        public bool IsLeft = true;
        public dynamic testItem;

        PowerCollector powerCollector;
        PressurerCollector pressurerCollector;
        public PumpTest(dynamic item, bool isLeft = true)
        {
            this.IsLeft = isLeft;
            this.testItem = item;
        }

        /// <summary>
        /// 排空等待（停泵）
        /// </summary>
        /// <returns></returns>
        private dynamic VentWait()
        {
            Result<ValueData> result = new Result<ValueData>(true);
            result.Data = new ValueData("排空时长");
            //正压
            ValueData positivePressure = testItem.DataBase["PositivePressure"];
            //负压
            ValueData negativePressure = testItem.DataBase["NegativePressure"];

            //正压0值
            RangeCondition positivePressureZero = testItem.Conditions[0] as RangeCondition;
            //负压0值
            RangeCondition negativePressureZero = testItem.Conditions[2] as RangeCondition;

            var tool = testItem.GetDevice("P01_Pump") as P21PumpTestTool;

            try
            {
                //关泵
                if (IsLeft ? !tool.SetLeftPumpClose() : !tool.SetRightPumpClose())
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "关泵失败"));
                    return result;
                }
                System.Threading.Thread.Sleep(500);
                //排空
                if (IsLeft ? !tool.LeftVent() : !tool.RightVent())
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "排空失败"));
                    return result;
                }
                //计时器
                System.Diagnostics.Stopwatch watch = new System.Diagnostics.Stopwatch();
                watch.Start();

                while (true)
                {
                    System.Threading.Thread.Sleep(500);
                    //检查时间s 
                    double m = watch.Elapsed.TotalSeconds;
                    result.Data.Value = m;
                    result.Data.Unit = "s";
                    if (positivePressureZero.IsTrue(positivePressure.Value) && negativePressureZero.IsTrue(negativePressure.Value))
                    {
                        break;
                    }
                    if (result.Data.Value > 5)
                    {
                        result.AddTestErrMsgs(new ErrMsg(10004, string.Format("排空超时，正压传感器{0}{1}， 负压传感器{2}{3}!", positivePressure.Value, positivePressure.Unit, negativePressure.Value, negativePressure.Unit)));
                        break;
                    }
                    if (!testItem.IsRunning)
                    {
                        result.AddTestErrMsgs(ErrMsg._09999);
                        return result;
                    }
                }
                watch.Stop();
                return result;
            }
            finally
            {
                powerCollector.ReStart(false);
                pressurerCollector.ReStart(false, false);
                Vent();
            }
        }
        /// <summary>
        /// 排空（停泵）
        /// </summary>
        /// <returns></returns>
        private dynamic Vent()
        {
            Result result = new Result(true);
            var tool = testItem.GetDevice("P01_Pump") as P21PumpTestTool;
            //关泵
            if (IsLeft ? !tool.SetLeftPumpClose() : !tool.SetRightPumpClose())
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "关泵失败"));
                return result;
            }
            System.Threading.Thread.Sleep(500);
            //排空
            if (IsLeft ? !tool.LeftVent() : !tool.RightVent())
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "排空失败"));
                return result;
            }
            return result;
        }
        /// <summary>
        /// 预检
        /// </summary>
        /// <returns></returns>
        private dynamic Beforehand()
        {
            Result result = new Result(true);

            //正压
            ValueData positivePressure = testItem.DataBase["PositivePressure"];
            //负压
            ValueData negativePressure = testItem.DataBase["NegativePressure"];

            //预检正压
            ValueParameter positivePressureLimt = testItem.Parameters[0] as ValueParameter;
            //预检负压
            ValueParameter negativePressureLimt = testItem.Parameters[1] as ValueParameter;


            //预检正压限定时间
            ValueCondition positivePressureTimeLimt = testItem.Conditions[1] as ValueCondition;

            //预检正压限定时间
            ValueCondition negativePressureTimeLimt = testItem.Conditions[3] as ValueCondition;

            var tool = testItem.GetDevice("P01_Pump") as P21PumpTestTool;

            try
            {
                //排空
                Result<ValueData> vent1 = VentWait();
                if (vent1.Assert != true)
                {
                    foreach (var err in vent1.ErrMsgs)
                    {
                        result.AddTestErrMsgs(err);
                    }
                    return result;
                }
                //计时器
                System.Diagnostics.Stopwatch watch = new System.Diagnostics.Stopwatch();

                RealTimeMsg msg1 = new RealTimeMsg("预检正压");
                testItem.AddRealTimeMsgs(msg1);

                //预检正压
                if (IsLeft ? !tool.SetLeftPositivePressureMode() : !tool.SetRightPositivePressureMode())
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "抽正压失败"));
                    return result;
                }
                watch.Restart();
                powerCollector.ReStart();
                pressurerCollector.ReStart(true, false);
                while (true)
                {
                    System.Threading.Thread.Sleep(1000);
                    msg1.Content = Util.FormatLongToTimeStr(watch.Elapsed);
                    //检查时间s
                    double m = watch.Elapsed.TotalSeconds;

                    Pressure positivePressureData = new Pressure(positivePressure.Value, PressureUnit.Parse(positivePressure.Unit));
                    Pressure positivePressureLimtData = new Pressure(positivePressureLimt.Value, PressureUnit.Parse(positivePressureLimt.Unit));

                    if (positivePressureData >= positivePressureLimtData)
                    {
                        msg1.Content = "合格";
                        break;
                    }

                    if (!positivePressureTimeLimt.IsTrue(m))
                    {
                        msg1.Content = "不合格，请检查单向阀安装是正确，气路连接是否正确!";
                        result.AddTestErrMsgs(new ErrMsg(30004, string.Format("预检正压失败，无法在规定时间{0}({1})内完成抽正压，结束时正压传感器{2}{3}!", positivePressureTimeLimt.Value, positivePressureTimeLimt.Unit, positivePressure.Value, positivePressure.Unit)));
                        return result;
                    }
                    //停止
                    if (!testItem.IsRunning)
                    {
                        result.AddTestErrMsgs(ErrMsg._09999);
                        return result;
                    }
                }
                watch.Stop();
                powerCollector.SetIsTotal(false);
                pressurerCollector.SetShowChart(false, false);

                //排空
                Result<ValueData> vent2 = VentWait();
                if (vent2.Assert != true)
                {
                    foreach (var err in vent2.ErrMsgs)
                    {
                        result.AddTestErrMsgs(err);
                    }
                    return result;
                }

                RealTimeMsg msg2 = new RealTimeMsg("预检负压");
                testItem.AddRealTimeMsgs(msg2);

                //预检失压
                if (IsLeft ? !tool.SetLeftNegativePressureMode() : !tool.SetRightNegativePressureMode())
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "抽负压失败"));
                    return result;
                }
                watch.Restart();
                powerCollector.ReStart();
                pressurerCollector.ReStart(false, true);
                while (true)
                {
                    System.Threading.Thread.Sleep(1000);
                    msg2.Content = Util.FormatLongToTimeStr(watch.Elapsed);
                    //检查时间s
                    double m = watch.Elapsed.TotalSeconds;

                    Pressure negativePressureData = new Pressure(negativePressure.Value, PressureUnit.Parse(negativePressure.Unit));
                    Pressure negativePressureLimtData = new Pressure(negativePressureLimt.Value, PressureUnit.Parse(negativePressureLimt.Unit));

                    if (negativePressureData <= negativePressureLimtData)
                    {
                        msg2.Content = "合格";
                        break;
                    }

                    if (!negativePressureTimeLimt.IsTrue(m))
                    {
                        msg2.Content = "不合格，请检查单向阀安装是正确，气路连接是否正确!";
                        result.AddTestErrMsgs(new ErrMsg(30004, string.Format("预检负压失败，无法在规定时间{0}({1})内完成抽负压，结束时负压传感器{2}{3}!", negativePressureTimeLimt.Value, negativePressureTimeLimt.Unit, negativePressure.Value, negativePressure.Unit)));
                        return result;
                    }
                    //停止
                    if (!testItem.IsRunning)
                    {
                        result.AddTestErrMsgs(ErrMsg._09999);
                        return result;
                    }
                }
                watch.Stop();
                powerCollector.SetIsTotal(false);
                pressurerCollector.SetShowChart(false, false);

                //排空
                Result<ValueData> vent3 = VentWait();
                if (vent3.Assert != true)
                {
                    foreach (var err in vent3.ErrMsgs)
                    {
                        result.AddTestErrMsgs(err);
                    }
                    return result;
                }

                return result;
            }
            finally
            {
                powerCollector.ReStart(false);
                pressurerCollector.ReStart(false, false);
                Vent();
            }

