        /// <summary>
        /// 正压测试
        /// </summary>
        /// <returns></returns>
        private dynamic PositivePressureTest()
        {
            Result<List<ValueData>> result = new Result<List<ValueData>>(true);
            List<ValueData> rData = new List<ValueData>() { new ValueData("正压测试用时"), new ValueData("正压测试功耗") };
            result.Data = rData;

            //正压
            ValueData positivePressure = testItem.DataBase["PositivePressure"];
            //电流积分（功耗）
            ValueData intCurrent = testItem.DataBase["IntCurrent"];

            //正压测试给定压力
            ValueParameter positivePressureTarget = testItem.Parameters[5] as ValueParameter;
            //正压升压限定时间
            ValueCondition positivePressureTimeLimt = testItem.Conditions[6] as ValueCondition;
            //正压升压限定电流积分
            ValueCondition positivePressureICLimt = testItem.Conditions[7] as ValueCondition;

            var tool = testItem.GetDevice("P01_Pump") as P21PumpTestTool;
            try
            {
                //排空
                Result<ValueData> vent1 = VentWait();
                if (vent1.Assert != true)
                {
                    foreach (var err in vent1.ErrMsgs)
                    {
                        result.AddTestErrMsgs(err);
                    }
                    return result;
                }

                RealTimeMsg msg1 = new RealTimeMsg("正压测试");
                testItem.AddRealTimeMsgs(msg1);

                //计时器
                System.Diagnostics.Stopwatch watch = new System.Diagnostics.Stopwatch();

                //抽正压
                if (IsLeft ? !tool.SetLeftPositivePressureMode() : !tool.SetRightPositivePressureMode())
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "抽正压失败"));
                    return result;
                }

                powerCollector.ReStart();
                pressurerCollector.ReStart(true, false);
                watch.Restart();
                while (true)
                {
                    System.Threading.Thread.Sleep(1000);

                    Pressure positivePressureData = new Pressure(positivePressure.Value, PressureUnit.Parse(positivePressure.Unit));
                    Pressure positivePressureTargetData = new Pressure(positivePressureTarget.Value, PressureUnit.Parse(positivePressureTarget.Unit));
                    msg1.Content = string.Format("用时{0}  正压压力值{1} ", Util.FormatLongToTimeStr(watch.Elapsed), positivePressureData.ToString());
                    //检查时间s
                    rData[0].Value = watch.Elapsed.TotalSeconds;
                    rData[0].Unit = positivePressureTimeLimt.Unit;

                    if (positivePressureData >= positivePressureTargetData)
                    {
                        break;
                    }
                    if (!positivePressureTimeLimt.IsTrue(rData[0].Value))
                    {
                        msg1.Content = string.Format("不合格，气泵正压效率测试失败，无法在规定时间{0}({1})内完成抽负压，结束时正压传感器{2}{3},目标压力值{4}{5}!", rData[0].Value, rData[0].Unit, positivePressure.Value, positivePressure.Unit, positivePressureTarget.Value, positivePressureTarget.Unit);
                        result.AddTestErrMsgs(new ErrMsg(30004, string.Format("气泵正压效率测试不合格，无法在规定时间{0}({1})内完成抽负压，结束时正压传感器{2}{3},目标压力值{4}{5}!", rData[0].Value, rData[0].Unit, positivePressure.Value, positivePressure.Unit, positivePressureTarget.Value, positivePressureTarget.Unit)));
                        return result;
                    }
                    //停止
                    if (!testItem.IsRunning)
                    {
                        result.AddTestErrMsgs(ErrMsg._09999);
                        return result;
                    }
                }
                watch.Stop();
                powerCollector.SetIsTotal(false);
                pressurerCollector.SetShowChart(false, false);
                rData[1].Value = intCurrent.Value;
                rData[1].Unit = intCurrent.Unit;
                if (!positivePressureICLimt.IsTrue(rData[1].Value))
                {
                    msg1.Content = string.Format("不合格，气泵正压功耗测试失败，当前功耗{0}({1})!", rData[1].Value, rData[1].Unit);
                    result.AddTestErrMsgs(new ErrMsg(30004, string.Format("气泵正压功耗测试不合格，当前功耗{0}({1})!", rData[1].Value, rData[1].Unit)));
                    return result;
                }
                msg1.Content = "合格";
                return result;
            }
            finally
            {
                powerCollector.ReStart(false);
                pressurerCollector.ReStart(false, false);
                Vent();
            }
        }
