        /// <summary>
        /// 疲劳测试
        /// </summary>
        /// <returns></returns>
        private dynamic FatigueTest()
        {
            Result<ValueData> result = new Result<ValueData>(true);
            result.Data = new ValueData("疲劳用时");

            //正压
            ValueData positivePressure = testItem.DataBase["PositivePressure"];
            //负压
            ValueData negativePressure = testItem.DataBase["NegativePressure"];

            //疲劳测试次数
            ValueParameter count = testItem.Parameters[7] as ValueParameter;

            //正压测试给定压力
            ValueParameter positivePressureTarget = testItem.Parameters[5] as ValueParameter;

            //负压测试给定压力
            ValueParameter negativePressureTarget = testItem.Parameters[6] as ValueParameter;

            //正压升压限定时间
            ValueCondition positivePressureTimeLimt = testItem.Conditions[6] as ValueCondition;
            //负压升压限定时间
            ValueCondition negativePressureTimeLimt = testItem.Conditions[8] as ValueCondition;



            var tool = testItem.GetDevice("P01_Pump") as P21PumpTestTool;

            try
            {

                RealTimeMsg msg1 = new RealTimeMsg("疲劳测试");
                testItem.AddRealTimeMsgs(msg1);

                //总计时器
                System.Diagnostics.Stopwatch watchT = new System.Diagnostics.Stopwatch();
                watchT.Start();
                //计时器
                System.Diagnostics.Stopwatch watch = new System.Diagnostics.Stopwatch();
                watch.Start();

                int currentCount = 1;
                while (currentCount <= count.Value)
                {
                    //停止
                    if (!testItem.IsRunning)
                    {
                        result.AddTestErrMsgs(ErrMsg._09999);
                        return result;
                    }

                    //排空
                    Result<ValueData> vent1 = VentWait();
                    if (vent1.Assert != true)
                    {
                        foreach (var err in vent1.ErrMsgs)
                        {
                            result.AddTestErrMsgs(err);
                        }
                        return result;
                    }

                    //抽正压
                    if (IsLeft ? !tool.SetLeftPositivePressureMode() : !tool.SetRightPositivePressureMode())
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "抽正压失败"));
                        return result;
                    }
                    watch.Restart();
                    powerCollector.ReStart();
                    pressurerCollector.ReStart(true, false);
                    while (true)
                    {
                        System.Threading.Thread.Sleep(1000);
                        msg1.Content = string.Format("（{0}/{1}）抽正压【{2}】", currentCount, count.Value, Util.FormatLongToTimeStr(watch.Elapsed.Ticks));
                        //检查时间s
                        double m = watch.Elapsed.TotalSeconds;
                        Pressure positivePressureData = new Pressure(positivePressure.Value, PressureUnit.Parse(positivePressure.Unit));
                        Pressure positivePressureTargetData = new Pressure(positivePressureTarget.Value, PressureUnit.Parse(positivePressureTarget.Unit));
                        if (positivePressureData >= positivePressureTargetData)
                        {
                            break;
                        }
                        if (!positivePressureTimeLimt.IsTrue(m))
                        {
                            result.AddTestErrMsgs(new ErrMsg(30004, string.Format("疲劳测试失败，无法在规定时间{0}({1})内完成抽正压，当前正压传感器{2}{3}!", positivePressureTimeLimt.Value, positivePressureTimeLimt.Unit, positivePressure.Value, positivePressure.Unit)));
                            return result;
                        }
                        //停止
                        if (!testItem.IsRunning)
                        {
                            result.AddTestErrMsgs(ErrMsg._09999);
                            return result;
                        }
                    }


                    //排空
                    Result<ValueData> vent2 = VentWait();
                    if (vent2.Assert != true)
                    {
                        foreach (var err in vent2.ErrMsgs)
                        {
                            result.AddTestErrMsgs(err);
                        }
                        return result;
                    }

                    //抽负压
                    if (IsLeft ? !tool.SetLeftNegativePressureMode() : !tool.SetRightNegativePressureMode())
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "抽负压失败"));
                        return result;
                    }
                    watch.Restart();
                    powerCollector.ReStart();
                    pressurerCollector.ReStart(false, true);
                    while (true)
                    {
                        System.Threading.Thread.Sleep(1000);
                        msg1.Content = string.Format("（{0}/{1}）抽负压【{2}】", currentCount, count.Value, Util.FormatLongToTimeStr(watch.Elapsed.Ticks));
                        //检查时间s
                        double m = watch.Elapsed.TotalSeconds;
                        Pressure negativePressureData = new Pressure(negativePressure.Value, PressureUnit.Parse(negativePressure.Unit));
                        Pressure negativePressureTargetData = new Pressure(negativePressureTarget.Value, PressureUnit.Parse(negativePressureTarget.Unit));
                        if (negativePressureData <= negativePressureTargetData)
                        {
                            break;
                        }

                        if (!negativePressureTimeLimt.IsTrue(m))
                        {
                            result.AddTestErrMsgs(new ErrMsg(30004, string.Format("疲劳测试失败，无法在规定时间{0}({1})内完成抽负压，当前负压传感器{2}{3}!", negativePressureTimeLimt.Value, negativePressureTimeLimt.Unit, negativePressure.Value, negativePressure.Unit)));
                            return result;
                        }
                        //停止
                        if (!testItem.IsRunning)
                        {
                            result.AddTestErrMsgs(ErrMsg._09999);
                            return result;
                        }
                    }
                    currentCount++;
                }
                watchT.Stop();
                result.Data.Value = watchT.Elapsed.TotalSeconds;
                result.Data.Unit = "s";
                return result;
            }
            finally
            {
                powerCollector.ReStart(false);
                pressurerCollector.ReStart(false, false);
                Vent();
            }
        }

        public dynamic Test()
        {
            Result<List<DataBase>> result = new Result<List<DataBase>>(true);
            List<DataBase> rData = new List<DataBase>() { };
            result.Data = rData;

            var tool = testItem.GetDevice("P01_Pump") as P21PumpTestTool;

            if (IsLeft ? !tool.SetLeftDataUploadON() : !tool.SetRightDataUploadON())
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "开启数据上传失败"));
                return result;
            }

            powerCollector = new PowerCollector(this);
            pressurerCollector = new PressurerCollector(this);

            powerCollector.Start(false);
            pressurerCollector.Start(false, false);

            try
            {
                BoolParameter isBeforehand = testItem.Parameters[8] as BoolParameter;  //是否预检
                BoolParameter isNoLoadRunIn = testItem.Parameters[9] as BoolParameter;   //是否空载磨合
                BoolParameter isNoLoadCurrentWaveformTest = testItem.Parameters[10] as BoolParameter;   //是否空载电流
                BoolParameter isNoLoadPowerWasteTest1 = testItem.Parameters[11] as BoolParameter;   //是否空载功耗测试
                BoolParameter isPositivePressureTest1 = testItem.Parameters[12] as BoolParameter;   //是否正压测试
                BoolParameter isNegativePressureTest1 = testItem.Parameters[13] as BoolParameter;   //是否负压测试
                BoolParameter isFatigueTest = testItem.Parameters[14] as BoolParameter;   //是否疲劳测试
                BoolParameter isNoLoadPowerWasteTest2 = testItem.Parameters[15] as BoolParameter;   //是否功耗测试二
                BoolParameter isPositivePressureTest2 = testItem.Parameters[16] as BoolParameter;   //是否正压测试二
                BoolParameter isNegativePressureTest2 = testItem.Parameters[17] as BoolParameter;   //是否负压测试二

                if (isBeforehand.Value)
                {
                    //预检
                    Result beforehand = Beforehand();
                    if (beforehand.Assert != true)
                    {
                        foreach (var err in beforehand.ErrMsgs)
                        {
                            result.AddTestErrMsgs(err);
                        }
                        return result;
                    }
                }

                if (isNoLoadRunIn.Value)
                {
                    //空载磨合
                    Result noLoadRunIn = NoLoadRunIn();
                    if (noLoadRunIn.Assert != true)
                    {
                        foreach (var err in noLoadRunIn.ErrMsgs)
                        {
                            result.AddTestErrMsgs(err);
                        }
                        return result;
                    }
                }

                if (isNoLoadCurrentWaveformTest.Value)
                {
                    //空载电流测试
                    Result<ValueData> noLoadCurrentWaveformTest = NoLoadCurrentWaveformTest();
                    if (noLoadCurrentWaveformTest.Assert != true)
                    {
                        foreach (var err in noLoadCurrentWaveformTest.ErrMsgs)
                        {
                            result.AddTestErrMsgs(err);
                        }
                        return result;
                    }
                    rData.Add(noLoadCurrentWaveformTest.Data);
                }

                if (isNoLoadPowerWasteTest1.Value)
                {
                    //空载功耗测试
                    Result<ValueData> noLoadPowerWasteTest1 = NoLoadPowerWasteTest();
                    if (noLoadPowerWasteTest1.Assert != true)
                    {
                        foreach (var err in noLoadPowerWasteTest1.ErrMsgs)
                        {
                            result.AddTestErrMsgs(err);
                        }
                        return result;
                    }
                    rData.Add(noLoadPowerWasteTest1.Data);
                }

                if (isPositivePressureTest1.Value)
                {
                    //正压测试
                    Result<List<ValueData>> positivePressureTest1 = PositivePressureTest();
                    if (positivePressureTest1.Assert != true)
                    {
                        foreach (var err in positivePressureTest1.ErrMsgs)
                        {
                            result.AddTestErrMsgs(err);
                        }
                        return result;
                    }
                    rData.AddRange(positivePressureTest1.Data);
                }

                if (isNegativePressureTest1.Value)
                {
                    //负压测试

                    Result<List<ValueData>> negativePressureTest1 = NegativePressureTest();
                    if (negativePressureTest1.Assert != true)
                    {
                        foreach (var err in negativePressureTest1.ErrMsgs)
                        {
                            result.AddTestErrMsgs(err);
                        }
                        return result;
                    }
                    rData.AddRange(negativePressureTest1.Data);
                }

                if (isFatigueTest.Value)
                {
                    //疲劳测试
                    Result<ValueData> fatigueTest = FatigueTest();
                    if (fatigueTest.Assert != true)
                    {
                        foreach (var err in fatigueTest.ErrMsgs)
                        {
                            result.AddTestErrMsgs(err);
                        }
                        return result;
                    }
                    rData.Add(fatigueTest.Data);
                }

                if (isNoLoadPowerWasteTest2.Value)
                {
                    //空载功耗测试2
                    Result<ValueData> noLoadPowerWasteTest2 = NoLoadPowerWasteTest();
                    if (noLoadPowerWasteTest2.Assert != true)
                    {
                        foreach (var err in noLoadPowerWasteTest2.ErrMsgs)
                        {
                            result.AddTestErrMsgs(err);
                        }
                        return result;
                    }
                    rData.Add(noLoadPowerWasteTest2.Data);
                }

                if (isPositivePressureTest2.Value)
                {
                    //正压测试2
                    Result<List<ValueData>> positivePressureTest2 = PositivePressureTest();
                    if (positivePressureTest2.Assert != true)
                    {
                        foreach (var err in positivePressureTest2.ErrMsgs)
                        {
                            result.AddTestErrMsgs(err);
                        }
                        return result;
                    }
                    rData.AddRange(positivePressureTest2.Data);
                }

                if (isNegativePressureTest2.Value)
                {
                    //负压测试2
                    Result<List<ValueData>> negativePressureTest2 = NegativePressureTest();
                    if (negativePressureTest2.Assert != true)
                    {
                        foreach (var err in negativePressureTest2.ErrMsgs)
                        {
                            result.AddTestErrMsgs(err);
                        }
                        return result;
                    }
                    rData.AddRange(negativePressureTest2.Data);
                }
                return result;
            }
            finally
            {
                VentWait();
                powerCollector.Clear();
                powerCollector.Stop();
                powerCollector.Clear();
                pressurerCollector.Stop();
            }
        }
    }
    #endregion 气泵测试

    #region 控制模块测试

    /// <summary>
    /// 测试控制版本
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestControlVersions(dynamic item)
    {
        Result<List<TextData>> result = new Result<List<TextData>>(true);
        List<TextData> rData = new List<TextData>() { new TextData("被检类型"), new TextData("原固件版本"), new TextData("新固件版本") };
        result.Data = rData;
        DUT dut = item.Root.DUT;
        try
        {
            item.GetDevice("P21_CM").StopRead();

            item.ClearRealTimeMsgs();

            System.Threading.Thread.Sleep(500);

            //读取被检类型
            RealTimeMsg msg0 = new RealTimeMsg();
            msg0.Content = "读取被检类型";
            item.AddRealTimeMsgs(msg0);
            string testType = "H";
            if (!item.GetDevice("P21_CM_T").GetTestModuleType(out testType))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "读取被检类型失败"));
                return result;
            }
            msg0.Name = "被检类型";
            msg0.Content = testType;
            rData[0].Value = testType;

            System.Threading.Thread.Sleep(500);

            //读取固件版本
            RealTimeMsg msg1 = new RealTimeMsg();
            msg1.Content = "读取固件版本";
            item.AddRealTimeMsgs(msg1);

            string oldver = "NULL";
            item.GetDevice("P21_CM").GetVersion(out oldver);
            msg1.Name = "固件版本";
            msg1.Content = oldver;
            rData[1].Value = oldver;

            System.Threading.Thread.Sleep(500);

            //读取固件升级包
            RealTimeMsg msg2 = new RealTimeMsg();
            msg2.Content = "读取固件升级包";
            item.AddRealTimeMsgs(msg2);
            string updateSRC = "";
            byte[] updateData = item.GetDevice("P21_CM").GetUpdateData(testType, out updateSRC);

            if (updateData == null || updateData.Length < 0x2200)
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "读取固件升级包失败"));
                return result;
            }
            msg2.Name = "固件升级包";
            msg2.Content = "大小" + Math.Round(updateData.Length / 1024.0, 2) + "KB（CRC:" + updateSRC + ")";

            Dictionary<int, byte[]> updatePackage = new Dictionary<int, byte[]>();//升级包分包
            byte packageSize = 128;           //每一包数据最大为128bytes. 
            int packageCount = updateData.Length % packageSize == 0 ? updateData.Length / packageSize : (updateData.Length / packageSize) + 1;//包数
            int offset = 0;
            for (int i = 0; i < packageCount; i++)
            {
                int count = updateData.Length - offset > packageSize ? packageSize : updateData.Length - offset;
                byte[] data = new byte[count];
                Array.Copy(updateData, offset, data, 0, count);
                updatePackage.Add(i, data);
                offset += count;
            }
            msg2.Content += ",需" + packageCount + "包（128bytes）发送";

            //开始升级
            RealTimeMsg msg10 = new RealTimeMsg("进入升级模式");
            item.AddRealTimeMsgs(msg10);
            msg10.Content = "";

            RealTimeMsg msg11 = new RealTimeMsg("擦除程序开始升级");
            item.AddRealTimeMsgs(msg11);
            msg11.Content = "";

            RealTimeMsg msg12 = new RealTimeMsg("升级发送进度");
            item.AddRealTimeMsgs(msg12);
            msg12.Content = "";

            RealTimeMsg msg13 = new RealTimeMsg("升级结果");
            item.AddRealTimeMsgs(msg13);
            msg13.Content = "";

            bool isUpdatedSucess = false;
            while (!isUpdatedSucess)
            {
                #region 进入升级模式
                bool isIntoUpdate = false;
                while (!isIntoUpdate)
                {
                    System.Threading.Thread.Sleep(500);
                    item.GetDevice("P21_CM_T").SetCMBPowerOff();
                    for (int i = 0; i < 5; i++)
                    {
                        msg10.ContentRunning();
                        System.Threading.Thread.Sleep(1000);
                        if (!item.IsRunning)
                        {
                            result.AddTestErrMsgs(ErrMsg._09999);
                            return result;
                        }
                    }
                    System.Threading.Tasks.Task<bool> intoUpdateTask = new System.Threading.Tasks.Task<bool>(() =>
                    {
                        return item.GetDevice("P21_CM").IntoUpdate(10);
                    });
                    intoUpdateTask.Start();
                    System.Threading.Thread.Sleep(2000);
                    for (int i = 0; i < 2; i++)
                    {
                        msg10.ContentRunning();
                        System.Threading.Thread.Sleep(1000);
                        if (!item.IsRunning)
                        {
                            result.AddTestErrMsgs(ErrMsg._09999);
                            return result;
                        }
                    }
                    item.GetDevice("P21_CM_T").SetCMBPowerOn();
                    while (!intoUpdateTask.IsCompleted)
                    {
                        msg10.ContentRunning();
                        System.Threading.Thread.Sleep(1000);
                        if (!item.IsRunning)
                        {
                            result.AddTestErrMsgs(ErrMsg._09999);
                            return result;
                        }
                    }


                    if (intoUpdateTask.IsCompleted)
                    {
                        isIntoUpdate = intoUpdateTask.Result;
                    }
                    if (!isIntoUpdate)
                    {
                        string isIntoUpdateResult = "";
                        isIntoUpdate = item.GetDevice("P21_CM").IsIntoUpdate(out isIntoUpdateResult);
                    }

                    if (isIntoUpdate)
                    {
                        msg10.Content = "成功";
                    }
                    else
                    {
                        msg10.Content = "失败";
                    }

                }

                #endregion

                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }

                #region 擦除程序开始升级
                string eraseChipResult = "";
                if (item.GetDevice("P21_CM").EraseChip(out eraseChipResult))
                {
                    msg11.Content = "成功";
                }
                else
                {
                    msg11.Content = "失败";
                    System.Threading.Thread.Sleep(2000);
                    break;
                }
                #endregion

                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }

                #region 发送升级包
                StringBuilder sb = new StringBuilder();
                for (int n = 0; n < 50; n++)
                {
                    sb.Append("-");
                }
                msg12.Content = sb.ToString();
                int index = 0;
                while (index < packageCount)
                {
                    if (item.GetDevice("P21_CM").WriteUpdateData(updatePackage[index]))
                    {
                        sb.Clear();
                        int c = index * 50 / packageCount;
                        for (int n = 0; n < 50; n++)
                        {
                            if (n > c)
                            {
                                sb.Append("-");
                            }
                            else
                            {
                                sb.Append("*");
                            }
                        }
                        msg12.Content = sb.ToString();
                    }
                    else
                    {
                        break;
                    }
                    System.Threading.Thread.Sleep(10);
                    index++;
                }
                if (index < packageCount)
                {
                    msg12.Content += "失败";
                }
                else
                {
                    msg12.Content = "完成";
                }
                #endregion

                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }

                #region 升级结果验证
                string updateResult = "";
                if (item.GetDevice("P21_CM").ReadUpdateResult(out updateResult))
                {
                    msg13.Content = updateResult;
                    //验证CRC
                    if (updateResult.Contains(updateSRC))
                    {
                        isUpdatedSucess = true;
                        msg13.Content += ",CRC验证成功，升级完成";
                    }
                    else
                    {
                        isUpdatedSucess = false;
                        msg13.Content += ",CRC验证失败，升级失败";
                    }

                }
                else
                {
                    isUpdatedSucess = false;
                    msg13.Content += "读取升级结果失败，升级失败";
                }
                //升级失败重新升级
                if (!isUpdatedSucess)
                {
                    System.Threading.Thread.Sleep(2000);
                    msg10.Content = "";
                    msg11.Content = "";
                    msg12.Content = "";
                    msg13.Content = "";
                }

                #endregion

                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
            }
            //读取固件版本
            RealTimeMsg msg100 = new RealTimeMsg("读取固件版本");
            item.AddRealTimeMsgs(msg100);
            int t = 0;
            while (t < 20)
            {
                msg100.ContentRunning();
                System.Threading.Thread.Sleep(1000);
                t++;

                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
            }
            string newver;
            if (!item.GetDevice("P21_CM").GetVersion(out newver))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "读取读取固件版本失败"));
                return result;
            }
            msg100.Name = "固件版本";
            msg100.Content = newver;
            rData[2].Value = newver;


            return result;

        }
        finally
        {
            item.GetDevice("P21_CM").StartRead();
            System.Threading.Thread.Sleep(2000);
        }

    }
    /// <summary>
    /// SN号写入测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestWriteControlSN(dynamic item)
    {
        Result<List<TextData>> result = new Result<List<TextData>>(true);
        List<TextData> rData = new List<TextData>() { new TextData("原SN"), new TextData("写入SN") };
        result.Data = rData;
        //DUT dut = item.Root.DUT;
        try
        {
            //重新设置SN
            //SetParameters(item);

            //获取参数
            if (item.Parameters == null)
            {
                result.AddTestErrMsgs(ErrMsg._10001);
                return result;
            }
            TextParameter parameter1 = item.Parameters[0] as TextParameter;

            item.ClearRealTimeMsgs();

            System.Threading.Thread.Sleep(500);

            RealTimeMsg msg1 = new RealTimeMsg();
            msg1.Content = "读取SN";
            item.AddRealTimeMsgs(msg1);

            string elesn;
            if (!item.GetDevice("P21_CM").GetSerialNumber(out elesn))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "读取SN失败"));
                return result;
            }

            msg1.Name = "SN";
            msg1.Content = elesn;
            rData[0].Value = elesn;

            System.Threading.Thread.Sleep(2000);

            RealTimeMsg msg2 = new RealTimeMsg();
            msg2.Content = "写入SN";
            item.AddRealTimeMsgs(msg2);
            string str = parameter1.Value;

            if (!item.GetDevice("P21_CM").SetSerialNumber(str))
            {
                if (str.Length > 12)
                    str = str.Substring(str.Length - 12);

                if (!item.GetDevice("P21_CM").SetSerialNumber(str))
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "写入SN失败"));
                    return result;
                }
            }

            msg2.Name = "写入SN";
            msg2.Content = str;

            System.Threading.Thread.Sleep(2000);

            RealTimeMsg msg3 = new RealTimeMsg();
            msg3.Content = "读取SN";
            item.AddRealTimeMsgs(msg3);

            if (!item.GetDevice("P21_CM").GetSerialNumber(out elesn))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "读取SN失败"));
                return result;
            }
            msg3.Name = "读取SN";
            msg3.Content = elesn;
            rData[1].Value = elesn;



            if (rData[1].Value.Trim() != str.Trim())
            {
                result.AddTestErrMsgs(new ErrMsg(30004, "写入SN与读取SN不一致"));
            }
            //else
            //{
            //    dut.DeviceCode = rData[1].Value;
            //}
            return result;

        }
        finally
        {
            if (result.Assert != true)
            {
                System.Threading.Thread.Sleep(2000);

                RealTimeMsg msg4 = new RealTimeMsg();
                msg4.Name = "写入原SN";
                msg4.Content = rData[0].Value;
                item.AddRealTimeMsgs(msg4);
                item.GetDevice("P21_CM").SetSerialNumber(rData[0].Value);
            }
        }
    }
    /// <summary>
    /// 各电源检测
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestElectricControllerPower(dynamic item)
    {
        Result<List<ValueData>> result = new Result<List<ValueData>>(true);
        List<ValueData> rData = new List<ValueData>();
        result.Data = rData;
        //获取条件
        if (item.Conditions == null)
        {
            result.AddTestErrMsgs(ErrMsg._10002);
            return result;
        }
        item.ClearRealTimeMsgs();

        item.AddRealTimeMsgs(new RealTimeMsg("读取各电源信息 "));

        while (true)
        {
            ElectricControllerInfo electricControllerInfo = new ElectricControllerInfo();
            if (!item.GetDevice("P21_CM").GetElectricControllerInfo(out electricControllerInfo))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "读取诊断信息失败！"));
                return result;
            }
            if (electricControllerInfo.N3V3 < 0)
            {
                break;
            }
            System.Threading.Thread.Sleep(1000);
        }


        Dictionary<string, double> readResult = null;
        if (!item.GetDevice("P21_CM").GetElectricControllerPower(out readResult))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "读取各电源信息失败！"));
            return result;
        }
        if (readResult.Count == 0)
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "读取各电源信息失败！"));
            return result;
        }

        foreach (RangeCondition conditions in item.Conditions)
        {
            if (readResult.ContainsKey(conditions.Name))
            {
                bool istrue = conditions.IsTrue(readResult[conditions.Name]);
                RealTimeMsg msg = new RealTimeMsg();
                msg.Name = conditions.Name;
                msg.Content = string.Format("读取值为{0},区间范围{1}~{2},测试{3}", readResult[conditions.Name], conditions.Lower, conditions.Upper, istrue ? "通过" : "不通过");
                item.AddRealTimeMsgs(msg);
                if (!istrue)
                {
                    result.AddTestErrMsgs(new ErrMsg(30003, string.Format("{0}条件不符,读取值为{1},区间范围{2}~{3}", conditions.Name, readResult[conditions.Name], conditions.Lower, conditions.Upper)));
                }
                rData.Add(new ValueData(conditions.Name, readResult[conditions.Name]));
            }
            else
            {
                result.AddTestErrMsgs(new ErrMsg(30003, "未采集到" + conditions.Name + "的数据"));
            }
            System.Threading.Thread.Sleep(500);
        }

        return result;
    }
    /// <summary>
    /// 内置压力模块在线监测
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestModuleIsOnline(dynamic item)
    {
        Result<List<TextData>> result = new Result<List<TextData>>(true);
        List<TextData> rData = new List<TextData>();
        result.Data = rData;
        item.ClearRealTimeMsgs();

        System.Diagnostics.Stopwatch watch = new System.Diagnostics.Stopwatch();

        ControlData controlData = new ControlData();
        controlData.DataModel = ControlDataModel.Cal;

        RealTimeMsg msg1 = new RealTimeMsg("读取模块在线状态");
        item.AddRealTimeMsgs(msg1);
        msg1.ReStart();

        watch.Restart();
        System.Threading.Thread.Sleep(1000);
        while (item.GetDevice("P21_CM").IsScanning && item.GetDevice("P21_CM").sensorR == 0)
        {
            System.Threading.Thread.Sleep(1000);
            msg1.Tick();
            if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > 30)
            {
                break;
            }
        }

        watch.Stop();

        if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > 30)
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "获取控制信息超时！"));
            return result;
        }


        Dictionary<string, bool> readResult = null;
        if (!item.GetDevice("P21_CM").GetModuleOnlineState(out readResult))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "读取模块在线状态失败！"));
            return result;
        }
        if (readResult.Count == 0)
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "读取模块在线状态失败！"));
            return result;
        }

        if (readResult.ContainsKey("HighModule") && readResult["HighModule"])
        {
            RealTimeMsg msg2 = new RealTimeMsg("HighModule");
            item.AddRealTimeMsgs(msg2);
            msg2.Content = "OnLine";
            rData.Add(new TextData("HighModule", "OnLine"));
        }
        else
        {
            RealTimeMsg msg2 = new RealTimeMsg("HighModule");
            item.AddRealTimeMsgs(msg2);
            msg2.Content = "OffLine";
            rData.Add(new TextData("HighModule", "OffLine"));
            result.AddTestErrMsgs(new ErrMsg(30003, "内置高压模块不在线"));
        }
        if (readResult.ContainsKey("LowModule") && readResult["LowModule"])
        {
            RealTimeMsg msg3 = new RealTimeMsg("LowModule");
            item.AddRealTimeMsgs(msg3);
            msg3.Content = "OnLine";
            rData.Add(new TextData("LowModule", "OnLine"));
        }
        else
        {
            RealTimeMsg msg3 = new RealTimeMsg("LowModule");
            item.AddRealTimeMsgs(msg3);
            msg3.Content = "OffLine";
            rData.Add(new TextData("LowModule", "OffLine"));
            result.AddTestErrMsgs(new ErrMsg(30003, "内置低压模块不在线"));
        }
        return result;
    }
