            msg0.Content = string.Format("{0}({1}~{2})kPa", "H", low, up);


            ValueCondition condition4 = new ValueCondition();
            condition4.Operator = condition1.Operator;
            condition4.Value = condition1.Value * span;
            condition4.Unit = "MPa";
            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region
            //V2打开 
            RealTimeMsg msg1 = new RealTimeMsg("V2");
            item.AddRealTimeMsgs(msg1);
            msg1.Content = "打开";
            if (!item.GetDevice("P21_CM").SetV2OpenState(true))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V2打开失败！"));
                return result;
            }
            //V13通电
            RealTimeMsg msg2 = new RealTimeMsg("V13");
            item.AddRealTimeMsgs(msg2);
            msg2.Content = "打开";
            if (!item.GetDevice("P21_CM_T").SetV13On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V13打开失败！"));
