            }

            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                if (condition0.IsTrue(sensor1.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > parameter0.Value)
                {
                    break;
                }
            }
            watch.Stop();

            if (!condition0.IsTrue(sensor1.Value))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "真空输入超时，V2阀连接错误！"));
                return result;
            }
            //V13关闭
            msg2.Content = "关闭";
            if (!item.GetDevice("P21_CM_T").SetV13Off())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V13关闭失败！"));
                return result;
            }


            RealTimeMsg msg3 = new RealTimeMsg("计时");
            item.AddRealTimeMsgs(msg3);
            //延时10秒
            for (int i = 0; i <= parameter1.Value; i++)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg3.Content = i + "秒";
                System.Threading.Thread.Sleep(1000);
            }
            //读取气压传感器1的值

            time1_sensor1.Value = sensor1.Value;

            msg3.Name = "气压传感器1(time1)";
            msg3.Content = string.Format("{0}({1})", time1_sensor1.Value, time1_sensor1.Unit);

            RealTimeMsg msg4 = new RealTimeMsg("计时");
            item.AddRealTimeMsgs(msg4);
            //延时30秒
            for (int i = 0; i <= parameter2.Value; i++)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg4.Content = i + "秒";
                System.Threading.Thread.Sleep(1000);
            }
            //再次读取气压传感器1的值

            time2_sensor1.Value = sensor1.Value;

            msg4.Name = "气压传感器1(time2)";
            msg4.Content = string.Format("{0}({1})", time2_sensor1.Value, time2_sensor1.Unit);
            //计算气压传感器绝对值变化
            double r1 = Math.Abs(Math.Round((time2_sensor1.Value - time1_sensor1.Value) / time1_sensor1.Value, 4));
            RealTimeMsg msg5 = new RealTimeMsg("气压传感器1变化率");
            item.AddRealTimeMsgs(msg5);
            msg5.Content = r1.ToString();

            RealTimeMsg msg6 = new RealTimeMsg("真空输入接口密封");
            item.AddRealTimeMsgs(msg6);
            if (condition2.IsTrue(r1))
            {
                msg6.Content = "合格";
            }
            else
            {
                msg6.Content = "不合格";
                result.AddTestErrMsgs(new ErrMsg(30003, "真空输入接口密封不合格,V2阀连接错误"));
                return result;
            }
            #endregion
            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }
            #region
            //V1打开 
            RealTimeMsg msg100 = new RealTimeMsg("V1");
            item.AddRealTimeMsgs(msg100);
            msg100.Content = "打开";
            if (!item.GetDevice("P21_CM").SetV1OpenState(true))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V1打开失败！"));
                return result;
            }
            //V16打开
            RealTimeMsg msg7 = new RealTimeMsg("V16");
            item.AddRealTimeMsgs(msg7);
            msg7.Content = "打开";
            if (!item.GetDevice("P21_CM_T").SetV16On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V16打开失败！"));
                return result;
            }
            //15打开
            RealTimeMsg msg8 = new RealTimeMsg("V15");
            item.AddRealTimeMsgs(msg8);
            msg8.Content = "打开";
            if (!item.GetDevice("P21_CM_T").SetV15On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V15打开失败！"));
                return result;
            }

            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                if (condition4.IsTrue(sensor2.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > parameter0.Value)
                {
                    break;
                }
            }
            watch.Stop();

            if (!condition4.IsTrue(sensor2.Value))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "高压输入超时，高压输入接口泄露！"));
                return result;
            }

            //V16关闭 
            msg7.Content = "关闭";
            if (!item.GetDevice("P21_CM_T").SetV16Off())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V16关闭失败！"));
                return result;
            }
            //15关闭
            msg8.Content = "关闭";
            if (!item.GetDevice("P21_CM_T").SetV15Off())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V15关闭失败！"));
                return result;
            }


            RealTimeMsg msg9 = new RealTimeMsg("计时");
            item.AddRealTimeMsgs(msg9);
            //延时10秒
            for (int i = 0; i <= parameter1.Value; i++)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg9.Content = i + "秒";
                System.Threading.Thread.Sleep(1000);
            }
            //读取气压传感器1的值

            time1_sensor2.Value = sensor2.Value;

            msg9.Name = "气压传感器2(time1)";
            msg9.Content = string.Format("{0}({1})", time1_sensor2.Value, time1_sensor2.Unit);

            RealTimeMsg msg10 = new RealTimeMsg("计时");
            item.AddRealTimeMsgs(msg10);
            //延时30秒
            for (int i = 0; i <= parameter2.Value; i++)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg10.Content = i + "秒";
                System.Threading.Thread.Sleep(1000);
            }
            //再次读取气压传感器1的值

            time2_sensor2.Value = sensor2.Value;

            msg10.Name = "气压传感器2(time2)";
            msg10.Content = string.Format("{0}({1})", time2_sensor2.Value, time2_sensor2.Unit);
            //计算气压传感器绝对值变化
            double r2 = Math.Abs(Math.Round((time2_sensor2.Value - time1_sensor2.Value) / span, 4));
            RealTimeMsg msg11 = new RealTimeMsg("气压传感器2变化率");
            item.AddRealTimeMsgs(msg11);
            msg11.Content = r2.ToString();

            RealTimeMsg msg12 = new RealTimeMsg("高压输入接口密封");
            item.AddRealTimeMsgs(msg12);
            if (condition3.IsTrue(r2))
            {
                msg12.Content = "合格";
            }
            else
            {
                msg12.Content = "不合格";
                result.AddTestErrMsgs(new ErrMsg(30003, "高压输入接口密封不合格,接口泄露"));
                return result;
            }
            #endregion
            return result;
        }
        finally
        {
            item.GetDevice("P21_CM_T").SafeExit();
            item.GetDevice("P21_CM").SafeExit();
            timer1.Stop();
            timer1.Dispose();
        }

    }

    /// <summary>
    /// 阀连接性测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestValue(dynamic item)
    {

        //数据采集定时器
        System.Timers.Timer timer1 = new System.Timers.Timer();

        //定义返回类型
        Result<List<DataBase>> result = new Result<List<DataBase>>(true);
        List<DataBase> rData = new List<DataBase>() { };
        result.Data = rData;


        ValueData sensor1 = item.DataBase["sensor1"];
        ValueData sensor2 = item.DataBase["sensor2"];
        ValueData sensor3 = item.DataBase["sensor3"];

        BooleanData V11 = item.DataBase["V11"];
        BooleanData V12 = item.DataBase["V12"];
        BooleanData V13 = item.DataBase["V13"];
        BooleanData V14 = item.DataBase["V14"];
        BooleanData V15 = item.DataBase["V15"];
        BooleanData V16 = item.DataBase["V16"];

        BooleanData V1 = item.DataBase["V1"];
        BooleanData V2 = item.DataBase["V2"];
        BooleanData V3 = item.DataBase["V3"];
        BooleanData V4 = item.DataBase["V4"];
        BooleanData V5 = item.DataBase["V5"];
        BooleanData V6 = item.DataBase["V6"];
        BooleanData V8 = item.DataBase["V8"];
        ValueData VC = item.DataBase["VC"];

        ValueData sensorR = item.DataBase["sensorR"];
        ValueData sensorH = item.DataBase["sensorH"];
        ValueData sensorL = item.DataBase["sensorL"];

        ValueData sensorP = item.DataBase["sensorP"];
        ValueData sensorN = item.DataBase["sensorN"];

        ValueData sensorA = item.DataBase["sensorA"];
        //清空实时信息
        item.ClearRealTimeMsgs();

        //获取条件参数
        ValueParameter parameter0;
        ValueParameter parameter1;
        try
        {
            parameter0 = item.Parameters[0] as ValueParameter;
            parameter1 = item.Parameters[1] as ValueParameter;
        }
        catch
        {
            result.AddTestErrMsgs(ErrMsg._10001);//添加错误信息
            return result;
        }

        //获取条件
        ValueCondition condition0;
        ValueCondition condition1;
        ValueCondition condition2;
        ValueCondition condition3;

        try
        {
            condition0 = item.Conditions[0] as ValueCondition;
            condition1 = item.Conditions[1] as ValueCondition;
            condition2 = item.Conditions[2] as ValueCondition;
            condition3 = item.Conditions[3] as ValueCondition;
        }
        catch
        {
            result.AddTestErrMsgs(ErrMsg._10002);//添加错误信息
            return result;
        }


        try
        {
            //数据采集
            timer1.Elapsed += (s, e) =>
            {
                item.GetDevice("P21_CM_T").SetDataBase(item.DataBase);
                item.GetDevice("P21_CM").SetDataBase(item.DataBase);
            };
            timer1.Interval = 500;
            timer1.Start();

            System.Diagnostics.Stopwatch watch = new System.Diagnostics.Stopwatch();

            #region
            System.Threading.Thread.Sleep(1000);
            while (item.GetDevice("P21_CM").IsScanning && item.GetDevice("P21_CM").sensorR == 0)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
            }
            #endregion
            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }
            #region
            //切换至低量程
            RealTimeMsg msg0 = new RealTimeMsg("切换量程模块");
            item.AddRealTimeMsgs(msg0);
            msg0.ReStart();
            if (!item.GetDevice("P21_CM").SetControlLPressureRangeModel())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "切换至低量程模块失败！"));
                return result;
            }

            System.Threading.Thread.Sleep(1000);

            while (item.GetDevice("P21_CM").IsRangeSwapping)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg0.Tick();
                System.Threading.Thread.Sleep(1000);
            }

            double low, up, span;
            if (!item.GetDevice("P21_CM").GetControlLPressureRange(out low, out up))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "获取第控制量程失败！"));
                return result;
            }
            span = up - low;
            msg0.Content = string.Format("{0}({1}~{2})kPa", "L", low, up);



            ValueCondition condition4 = new ValueCondition();
            condition4.Value = condition1.Value * span;
            condition4.Operator = condition1.Operator;
            condition4.Unit = "kPa";

            ValueCondition condition5 = new ValueCondition();
            condition5.Value = condition3.Value * span;
            condition5.Operator = condition3.Operator;
            condition5.Unit = "kPa";

            RangeCondition condition6 = new RangeCondition();
            condition6.Lower = -1;
            condition6.Upper = 1;
            condition6.Unit = "kPa";

            RangeCondition condition7 = new RangeCondition();
            condition7.Lower = -2;
            condition7.Upper = 2;
            condition7.Unit = "kPa";

            #endregion
            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }
            #region
            //V4关闭
            RealTimeMsg msg1000 = new RealTimeMsg("V4");
            item.AddRealTimeMsgs(msg1000);
            msg1000.Content = "关闭";
            if (!item.GetDevice("P21_CM").SetV4OpenState(false))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V4关闭失败！"));
                return result;
            }
            System.Threading.Thread.Sleep(1000);
            //V2 V3 VOUT 开启
            RealTimeMsg msg1 = new RealTimeMsg("V2、V3、VOUT");
            item.AddRealTimeMsgs(msg1);
            msg1.Content = "打开";
            if (!item.GetDevice("P21_CM").SetV2V3VOUTToOpen())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V2、V3、VOUT打开失败！"));
                return result;
            }

            //V13通电 真空输入
            RealTimeMsg msg2 = new RealTimeMsg("V13");
            item.AddRealTimeMsgs(msg2);
            msg2.Content = "打开";
            if (!item.GetDevice("P21_CM_T").SetV13On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V13打开失败！"));
                return result;
            }
            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                if (condition0.IsTrue(sensor1.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > parameter0.Value)
                {
                    break;
                }
            }
            watch.Stop();

            if (!condition0.IsTrue(sensor1.Value))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "真空输入超时！"));
                return result;
            }
            //V13关闭
            msg2.Content = "关闭";
            if (!item.GetDevice("P21_CM_T").SetV13Off())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V13关闭失败！"));
                return result;
            }

            RealTimeMsg msg3 = new RealTimeMsg("计时");
            item.AddRealTimeMsgs(msg3);
            //延时5秒
            for (int i = 0; i <= parameter1.Value; i++)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg3.Content = i + "秒";
                System.Threading.Thread.Sleep(1000);
            }
            //读取高压压力模块的值
            msg3.Name = "高压压力模块";
            msg3.Content = string.Format("{0}({1})", sensorH.Value, sensorH.Unit);

            if (!condition2.IsTrue(Math.Abs(sensorH.Value - sensor1.Value)))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "V3或VOUT阀连接错误！"));
                return result;
            }

            //读取低压压力模块的值
            RealTimeMsg msg4 = new RealTimeMsg("低压压力模块");
            item.AddRealTimeMsgs(msg4);
            msg4.Content = string.Format("{0}({1})", sensorL.Value, sensorL.Unit);

            if (!condition2.IsTrue(Math.Abs(sensorL.Value - sensor1.Value)))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "V5阀连接错误！"));
                return result;
            }

            //V2 V3 VOUT 关闭
            RealTimeMsg msg5 = new RealTimeMsg("V2、V3、VOUT");
            item.AddRealTimeMsgs(msg5);
            msg5.Content = "关闭";
            if (!item.GetDevice("P21_CM").SetV2V3VOUTToClose())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V2、V3、VOUT关闭失败！"));
                return result;
            }

            //V4打开
            RealTimeMsg msg6 = new RealTimeMsg("V4");
            item.AddRealTimeMsgs(msg6);
            msg6.Content = "打开";
            if (!item.GetDevice("P21_CM").SetV4OpenState(true))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V4打开失败！"));
                return result;
            }

            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                if (condition6.IsTrue(sensorH.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > 5)
                {
                    break;
                }
            }
            watch.Stop();

            RealTimeMsg msg7 = new RealTimeMsg("高压压力模块");
            item.AddRealTimeMsgs(msg7);
            msg7.Content = string.Format("{0}({1})", sensorH.Value, sensorH.Unit);
            if (!condition6.IsTrue(sensorH.Value))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "V4阀连接错误！"));
                return result;
            }

            //V2 V3 VOUT 打开
            if (!item.GetDevice("P21_CM").SetV2V3VOUTToOpen())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V2、V3、V打开失败！"));
                return result;
            }
            System.Threading.Thread.Sleep(5000);
            //关闭所有电磁阀
            if (!item.GetDevice("P21_CM").SetAllToClose())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "关闭所有电磁阀失败！"));
                return result;
            }
            #endregion
            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }
            #region
            //V1 VIN 打开
            RealTimeMsg msg8 = new RealTimeMsg("V1、VIN ");
            item.AddRealTimeMsgs(msg8);
            msg8.Content = "打开";
            if (!item.GetDevice("P21_CM").SetV1VINToOpen())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V1、VIN打开失败！"));
                return result;
            }

            //V11、V15打开，高压输入
            RealTimeMsg msg9 = new RealTimeMsg("V11、V15 ");
            item.AddRealTimeMsgs(msg9);
            msg9.Content = "打开";
            if (!item.GetDevice("P21_CM_T").SetV11On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V11关闭失败！"));
                return result;
            }
            if (!item.GetDevice("P21_CM_T").SetV15On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V15关闭失败！"));
                return result;
            }

            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                if (condition4.IsTrue(sensor2.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > parameter0.Value)
                {
                    break;
                }
            }
            watch.Stop();

            if (!condition4.IsTrue(sensor2.Value))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "高压输入超时！"));
                return result;
            }
            //V11、15关闭 
            msg9.Content = "关闭";
            if (!item.GetDevice("P21_CM_T").SetV11Off())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V11关闭失败！"));
                return result;
            }
            if (!item.GetDevice("P21_CM_T").SetV15Off())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V15关闭失败！"));
                return result;
            }

            RealTimeMsg msg10 = new RealTimeMsg("计时");
            item.AddRealTimeMsgs(msg10);
            //延时5秒
            for (int i = 0; i <= parameter1.Value; i++)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg10.Content = i + "秒";
                System.Threading.Thread.Sleep(1000);
            }
            //读取高压压力模块的值

            msg10.Name = "高压压力模块)";
            msg10.Content = string.Format("{0}({1})", sensorH.Value, sensorH.Unit);

            if (!condition5.IsTrue(Math.Abs(sensorH.Value - sensor2.Value)))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "V1或VIN阀连接错误！"));
                return result;
            }

            //V6打开
            RealTimeMsg msg11 = new RealTimeMsg("V6");
            item.AddRealTimeMsgs(msg11);
            msg11.Content = "打开";
            if (!item.GetDevice("P21_CM").SetV6OpenState(true))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V6打开失败！"));
                return result;
            }

            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                if (condition6.IsTrue(sensorH.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > 10)
                {
                    break;
                }
            }
            watch.Stop();
            System.Threading.Thread.Sleep(1000);
            RealTimeMsg msg12 = new RealTimeMsg("高压压力模块");
            item.AddRealTimeMsgs(msg12);
            msg12.Content = string.Format("{0}({1})", sensorH.Value, sensorH.Unit);
            if (!condition7.IsTrue(sensorH.Value))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "V6阀连接错误！"));
                return result;
            }
            #endregion

            return result;

        }
        finally
        {
            item.GetDevice("P21_CM_T").SafeExit();
            item.GetDevice("P21_CM").SafeExit();
            timer1.Stop();
            timer1.Dispose();
        }


    }

    /// <summary>
    /// 阀连接性测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestValue_H(dynamic item)
    {

        //数据采集定时器
        System.Timers.Timer timer1 = new System.Timers.Timer();

        //定义返回类型
        Result<List<DataBase>> result = new Result<List<DataBase>>(true);
        List<DataBase> rData = new List<DataBase>() { };
        result.Data = rData;


        ValueData sensor1 = item.DataBase["sensor1"];
        ValueData sensor2 = item.DataBase["sensor2"];
        ValueData sensor3 = item.DataBase["sensor3"];

        BooleanData V11 = item.DataBase["V11"];
        BooleanData V12 = item.DataBase["V12"];
        BooleanData V13 = item.DataBase["V13"];
        BooleanData V14 = item.DataBase["V14"];
        BooleanData V15 = item.DataBase["V15"];
        BooleanData V16 = item.DataBase["V16"];

        BooleanData V1 = item.DataBase["V1"];
        BooleanData V2 = item.DataBase["V2"];
        BooleanData V3 = item.DataBase["V3"];
        BooleanData V4 = item.DataBase["V4"];
        BooleanData V5 = item.DataBase["V5"];
        BooleanData V6 = item.DataBase["V6"];
        BooleanData V8 = item.DataBase["V8"];
        ValueData VC = item.DataBase["VC"];

        ValueData sensorR = item.DataBase["sensorR"];
        ValueData sensorH = item.DataBase["sensorH"];
        ValueData sensorL = item.DataBase["sensorL"];

        ValueData sensorP = item.DataBase["sensorP"];
        ValueData sensorN = item.DataBase["sensorN"];

        ValueData sensorA = item.DataBase["sensorA"];
        //清空实时信息
        item.ClearRealTimeMsgs();

        //获取条件参数
        ValueParameter parameter0;
        ValueParameter parameter1;
        try
        {
            parameter0 = item.Parameters[0] as ValueParameter;
            parameter1 = item.Parameters[1] as ValueParameter;
        }
        catch
        {
            result.AddTestErrMsgs(ErrMsg._10001);//添加错误信息
            return result;
        }

        //获取条件
        ValueCondition condition0;
        ValueCondition condition1;
        ValueCondition condition2;
        ValueCondition condition3;

        try
        {
            condition0 = item.Conditions[0] as ValueCondition;
            condition1 = item.Conditions[1] as ValueCondition;
            condition2 = item.Conditions[2] as ValueCondition;
            condition3 = item.Conditions[3] as ValueCondition;
        }
        catch
        {
            result.AddTestErrMsgs(ErrMsg._10002);//添加错误信息
            return result;
        }


        try
        {
            //数据采集
            timer1.Elapsed += (s, e) =>
            {
                item.GetDevice("P21_CM_T").SetDataBase(item.DataBase);
                item.GetDevice("P21_CM").SetDataBase(item.DataBase);
            };
            timer1.Interval = 500;
            timer1.Start();

            System.Diagnostics.Stopwatch watch = new System.Diagnostics.Stopwatch();

            #region
            System.Threading.Thread.Sleep(1000);
            while (item.GetDevice("P21_CM").IsScanning && item.GetDevice("P21_CM").sensorR == 0)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
            }
            #endregion
            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }
            #region
            //切换至低量程
            RealTimeMsg msg0 = new RealTimeMsg("切换量程模块");
            item.AddRealTimeMsgs(msg0);
            msg0.ReStart();
            if (!item.GetDevice("P21_CM").SetControlHPressureRangeModel())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "切换至高量程模块失败！"));
                return result;
            }

            System.Threading.Thread.Sleep(1000);

            while (item.GetDevice("P21_CM").IsRangeSwapping)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg0.Tick();
                System.Threading.Thread.Sleep(1000);
            }

            double low, up, span;
            if (!item.GetDevice("P21_CM").GetControlHPressureRange(out low, out up))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "获取高控制量程失败！"));
                return result;
            }
            span = up - low;
            msg0.Content = string.Format("{0}({1}~{2})kPa", "L", low, up);



            ValueCondition condition4 = new ValueCondition();
            condition4.Value = condition1.Value * span;
            condition4.Operator = condition1.Operator;
            condition4.Unit = "kPa";

            ValueCondition condition5 = new ValueCondition();
            condition5.Value = condition3.Value * span;
            condition5.Operator = condition3.Operator;
            condition5.Unit = "kPa";

            RangeCondition condition6 = new RangeCondition();
            condition6.Lower = -1;
            condition6.Upper = 1;
            condition6.Unit = "kPa";

            #endregion
            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }
            #region
            //V4关闭
            RealTimeMsg msg1000 = new RealTimeMsg("V4");
            item.AddRealTimeMsgs(msg1000);
            msg1000.Content = "关闭";
            if (!item.GetDevice("P21_CM").SetV4OpenState(false))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V4关闭失败！"));
                return result;
            }
            System.Threading.Thread.Sleep(1000);
            //V2 V3 VOUT 开启
            RealTimeMsg msg1 = new RealTimeMsg("V2、V3、VOUT");
            item.AddRealTimeMsgs(msg1);
            msg1.Content = "打开";
            if (!item.GetDevice("P21_CM").SetV2V3VOUTToOpen())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V2、V3、VOUT打开失败！"));
                return result;
            }

            //V13通电 真空输入
            RealTimeMsg msg2 = new RealTimeMsg("V13");
            item.AddRealTimeMsgs(msg2);
            msg2.Content = "打开";
            if (!item.GetDevice("P21_CM_T").SetV13On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V13打开失败！"));
                return result;
            }
            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                if (condition0.IsTrue(sensor1.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > parameter0.Value)
                {
                    break;
                }
            }
            watch.Stop();

            if (!condition0.IsTrue(sensor1.Value))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "真空输入超时！"));
                return result;
            }
            //V13关闭
            msg2.Content = "关闭";
            if (!item.GetDevice("P21_CM_T").SetV13Off())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V13关闭失败！"));
                return result;
            }

            RealTimeMsg msg3 = new RealTimeMsg("计时");
            item.AddRealTimeMsgs(msg3);
            //延时5秒
            for (int i = 0; i <= parameter1.Value; i++)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg3.Content = i + "秒";
                System.Threading.Thread.Sleep(1000);
            }
            //读取高压压力模块的值
            msg3.Name = "高压压力模块";
            msg3.Content = string.Format("{0}({1})", sensorH.Value, sensorH.Unit);

            if (!condition2.IsTrue(Math.Abs(sensorH.Value - sensor1.Value)))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "V3或VOUT阀连接错误！"));
                return result;
            }


            //V2 V3 VOUT 关闭
            RealTimeMsg msg5 = new RealTimeMsg("V2、V3、VOUT");
            item.AddRealTimeMsgs(msg5);
            msg5.Content = "关闭";
            if (!item.GetDevice("P21_CM").SetV2V3VOUTToClose())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V2、V3、VOUT关闭失败！"));
                return result;
            }

            //V4打开
            RealTimeMsg msg6 = new RealTimeMsg("V4");
            item.AddRealTimeMsgs(msg6);
            msg6.Content = "打开";
            if (!item.GetDevice("P21_CM").SetV4OpenState(true))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V4打开失败！"));
                return result;
            }

            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                if (condition6.IsTrue(sensorH.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > 5)
                {
                    break;
                }
            }
            watch.Stop();

            RealTimeMsg msg7 = new RealTimeMsg("高压压力模块");
            item.AddRealTimeMsgs(msg7);
            msg7.Content = string.Format("{0}({1})", sensorH.Value, sensorH.Unit);
            if (!condition6.IsTrue(sensorH.Value))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "V4阀连接错误！"));
                return result;
            }

            //V2 V3 VOUT 打开
            if (!item.GetDevice("P21_CM").SetV2V3VOUTToOpen())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V2、V3、V打开失败！"));
                return result;
            }
            System.Threading.Thread.Sleep(5000);
            //关闭所有电磁阀
            if (!item.GetDevice("P21_CM").SetAllToClose())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "关闭所有电磁阀失败！"));
                return result;
            }
            #endregion
            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }
            #region
            //V1 VIN 打开
            RealTimeMsg msg8 = new RealTimeMsg("V1、VIN ");
            item.AddRealTimeMsgs(msg8);
            msg8.Content = "打开";
            if (!item.GetDevice("P21_CM").SetV1VINToOpen())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V1、VIN打开失败！"));
                return result;
            }

            //V11、V15打开，高压输入
            RealTimeMsg msg9 = new RealTimeMsg("V11、V15 ");
            item.AddRealTimeMsgs(msg9);
            msg9.Content = "打开";
            if (!item.GetDevice("P21_CM_T").SetV11On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V11关闭失败！"));
                return result;
            }
            if (!item.GetDevice("P21_CM_T").SetV15On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V15关闭失败！"));
                return result;
            }

            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                if (condition4.IsTrue(sensor2.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > parameter0.Value)
                {
                    break;
                }
            }
            watch.Stop();

            if (!condition4.IsTrue(sensor2.Value))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "高压输入超时！"));
                return result;
            }
            //V11、15关闭 
            msg9.Content = "关闭";
            if (!item.GetDevice("P21_CM_T").SetV11Off())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V11关闭失败！"));
                return result;
            }
            if (!item.GetDevice("P21_CM_T").SetV15Off())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V15关闭失败！"));
                return result;
            }

            RealTimeMsg msg10 = new RealTimeMsg("计时");
            item.AddRealTimeMsgs(msg10);
            //延时5秒
            for (int i = 0; i <= parameter1.Value; i++)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg10.Content = i + "秒";
                System.Threading.Thread.Sleep(1000);
            }
            //读取高压压力模块的值

            msg10.Name = "高压压力模块)";
            msg10.Content = string.Format("{0}({1})", sensorH.Value, sensorH.Unit);

            if (!condition5.IsTrue(Math.Abs(sensorH.Value - sensor2.Value)))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "V1或VIN阀连接错误！"));
                return result;
            }

            //V6打开
            RealTimeMsg msg11 = new RealTimeMsg("V6");
            item.AddRealTimeMsgs(msg11);
            msg11.Content = "打开";
            if (!item.GetDevice("P21_CM").SetV6OpenState(true))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V6打开失败！"));
                return result;
            }

            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                if (condition6.IsTrue(sensorH.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > 5)
                {
                    break;
                }
            }
            watch.Stop();

            RealTimeMsg msg12 = new RealTimeMsg("高压压力模块");
            item.AddRealTimeMsgs(msg12);
            msg12.Content = string.Format("{0}({1})", sensorH.Value, sensorH.Unit);
            if (!condition6.IsTrue(sensorH.Value))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "V6阀连接错误！"));
                return result;
            }
            #endregion

            return result;

        }
        finally
        {
            item.GetDevice("P21_CM_T").SafeExit();
            item.GetDevice("P21_CM").SafeExit();
            timer1.Stop();
            timer1.Dispose();
        }


    }
    /// <summary>
    /// 阀连接性测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestValue_D(dynamic item)
    {

        //数据采集定时器
        System.Timers.Timer timer1 = new System.Timers.Timer();

        //定义返回类型
        Result<List<DataBase>> result = new Result<List<DataBase>>(true);
        List<DataBase> rData = new List<DataBase>() { };
        result.Data = rData;


        ValueData sensor1 = item.DataBase["sensor1"];
        ValueData sensor2 = item.DataBase["sensor2"];
        ValueData sensor3 = item.DataBase["sensor3"];

        BooleanData V11 = item.DataBase["V11"];
        BooleanData V12 = item.DataBase["V12"];
        BooleanData V13 = item.DataBase["V13"];
        BooleanData V14 = item.DataBase["V14"];
        BooleanData V15 = item.DataBase["V15"];
        BooleanData V16 = item.DataBase["V16"];

        BooleanData V1 = item.DataBase["V1"];
        BooleanData V2 = item.DataBase["V2"];
        BooleanData V3 = item.DataBase["V3"];
        BooleanData V4 = item.DataBase["V4"];
        BooleanData V5 = item.DataBase["V5"];
        BooleanData V6 = item.DataBase["V6"];
        BooleanData V8 = item.DataBase["V8"];
        ValueData VC = item.DataBase["VC"];

        ValueData sensorR = item.DataBase["sensorR"];
        ValueData sensorH = item.DataBase["sensorH"];
        ValueData sensorL = item.DataBase["sensorL"];

        ValueData sensorP = item.DataBase["sensorP"];
        ValueData sensorN = item.DataBase["sensorN"];

        ValueData sensorA = item.DataBase["sensorA"];
        //清空实时信息
        item.ClearRealTimeMsgs();

        //获取条件参数
        ValueParameter parameter0;
        ValueParameter parameter1;
        try
        {
            parameter0 = item.Parameters[0] as ValueParameter;
            parameter1 = item.Parameters[1] as ValueParameter;
        }
        catch
        {
            result.AddTestErrMsgs(ErrMsg._10001);//添加错误信息
            return result;
        }

        //获取条件
        ValueCondition condition0;
        ValueCondition condition1;
        ValueCondition condition2;
        ValueCondition condition3;

        try
        {
            condition0 = item.Conditions[0] as ValueCondition;
            condition1 = item.Conditions[1] as ValueCondition;
            condition2 = item.Conditions[2] as ValueCondition;
            condition3 = item.Conditions[3] as ValueCondition;
        }
        catch
        {
            result.AddTestErrMsgs(ErrMsg._10002);//添加错误信息
            return result;
        }


        try
        {
            //数据采集
            timer1.Elapsed += (s, e) =>
            {
                item.GetDevice("P21_CM_T").SetDataBase(item.DataBase);
                item.GetDevice("P21_CM").SetDataBase(item.DataBase);
            };
            timer1.Interval = 500;
            timer1.Start();

            System.Diagnostics.Stopwatch watch = new System.Diagnostics.Stopwatch();

            #region
            System.Threading.Thread.Sleep(1000);
            while (item.GetDevice("P21_CM").IsScanning && item.GetDevice("P21_CM").sensorR == 0)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
            }
            #endregion
            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }
            #region
            //切换至低量程
            RealTimeMsg msg0 = new RealTimeMsg("切换量程模块");
            item.AddRealTimeMsgs(msg0);
            msg0.ReStart();
            if (!item.GetDevice("P21_CM").SetControlLPressureRangeModel())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "切换至低量程模块失败！"));
                return result;
            }

            System.Threading.Thread.Sleep(1000);

            while (item.GetDevice("P21_CM").IsRangeSwapping)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg0.Tick();
                System.Threading.Thread.Sleep(1000);
            }

            double low, up, span;
            if (!item.GetDevice("P21_CM").GetControlLPressureRange(out low, out up))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "获取低控制量程失败！"));
                return result;
            }
            span = up - low;
            msg0.Content = string.Format("{0}({1}~{2})kPa", "L", low, up);



            ValueCondition condition4 = new ValueCondition();
            condition4.Value = condition1.Value * span;
            condition4.Operator = condition1.Operator;
            condition4.Unit = "kPa";

            ValueCondition condition5 = new ValueCondition();
            condition5.Value = condition3.Value * span;
            condition5.Operator = condition3.Operator;
            condition5.Unit = "kPa";

            RangeCondition condition6 = new RangeCondition();
            condition6.Lower = -1;
            condition6.Upper = 1;
            condition6.Unit = "kPa";

            #endregion
            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }
            #region
            //V4关闭
            RealTimeMsg msg1000 = new RealTimeMsg("V4");
            item.AddRealTimeMsgs(msg1000);
            msg1000.Content = "关闭";
            if (!item.GetDevice("P21_CM").SetV4OpenState(false))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V4关闭失败！"));
                return result;
            }
            System.Threading.Thread.Sleep(1000);
            RealTimeMsg msg1006 = new RealTimeMsg("V8");
            item.AddRealTimeMsgs(msg1006);
            if (!item.GetDevice("P21_CM").SetV8OpenState(false))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V8关闭失败！"));
                return result;
            }
            msg1006.Content = "关闭";
            System.Threading.Thread.Sleep(1000);
            //V2 V3 VOUT 开启
            RealTimeMsg msg1 = new RealTimeMsg("V2、V3、VOUT");
            item.AddRealTimeMsgs(msg1);
            msg1.Content = "打开";
            if (!item.GetDevice("P21_CM").SetV2V3VOUTToOpen())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V2、V3、VOUT打开失败！"));
                return result;
            }

            //V13通电 真空输入
            RealTimeMsg msg2 = new RealTimeMsg("V13");
            item.AddRealTimeMsgs(msg2);
            msg2.Content = "打开";
            if (!item.GetDevice("P21_CM_T").SetV13On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V13打开失败！"));
                return result;
            }
            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                if (condition0.IsTrue(sensor1.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > parameter0.Value)
                {
                    break;
                }
            }
            watch.Stop();

            if (!condition0.IsTrue(sensor1.Value))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "真空输入超时！"));
                return result;
            }
            //V13关闭
            msg2.Content = "关闭";
            if (!item.GetDevice("P21_CM_T").SetV13Off())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V13关闭失败！"));
                return result;
            }

            RealTimeMsg msg3 = new RealTimeMsg("计时");
            item.AddRealTimeMsgs(msg3);
            //延时5秒
            for (int i = 0; i <= parameter1.Value; i++)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg3.Content = i + "秒";
                System.Threading.Thread.Sleep(1000);
            }
            //读取高压压力模块的值
            msg3.Name = "高压压力模块";
            msg3.Content = string.Format("{0}({1})", sensorH.Value, sensorH.Unit);

            if (!condition2.IsTrue(Math.Abs(sensorH.Value - sensor1.Value)))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "V3或VOUT阀连接错误！"));
                return result;
            }

            //读取低压压力模块的值
            RealTimeMsg msg4 = new RealTimeMsg("低压压力模块");
            item.AddRealTimeMsgs(msg4);
            msg4.Content = string.Format("{0}({1})", sensorL.Value, sensorL.Unit);

            if (!condition2.IsTrue(Math.Abs(sensorL.Value - sensor1.Value)))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "V5阀连接错误！"));
                return result;
            }

            //VOUT 关闭
            RealTimeMsg msg5 = new RealTimeMsg("VOUT");
            item.AddRealTimeMsgs(msg5);
            msg5.Content = "关闭";
            if (!item.GetDevice("P21_CM").SetVOUTOpenState(false))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "VOUT关闭失败！"));
                return result;
            }
            //V8打开
            RealTimeMsg msg6 = new RealTimeMsg("V8");
            item.AddRealTimeMsgs(msg6);
            msg6.Content = "打开";
            if (!item.GetDevice("P21_CM").SetV8OpenState(true))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V8打开失败！"));
                return result;
            }

            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                if (condition6.IsTrue(sensorL.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > 5)
                {
                    break;
                }
            }
            watch.Stop();

            RealTimeMsg msg7 = new RealTimeMsg("低压压力模块");
            item.AddRealTimeMsgs(msg7);
            msg7.Content = string.Format("{0}({1})", sensorL.Value, sensorL.Unit);
            if (!condition6.IsTrue(sensorL.Value))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "V8阀连接错误！"));
                return result;
            }
            //V8关闭
            RealTimeMsg msg8 = new RealTimeMsg("V8");
            item.AddRealTimeMsgs(msg8);
            msg8.Content = "关闭";
            if (!item.GetDevice("P21_CM").SetV8OpenState(false))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V8关闭失败！"));
                return result;
            }
            //VOUT 打开
            RealTimeMsg msg9 = new RealTimeMsg("VOUT");
            item.AddRealTimeMsgs(msg9);
            msg9.Content = " 打开";
            if (!item.GetDevice("P21_CM").SetVOUTOpenState(true))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "VOUT 打开失败！"));
                return result;
            }


            //V4打开
            RealTimeMsg msg10 = new RealTimeMsg("V4");
            item.AddRealTimeMsgs(msg10);
            msg10.Content = "打开";
            if (!item.GetDevice("P21_CM").SetV4OpenState(true))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V4打开失败！"));
                return result;
            }

            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                if (condition6.IsTrue(sensorH.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > 5)
                {
                    break;
                }
            }
            watch.Stop();

            RealTimeMsg msg11 = new RealTimeMsg("低压压力模块");
            item.AddRealTimeMsgs(msg11);
            msg11.Content = string.Format("{0}({1})", sensorL.Value, sensorL.Unit);
            if (!condition6.IsTrue(sensorL.Value))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "V4阀连接错误！"));
                return result;
            }

            System.Threading.Thread.Sleep(5000);
            //关闭所有电磁阀
            if (!item.GetDevice("P21_CM").SetAllToClose())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "关闭所有电磁阀失败！"));
                return result;
            }
            #endregion
            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }
            #region
            //V1 VIN 打开
            RealTimeMsg msg12 = new RealTimeMsg("V1、VIN ");
            item.AddRealTimeMsgs(msg12);
            msg12.Content = "打开";
            if (!item.GetDevice("P21_CM").SetV1VINToOpen())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V1、VIN打开失败！"));
                return result;
            }

            //V16、V15打开，高压输入
            RealTimeMsg msg13 = new RealTimeMsg("V16、V15 ");
            item.AddRealTimeMsgs(msg13);
            msg13.Content = "打开";
            if (!item.GetDevice("P21_CM_T").SetV16On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V16打开失败！"));
                return result;
            }
            if (!item.GetDevice("P21_CM_T").SetV15On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V15打开失败！"));
                return result;
            }

            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                if (condition4.IsTrue(sensor2.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > parameter0.Value)
                {
                    break;
                }
            }
            watch.Stop();

            if (!condition4.IsTrue(sensor2.Value))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "高压输入超时！"));
                return result;
            }
            //V16、15关闭 
            msg13.Content = "关闭";
            if (!item.GetDevice("P21_CM_T").SetV16Off())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V16关闭失败！"));
                return result;
            }
            if (!item.GetDevice("P21_CM_T").SetV15Off())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V15关闭失败！"));
                return result;
            }

            RealTimeMsg msg14 = new RealTimeMsg("计时");
            item.AddRealTimeMsgs(msg14);
            //延时5秒
            for (int i = 0; i <= parameter1.Value; i++)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg10.Content = i + "秒";
                System.Threading.Thread.Sleep(1000);
            }
            //读取高压压力模块的值
            msg14.Name = "高压压力模块)";
            msg14.Content = string.Format("{0}({1})", sensorH.Value, sensorH.Unit);

            if (!condition5.IsTrue(Math.Abs(sensorH.Value - sensor2.Value)))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "V1或VIN阀连接错误！"));
                return result;
            }
            #endregion

            return result;

        }
        finally
        {
            item.GetDevice("P21_CM_T").SafeExit();
            item.GetDevice("P21_CM").SafeExit();
            timer1.Stop();
            timer1.Dispose();
        }


    }


    /// <summary>
    /// 进气真空传感器测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestIOSensor(dynamic item)
    {
        //数据采集定时器
        System.Timers.Timer timer1 = new System.Timers.Timer();

        //定义返回类型
        Result<List<DataBase>> result = new Result<List<DataBase>>(true);
        List<DataBase> rData = new List<DataBase>() { };
        result.Data = rData;


        ValueData sensor1 = item.DataBase["sensor1"];
        ValueData sensor2 = item.DataBase["sensor2"];
        ValueData sensor3 = item.DataBase["sensor3"];

        BooleanData V11 = item.DataBase["V11"];
        BooleanData V12 = item.DataBase["V12"];
        BooleanData V13 = item.DataBase["V13"];
        BooleanData V14 = item.DataBase["V14"];
        BooleanData V15 = item.DataBase["V15"];
        BooleanData V16 = item.DataBase["V16"];

        BooleanData V1 = item.DataBase["V1"];
        BooleanData V2 = item.DataBase["V2"];
        BooleanData V3 = item.DataBase["V3"];
        BooleanData V4 = item.DataBase["V4"];
        BooleanData V5 = item.DataBase["V5"];
        BooleanData V6 = item.DataBase["V6"];
        BooleanData V8 = item.DataBase["V8"];
        ValueData VC = item.DataBase["VC"];

        ValueData sensorR = item.DataBase["sensorR"];
        ValueData sensorH = item.DataBase["sensorH"];
        ValueData sensorL = item.DataBase["sensorL"];

        ValueData sensorP = item.DataBase["sensorP"];
        ValueData sensorN = item.DataBase["sensorN"];

        ValueData sensorA = item.DataBase["sensorA"];
        //清空实时信息
        item.ClearRealTimeMsgs();


        //获取条件
        RangeCondition condition0;
        RangeCondition condition1;
        RangeCondition condition2;
        RangeCondition condition3;
        RangeCondition condition4;
        try
        {
            condition0 = item.Conditions[0] as RangeCondition;
            condition1 = item.Conditions[1] as RangeCondition;
            condition2 = item.Conditions[2] as RangeCondition;
            condition3 = item.Conditions[3] as RangeCondition;
            condition4 = item.Conditions[4] as RangeCondition;

        }
        catch
        {
            result.AddTestErrMsgs(ErrMsg._10002);//添加错误信息
            return result;
        }


        try
        {
            //数据采集
            timer1.Elapsed += (s, e) =>
            {
                item.GetDevice("P21_CM_T").SetDataBase(item.DataBase);
                item.GetDevice("P21_CM").SetDataBase(item.DataBase);
            };
            timer1.Interval = 500;
            timer1.Start();

            System.Diagnostics.Stopwatch watch = new System.Diagnostics.Stopwatch();

            #region 数据正常上传
            System.Threading.Thread.Sleep(1000);
            while (item.GetDevice("P21_CM").IsScanning && item.GetDevice("P21_CM").sensorR == 0)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
            }
            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region 量程切换
            //切换至高量程
            RealTimeMsg msg0 = new RealTimeMsg("切换量程模块");
            item.AddRealTimeMsgs(msg0);
            msg0.Content = "H";
            if (!item.GetDevice("P21_CM").SetControlHPressureRangeModel())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "切换至高量程模块失败！"));
                return result;
            }

            System.Threading.Thread.Sleep(1000);

            while (item.GetDevice("P21_CM").IsRangeSwapping)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg0.Tick();
                System.Threading.Thread.Sleep(1000);
            }

            double low, up, span;
            if (!item.GetDevice("P21_CM").GetControlHPressureRange(out low, out up))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "获取高控制量程失败！"));
                return result;
            }
            span = up - low;
            msg0.Content = string.Format("{0}({1}~{2})kPa", "H", low, up);

            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region 判断大气压
            //读取大气压值
            RealTimeMsg msg100 = new RealTimeMsg("大气压值");
            msg100.Content = string.Format("{0}({1})", sensorA.Value, sensorA.Unit);

            if (!condition1.IsTrue(sensorA.Value))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "大气压异常"));
                return result;
            }


            #endregion

            #region
            //V4关闭
            RealTimeMsg msg1000 = new RealTimeMsg("V4");
            item.AddRealTimeMsgs(msg1000);
            msg1000.Content = "关闭";
            if (!item.GetDevice("P21_CM").SetV4OpenState(false))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V4关闭失败！"));
                return result;
            }
            System.Threading.Thread.Sleep(1000);
            //V2 V3 VOUT 开启
            RealTimeMsg msg1 = new RealTimeMsg("V2、V3、VOUT");
            item.AddRealTimeMsgs(msg1);
            msg1.Content = "打开";
            if (!item.GetDevice("P21_CM").SetV2V3VOUTToOpen())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V2、V3、VOUT打开失败！"));
                return result;
            }

            //V4打开
            RealTimeMsg msg2 = new RealTimeMsg("V4");
            item.AddRealTimeMsgs(msg2);
            msg2.Content = "打开";
            if (!item.GetDevice("P21_CM").SetV4OpenState(true))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V4打开失败！"));
                return result;
            }

            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                if (condition0.IsTrue(sensorH.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > 5)
                {
                    break;
                }
            }
            watch.Stop();


            //读取高压压力模块的值
            RealTimeMsg msg3 = new RealTimeMsg("高压压力模块");
            msg3.Content = string.Format("{0}({1})", sensorH.Value, sensorH.Unit);

            if (!condition0.IsTrue(sensorH.Value))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "负压排空失败"));
                return result;
            }

            //读取真空传感器的值
            RealTimeMsg msg4 = new RealTimeMsg("真空传感器");
            item.AddRealTimeMsgs(msg4);
            msg4.Content = string.Format("{0}({1})", sensorN.Value, sensorN.Unit);

            if (!condition2.IsTrue(sensorN.Value))
            {
                if (condition4.IsTrue(sensorN.Value))
                {
                    msg4.Content += "核对控制板是否进行过校准";
                }
                else
                {
                    msg4.Content += "异常";
                    result.AddTestErrMsgs(new ErrMsg(30005, "真空压力传感器异常！"));
                    return result;
                }
            }
            else
            {
                msg4.Content += "正常";
            }

            //关闭所有电磁阀
            RealTimeMsg msg5 = new RealTimeMsg("所有电磁阀");
            item.AddRealTimeMsgs(msg5);
            msg5.Content = "关闭";
            if (!item.GetDevice("P21_CM").SetAllToClose())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "关闭所有电磁阀失败！"));
                return result;
            }
            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region
            //V1 VIN 打开
            RealTimeMsg msg6 = new RealTimeMsg("V1、VIN ");
            item.AddRealTimeMsgs(msg6);
            msg6.Content = "打开";
            if (!item.GetDevice("P21_CM").SetV1VINToOpen())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V1、VIN打开失败！"));
                return result;
            }

            //V6打开
            RealTimeMsg msg7 = new RealTimeMsg("V6");
            item.AddRealTimeMsgs(msg7);
            msg7.Content = "打开";
            if (!item.GetDevice("P21_CM").SetV6OpenState(true))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V6打开失败！"));
                return result;
            }

            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                if (condition0.IsTrue(sensorH.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > 5)
                {
                    break;
                }
            }
            watch.Stop();


            //读取高压压力模块的值
            RealTimeMsg msg8 = new RealTimeMsg("高压压力模块");
            msg8.Content = string.Format("{0}({1})", sensorH.Value, sensorH.Unit);

            if (!condition0.IsTrue(sensorH.Value))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "正压排空失败！"));
                return result;
            }

            //读取进气传感器的值
            RealTimeMsg msg9 = new RealTimeMsg("进气传感器");
            item.AddRealTimeMsgs(msg9);
            msg9.Content = string.Format("{0}({1})", sensorP.Value, sensorP.Unit);

            if (!condition3.IsTrue(sensorP.Value))
            {
                if (condition4.IsTrue(sensorP.Value))
                {
                    msg9.Content += "核对控制板是否进行过校准";
                }
                else
                {
                    msg4.Content += "异常";
                    result.AddTestErrMsgs(new ErrMsg(30005, "进气压力传感器异常！"));
                    return result;
                }
            }
            else
            {
                msg4.Content += "正常";
            }
            #endregion

            return result;
        }
        finally
        {
            item.GetDevice("P21_CM_T").SafeExit();
            item.GetDevice("P21_CM").SafeExit();
            timer1.Stop();
            timer1.Dispose();
        }

    }

