            else
            {
                msg4.Content += "正常";
            }

            //关闭所有电磁阀
            RealTimeMsg msg5 = new RealTimeMsg("所有电磁阀");
            item.AddRealTimeMsgs(msg5);
            msg5.Content = "关闭";
            if (!item.GetDevice("P21_CM").SetAllToClose())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "关闭所有电磁阀失败！"));
                return result;
            }
            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region
            //V1 VIN 打开
            RealTimeMsg msg6 = new RealTimeMsg("V1、VIN ");
            item.AddRealTimeMsgs(msg6);
            msg6.Content = "打开";
            if (!item.GetDevice("P21_CM").SetV1VINToOpen())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V1、VIN打开失败！"));
                return result;
            }

            //V4打开
            RealTimeMsg msg7 = new RealTimeMsg("V4");
            item.AddRealTimeMsgs(msg7);
            msg7.Content = "打开";
            if (!item.GetDevice("P21_CM").SetV4OpenState(true))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V4打开失败！"));
                return result;
            }

            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);
                if (condition0.IsTrue(sensorH.Value))
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > 5)
                {
                    break;
                }
            }
            watch.Stop();


            //读取高压压力模块的值
            RealTimeMsg msg8 = new RealTimeMsg("高压压力模块");
            msg8.Content = string.Format("{0}({1})", sensorH.Value, sensorH.Unit);

            if (!condition0.IsTrue(sensorH.Value))
            {
                result.AddTestErrMsgs(new ErrMsg(30005, "正压排空失败！"));
                return result;
            }

            //读取进气传感器的值
            RealTimeMsg msg9 = new RealTimeMsg("进气传感器");
            item.AddRealTimeMsgs(msg9);
            msg9.Content = string.Format("{0}({1})", sensorP.Value, sensorP.Unit);

            if (!condition3.IsTrue(sensorP.Value))
            {
                if (condition4.IsTrue(sensorP.Value))
                {
                    msg9.Content += "核对控制板是否进行过校准";
                }
                else
                {
                    msg4.Content += "异常";
                    result.AddTestErrMsgs(new ErrMsg(30005, "进气压力传感器异常！"));
                    return result;
                }
            }
            else
            {
                msg4.Content += "正常";
            }
            #endregion

            return result;
        }
        finally
        {
            item.GetDevice("P21_CM_T").SafeExit();
            item.GetDevice("P21_CM").SafeExit();
            timer1.Stop();
            timer1.Dispose();
        }

    }

    /// <summary>
    /// 进气真空传感器校准测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestPressureSensorCal(dynamic item)
    {
        //数据采集定时器
        System.Timers.Timer timer1 = new System.Timers.Timer();

        //定义返回类型
        Result<List<DataBase>> result = new Result<List<DataBase>>(true);
        List<DataBase> rData = new List<DataBase>() { };
        result.Data = rData;

        ValueData sensor1 = item.DataBase["sensor1"];
        ValueData sensor2 = item.DataBase["sensor2"];

        //清空实时信息
        item.ClearRealTimeMsgs();

        //获取条件参数
        ValueParameter parameter0;

        try
        {
            parameter0 = item.Parameters[0] as ValueParameter;
        }
        catch
        {
            result.AddTestErrMsgs(ErrMsg._10001);//添加错误信息
            return result;
        }

        //获取条件
        ValueCondition condition0;
        ValueCondition condition1;
        RangeCondition condition2;
        try
        {
            condition0 = item.Conditions[0] as ValueCondition;
            condition1 = item.Conditions[1] as ValueCondition;
            condition2 = item.Conditions[2] as RangeCondition;
        }
        catch
        {
            result.AddTestErrMsgs(ErrMsg._10002);//添加错误信息
            return result;
        }


        try
        {
            //数据采集
            timer1.Elapsed += (s, e) =>
            {
                item.GetDevice("P21_CM_T").SetDataBase(item.DataBase);
                item.GetDevice("P21_CM").SetDataBase(item.DataBase);
            };
            timer1.Interval = 500;
            timer1.Start();

            System.Diagnostics.Stopwatch watch = new System.Diagnostics.Stopwatch();



            #region 气源压力判断

            //V11、V15打开
            if (!item.GetDevice("P21_CM_T").SetV11On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V11打开失败！"));
                return result;
            }
            if (!item.GetDevice("P21_CM_T").SetV15On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V15打开失败！"));
                return result;
            }
            //V2 V13打开
            if (!item.GetDevice("P21_CM").SetV2OpenState(true))
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V2打开失败！"));
                return result;
            }
            if (!item.GetDevice("P21_CM_T").SetV13On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V13打开失败！"));
                return result;
            }

            //进气压力判断
            RealTimeMsg msg0 = new RealTimeMsg("判断正压气源压力");
            item.AddRealTimeMsgs(msg0);
            RealTimeMsg msg00 = new RealTimeMsg("判断负压气源压力");
            item.AddRealTimeMsgs(msg00);
            bool isOK1 = false, isOK2 = false;
            watch.Restart();
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(1000);

                if (!isOK1 && condition0.IsTrue(sensor2.Value))
                {
                    isOK1 = true;
                    msg0.Name = "正压气源压力";
                    msg0.Content = string.Format("{0}({1})合格", sensor2.Value, sensor2.Unit);

                    //V11、V15关闭
                    if (!item.GetDevice("P21_CM_T").SetV11Off())
                    {
                        result.AddTestErrMsgs(new ErrMsg(20005, "V11关闭失败！"));
                        return result;
                    }
                    if (!item.GetDevice("P21_CM_T").SetV15Off())
                    {
                        result.AddTestErrMsgs(new ErrMsg(20005, "V15关闭失败！"));
                        return result;
                    }
                }
                else
                {
                    if (!isOK1)
                    {
                        msg0.ContentRunning();
                    }
                }
                if (!isOK2 && condition1.IsTrue(sensor1.Value))
                {
                    isOK2 = true;
                    msg00.Name = "负压气源压力";
                    msg00.Content = string.Format("{0}({1})合格", sensor1.Value, sensor1.Unit);
                    //V2 V13关闭           
                    if (!item.GetDevice("P21_CM_T").SetV13Off())
                    {
                        result.AddTestErrMsgs(new ErrMsg(20005, "V13打开失败！"));
                        return result;
                    }
                    if (!item.GetDevice("P21_CM").SetV2OpenState(false))
                    {
                        result.AddTestErrMsgs(new ErrMsg(20005, "V2打开失败！"));
                        return result;
                    }
                }
                else
                {
                    if (!isOK2)
                    {
                        msg00.ContentRunning();
                    }
                }
                if (isOK1 && isOK2)
                {
                    break;
                }
                if (TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalSeconds > parameter0.Value)
                {
                    break;
                }
            }
            watch.Stop();

            if (!isOK1)
            {
                msg0.Name = "正压气源压力";
                msg0.Content = string.Format("{0}({1})不合格,请调整气源压力!", sensor2.Value, sensor2.Unit);
                result.AddTestErrMsgs(new ErrMsg(30005, "正压气源压力不合格"));
            }
            if (!isOK2)
            {
                msg00.Name = "负压气源压力";
                msg00.Content = string.Format("{0}({1})不合格,请调整气源压力!", sensor1.Value, sensor1.Unit);
                result.AddTestErrMsgs(new ErrMsg(30005, "负压气源压力不合格"));
            }

            if (!(isOK1 && isOK2))
            {
                return result;
            }

            #endregion 气源压力判断

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region
            //开始校准
            RealTimeMsg msg1 = new RealTimeMsg("进气、真空传感器");
            item.AddRealTimeMsgs(msg1);
            msg1.Content = "开始校准";

            //获取校准进程
            int process = 255;

            RealTimeMsg msg2 = new RealTimeMsg("校准进程");
            item.AddRealTimeMsgs(msg2);
            msg2.Content = process.ToString();

            while (process == 255 || process == 21)
            {
                if (!item.GetDevice("P21_CM").StartPressureSensorCal())
                {
                    result.AddTestErrMsgs(new ErrMsg(20005, "进气、真空传感器开始校准失败！"));
                    return result;
                }
                System.Threading.Thread.Sleep(2000);
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }

                if (item.GetDevice("P21_CM").GetPressureSensorCalProcess(out process))
                {
                    msg2.Content = process.ToString();
                }
            }


            //打开V11
            if (!item.GetDevice("P21_CM_T").SetV11On())
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "V11打开失败！"));
                return result;
            }
            CalState state = new CalState();
            state.CalFunction = CalFunction.PressureSensor;

            RealTimeMsg msg3 = new RealTimeMsg("设定压力");
            item.AddRealTimeMsgs(msg3);

            RealTimeMsg msg4 = new RealTimeMsg("进气阀控制量");
            item.AddRealTimeMsgs(msg4);

            RealTimeMsg msg5 = new RealTimeMsg("放气阀控制量");
            item.AddRealTimeMsgs(msg5);

            while (!(process == 21 || process == 255))
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                System.Threading.Thread.Sleep(500);
                if (process == 1)
                {
                    if (!condition0.IsTrue(sensor1.Value))
                    {
                        if (!item.GetDevice("P21_CM_T").GetV15())
                        {
                            //V15打开
                            RealTimeMsg msg6 = new RealTimeMsg("V15 ");
                            item.AddRealTimeMsgs(msg6);
                            msg6.Content = "打开";
                            if (!item.GetDevice("P21_CM_T").SetV15On())
                            {
                                result.AddTestErrMsgs(new ErrMsg(20005, "V15打开失败！"));
                                return result;
                            }
                        }
                    }
                    else
                    {
                        if (item.GetDevice("P21_CM_T").GetV15())
                        {
                            //V15关闭
                            RealTimeMsg msg7 = new RealTimeMsg("V15 ");
                            item.AddRealTimeMsgs(msg7);
                            msg7.Content = "关闭";

                            if (!item.GetDevice("P21_CM_T").SetV15Off())
                            {
                                result.AddTestErrMsgs(new ErrMsg(20005, "V15关闭失败！"));
                                return result;
                            }
                        }
                    }


                }
                else if (process == 2 || process == 3 || process == 4 || process == 5)
                {
                    if (item.GetDevice("P21_CM_T").GetV15())
                    {
                        //V15关闭
                        RealTimeMsg msg8 = new RealTimeMsg("V15 ");
                        item.AddRealTimeMsgs(msg8);
                        msg8.Content = "关闭";
                        if (!item.GetDevice("P21_CM_T").SetV15Off())
                        {
                            result.AddTestErrMsgs(new ErrMsg(20005, "V15关闭失败！"));
                            return result;
                        }
                    }
                }
                else if (process == 6)
                {
                    if (!condition1.IsTrue(sensor2.Value))
                    {
                        if (!item.GetDevice("P21_CM_T").GetV13())
                        {
                            //V13打开
                            RealTimeMsg msg9 = new RealTimeMsg("V13 ");
                            item.AddRealTimeMsgs(msg9);
                            msg9.Content = "打开";
                            if (!item.GetDevice("P21_CM_T").SetV13On())
                            {
                                result.AddTestErrMsgs(new ErrMsg(20005, "V13打开失败！"));
                                return result;
                            }
                        }
                    }
                    else
                    {
                        if (item.GetDevice("P21_CM_T").GetV13())
                        {
                            //V13关闭
                            RealTimeMsg msg10 = new RealTimeMsg("V13");
                            item.AddRealTimeMsgs(msg10);
                            msg10.Content = "关闭";
                            if (!item.GetDevice("P21_CM_T").SetV13Off())
                            {
                                result.AddTestErrMsgs(new ErrMsg(20005, "V13关闭失败！"));
                                return result;
                            }
                        }
                    }

                }
                else if (process == 7 || process == 8 || process == 9 || process == 10)
                {
                    if (item.GetDevice("P21_CM_T").GetV13())
                    {
                        //V13关闭
                        RealTimeMsg msg11 = new RealTimeMsg("V13");
                        item.AddRealTimeMsgs(msg11);
                        msg11.Content = "关闭";
                        if (!item.GetDevice("P21_CM_T").SetV13Off())
                        {
                            result.AddTestErrMsgs(new ErrMsg(20005, "V13关闭失败！"));
                            return result;
                        }
                    }
                }
                if (item.GetDevice("P21_CM").GetCalState(state))
                {
                    process = state.TuneProcess;
                    msg2.Content = process.ToString();
                    msg3.Content = state.SetPressure.ToString();
                    msg4.Content = state.IValueControl.ToString();
                    msg5.Content = state.OValueControl.ToString();
                }


            }
            if (process == 21)
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "校准被异常终止！"));
                return result;
            }
            if (process == 255)
            {
                RealTimeMsg msg12 = new RealTimeMsg("进气、真空传感器");
                item.AddRealTimeMsgs(msg12);
                msg12.Content = "校准完成";
            }
            else
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "校准未能正常完成！"));
                return result;
            }
            //写校准
            if (item.GetDevice("P21_CM").WritePressureSensorSetCalRecord())
            {
                RealTimeMsg msg13 = new RealTimeMsg("进气、真空传感器");
                item.AddRealTimeMsgs(msg13);
                msg13.Content = "写校准日期完成";
            }
            else
            {
                result.AddTestErrMsgs(new ErrMsg(20005, "写校准日期失败！"));
                return result;
            }
            #endregion

            return result;
        }
        finally
        {
            item.GetDevice("P21_CM").StopPressureSensorCal();
            System.Threading.Thread.Sleep(3000);
            item.GetDevice("P21_CM_T").SafeExit();
            item.GetDevice("P21_CM").SafeExit();
            timer1.Stop();
            timer1.Dispose();
        }

    }

