    #region 电池测试
    /// <summary>
    /// 充电口电压
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestBetteryChargeInterfaceVoltage(dynamic item)
    {
        Result<TextData> result = new Result<TextData>(true);
        TextData rData = new TextData("充电口电压");
        result.Data = rData;

        //获取条件
        if (item.Conditions == null)
        {
            result.AddTestErrMsgs(new ErrMsg(10002, "条件为空"));//添加错误信息
            return result;
        }
        ValueCondition condition = item.Conditions[0] as ValueCondition;

        item.ClearRealTimeMsgs();

        System.Threading.Thread.Sleep(500);



        RealTimeMsg msg1 = new RealTimeMsg();
        msg1.Content = "读取充电口电压";
        item.AddRealTimeMsgs(msg1);

        if (!item.GetDevice("P21_Ba_T").OpenDisch())
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "断开充电口失败"));
            return result;
        }
        System.Threading.Thread.Sleep(500);
        Voltage vol = new Voltage(0, VoltageUnit.V);
        if (!item.GetDevice("P21_Ba_T").GetChargeInterfaceVoltage(out vol))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "读取充电口电压失败"));
            return result;
        }

        msg1.Name = "充电口电压";
        msg1.Content = vol.ToString();
        rData.Value = vol.ToString();

        if (!condition.IsTrue(vol.Value))
        {
            result.AddTestErrMsgs(new ErrMsg(30004, "充电口电压超出指定范围"));
        }
        return result;
    }
