    /// <summary>
    /// 电池温度
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestBetteryTemperature(dynamic item)
    {
        Result<TextData> result = new Result<TextData>(true);
        TextData rData = new TextData("电池温度");
        result.Data = rData;

        //获取条件
        if (item.Conditions == null)
        {
            result.AddTestErrMsgs(new ErrMsg(10002, "条件为空"));//添加错误信息
            return result;
        }
        ValueCondition condition1 = item.Conditions[0] as ValueCondition;
        ValueCondition condition2 = item.Conditions[1] as ValueCondition;

        item.ClearRealTimeMsgs();

        System.Threading.Thread.Sleep(500);

        RealTimeMsg msg1 = new RealTimeMsg();
