    /// <summary>
    /// 电池充放电次数
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestBetteryCycle(dynamic item)
    {
        Result<TextData> result = new Result<TextData>(true);
        TextData rData = new TextData("电池充放电次数");
        result.Data = rData;

        //获取条件
        if (item.Conditions == null)
        {
            result.AddTestErrMsgs(new ErrMsg(10002, "条件为空"));//添加错误信息
            return result;
        }
        ValueCondition condition = item.Conditions[0] as ValueCondition;


        item.ClearRealTimeMsgs();

        System.Threading.Thread.Sleep(500);

        RealTimeMsg msg1 = new RealTimeMsg();
        msg1.Content = "读取电池充放电次数";
        item.AddRealTimeMsgs(msg1);
        string count = string.Empty;
        if (!item.GetDevice("P21_Ba_T").GetBatteryCycle(out count))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "读取电池充放电次数失败"));
            return result;
        }

        int value = 0;
        msg1.Name = "电池充放电次数";
        if (!int.TryParse(count, out value))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "指令返回值不为数字"));
            return result;

        }
        msg1.Content = value + "次";
        rData.Value = value + "次";

        if (!condition.IsTrue(value))
        {
            result.AddTestErrMsgs(new ErrMsg(30004, "电池电池充放电次数超出指定范围"));
        }
        return result;
    }
