        if (!condition.IsTrue(cur.Value))
        {
            result.AddTestErrMsgs(new ErrMsg(30004, "电池电压超出指定范围"));
        }
        return result;
    }
    /// <summary>
    /// 电池校准
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestBatteryElectricCal(dynamic item)
    {
        Result<TextData> result = new Result<TextData>(true);
        TextData rData = new TextData("比率差值");
        result.Data = rData;

        //获取条件
        if (item.Conditions == null)
        {
            result.AddTestErrMsgs(new ErrMsg(10002, "条件为空"));//添加错误信息
            return result;
        }
        ValueCondition condition = item.Conditions[0] as ValueCondition;
        //获取参数
        if (item.Parameters == null)
        {
            result.AddTestErrMsgs(new ErrMsg(10001, "参数为空"));
            return result;
        }
        ValueParameter parameter = item.Parameters[0] as ValueParameter;

        item.ClearRealTimeMsgs();

        System.Threading.Thread.Sleep(500);

        #region 读取电池剩余电量

        RealTimeMsg msg1 = new RealTimeMsg();
        msg1.Content = "读取电池剩余电量";
        item.AddRealTimeMsgs(msg1);
        ValueAndUnit remain = new ValueAndUnit();
        if (!item.GetDevice("P21_Ba_T").GetRemainEnergy(out remain))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "读取电池剩余电量失败"));
            return result;
        }

        msg1.Name = "电池剩余电量";
        msg1.Content = remain.ToString();
        #endregion

        #region 读取电池电量

        RealTimeMsg msg2 = new RealTimeMsg();
        msg2.Content = "读取电池电量";
        item.AddRealTimeMsgs(msg2);
        ValueAndUnit full = new ValueAndUnit();
        if (!item.GetDevice("P21_Ba_T").GetElectricQuantity(out full))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "读取电池电量失败"));
            return result;
        }

        msg2.Name = "电池电量";
        msg2.Content = full.ToString();
        #endregion

        #region 读取电池电压

        RealTimeMsg msg3 = new RealTimeMsg();
        msg3.Content = "读取电池电压";
        item.AddRealTimeMsgs(msg3);
        Voltage cur = new Voltage();
        if (!item.GetDevice("P21_Ba_T").GetBatteryVoltageChecking(out cur))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "读取电池电压失败"));
            return result;
        }

        msg3.Name = "电池电压";
        msg3.Content = cur.ToString();
        #endregion

        #region 计算比率差值
        RealTimeMsg msg4 = new RealTimeMsg("剩余电量与总电量比率");
        item.AddRealTimeMsgs(msg4);
        double data1 = remain.Value / full.Value;
        msg4.Content = data1.ToString();
        RealTimeMsg msg5 = new RealTimeMsg("电池电压与标准参数差值的七分之一");
        item.AddRealTimeMsgs(msg5);
        double data2 = ((cur.Value - parameter.Value) / 7);
        msg5.Content = (data2 * 100).ToString("f1") + "%";

        RealTimeMsg msg6 = new RealTimeMsg("比率差值");
        item.AddRealTimeMsgs(msg6);
        double resultData = Math.Abs(data1 - data2);
        msg6.Content = (resultData * 100).ToString("f1") + "%";
        #endregion

        if (!condition.IsTrue(resultData))
        {
            result.AddTestErrMsgs(new ErrMsg(30004, "比率差值超出指定范围"));
        }
        return result;
    }

    #endregion

