    /// <summary>
    /// 写入设备型号
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestDeviceWriteType(dynamic item)
    {
        Result<List<TextData>> result = new Result<List<TextData>>(true);
        List<TextData> rData = new List<TextData>() { new TextData("原设备类型"), new TextData("写入设备类型") };
        result.Data = rData;

        //控制板机型控压系数写入
        //表压、7MPa：90.5%（默认值）
        //表压、2.5MPa及以上高精度：90.5%
        //表压、2.5MPa以下高精度：95%
        //气象版：90.5%
        //2差压：95%
        //3微差压：30%
        item.ClearRealTimeMsgs();
        double setControlPanelModelParameter = 0;
        string orgDeviceMode = item.Root.DUT.DeviceMode;
        RealTimeMsg msg_SetDumpCurrent = new RealTimeMsg("获取设备类型");
        msg_SetDumpCurrent.Content += $"{orgDeviceMode}";
        item.AddRealTimeMsgs(msg_SetDumpCurrent);
        if (orgDeviceMode.Contains("AG"))
        {
            //rData[1].Value = "ConST811A-7M";
            setControlPanelModelParameter = 0.905;
        }
        else if (orgDeviceMode.Contains("AD"))
        {
            //rData[1].Value = "ConST811A-D";
            setControlPanelModelParameter = 0.95;
        }
        else if (orgDeviceMode.Contains("AAM"))
        {
            //rData[1].Value = "ConST811A-UP";
            setControlPanelModelParameter = 0.905;

        }
        else if (orgDeviceMode.Contains("AAL"))
        {
            //rData[1].Value = "ConST811A-UP";
            setControlPanelModelParameter = 0.95;
        }
        else if (orgDeviceMode.Contains("AL"))
        {
            //rData[1].Value = "ConST811A-LLP";
            setControlPanelModelParameter = 0.30;
        }
        else if (orgDeviceMode.Contains("AB"))
        {
            //rData[1].Value = "ConST811A-BP";
            setControlPanelModelParameter = 0.95;

        }
        else if (orgDeviceMode.Contains("10M"))
        {
            //rData[1].Value = "ConST811A-BP";
            //因10M设备的泵阻转电流需设置为8A，写入设备类型时，并行写入泵阻转电流。
            setControlPanelModelParameter = 0.905;
            msg_SetDumpCurrent.Content += "\r\n当前设备为10M机型,需将泵阻转电流设置为8A";
            if (!item.GetDevice("P21").SetDumpStallingCurrent())
            {
                msg_SetDumpCurrent.Content += "\r\n 泵阻转电流上限修改设置【失败】，可能会导致泵阻转电流设置异常";
            }
            if (!item.GetDevice("P21").SetDumpCurrent(8))
            {
                msg_SetDumpCurrent.Content = "\r\n泵阻转电流设置失败，可能会影响后续控压测试。";
            }
            else
            {
                msg_SetDumpCurrent.Content += "\r\n泵阻转电流设置成功!";
            }            
            if (!item.GetDevice("P21").GetDumpCurrent(out string current))
            {
                msg_SetDumpCurrent.Content += "\r\n泵阻转电流读取失败。";
            }
            else
            {
                msg_SetDumpCurrent.Content += $"\r\n当前泵阻转电流为：{current}A";            }
            
        }
        item.GetDevice("P21").SetControlPanelModelParameter(setControlPanelModelParameter);
        double parameter = 0;
        item.GetDevice("P21").GetControlPanelModelParameter(out parameter);

        
        RealTimeMsg msg0 = new RealTimeMsg("写入后的控制板机型参数");
        item.AddRealTimeMsgs(msg0);
        msg0.Content = string.Format("参数{0},机型{1}", parameter.ToString("F4"), orgDeviceMode);



        RealTimeMsg msg2 = new RealTimeMsg();
        msg2.Content = "写入设备类型";
        item.AddRealTimeMsgs(msg2);

        if (string.IsNullOrEmpty(orgDeviceMode))
        {
            result.AddTestErrMsgs(new ErrMsg(30001, "写入的设备类型为空"));
            return result;
        }
        if (!item.GetDevice("P21").SetPrimaryDevType(orgDeviceMode))
        {
            result.AddTestErrMsgs(new ErrMsg(20001, "指令执行有问题，写入设备类型失败"));
            return result;
        }
        msg2.Name = "写入设备类型";
        msg2.Content = orgDeviceMode;


        RealTimeMsg msg3 = new RealTimeMsg();
        msg3.Content = "读取设备类型";
        item.AddRealTimeMsgs(msg3);

        string newType;
        if (!item.GetDevice("P21").GetDevType(out newType))
        {
            result.AddTestErrMsgs(new ErrMsg(20001, "指令执行有问题，读取整机设备类型失败"));
            return result;
        }
        msg3.Name = "读取设备类型";
        msg3.Content = newType;

        if (newType != orgDeviceMode)
        {
            result.AddTestErrMsgs(new ErrMsg(30003, "结果比对失败，获取的设备类型和要写入的设备类型不一致"));
        }
        return result;
    }

    /// <summary>
    /// 恢复出厂
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic FactoryRestoration(dynamic item)
    {
        Result<List<TextData>> result = new Result<List<TextData>>(true);
        RealTimeMsg msg7 = new RealTimeMsg();
        msg7.Name = "恢复出厂";
        item.AddRealTimeMsgs(msg7);
        DateTime now7 = DateTime.UtcNow;
        item.GetDevice("P21").ResetFactoryByManufactor("3721");

        RealTimeMsg msg11 = new RealTimeMsg("设备正在重新启动");
        item.AddRealTimeMsgs(msg11);
        DateTime startTime = DateTime.Now;
        while (true)
        {
            if ((DateTime.Now - startTime).TotalSeconds >= 30)
            {
                break;
            }
            System.Threading.Thread.Sleep(1000);
            msg11.ContentRunning();
        }
        startTime = DateTime.Now;
        while (!item.GetDevice("P21").Open())
        {
            if ((DateTime.Now - startTime).TotalSeconds >= 30)
            {
                msg11.Content = "设备通讯重连超时，请检查通讯线连接";
                result.AddTestErrMsgs(new ErrMsg(20001, "设备通讯重连超时，请检查通讯线连接"));
                return result;
            }
            System.Threading.Thread.Sleep(2000);
            msg11.ContentRunning();
        }
        msg11.Name = "设备重新启动";

        msg7.Content = now7.ToString();
        System.Threading.Thread.Sleep(1000);
        return result;
    }

    /// <summary>
    /// 软件版本测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestSoftVersions(dynamic item)
    {
        Result<List<TextData>> result = new Result<List<TextData>>(true);
        List<TextData> rData = new List<TextData>()
        {
            new TextData("系统版本"),
            new TextData("电测版本"),
            new TextData("控制板版本"),
            new TextData("升级后的控制板版本"),
            new TextData("操作系统版本")
        };
        result.Data = rData;

        //获取参数
        if (item.Parameters == null)
        {
            result.AddTestErrMsgs(ErrMsg._10001);
            return result;
        }
        TextParameter parameter1 = item.Parameters[0] as TextParameter;

        item.ClearRealTimeMsgs();

        //是否检验通过
        bool isCheckPass = false;
        //主版本是否高于最新版本
        bool isGreaterHost = false;
        //电测板版本是否高于最新版本
        bool isGreaterELE = false;
        //控制板版本是否高于最新版本
        bool isGreaterCOL = false;
        //DD库版本是否高于最新版本
        bool isGreaterDD = false;

        bool isGreaterOS = false;

        #region 获取系统版本
        string version;
        if (!item.GetDevice("P21").GetVersion(out version))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "读取系统版本失败"));
            return result;
        }
        rData[0].Value = version;
        RealTimeMsg msg1 = new RealTimeMsg("系统版本");
        msg1.Content = rData[0].Value;
        item.AddRealTimeMsgs(msg1);

        VersionValidResponse response = Bots.Service.ServiceHelper.DBService.VersionValid(rData[0].Value);
        string versionSTD = response.LatestVersion;
        string versionUUD = rData[0].Value;
        switch (response.Result)
        {
            case VersionValidResult.NonStandard:
                result.AddTestErrMsgs(new ErrMsg(30003, string.Format("验证主程序版本{0}格式不规范", versionUUD)));
                break;
            case VersionValidResult.UnKnown:
                result.AddTestErrMsgs(new ErrMsg(30003, string.Format("验证主程序版本{0}未匹配到服务器版本", versionUUD)));
                break;
            case VersionValidResult.Less:
                result.AddTestErrMsgs(new ErrMsg(30003, string.Format("验证主程序版本{0}不是最新版本{1}", versionUUD, versionSTD)));
                break;
            case VersionValidResult.Equal:
                isCheckPass = true;
                break;
            case VersionValidResult.Greater:
                isGreaterHost = true;
                break;
        }

        #endregion

        #region 获取电测版本
        string coreVersion;
        isCheckPass = false;
        if (!item.GetDevice("P21").GetVersion_Electricity(out coreVersion))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "获取电测版本失败"));
            return result;
        }
        rData[1].Value = coreVersion;
        RealTimeMsg msg2 = new RealTimeMsg("电测版本");
        msg2.Content = coreVersion;
        item.AddRealTimeMsgs(msg2);


        response = Bots.Service.ServiceHelper.DBService.VersionValid(rData[1].Value);
        string versionSTDELE = response.LatestVersion;
        string versionUUDELE = rData[1].Value;
        switch (response.Result)
        {
            case VersionValidResult.NonStandard:
                result.AddTestErrMsgs(new ErrMsg(30003, string.Format("验证电测版本{0}格式不规范", versionUUDELE)));
                break;
            case VersionValidResult.UnKnown:
                result.AddTestErrMsgs(new ErrMsg(30003, string.Format("验证电测版本{0}未匹配到服务器版本", versionUUDELE)));
                break;
            case VersionValidResult.Less:
                result.AddTestErrMsgs(new ErrMsg(30003, string.Format("验证电测版本{0}不是最新版本{1}", versionUUDELE, versionSTDELE)));
                break;
            case VersionValidResult.Equal:
                isCheckPass = true;
                break;
            case VersionValidResult.Greater:
                isGreaterELE = true;
                break;
        }

        #endregion

        #region 获取控制板固件版本
        string type;
        isCheckPass = false;
        if (!item.GetDevice("P21").GetDevType(out type))
        {
            result.AddTestErrMsgs(new ErrMsg(20001, "获取整机设备类型失败"));
            return result;
        }

        //获取控制板固件版本
        string controllerVersion;
        if (!item.GetDevice("P21").GetVersion_Controller(out controllerVersion))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "获取控制板版本失败"));
            return result;
        }
        rData[2].Value = controllerVersion;
        RealTimeMsg msg3 = new RealTimeMsg("控制板版本");
        msg3.Content = rData[2].Value;
        item.AddRealTimeMsgs(msg3);

        response = Bots.Service.ServiceHelper.DBService.VersionValid(rData[2].Value);
        string versionSTDCOL = response.LatestVersion;
        string versionUUDCOL = rData[2].Value;
        switch (response.Result)
        {
            case VersionValidResult.NonStandard:
                result.AddTestErrMsgs(new ErrMsg(30003, string.Format("验证控制版本{0}格式不规范", versionUUDCOL)));
                break;
            case VersionValidResult.UnKnown:
                result.AddTestErrMsgs(new ErrMsg(30003, string.Format("验证控制版本{0}未匹配到服务器版本", versionUUDCOL)));
                break;
            case VersionValidResult.Less:
                result.AddTestErrMsgs(new ErrMsg(30003, string.Format("验证控制版本{0}不是最新版本{1}", versionUUDCOL, versionSTDCOL)));
                break;
            case VersionValidResult.Equal:
                isCheckPass = true;
                break;
            case VersionValidResult.Greater:
                isGreaterCOL = true;
                break;
        }

        #endregion

        #region 获取DD库版本
        //获取系统版本，气压1.0.0.57才支持DD库的信息
        Version Taget = new Version("1.0.0.57");
        isCheckPass = false;
        var verlist = version.Split(' ');
        Version nowver = new Version(verlist[1]);
        string ddversion = "";
        string ddversionSTD = "";
        //获取HART功能状态，关闭HART功能的设备不进行DD库校验
        bool hartIsClose = false;
        if (!item.GetDevice("P21").GetFunctionState(FunctionType.HART, out OpenCloseState hartStatus))
        {
            return result.AddTestErrMsgs(new ErrMsg(20003, "读取HART功能状态指令执行失败"));
        }
        if (hartStatus == OpenCloseState.Close)
        {
            item.AddRealTimeMsgs(new RealTimeMsg("HART功能关闭", "不进行DD库校验"));
            hartIsClose = true;
        }
        if (nowver >= Taget && !hartIsClose)
        {
            if (!item.GetDevice("P21").GetDeviceDDT(out ddversion))
            {
                return result.AddTestErrMsgs(new ErrMsg(20003, "读取DD库版本指令执行失败"));
            }
            rData[3].Value = ddversion;
            RealTimeMsg msg13 = new RealTimeMsg("DD库版本", ddversion);
            item.AddRealTimeMsgs(msg13);
            
            if (string.IsNullOrWhiteSpace(ddversion))
            {
                return result.AddTestErrMsgs(new ErrMsg(30003, "设备没有安装DD库，联系研发人员安装。"));
            }
            response = Bots.Service.ServiceHelper.DBService.VersionValidByDeviceType(ddversion, "ConST811A");
            ddversionSTD = response.LatestVersion;
            switch (response.Result)
            {
                case VersionValidResult.NonStandard:
                    result.AddTestErrMsgs(new ErrMsg(30003, string.Format("DD库版本{0}格式不规范，没有正确解析", ddversion)));
                    break;
                case VersionValidResult.UnKnown:
                    result.AddTestErrMsgs(new ErrMsg(30003, string.Format("DD库版本{0}未匹配到服务器版本，请确认服务器是否管控", ddversion)));
                    break;
                case VersionValidResult.Less:
                    result.AddTestErrMsgs(new ErrMsg(30003, $"DD库版本{ddversion}不是最新版本{response.LatestVersion}，升级到最新版本再进行测试。"));
                    break;
                case VersionValidResult.Equal:
                    isCheckPass = true;
                    break;
                case VersionValidResult.Greater:
                    isGreaterDD = true;
                    break;
            }
        }
        else
        {
            RealTimeMsg msg13 = new RealTimeMsg("DD库版本", "HART功能关闭或当前整机版本还不支持读取DD库文件版本，需要手动确认。");
            item.AddRealTimeMsgs(msg13);
        }

        #endregion

        #region 操作系统版本
        isCheckPass = false;
        RealTimeMsg msg_GetOSversion = new RealTimeMsg("操作系统版本");
        item.AddRealTimeMsgs(msg_GetOSversion);
        if (!item.GetDevice("P21").GetVersion_OS(out string osVersion))
        {
            msg_GetOSversion.Content = "读取操作系统版本指令执行失败";
            return result.AddTestErrMsgs(new ErrMsg(20003, "读取操作系统版本指令执行失败"));
        }
        msg_GetOSversion.Content =$"{osVersion}";
        rData[4].Value = osVersion;
        string osVersionSTD = "";
        response = Bots.Service.ServiceHelper.DBService.VersionValidByDeviceType(osVersion, "ConST811A");
        osVersionSTD = response.LatestVersion;
        switch (response.Result)
        {
            case VersionValidResult.NonStandard:
                result.AddTestErrMsgs(new ErrMsg(30003, string.Format("验证系统版本{0}格式不规范", osVersion)));
                break;
            case VersionValidResult.UnKnown:
                result.AddTestErrMsgs(new ErrMsg(30003, string.Format("验证系统版本{0}未匹配到服务器版本", osVersion)));
                break;
            case VersionValidResult.Less:
                result.AddTestErrMsgs(new ErrMsg(30003, string.Format("验证系统版本{0}不是最新版本{1}", osVersion, osVersionSTD)));
                break;
            case VersionValidResult.Equal:
                isCheckPass = true;
                break;
            case VersionValidResult.Greater:
                isGreaterOS = true;
                break;
        }
        #endregion


        if (isGreaterHost || isGreaterELE || isGreaterCOL || isGreaterDD || isGreaterOS)
        {
            System.Text.StringBuilder sb = new System.Text.StringBuilder();

            if (isGreaterHost)
            {

                sb.AppendFormat("请确认\r\n设备软件版本:{0},\r\n服务器端最新版本:{1} 是否合格！", versionUUD, versionSTD);
                sb.AppendLine();
            }
            if (isGreaterCOL)
            {

                sb.AppendFormat("请确认\r\n设备控制板版本:{0},\r\n服务器端最新版本:{1} 是否合格！", versionUUDCOL, versionSTDCOL);
                sb.AppendLine();
            }
            if (isGreaterELE)
            {

                sb.AppendFormat("请确认\r\n设备电测板版本:{0},\r\n服务器端最新版本:{1} 是否合格！", versionUUDELE, versionSTDELE);
                sb.AppendLine();
            }
            if (isGreaterDD)
            {
                sb.AppendFormat("设备DD库版本:{0},服务器最新版本:{1}\r\n高于服务器，请确认是否合格！", ddversion, ddversionSTD);
                sb.AppendLine();
            }
            if (isGreaterOS)
            {
                sb.AppendFormat("请确认\r\n设备操作系统版本:{0},\r\n服务器端最新版本:{1} 是否合格！", osVersion, osVersionSTD);
                sb.AppendLine();
            }
            sb.Append("\r\n单击‘确认’按钮，测试通过。否则测试失败。");

            bool? key = ScriptHelper.OpenInfoConfirmWindow(item, sb.ToString());

            if (key != true)
            {
                result.AddTestErrMsgs(new ErrMsg(30003, "验证设备版本高于最新版本"));
            }
            else
            {
                isCheckPass = true;
            }
        }
        if (!isCheckPass)
        {
            return result;
        }
        if (type.Contains("BP"))
        {
            return result;
        }

        var typevalue = Helper.GetSNType(parameter1.Value)?.Trim();
        if (string.IsNullOrWhiteSpace(typevalue))
        {
            item.Root.IsRunning = false;
            return result.AddTestErrMsgs(new ErrMsg(000001, "提示：当前编号在系统中不存在，请确认编号是否正确。"));
        }
        RealTimeMsg msg133 = new RealTimeMsg("MES中的型号", typevalue);
        item.AddRealTimeMsgs(msg133);
        var tempType = "";
        if (typevalue.Contains("10M"))
        {
            tempType = "ConST811A-H";
        }
        else if (typevalue.Contains("M") || typevalue.Contains("U") || typevalue.Contains("AG"))
        {
            tempType = "ConST811A-M";
        }
        else if (type.EndsWith("D"))
        {
            tempType = "ConST811A-D";
        }
        else if (type.Contains("L"))
        {
            tempType = "ConST811A-LP";
        }
        else
        {
            tempType = "ConST811A-M";
        }

        if (string.IsNullOrWhiteSpace(tempType))
        {
            item.Parent.VM.OpenInfoConfirmWindow($"当前控制板版本 {controllerVersion} 与当前机型 {type} 不匹配。没有在MES系统中查到对应的型号信息，无法进行时比较。\r\n请确认设备压力类型与控制板是否匹配，\r\n点击【确认】，没有问题，点击【取消】，测试失败。");
            result.SetConclusion($"当前控制板版本 {controllerVersion} 与当前机型 {type} 不匹配");
            return result.AddTestErrMsgs(new ErrMsg(20003, $"没有在MES系统中查到对应的型号信息，无法进行时比较。当前控制板版本 {controllerVersion} 与当前机型 {type} 不匹配"));
        }

        if (!controllerVersion.Contains(tempType.Split('-')[1]))
        {
            bool? key = item.Parent.VM.OpenInfoConfirmWindow($"当前控制板版本{controllerVersion}与当前机型{type}不匹配，请使用U盘升级最新固件！确认设备压力类型与控制板是否匹配，\r\n点击【确认】，没有问题，点击【取消】，测试失败。");
            if (key.HasValue && key.Value)
            {
                return result;
            }
            else
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "当前控制板版本与主机版本不匹配！"));
                return result;
            }
        }


        return result;
    }
    /// <summary>
    /// 电池功耗测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestMeterState(dynamic item)
    {
        Result<List<TextData>> result = new Result<List<TextData>>(true);
        List<TextData> rData = new List<TextData>() { new TextData("主板状态"), new TextData("电池状态"), new TextData("排空状态"), new TextData("控制器测试状态"), new TextData("功耗状态"), new TextData("输出测试状态") };
        result.Data = rData;

        item.ClearRealTimeMsgs();

        //获取条件
        if (item.Conditions == null)
        {
            result.AddTestErrMsgs(ErrMsg._10002);
            return result;
        }
        //根据机型获取电池功耗参数,10MPa机型单独一个电池功耗参数
        string DeviceMode = item.Root.DUT.DeviceMode;
        ValueCondition condition0;
        if (!string.IsNullOrEmpty(DeviceMode)&&DeviceMode.Contains("10M"))
        {
            condition0 = item.Conditions[1] as ValueCondition;
        }
        else
        {
            condition0 = item.Conditions[0] as ValueCondition;
        }
        

        int trynum = 1;
    tryagain:
        OpenCloseState v27state = OpenCloseState.Open;
        if (item.GetDevice("GZP21") != null && item.GetDevice("GZP21").Gett27VState(out v27state))
        {
            RealTimeMsg msg0 = new RealTimeMsg("电池功耗测试");
            item.AddRealTimeMsgs(msg0);
            RealTimeWatch watch = new RealTimeWatch();
            watch.RTMsg = msg0;
            watch.ReStart();
            DateTime start = DateTime.Now;
            TimeSpan timeSpan = new TimeSpan();
            if (v27state == OpenCloseState.Close)
            {
                while (true)
                {
                    timeSpan = DateTime.Now - start;
                    msg0.Content = string.Format("不处于充电状态，功耗测试开始前等待10秒,当前等待时间:{0}秒", timeSpan.TotalSeconds);
                    System.Threading.Thread.Sleep(1000);
                    if (timeSpan.TotalSeconds >= 10)
                    {
                        break;
                    }
                }
            }
            else
            {
                item.GetDevice("GZP21").Set27VState(OpenCloseState.Close);
                while (true)
                {
                    timeSpan = DateTime.Now - start;
                    msg0.Content = string.Format("之前处于充电状态，功耗测试开始前等待20秒,当前等待时间:{0}秒", timeSpan.TotalSeconds);
                    System.Threading.Thread.Sleep(1000);
                    if (timeSpan.TotalSeconds >= 20)
                    {
                        break;
                    }
                }
            }
            watch.Stop();
            watch.Close();
        }
        else
        {
            if (trynum++ < 3)
            {
                System.Threading.Thread.Sleep(1000);
                goto tryagain;
            }

            return result.AddTestErrMsgs(new ErrMsg(30001, "工装断开适配器充电失败,重测后没有改善,请将工装重新上电后重试。"));
        }

        #region 初始化
        if (!item.GetDevice("P21").SetBrightness(BrightnessType.Percentage, "50"))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "指令通讯有问题，初始化屏幕亮度50%失败"));
            return result;
        }
        if (!item.GetDevice("P21").SetWifiClose())
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "指令通讯有问题，初始化WIFI关闭失败"));
            return result;
        }
        //初始化蓝牙关闭
        if (!item.GetDevice("P21").CloseBlueTooth())
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "指令通讯有问题，初始化蓝牙关闭失败"));
            return result;
        }
        if (!item.GetDevice("P21").SetTestMode())
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "指令通讯有问题，初始化压力测量模式失败"));
            return result;
        }
        if (!item.GetDevice("P21").SetEleChannelItem_VOL())
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "指令通讯有问题，初始化电压测量模式失败"));
            return result;
        }
        if (!item.GetDevice("P21").SetElectricSource_MA(true))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "指令通讯有问题，初始化电流输出模式失败"));
            return result;
        }
        #endregion

        CheckState MainBoardCheckStata = CheckState.UnKnown;
        if (!item.GetDevice("P21").GetMainBoardCheckState(out MainBoardCheckStata))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "指令通讯有问题，读取主板自检状态失败"));
            return result;
        }
        result.Data[0].Value = MainBoardCheckStata.ToString();
        RealTimeMsg msg1 = new RealTimeMsg("1>>>主板自检信息中的电源状态");
        msg1.Content = rData[0].Value;
        item.AddRealTimeMsgs(msg1);
        if (MainBoardCheckStata != CheckState.OK)
        {
            result.AddTestErrMsgs(new ErrMsg(30004, "设备自检不通过，主板电源状态验证未通过"));
            return result;
        }

        PowerType BatteryCheckStata = PowerType.Unknow;
        if (!item.GetDevice("P21").GetPowerSupplyCheck(out BatteryCheckStata))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "指令通讯有问题，读取供电方式失败"));
            return result;
        }
        result.Data[1].Value = BatteryCheckStata.ToString();
        RealTimeMsg msg2 = new RealTimeMsg("2>>>供电方式读取");
        msg2.Content = rData[1].Value;
        item.AddRealTimeMsgs(msg2);
        if (BatteryCheckStata != PowerType.Battery)
        {
            result.AddTestErrMsgs(new ErrMsg(30004, "非电池供电,供电方式验证未通过"));
            return result;
        }



        int tryCount = 0;
        RealTimeMsg msg3 = new RealTimeMsg("设置排空模式");
        item.AddRealTimeMsgs(msg3);
        //设置排空模式
        while (true)
        {
            msg3.ContentRunning();
            if (item.GetDevice("P21").SetVentMode())
            {
                break;
            }
            else
                tryCount++;
            if (tryCount > 3)
            {
                bool? key = item.Parent.VM.OpenInfoConfirmWindow("切换排空模式失败,重试？");
                if (key.HasValue && key.Value)
                    continue;
                else
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "指令通讯有问题，切换排空模式失败"));
                    msg3.Content = rData[2].Value = "切换排空模式失败";
                    return result;
                }
            }
        }
        if (string.IsNullOrEmpty(rData[2].Value))
        {
            msg3.Content = rData[2].Value = "切换排空模式成功";
        }


        RealTimeMsg msg4 = new RealTimeMsg("设置控制器测试模式");
        item.AddRealTimeMsgs(msg4);
        //设置控制器测试模式
        while (true)
        {
            msg4.ContentRunning();
            if (item.GetDevice("P21").SetTestMode())
            {
                break;
            }
            else
                tryCount++;
            if (tryCount > 3)
            {
                bool? key = item.Parent.VM.OpenInfoConfirmWindow("切换控制器测试模式失败,重试？");
                if (key.HasValue && key.Value)
                    continue;
                else
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "指令通讯有问题，切换控制器测试模式失败"));
                    msg4.Content = rData[3].Value = "切换控制器测试模式失败";
                    return result;
                }
            }
        }
        if (string.IsNullOrEmpty(rData[3].Value))
        {
            msg4.Content = rData[3].Value = "切换控制器测试模式成功";
        }

        System.Threading.Thread.Sleep(5000);

        RealTimeMsg msg5 = new RealTimeMsg("3>>>整机功耗自检测试");
        item.AddRealTimeMsgs(msg5);
        List<double> EnergyCheckStata = null;

        for (int i = 0; i < 10; i++)
        {
            if (!item.GetDevice("P21").GetEnergyCheckStata(out EnergyCheckStata))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "指令通讯有问题，获取整机功耗数据失败"));
                msg5.Content = rData[4].Value = "获取整机功耗数据失败";
            }
            else
            {
                item.AddRealTimeMsgs(new RealTimeMsg("自检信息", $"{string.Join("-", EnergyCheckStata)}"));
                if (!condition0.IsTrue(Math.Abs(EnergyCheckStata[2])))
                {
                    if (i == 9)
                    {
                        result.AddTestErrMsgs(new ErrMsg(30004, Math.Abs(EnergyCheckStata[2]) + "mW  整机功耗测试错误"));
                        msg5.Content = rData[4].Value = Math.Abs(EnergyCheckStata[2]) + "mW   整机功耗测试错误";
                    }
                }
                else
                {
                    msg5.Content = rData[4].Value = Math.Abs(EnergyCheckStata[2]) + "mW  整机功耗测试通过";
                    return result;
                }
            }
            System.Threading.Thread.Sleep(1000);
        }

        #region 检测电池电量

        RealTimeMsg msg111 = new RealTimeMsg("电池电量");
        item.AddRealTimeMsgs(msg111);
        if (!item.GetDevice("P21").GetBatteryValue(out double Bval))
            return result.AddTestErrMsgs(new ErrMsg(30001, "获取电池电量失败"));
        msg111.Content = $"{Math.Round(Bval, 2) * 100}%";

        if (Bval > 0.8)
        {
            if (item.GetDevice("GZP21") != null && item.GetDevice("GZP21").IsOpen)
            {
                item.GetDevice("GZP21").Set27VState(OpenCloseState.Close);
            }
        }
        if (Bval < 0.3)
        {
            if (item.GetDevice("GZP21") != null && item.GetDevice("GZP21").IsOpen)
            {
                item.GetDevice("GZP21").Set27VState(OpenCloseState.Open);
            }
        }

        #endregion

        return result;
    }

    /// <summary>
    /// 适配器供电测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestPowerAdapter(dynamic item)
    {
        Result<List<TextData>> result = new Result<List<TextData>>(true);
        List<TextData> rData = new List<TextData>() { new TextData("适配器状态"), new TextData("主板电源验证"), new TextData("电池电量"), new TextData("充电电流") };
        result.Data = rData;

        item.ClearRealTimeMsgs();

        #region 判断电池电量
        RealTimeMsg msg = new RealTimeMsg("获取电池电量(百分比)");
        item.AddRealTimeMsgs(msg);
        if (!item.GetDevice("P21").GetBatteryValue(out double val))
        {
            result.AddTestErrMsgs(new ErrMsg(30001, "获取电池电量(百分比)失败"));
            return result;
        }
        msg.Content = $"{Math.Round(val, 2) * 100}%";
        rData[2].Value = msg.Content;

        #endregion

        int trynum = 0;

    tryagain:

        #region 打开适配器
        RealTimeMsg msg0 = new RealTimeMsg("工装供电状态");
        item.AddRealTimeMsgs(msg0);
        OpenCloseState v27state = OpenCloseState.Open;
        if (item.GetDevice("GZP21").Gett27VState(out v27state))
        {
            msg0.Content = v27state.ToString();
            if (v27state == OpenCloseState.Close)
            {
                item.GetDevice("GZP21").Set27VState(OpenCloseState.Open);
                msg0.Content += " 打开充电，等待电流稳定";
                System.Threading.Thread.Sleep(10000); //等待设备充电电流稳定
            }
        }
        else
        {
            if (trynum++ < 3)
            {
                Task.Delay(1000).Wait();
                goto tryagain;
            }
            return result.AddTestErrMsgs(new ErrMsg(30001, "获取工装电源通断状态失败"));
        }
        #endregion

        #region 持续检测适配器识别结果
        if (!item.IsRunning)
            item.Root.IsRunning = false;
        int Getnum = 0;
        trynum = 0;

        double[] PowerCheck = new double[3];
        PowerType PowerAdapterCheck = PowerType.Unknow;
        while (true)
        {
            if (!item.IsRunning)
            {
                item.Root.IsRunning = false;
                return result.AddTestErrMsgs(new ErrMsg(20003, "操作员手动停止测试，测试失败"));
            }
            if (!item.GetDevice("P21").GetBATTery2(out PowerCheck))
            {
                return result.AddTestErrMsgs(new ErrMsg(20003, "读取充电电流失败"));
            }
            rData[0].Value = $"电池电压：{PowerCheck[0]} V,充电电流：{PowerCheck[1]} mA,放电电流：{PowerCheck[2]} mA";
            RealTimeMsg msg1 = new RealTimeMsg("电池");
            item.AddRealTimeMsgs(msg1);
            msg1.Content += $"电压：{PowerCheck[0]} V,充电电流：{PowerCheck[1]} mA,放电电流：{PowerCheck[2]} mA";
            rData[3].Value = PowerCheck[1] + "mA";

            if (!item.GetDevice("P21").GetPowerSupplyCheck(out PowerAdapterCheck))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "读取设备适配器自测试结果失败"));
                return result;
            }

            if (PowerAdapterCheck == PowerType.Adapter)
            {
                if (++Getnum >= 5)
                    break;
            }
            else
            {
                if (++trynum > 2)
                {
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("当前设备自检测是电池供电，应该是适配器供电，请确认是否插入适配器？\r\n点击确定，重新检测，否则设备适配器功能有问题，中止测试。");
                    if (key.HasValue && key.Value)
                    {
                        goto tryagain;
                    }
                    else
                    {
                        if (trynum > 4)
                        {
                            return result.AddTestErrMsgs(new ErrMsg(20003, $"第{trynum}次测试，当前设备自检测是电池供电，应该是适配器供电，操作员手动停止，测试失败"));
                        }

                        int trychangenum = 1;

                    trychangeBattery:

                        #region 检测电池电量
                        var bateryinfo = item.Conditions[0] as RangeCondition;
                        if (!item.GetDevice("P21").GetBatteryValue(out val))
                        {
                            result.AddTestErrMsgs(new ErrMsg(30001, "更换电池后，获取电池电量(百分比)失败"));
                            return result;
                        }
                        if (!bateryinfo.IsTrue(val * 100))
                        {
                            bool? key2 = item.Parent.VM.OpenInfoConfirmWindow($"电池电量{val * 100}不指标内{bateryinfo}，可能会影响一次合格率。\r\n请更换电量在指标内的电池，然后等设备开机后，再点击确定继续测试，点击取消中止测试。");

                            if (key2.HasValue && key2.Value)
                            {
                                item.GetDevice("P21").Close();
                                System.Threading.Thread.Sleep(25000);
                                //尝试打开连接
                                int tryCount = 0;
                                while (true)
                                {
                                    tryCount++;
                                    System.Threading.Thread.Sleep(1000);
                                    if (!item.GetDevice("P21").Open())
                                    {
                                        if (tryCount < 10)
                                            continue;
                                        else
                                        {
                                            result.AddTestErrMsgs(new ErrMsg(20003, "更换电池重启后，通讯失败！"));
                                            return result;
                                        }
                                    }
                                }
                                if (trychangenum++ < 3)
                                {
                                    goto trychangeBattery;
                                }
                            }
                            else
                            {
                                return result.AddTestErrMsgs(new ErrMsg(20003, $"测试{trychangenum}次，电池电量{val * 100}超出指标{bateryinfo}，不能准确测试适配器的充电功能，操作员手动停止。"));
                            }
                        }
                        else
                        {
                            goto tryagain;
                        }
                        #endregion
                    }

                }

            }
            Task.Delay(1000).Wait();
        }
        #endregion

        CheckState MainBoardCheckStata = CheckState.UnKnown;
        if (!item.GetDevice("P21").GetMainBoardCheckState(out MainBoardCheckStata))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "读取主板状态失败"));
            return result;
        }
        RealTimeMsg msg2 = new RealTimeMsg("1>>>主板状态");
        msg2.Content = rData[1].Value = MainBoardCheckStata.ToString();
        item.AddRealTimeMsgs(msg2);
        if (MainBoardCheckStata != CheckState.OK)
        {
            result.AddTestErrMsgs(new ErrMsg(30004, "主板状态验证未通过"));
        }

        //电池电量过高，停止充电
        if (val * 100 > 60)
        {
            item.GetDevice("GZP21").Set27VState(OpenCloseState.Close);
        }

        if (val < 0.3)
        {
            if (item.GetDevice("GZP21") != null && item.GetDevice("GZP21").IsOpen)
            {
                item.GetDevice("GZP21").Set27VState(OpenCloseState.Open);
            }
        }
        return result;
    }
    /// <summary>
    /// USB主测试
    /// </summary>
    /// <param name="commobject"></param>
    /// <param name="testItem"></param>
    /// <returns></returns>
    public dynamic TestUSBPrincipal(dynamic testItem)
    {
        Result<TextData> result = new Result<TextData>(true);
        result.Data = new TextData("读取内容");
        try
        {
            TextParameter parameter = testItem.Parameters[0] as TextParameter;
            TextCondition condition = testItem.Conditions[0] as TextCondition;
            int trynum = 0;

        tryagain:

            testItem.ClearRealTimeMsgs();
            RealTimeMsg msg1 = new RealTimeMsg("读取USB状态");
            testItem.AddRealTimeMsgs(msg1);
            bool USBstate = false;
            if (!testItem.GetDevice("P21").GetUSBdriveState(out USBstate))
            {
                if (++trynum < 3)
                    goto tryagain;

                result.AddTestErrMsgs(new ErrMsg(20001, "读取U盘状态指令执行失败！"));
                return result;
            }
            long[] size;
            if (USBstate)
            {
                if (!testItem.GetDevice("P21").GetUSBdriveSize(out size))
                {
                    if (++trynum < 3)
                        goto tryagain;

                    result.AddTestErrMsgs(new ErrMsg(20001, "读取USB设备大小失败"));
                    return result;
                }
                msg1.Name = "USB设备";
                msg1.Content = string.Format("{0},总字节{1}", size.Length >= 2 ? "识别成功" : "未识别", Math.Round(size[1] / 1024.0 / 1024.0 / 1024.0, 2));
                if (size.Length < 2)
                {
                    result.AddTestErrMsgs(new ErrMsg(30004, "USB状态识别错误"));
                    return result;
                }
            }
            else
            {
                msg1.Content = "未插入U盘";

                bool? key1 = testItem.Parent.VM.OpenInfoConfirmWindow("没有检测到U盘，请先将U盘正确接入到设备上，再点击确认按钮，进行测试！");
                if (key1.HasValue && key1.Value)
                {
                    Task.Delay(3000).Wait();
                    goto tryagain;
                }
                else if (++trynum < 3)
                {
                    return result.AddTestErrMsgs(new ErrMsg(10003, "没有检测到U盘，设备识别U盘功能不正确。"));
                }
                return result.AddTestErrMsgs(new ErrMsg(30004, "未插入U盘"));
            }

            //创建文件并写入数据 
            RealTimeMsg msg2 = new RealTimeMsg("向U盘添加文件Test1.txt");
            testItem.AddRealTimeMsgs(msg2);
            if (!testItem.GetDevice("P21").AddDataToUSB("Test1.txt", parameter.Value))
            {
                result.AddTestErrMsgs(new ErrMsg(20001, "写入失败！"));
                return result;
            }
            msg2.Name = "写入内容";
            msg2.Content = parameter.Value;

            RealTimeMsg msg3 = new RealTimeMsg("读取U盘文件Test1.txt内容");
            testItem.AddRealTimeMsgs(msg3);
            string readerVal = string.Empty;
            if (!testItem.GetDevice("P21").ReadDataFromUSB("Test1.txt", out readerVal))
            {
                result.AddTestErrMsgs(new ErrMsg(20001, "读取失败！"));
                return result;
            }
            msg3.Name = "读取内容";
            msg3.Content = readerVal;
            result.Data.Value = readerVal;
            if (condition.IsTrue(result.Data.Value))
            {
                result.Assert = true;
            }
            else
            {
                result.AddTestErrMsgs(new ErrMsg(30003, "写入内容与读取内容不一致"));
            }

            return result;
        }
        finally
        {
            if (testItem.GetDevice("P21").QueryUSBfileExists("Test1.txt"))
            {
                bool? IsDelfile = testItem.GetDevice("P21").DelUSBfile("Test1.txt");
                if (!IsDelfile.HasValue)
                {
                    //指定文件名的文件不存在

                }
                else if (!IsDelfile.Value)
                {
                    //未能正常执行删除指令
                    result.AddTestErrMsgs(new ErrMsg(20003, "未能正常执行删除指令！"));
                }
            }
        }
    }
    /// <summary>
    /// USB从测试
    /// </summary> 
    /// <param name="testItem"></param>
    /// <returns></returns>
    public dynamic TestUSBSubordinate(dynamic testItem)
    {
        try
        {
            Result<TextData> result = new Result<TextData>(true);
            result.Data = new TextData("测试结果");
            testItem.ClearRealTimeMsgs();
            RealTimeMsg msg0 = new RealTimeMsg("验证当前连接是否为USB线连接通信");
            testItem.AddRealTimeMsgs(msg0);
            CommType commType = testItem.GetDevice("P21").GetCommType();
            if (commType == CommType.USB)
            {
                msg0.Content = "当前USB线连接，通信正常！";
                result.Data.Value = "USB从测试通过";
                return result;
            }
            msg0.Content = "当前不是USB线连接，开始测试！！";
            //计时器
            System.Diagnostics.Stopwatch watch = new System.Diagnostics.Stopwatch();
            watch.Start();
            RealTimeMsg msg1 = new RealTimeMsg("获取usb location");
            testItem.AddRealTimeMsgs(msg1);
            RealTimeMsg msg2 = new RealTimeMsg("时间");
            testItem.AddRealTimeMsgs(msg2);

            string location;
            while (true)
            {
                System.Threading.Thread.Sleep(1000);
                msg2.Content = Util.FormatLongToTimeStr(watch.Elapsed.Ticks);
                if (testItem.GetDevice("P21").GetUSBLocation(out location) || TimeSpan.FromTicks(watch.Elapsed.Ticks).TotalMilliseconds > 10 * 1000)
                {
                    break;
                }
            }
            watch.Stop();
            if (!string.IsNullOrEmpty(location))
            {
                result.Data.Name = "usb location";
                result.Data.Value = location;
                msg1.Name = "usb location";
                msg1.Content = location;
            }
            else
            {
                msg1.Content = "失败";
                result.AddTestErrMsgs(new ErrMsg(30003, "获取usb location失败"));
            }

            return result;
        }
        finally
        {

        }
    }

    /// <summary>
    /// 网口测试
    /// </summary> 
    /// <param name="testItem"></param>
    /// <returns></returns>
    public dynamic TestLAN(dynamic testItem)
    {
        Result<TextData> result = new Result<TextData>(true);
        result.Data = new TextData("测试结果");
        testItem.ClearRealTimeMsgs();

        try
        {

            int trynum = 1;

        tryagain:

            RealTimeMsg msg = new RealTimeMsg("读取设备以太网IP");
            testItem.AddRealTimeMsgs(msg);
            if (!testItem.GetDevice("P21").GetEthemetIPAddress(out string IPAddress))
            {
                if (trynum++ < 3)
                {
                    System.Threading.Tasks.Task.Delay(200).Wait();
                    testItem.AddRealTimeMsgs(new RealTimeMsg());
                    goto tryagain;
                }

                result.AddTestErrMsgs(new ErrMsg(20001, "与设备指令通讯有问题，读取设备以太网IP失败！"));
                msg.Content = "失败";
                return result;
            }
            msg.Content = IPAddress;
            trynum = 1;
            if (string.IsNullOrEmpty(IPAddress) || IPAddress.StartsWith("0.0"))
            {
                bool? key1 = testItem.Parent.VM.OpenInfoConfirmWindow($"请先用网线将设备与工装连接，再点击确认按钮，进行第{trynum}次测试！");
                if (key1.HasValue && !key1.Value)
                {
                    return result.AddTestErrMsgs(new ErrMsg(10003, $"第{trynum}次测试，读取设备的有线网IP{IPAddress}是不合法的，正常应该是192或者169开头。网线可能没接，或者设备网口有问题，操作员手动停止。"));
                }
                else
                {
                    testItem.AddRealTimeMsgs(new RealTimeMsg($"第{trynum}次测试", $"读取设备的有线网IP{IPAddress}是不合法的，正常应该是192或者169开头。网线可能没接，或者设备网口有问题，操作员选择重测。"));

                    Task.Delay(3000).Wait();
                    if (trynum++ < 3)
                        goto tryagain;

                    return result.AddTestErrMsgs(new ErrMsg(20001, $"读取设备的有线网IP{IPAddress}是不合法的，正常应该是192或者169开头。"));
                }
            }

            trynum = 1;

            RealTimeMsg msg1 = new RealTimeMsg("启动网口IP检查程序");
            testItem.AddRealTimeMsgs(msg1);
            if (!testItem.GetDevice("P21").SetCheckerOpen(ProgramFunction.LAN))
            {
                result.AddTestErrMsgs(new ErrMsg(20001, "与设备指令通讯有问题，启动网口IP检查程序失败"));
                return result;
            }
            msg1.Name = "网口IP检查程序";
            ProgramFunctionCheckResult checkResult = ProgramFunctionCheckResult.Unknow;
            while (true)
            {
                System.Threading.Thread.Sleep(500);
                if (!testItem.IsRunning)
                {
                    result.AddTestErrMsgs(new ErrMsg(10004, "测试被操作员手动停止。"));
                    break;
                }
                if (!testItem.GetDevice("P21").GetCheckerState(ProgramFunction.LAN, out checkResult))
                {
                    if (trynum++ < 3)
                    {
                        System.Threading.Tasks.Task.Delay(200).Wait();
                        testItem.AddRealTimeMsgs(new RealTimeMsg());
                        goto tryagain;
                    }

                    result.AddTestErrMsgs(new ErrMsg(20003, "与设备指令通讯有问题，获取自检测试结果失败"));
                    return result;
                }
                if (checkResult == ProgramFunctionCheckResult.Unknow || checkResult == ProgramFunctionCheckResult.NoTest)
                {
                    msg1.Content = "未完成";
                    result.Data.Value = "未完成";
                    continue;
                }
                else if (checkResult == ProgramFunctionCheckResult.TestPass)
                {
                    msg1.Content = "通过";
                    result.Data.Value = "通过";
                    break;
                }
                else
                {
                    Task.Delay(1000).Wait();

                    bool? keyask = testItem.Parent.VM.OpenInfoConfirmWindow($"当前测试没通过，是否需要重新测试一次？点击【确认】进行第{++trynum}次测试，否则测试不通过，设备有问题。");
                    if (keyask.HasValue && !keyask.Value)
                    {
                        msg1.Content = "未通过";
                        result.Data.Value = "未通过";
                        result.AddTestErrMsgs(new ErrMsg(30004, "网口通讯测试失败"));
                        break;
                    }
                    else
                    {
                        testItem.GetDevice("P21").SetCheckerClose();
                        goto tryagain;
                    }
                }
            }
            System.Threading.Thread.Sleep(500);
            return result;
        }
        finally
        {
            testItem.GetDevice("P21").SetCheckerClose();
        }
    }
