    /// <summary>
    /// 按键测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestKeyBoard(dynamic item)
    {
        Result<TextData> result = new Result<TextData>(true);
        result.Data = new TextData("测试结果");
        RealTimeWatch watch = new RealTimeWatch();
        try
        {
            item.ClearRealTimeMsgs();

            int trynum = 1;

        tryagain:

            #region 按键测试
            RealTimeMsg msg1 = new RealTimeMsg("按键测试");
            item.AddRealTimeMsgs(msg1);

            RealTimeMsg msg12 = new RealTimeMsg("测试用时");
            item.AddRealTimeMsgs(msg12);

            if (!item.GetDevice("P21").SetCheckerOpen(ProgramFunction.KeyBoard))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "与设备指令通讯有问题，启动按键测试失败"));
                return result;
            }
            watch.RTMsg = msg1;
            watch.ReStart();
            ProgramFunctionCheckResult checkResult = ProgramFunctionCheckResult.Unknow;

            while (true)
            {
                System.Threading.Thread.Sleep(500);
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(new ErrMsg(10004, "测试被操作员手动终止"));
                    break;
                }
                if (!item.GetDevice("P21").GetCheckerState(ProgramFunction.KeyBoard, out checkResult))
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "与设备指令通讯有问题，获取自检测试结果失败"));
                    return result;
                }
                if (checkResult != ProgramFunctionCheckResult.Unknow && checkResult != ProgramFunctionCheckResult.NoTest)
                {
                    break;
                }
            }
            msg12.Content = $"{watch.TotalSeconds} s,{checkResult}";

            watch.Stop();
            if (checkResult == ProgramFunctionCheckResult.TestPass)
            {
                msg1.Content += "  通过";
                result.Data.Value = "通过";
            }
            else
            {
                Task.Delay(1000).Wait();

                bool? keyask = item.Parent.VM.OpenInfoConfirmWindow($"当前测试没通过，是否需要重新测试一次？点击【确认】进行第{++trynum}次测试，否则测试不通过，设备有问题。");
                if (keyask.HasValue && !keyask.Value)
                {
                    msg1.Content += "  未通过";
                    result.Data.Value = "未通过";
                    result.AddTestErrMsgs(new ErrMsg(30004, "设备返回测试不通过，按键测试失败"));
                }
                else
                {
                    item.GetDevice("P21").SetCheckerClose();
                    Task.Delay(3000).Wait();
                    goto tryagain;
                }

            }

            #endregion 按键测试

            return result;
        }
        finally
        {
            watch.Close();
            item.GetDevice("P21").SetCheckerClose();
        }
    }
    /// <summary>
    /// 屏幕触摸测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic LCDTest(dynamic item)
    {
        Result<List<TextData>> result = new Result<List<TextData>>(true);
        List<TextData> rData = new List<TextData> { new TextData("屏幕亮度测试"), new TextData("屏幕坏点测试"), new TextData("屏幕触摸测试") };
        result.Data = rData;
        RealTimeWatch watch = new RealTimeWatch();
        try
        {
            item.ClearRealTimeMsgs();

