    /// <summary>
    /// 外接模块通讯测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic ModuleConnectStateTest(dynamic item)
    {
        Result<List<TextData>> result = new Result<List<TextData>>(true);
        List<TextData> rData = new List<TextData>() { new TextData("外接压力模块A"), new TextData("外接压力模块B") };
        result.Data = rData;

        item.ClearRealTimeMsgs();


        RealTimeMsg msg1 = new RealTimeMsg("测试外接压力模块A通讯");
        item.AddRealTimeMsgs(msg1);
        OnOFFLineState moduleAConnectState = OnOFFLineState.UnKnown;
        if (!item.GetDevice("P21").GetPressureModelOnlineState(OnLinePressureModelType.ExternalAPressure, out moduleAConnectState))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "获取外接压力模块A在线状态失败，外接压力模块A通讯异常"));
            return result;
        }
        if (moduleAConnectState != Xmas11.Comm.Data.Common.OnOFFLineState.Online)
        {
            bool? key1 = item.Parent.VM.OpenInfoConfirmWindow("请先插入外接模块A的航插接口线到设备上，再点击确认按钮，进行测试！");
            if (key1.HasValue && !key1.Value)
            {
                result.AddTestErrMsgs(new ErrMsg(10003, "未能插入外接模块A接口"));
                return result;
            }

            System.Threading.Tasks.Task.Delay(2000).Wait();

            if (!item.GetDevice("P21").GetPressureModelOnlineState(OnLinePressureModelType.ExternalAPressure, out moduleAConnectState))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "获取外接压力模块A在线状态失败，外接压力模块A通讯异常"));
                return result;
            }
            if (moduleAConnectState != Xmas11.Comm.Data.Common.OnOFFLineState.Online)
            {

                result.AddTestErrMsgs(new ErrMsg(30004, "外接压力模块A通讯测试失败，设备外接模块识别有问题"));
                return result;
            }
        }
        msg1.Content = "完成";
        result.Data[0].Value = "正常";

        RealTimeMsg msg2 = new RealTimeMsg("测试外接压力模块B通讯");
        item.AddRealTimeMsgs(msg2);
        OnOFFLineState moduleBConnectState = OnOFFLineState.UnKnown;
        if (!item.GetDevice("P21").GetPressureModelOnlineState(OnLinePressureModelType.ExternalBPressure, out moduleBConnectState))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "获取外接压力模块B在线状态失败，外接压力模块A通讯异常"));
            return result;
        }
        if (moduleBConnectState != Xmas11.Comm.Data.Common.OnOFFLineState.Online)
        {
            bool? key2 = item.Parent.VM.OpenInfoConfirmWindow("请先插入外接模块B的航插接口线到设备上，再点击确认按钮，进行测试！");
            if (!key2.HasValue || !key2.Value)
            {
                result.AddTestErrMsgs(new ErrMsg(10003, "未能插入外接模块B接口"));
                return result;
            }

            System.Threading.Tasks.Task.Delay(2000).Wait();

            if (!item.GetDevice("P21").GetPressureModelOnlineState(OnLinePressureModelType.ExternalBPressure, out moduleBConnectState))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "获取外接压力模块B在线状态失败，外接压力模块A通讯异常"));
                return result;
            }
            if (moduleBConnectState != Xmas11.Comm.Data.Common.OnOFFLineState.Online)
            {
                result.AddTestErrMsgs(new ErrMsg(30004, "外接压力模块B通讯测试失败，设备外接模块识别有问题"));
                return result;
            }
        }
        msg2.Content = "完成";
        result.Data[1].Value = "正常";

        return result;
    }
    /// <summary>
    /// 电测板电源测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic ElectricalPowerTest(dynamic item)
    {
        Result<TextData> result = new Result<TextData>(true);
        result.Data = new TextData("测试结果");
        item.ClearRealTimeMsgs();

        // 发送指令读取电测板自检状态码，状态码为0，无故障
        RealTimeMsg msg1 = new RealTimeMsg();
        msg1.Name = "获取电测板电源状态";
        item.AddRealTimeMsgs(msg1);
        CheckState state = CheckState.UnKnown;
        if (!item.GetDevice("P21").GetElectricalBroadPowerCheckState(out state))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "获取电测板电源状态失败"));
            return result;
        }
        result.Data.Value = msg1.Content = state.ToString();

        RealTimeMsg msg2 = new RealTimeMsg();
        msg2.Name = "验证电测板电源状态";
        item.AddRealTimeMsgs(msg2);
        if (state == CheckState.OK)
        {
            msg2.Content = "通过";
        }
        else
        {
            msg2.Content = "未通过";
            result.AddTestErrMsgs(new ErrMsg(30004, "电测板电源状态异常"));
        }

        return result;
    }
    /// <summary>
    /// 电测板测量/输出功能测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic ElectricalMeasurementAndOutputFunctionTest(dynamic item)
    {
        Result<List<TextData>> result = new Result<List<TextData>>(true);
        List<TextData> rData = new List<TextData>()
        {
            new TextData("电压0V"),
            new TextData("电压0.1V"),
            new TextData("电压1V"),
            new TextData("电压10V"),
            new TextData("电压高压档16V"),
            new TextData("电压高压档24V"),
            new TextData("电压高压档29V"),
            new TextData("电流0mA"),
            new TextData("电流1mA"),
            new TextData("电流10mA")

        };
        result.Data = rData;
        item.ClearRealTimeMsgs();

        try
        {
        tryagain:
            item.GetDevice("GZP21").SetEleState(OpenCloseState.Open);



            #region 测量自输出自测量功能 
            //未确定前,设定允差为0.5
            for (int i = 0; i < rData.Count; i++)
            {
                item.AddRealTimeMsgs(new RealTimeMsg());
                TextData data = rData[i];
                ValueCondition condition = item.Conditions[i] as ValueCondition;
                RealTimeMsg msg = new RealTimeMsg(string.Format(">>测【{0}】档", data.Name));
                item.AddRealTimeMsgs(msg);
                int tryCount = 0;
                while (true)
                {
                    Regex regexNumber = new Regex(@"\d?\.?\d+");
                    Match matchNumber = regexNumber.Match(data.Name);
                    Regex regexUnit = new Regex(@"V|mA");
                    Match matchUnit = regexUnit.Match(data.Name);
                    double tagertValue = Convert.ToDouble(matchNumber.Value);
                    ElectricMeasure electricMeasure = new ElectricMeasure();
                    List<ElectricMeasure> electricMeasureLists = new List<ElectricMeasure>();

                    #region 切电测档位,并输出目标值
                    switch (matchUnit.Value)
                    {
                        case "V":
                            {
                                RealTimeMsg msg2 = new RealTimeMsg("切换电测电压档位");
                                item.AddRealTimeMsgs(msg2);
                                //设置电输出档位
                                if (data.Name.Contains("高压档"))
                                {
                                    if (!item.GetDevice("P21").SetElectricSourceFunction(ElectricSourceFunction.V2))
                                    {
                                        result.AddTestErrMsgs(new ErrMsg(20003, "切换电测电压高压档位失败"));
                                        return result;
                                    }
                                }
                                else
                                {
                                    if (!item.GetDevice("P21").SetElectricSourceFunction(ElectricSourceFunction.V))
                                    {
                                        result.AddTestErrMsgs(new ErrMsg(20003, "切换电测电压低压档位失败"));
                                        return result;
                                    }
                                }
                                msg2.Content = "√";

                                RealTimeMsg msg3 = new RealTimeMsg("设置电输出目标值");
                                item.AddRealTimeMsgs(msg3);
                                //设置电输出目标值
                                if (!item.GetDevice("P21").SetElectricSourceTarget(tagertValue))
                                {
                                    result.AddTestErrMsgs(new ErrMsg(20003, "设置电输出目标值失败"));
                                    return result;
                                }
                                msg3.Content = tagertValue.ToString() + matchUnit.Value;
                                //延时等待设置成功

                                RealTimeMsg msg4 = new RealTimeMsg();
                                msg4.Name = "设置电测量档位为电压档";
                                item.AddRealTimeMsgs(msg4);
                                //设置电测量档位为电压档
                                if (!item.GetDevice("P21").SetEleChannelItem_VOL())
                                {
                                    result.AddTestErrMsgs(new ErrMsg(20003, "设置电测量档位为电压档失败"));
                                    return result;
                                }
                                msg4.Content = "√";

                                System.Threading.Thread.Sleep(3000);

                                RealTimeMsg msg5 = new RealTimeMsg();
                                msg5.Name = "读取电测量值";
                                item.AddRealTimeMsgs(msg5);
                                //读取电测量值
                                int tryCount1 = 3;
                                while (true)
                                {
                                    if (!item.GetDevice("P21").GetCurrentElectricMeasure(out electricMeasure))
                                    {
                                        result.AddTestErrMsgs(new ErrMsg(20003, "读取测量值失败"));
                                        return result;
                                    }
                                    electricMeasureLists.Add(electricMeasure);
                                    if (tryCount1 > 3)
                                    {
                                        break;
                                    }
                                    tryCount1++;
                                }
                                double eleData = 0;
                                foreach (ElectricMeasure dataItem in electricMeasureLists)
                                {
                                    eleData += Convert.ToDouble(dataItem.MeasureValue);
                                }
                                electricMeasure.MeasureValue = eleData / electricMeasureLists.Count;
                                string resultValue = electricMeasure.MeasureValue.ToString("f4") + electricMeasure.Unit;
                                msg5.Content = data.Value = resultValue.ToString();

                            };
                            break;
                        case "mA":
                            {
                                RealTimeMsg msg2 = new RealTimeMsg("切换电输出毫安电流档位");
                                item.AddRealTimeMsgs(msg2);
                                //设置电输出档位
                                if (!item.GetDevice("P21").SetElectricSource_MA(false))
                                {
                                    result.AddTestErrMsgs(new ErrMsg(20003, "切换电输出电流档位失败"));
