                                }
                                electricMeasure.MeasureValue = eleData / electricMeasureLists.Count;
                                string resultValue = electricMeasure.MeasureValue.ToString("f4") + electricMeasure.Unit;
                                msg5.Content = data.Value = resultValue.ToString();
                            };
                            break;
                        default:
                            break;
                    }

                    #endregion 切电测档位,并输出目标值
                    double measuredValue = Convert.ToDouble(electricMeasure.MeasureValue);

                    //需要在这里对测量值是否为0进行判定，来决定要不要
                    if (tagertValue != 0 && Math.Round(measuredValue, 2) == 0)
                    {
                        item.AddRealTimeMsgs(new RealTimeMsg($"设定点{tagertValue}", $"测量值{measuredValue}，测量值接近0，电测线可能没接。"));

