                    }
                }


            }
            #endregion

            #region 测量24V环路电压供电功能
            item.AddRealTimeMsgs(new RealTimeMsg());

            item.AddRealTimeMsgs(new RealTimeMsg(">>开始测试24V环路电压供电功能"));

