    /// <summary>
    /// 检查HART小板是否装配好
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestHart(dynamic item)
    {
        try
        {
            Result<TextData> result = new Result<TextData>(true);
            result.Data = new TextData("hart");
            item.ClearRealTimeMsgs();

            int trynum = 1;

        tryagain:

            if (item.GetDevice("GZP21") != null)
            {
                item.GetDevice("GZP21").SetHartState(OpenCloseState.Open);
            }
            System.Threading.Thread.Sleep(1000);

            RealTimeMsg msg1 = new RealTimeMsg("切换hart档位");
            item.AddRealTimeMsgs(msg1);

            if (!item.GetDevice("P21").SetEleChannelItem_HART())
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "与设备指令通讯有问题，切换hart档位失败"));
                return result;
            }
            msg1.Content = "完成";

            ResistancePowerSupplyMode supplyMode = ResistancePowerSupplyMode.Unknow;
            RealTimeMsg msg0 = new RealTimeMsg("获取当前供电模式");
            item.AddRealTimeMsgs(msg0);
            if (!item.GetDevice("P21").GetSupplyMode(out supplyMode))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "与设备指令通讯有问题，获取当前供电模式失败"));
                return result;
            }
            msg0.Content = supplyMode.ToString();
            if (supplyMode != ResistancePowerSupplyMode.IPIR)
            {
                RealTimeMsg msg2 = new RealTimeMsg("切换供电模式为IPIR-内部电源内部电阻模式");
                item.AddRealTimeMsgs(msg2);
                if (!item.GetDevice("P21").SetSwitchMode_IPIR())
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "与设备指令通讯有问题，切换供电模式失败"));
                    return result;
                }
                msg2.Content = "切换完成";
            }

            System.Threading.Thread.Sleep(8000);
            if (!item.GetDevice("P21").StartSearchHart())
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "与设备指令通讯有问题，搜索Hart失败"));
                return result;
            }
            RealTimeMsg msg3 = new RealTimeMsg("获取hart");
            item.AddRealTimeMsgs(msg3);
            int i = 0;
            while (true)
            {
                System.Threading.Thread.Sleep(1000);
                string msg;
                if (!item.GetDevice("P21").GetEleHartMassage(out msg))
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "与设备指令通讯有问题，获取hart信息失败"));
                    return result;
                }
                else
                {
                    result.Data.Value = msg;
                    msg3.Content = i + "秒";
                    if (result.Data.Value != "0")
                    {
                        msg3.Content = result.Data.Value;
                        break;
                    }
                }
                if (i > 40)
                {
                    break;
                }
                i++;
            }

            if (result.Data.Value == "0")
            {
                if (trynum++ < 3)
                {
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("电测线可能没接，请先使用测试线 连接设备与工装的SRC和MEAS插孔，红对红，黑对黑。\r\n点击确认，重新测试，否则测试失败。");
                    if (!key.HasValue || key != true)
                        return result.AddTestErrMsgs(new ErrMsg(30001, "电测线可能没接，或者设备的功能有问题，操作员手动停止。"));

                    item.AddRealTimeMsgs(new RealTimeMsg("重新测试", $"第{trynum}次"));
                    System.Threading.Thread.Sleep(5000);
                    goto tryagain;
                }
            }

            RealTimeMsg msg4 = new RealTimeMsg();
            msg4.Name = "开始连接(默认连接第一个搜索到的HART变送器)";
            item.AddRealTimeMsgs(msg4);
            int address = int.Parse(result.Data.Value.Split(';')[0].Split(',')[0]);
            if (!item.GetDevice("P21").ConnectHart(address))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "与设备指令通讯有问题，连接Hart变送器失败"));
                return result;
            }
            msg4.Content = "连接完成";

            return result;
        }
        finally
        {
            item.GetDevice("P21").StopSearchHart();
            item.GetDevice("P21").SetEleChannelItem_HARTClose();
            if (item.GetDevice("GZP21") != null)
            {
                item.GetDevice("GZP21").SetHartState(OpenCloseState.Close);
            }
            item.GetDevice("P21").SetTestMode();
        }
    }
    /// <summary>
    /// 开关测量功能测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestSwitch(dynamic item)
    {
        Result<List<TextData>> result = new Result<List<TextData>>(true);
        List<TextData> rData = new List<TextData>() { new TextData("机械开关分开"), new TextData("机械开关短接"), new TextData("PNP闭合"), new TextData("PNP断开") };
        result.Data = rData;
        try
        {
            item.ClearRealTimeMsgs();
            int tryCount = 0;

        trySW:

            item.GetDevice("GZP21").SetEleState(OpenCloseState.Open);

            RealTimeMsg msg1 = new RealTimeMsg();
            msg1.Name = "设置(0~16)V电压输出档";
            item.AddRealTimeMsgs(msg1);
            if (!item.GetDevice("P21").SetElectricSourceFunction(ElectricSourceFunction.V))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "切换电测电压档位失败"));
                return result;
            }
            msg1.Content = "√";

            item.AddRealTimeMsgs(new RealTimeMsg());

            #region 机械测试
            RealTimeMsg msg11 = new RealTimeMsg("打开机械开关");
            item.AddRealTimeMsgs(msg11);

            if (!item.GetDevice("P21").SetEleChannelItem_SW_Normal())
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "打开机械开关失败"));
                return result;
            }
            msg11.Content = "√";

            System.Threading.Thread.Sleep(1000);
            ElectricMeasure electricMeasureNormal = new ElectricMeasure();

            #region 机械(或NPN)开关测试--打开


            RealTimeMsg msg33 = new RealTimeMsg();
            msg33.Name = "设置电输出目标值";
            item.AddRealTimeMsgs(msg33);
            //设置电输出目标值
            if (!item.GetDevice("P21").SetElectricSourceTarget(5))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "设置电输出目标值失败"));
                return result;
            }
            msg33.Content = "5V";

            RealTimeMsg msg32 = new RealTimeMsg(">>机械开关测试--有电压应该断开");
            item.AddRealTimeMsgs(msg32);
            while (true)
            {
                Thread.Sleep(1000);
                msg32.ContentRunning();
                if (!item.GetDevice("P21").GetCurrentElectricMeasure(out electricMeasureNormal))
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "读取当前电测测量值失败"));
                    return result;
                }
                if (electricMeasureNormal.MeasureFunction != ElectricMeasureFunction.SW)
                {
                    if (!item.GetDevice("P21").SetEleChannelItem_SW_Normal())
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "打开机械开关失败"));
                        return result;
                    }
                }
                if (!Convert.ToBoolean(Convert.ToInt32(electricMeasureNormal.MeasureValue)))
                {
                    rData[0].Value = msg32.Content = "√";
                    break;
                }
                else
                {
                    if (tryCount == 2)
                    {
                        rData[0].Value = "机械(或NPN)开关测试未通过";
                        result.AddTestErrMsgs(new ErrMsg(30004, "机械(或NPN)开关，5V下没断开，测试未通过"));
                        break;
                    }

                    if (++tryCount > 1)
                    {
                        //需要在这里对测量值是否为0进行判定，来决定要不要
                        item.AddRealTimeMsgs(new RealTimeMsg($"机械(或NPN)开关，5V下没断开，测试未通过。"));

                        bool? key1 = item.Parent.VM.OpenInfoConfirmWindow("电测线可能没接，请先使用测试线 连接设备与工装的SRC和MEAS插孔，红对红，黑对黑。\r\n点击确认，重新测试，否则测试失败。");
                        if (key1.HasValue && key1.Value)
                        {
                            goto trySW;
                        }

                        rData[0].Value = "机械(或NPN)开关测试未通过";
                        result.AddTestErrMsgs(new ErrMsg(30004, "机械(或NPN)开关，5V下没断开，测试未通过"));
                        break;
                    }

                }
            }
            #endregion 分开黑红测量插孔

            #region 机械开关测试--短接
            System.Threading.Thread.Sleep(1000);

            tryCount = 0;

            RealTimeMsg msg331 = new RealTimeMsg();
            msg331.Name = "设置电输出目标值";
            item.AddRealTimeMsgs(msg331);
            //设置电输出目标值
            if (!item.GetDevice("P21").SetElectricSourceTarget(0))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "设置电输出目标值失败"));
                return result;
            }
            msg331.Content = "0V";

            RealTimeMsg msg52 = new RealTimeMsg(">>机械开关测试--无电压应该导通");
            item.AddRealTimeMsgs(msg52);
            while (true)
            {
                msg52.ContentRunning();
                Thread.Sleep(1000);
                if (!item.GetDevice("P21").GetCurrentElectricMeasure(out electricMeasureNormal))
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "读取当前电测测量值失败"));
                    return result;
                }
                if (electricMeasureNormal.MeasureFunction != ElectricMeasureFunction.SW)
                {
                    if (!item.GetDevice("P21").SetEleChannelItem_SW_Normal())
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "打开机械开关失败"));
                        return result;
                    }
                }
                if (Convert.ToBoolean(Convert.ToInt32(electricMeasureNormal.MeasureValue)))
                {
                    rData[1].Value = msg52.Content = "√";
                    break;
                }
                else
                {
                    if (tryCount == 2)
                    {
                        rData[1].Value = "机械(或NPN)开关测试未通过";
                        result.AddTestErrMsgs(new ErrMsg(30004, "机械(或NPN)开关，0V下没导通，测试未通过"));
                        break;
                    }

                    if (++tryCount > 1)
                    {
                        //需要在这里对测量值是否为0进行判定，来决定要不要
                        item.AddRealTimeMsgs(new RealTimeMsg($"机械(或NPN)开关，0V下没导通，测试未通过。"));

                        bool? key1 = item.Parent.VM.OpenInfoConfirmWindow("电测线可能没接，请先使用测试线 连接设备与工装的SRC和MEAS插孔，红对红，黑对黑。\r\n点击确认，重新测试，否则测试失败。");
                        if (key1.HasValue && key1.Value)
                        {
                            goto trySW;
                        }

                        rData[1].Value = "机械(或NPN)开关测试未通过";
                        result.AddTestErrMsgs(new ErrMsg(30004, "机械(或NPN)开关，0V下没导通，测试未通过"));
                        break;
                    }
                }
                tryCount++;
            }
            #endregion 分开黑红测量插孔

            #endregion 机械测试

            item.AddRealTimeMsgs(new RealTimeMsg());

            #region PNP测试

            RealTimeMsg msg3 = new RealTimeMsg("打开PNP开关");
            item.AddRealTimeMsgs(msg3);

            if (!item.GetDevice("P21").SetEleChannelItem_SW_PNP())
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "打开PNP开关失败"));
                return result;
            }
            msg3.Content = "√";
            System.Threading.Thread.Sleep(1000);

            ElectricMeasure electricMeasurePNP = new ElectricMeasure();
            tryCount = 0;

            #region  PNP开关测试--闭合
            System.Threading.Thread.Sleep(1000);



            RealTimeMsg msg332 = new RealTimeMsg();
            msg332.Name = "设置电输出目标值";
            item.AddRealTimeMsgs(msg332);
            //设置电输出目标值
            if (!item.GetDevice("P21").SetElectricSourceTarget(5))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "设置电输出目标值失败"));
                return result;
            }
            msg332.Content = "5V";

            RealTimeMsg msg14 = new RealTimeMsg(">>PNP开关测试--有电压应该导通");
            item.AddRealTimeMsgs(msg14);
            while (true)
            {
                msg14.ContentRunning();

                Thread.Sleep(1000);

                if (!item.GetDevice("P21").GetCurrentElectricMeasure(out electricMeasurePNP))
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "读取当前电测测量值失败"));
                    return result;
                }
                if (electricMeasurePNP.MeasureFunction != ElectricMeasureFunction.SW)
                {
                    if (!item.GetDevice("P21").SetEleChannelItem_SW_NPN())
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "打开PNP开关失败"));
                        return result;
                    }
                }
                if (Convert.ToBoolean(Convert.ToInt32(electricMeasurePNP.MeasureValue)))
                {
                    rData[2].Value = msg14.Content = "√";
                    break;
                }
                else
                {
                    if (tryCount == 2)
                    {
                        rData[2].Value = "PNP开关未通过";
                        result.AddTestErrMsgs(new ErrMsg(30004, "PNP开关，有电压下没导通，测试未通过"));
                        break;
                    }

                    if (++tryCount > 1)
                    {
                        //需要在这里对测量值是否为0进行判定，来决定要不要
                        item.AddRealTimeMsgs(new RealTimeMsg($"机械(或NPN)开关，0V下没导通，测试未通过。"));

                        bool? key1 = item.Parent.VM.OpenInfoConfirmWindow("电测线可能没接，请先使用测试线 连接设备与工装的SRC和MEAS插孔，红对红，黑对黑。\r\n点击确认，重新测试，否则测试失败。");
                        if (key1.HasValue && key1.Value)
                        {
                            //这里是重试
