                        }

                        rData[2].Value = "PNP开关未通过";
                        result.AddTestErrMsgs(new ErrMsg(30004, "PNP开关，有电压下没导通，测试未通过"));
                        break;
                    }
                }
                tryCount++;
            }
            #endregion  输出黑红插孔与输入黑红插孔断开

            #region  PNP开关测试--断开
            System.Threading.Thread.Sleep(1000);


            RealTimeMsg msg334 = new RealTimeMsg();
            msg334.Name = "设置电输出目标值";
            item.AddRealTimeMsgs(msg334);
            //设置电输出目标值
            if (!item.GetDevice("P21").SetElectricSourceTarget(0))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "设置电输出目标值失败"));
                return result;
            }
            msg334.Content = "0V";

            RealTimeMsg msg24 = new RealTimeMsg(">>PNP开关测试--无电压应该断开");
            item.AddRealTimeMsgs(msg24);
            while (true)
            {
                msg24.ContentRunning();
                Thread.Sleep(1000);
                if (!item.GetDevice("P21").GetCurrentElectricMeasure(out electricMeasurePNP))
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "读取当前电测测量值失败"));
