                    rData[3].Value = msg24.Content = "√";
                    break;
                }
                else
                {

                    if (tryCount == 2)
                    {
                        rData[3].Value = "PNP开关测试未通过";
                        result.AddTestErrMsgs(new ErrMsg(30004, "PNP开关，无电压应该断开，测试未通过"));
                        break;
                    }

                    if (++tryCount > 1)
                    {
                        //需要在这里对测量值是否为0进行判定，来决定要不要
                        item.AddRealTimeMsgs(new RealTimeMsg($"机械(或NPN)开关，0V下没导通，测试未通过。"));

