    /// <summary>
    /// SD卡存储测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestStorageCardPrincipal(dynamic item)
    {
        Result<TextData> result = new Result<TextData>(true);
        result.Data = new TextData("读取内容");
        try
        {
            //获取参数
            if (item.Parameters == null)
            {
                result.AddTestErrMsgs(ErrMsg._10001);//添加错误信息
                return result;
            }
            TextParameter parameter = item.Parameters[0] as TextParameter;


            //获取条件
            if (item.Conditions == null)
            {
                result.AddTestErrMsgs(ErrMsg._10002);//添加错误信息
                return result;
            }
            TextCondition condition = item.Conditions[0] as TextCondition;


            item.ClearRealTimeMsgs();

            RealTimeMsg msg1 = new RealTimeMsg("读取SD卡状态");
            item.AddRealTimeMsgs(msg1);

            bool storageCardState = false;
            if (!item.GetDevice("P21").GetStorageCardState(out storageCardState))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "读取SD卡状态失败"));
                return result;
            }

            long[] size;
            if (!item.GetDevice("P21").GetStorageCardSize(out size))
            {
                result.AddTestErrMsgs(new ErrMsg(20001, "读取SD卡大小失败"));
                return result;
            }
            if (!storageCardState && size.Length < 2)
            {
                result.AddTestErrMsgs(new ErrMsg(30004, "SD卡识别错误"));
                return result;
            }

            msg1.Name = "SD卡状态";
            msg1.Content = string.Format("{0},总字节{1}", storageCardState ? "识别成功" : "未识别", Math.Round(size[1] / 1024.0 / 1024.0 / 1024.0, 2));
            //创建文件并写入数据

            RealTimeMsg msg2 = new RealTimeMsg("向SD卡添加文件Test.txt");
            item.AddRealTimeMsgs(msg2);
            if (!item.GetDevice("P21").AddDataToSD("Test1.txt", parameter.Value))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "向SD卡添加文件Test.txt(" + parameter.Value + ")失败"));
                return result;
            }

            msg2.Name = "写入内容";
            msg2.Content = parameter.Value;


            RealTimeMsg msg3 = new RealTimeMsg("读取SD卡文件Test.txt内容");
            item.AddRealTimeMsgs(msg3);

            string content;
            if (!item.GetDevice("P21").ReadDataFromSD("Test1.txt", out content))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "读取SD卡文件Test.txt内容失败"));
                return result;
            }
            msg3.Name = "读取内容";
            msg3.Content = content;


            result.Data.Value = content;
            if (condition.IsTrue(result.Data.Value))
            {
                result.Assert = true;
            }
            else
            {
                result.AddTestErrMsgs(new ErrMsg(30004, "写入内容与读取内容不一致"));
            }
            return result;
        }
        finally
        {
            if (item.GetDevice("P21").QuerySDCardfileExists("Test1.txt"))
            {
                bool? IsDelfile = item.GetDevice("P21").DelSDCardfile("Test1.txt");
                if (!IsDelfile.HasValue)
                {
                    //指定文件名的文件不存在

                }
                else if (!IsDelfile.Value)
                {
                    //未能正常执行删除指令
                    result.AddTestErrMsgs(new ErrMsg(20003, "未能正常执行删除指令！"));
                }
            }
        }
    }
    /// <summary>
    /// 系统板PA模块测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestPaModule(dynamic item)
    {
        Result<TextData> result = new Result<TextData>(true);
        result.Data = new TextData("PA");
        try
        {
            item.ClearRealTimeMsgs();

            int trynum = 1;

        tryagain:

            if (item.GetDevice("GZP21") != null)
                item.GetDevice("GZP21").SetPAState(OpenCloseState.Open);
            RealTimeMsg msg1 = new RealTimeMsg();
            msg1.Name = "电测档位切换PA变送器";
            item.AddRealTimeMsgs(msg1);
            if (!item.GetDevice("P21").SetEleChannelItem_PA())
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "与设备指令通讯有问题，电测档位切换PA变送器失败"));
                return result;
            }
            msg1.Content = "完成";
            System.Threading.Thread.Sleep(5000);
            RealTimeWatch watch = new RealTimeWatch();
            RealTimeMsg msg2 = new RealTimeMsg("开始搜索PA变送器");
            item.AddRealTimeMsgs(msg2);

            watch.RTMsg = msg2;
            watch.ReStart();
            if (!item.GetDevice("P21").SearchPA())
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "与设备指令通讯有问题，搜索PA变送器失败"));
                return result;
            }

            List<PAMassage> massage = new List<PAMassage>();

            for (int i = 0; i < 10; i++)
            {
                item.GetDevice("P21").GetPAMassage(out massage);
                if (massage != null && massage.Count > 0)
                    break;
                System.Threading.Thread.Sleep(1000);
            }

            watch.Stop();
            msg2.Content = "搜索结束";

            RealTimeMsg msg3 = new RealTimeMsg("获取搜索列表");
            item.AddRealTimeMsgs(msg3);

            if (massage == null || massage.Count() == 0)
            {
                if (trynum++ < 3)
                {
                    item.AddRealTimeMsgs(new RealTimeMsg("没有获取搜索列表，弹窗提示是否正确接好电测线，然后重新搜索。"));

                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("没有搜索到设备，电测线可能没接，请先使用测试线 连接设备与工装的SRC和MEAS插孔，红对红，黑对黑。\r\n点击确认，重新测试，否则测试失败。");

                    if (!key.HasValue || key != true)
                        return result.AddTestErrMsgs(new ErrMsg(30001, "没有搜索到设备，操作员手动中止"));

                    System.Threading.Thread.Sleep(5000);
                    goto tryagain;
                }
                return result.AddTestErrMsgs(new ErrMsg(20003, "没有搜索任何PA"));
            }

            watch.Close();
            msg3.Name = "搜索列表";
            msg3.Content = massage[0].toString();
            System.Threading.Thread.Sleep(1000);
            result.Data.Value = "Address(" + massage[0].Address + ")";
            RealTimeMsg msg4 = new RealTimeMsg();
            msg4.Name = "开始连接(默认连接第一个搜索到的PA变送器)";
            item.AddRealTimeMsgs(msg4);
            if (!item.GetDevice("P21").ConnectPA(massage[0].Address))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "与设备指令通讯有问题，连接PA变送器失败"));
                return result;
            }
            msg4.Content = "连接完成";
            System.Threading.Thread.Sleep(1000);

            RealTimeMsg msg5 = new RealTimeMsg();
            msg5.Name = "获取当前测试信息";
            item.AddRealTimeMsgs(msg5);
            ElectricMeasure electricMeasure = new ElectricMeasure();
            if (!item.GetDevice("P21").GetCurrentElectricMeasure(out electricMeasure))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "与设备指令通讯有问题，获取当前电测信息失败"));
                return result;
            }
            msg5.Content = electricMeasure.MeasureFunction + "档位:" + electricMeasure.MeasureValue + electricMeasure.Unit.ToString();
            result.Data.Value += " MeasureValue(" + electricMeasure.MeasureValue + ")";
            if (double.IsNaN(electricMeasure.MeasureValue) || electricMeasure.MeasureFunction != ElectricMeasureFunction.PA)
            {
                result.AddTestErrMsgs(new ErrMsg(30004, "当前PA传感器的测量值为空或者搜索到的不是PA传感器。"));
                return result;
            }
            return result;
        }
        finally
        {
            if (item.GetDevice("GZP21") != null)
            {
                item.GetDevice("GZP21").SetPAState(OpenCloseState.Close);
            }
        }
    }
    /// <summary>
    /// RTC时间测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic RTCTimeTest(dynamic item)
    {
        Result<DateTimeData> result = new Result<DateTimeData>(true);
        result.Data = new DateTimeData("写入时间");
        item.ClearRealTimeMsgs();
        RangeCondition TimeRange = item.Conditions[0] as RangeCondition;

        RealTimeMsg msg1 = new RealTimeMsg("写入日期与时间");
        item.AddRealTimeMsgs(msg1);

        DateTime computerTime = DateTime.Now;
        if (!item.GetDevice("P21").SetSystemTime(computerTime))
        {
            return result.AddTestErrMsgs(new ErrMsg(20003, "写入时间失败"));
        }

        if (!item.GetDevice("P21").SetSystemDate(computerTime))
        {
            return result.AddTestErrMsgs(new ErrMsg(20003, "写入日期失败"));
        }

        msg1.Content = computerTime.ToString();
        result.Data.Value = computerTime;

        RealTimeMsg msg12 = new RealTimeMsg("回读日期与时间");
        item.AddRealTimeMsgs(msg12);
        //回读
        if (!item.GetDevice("P21").GetDevSysDate(out DateTime ReadDT))
        {
            return result.AddTestErrMsgs(new ErrMsg(20003, "读取设备的日期时间失败"));
        }
        msg12.Content = $"{ReadDT}";

        RealTimeMsg msg123 = new RealTimeMsg("时间差值");
        item.AddRealTimeMsgs(msg123);
        var dtgap = (ReadDT - DateTime.Now).TotalSeconds;
        msg123.Content = $"{Math.Round(dtgap, 2)} s";

        if (!TimeRange.IsTrue(dtgap))
        {
            return result.AddTestErrMsgs(new ErrMsg(20003, $"设备的时间与刚写入的时间相差大{Math.Round(dtgap, 2)}s，时钟不准确"));
        }

        item.AddRealTimeMsgs(new RealTimeMsg());

        RealTimeMsg msg2 = new RealTimeMsg("设备重启");
        item.AddRealTimeMsgs(msg2);

        item.GetDevice("P21").SetReboot();
        item.GetDevice("P21").Close();
        item.GetDevice("P21").SetCommConfigEmpty();
        DateTime start = DateTime.Now;
        TimeSpan timeSpan = new TimeSpan();
        while (true)
        {
            timeSpan = DateTime.Now - start;
            msg2.Content = string.Format("等待25秒,判断重启,当前等待时间:{0}秒", Math.Round(timeSpan.TotalSeconds, 1));
            System.Threading.Thread.Sleep(1000);
            if (timeSpan.TotalSeconds > 25)
                break;
        }
        msg2.Content = "尝试设备通讯";

        RealTimeMsg msg3 = new RealTimeMsg("尝试打开设备通讯");
        item.AddRealTimeMsgs(msg3);
        int tryCount = 0;
        while (true)
        {
            tryCount++;
            System.Threading.Thread.Sleep(1000);
            if (!item.GetDevice("P21").Open())
            {
                if (tryCount < 10)
                {
                    msg3.Content = "通讯失败.重试";
                    continue;
                }
                else
                {
                    msg3.Content = "重启失败.";
                    item.Parent.VM.OpenInfoConfirmWindow("重启失败,请确认设备是否重启成功,若无异常,再重新测试!");
                    result.AddTestErrMsgs(new ErrMsg(20003, "RTC时间测试失败"));
                    return result;
                }
            }
            else
            {
                break;
            }
        }
        msg3.Content = "重新通讯成功,重启完成";

        RealTimeMsg msg4 = new RealTimeMsg("重启后设备时间");
        item.AddRealTimeMsgs(msg4);
        //回读
        if (!item.GetDevice("P21").GetDevSysDate(out ReadDT))
        {
            return result.AddTestErrMsgs(new ErrMsg(20003, "读取设备的日期时间失败"));
        }
        msg4.Content = $"{ReadDT}";
        item.AddRealTimeMsgs(new RealTimeMsg("电脑时间", DateTime.Now.ToString()));
        dtgap = (ReadDT - DateTime.Now).TotalSeconds;
        RealTimeMsg msg1234 = new RealTimeMsg("时间差值");
        item.AddRealTimeMsgs(msg1234);
        msg1234.Content = $"{Math.Round(dtgap, 2)} s";

        if (!TimeRange.IsTrue(dtgap))
        {
            return result.AddTestErrMsgs(new ErrMsg(20003, $"设备重启后的时间与电脑的时间相差大{Math.Round(dtgap, 2)}s，时钟不准确"));
        }
        return result;
    }
    /// <summary>
    /// 控制板电源测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestControllerBroadPower(dynamic item)
    {
        Result<TextData> result = new Result<TextData>(true);
        result.Data = new TextData("控制板电源状态");
        item.ClearRealTimeMsgs();

        RealTimeMsg msg1 = new RealTimeMsg();
        msg1.Name = "获取控制板电源状态";
        item.AddRealTimeMsgs(msg1);
        CheckState state = CheckState.UnKnown;
        if (!item.GetDevice("P21").GetControllerBroadPowerCheckState(out state))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "获取控制板电源状态失败"));
            return result;
        }
        result.Data.Value = msg1.Content = state.ToString();

        RealTimeMsg msg2 = new RealTimeMsg();
        msg2.Name = "验证控制板电源状态";
        item.AddRealTimeMsgs(msg2);
        if (state == CheckState.OK)
        {
            msg2.Content = "通过";
        }
        else
        {
            msg2.Content = "未通过";
            result.AddTestErrMsgs(new ErrMsg(30004, "控制板电源状态异常"));
        }
        return result;
    }
    /// <summary>
    /// NTC测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic NTCTest(dynamic item)
    {
        Result<List<TextData>> result = new Result<List<TextData>>(true);
        List<TextData> rData = new List<TextData>()
        {
            new TextData("电机温度")
        };
        result.Data = rData;

        item.ClearRealTimeMsgs();
        //获取条件
        if (item.Conditions == null)
        {
            result.AddTestErrMsgs(ErrMsg._10002);
            return result;
        }
        ValueCondition MachineTempratureTopLimit = item.Conditions[0] as ValueCondition;   //设定温度上限
        ValueCondition MachineTempratureLowLimit = item.Conditions[1] as ValueCondition;   //设定温度下限
        ValueCondition OverTempratureLowLimit = item.Conditions[2] as ValueCondition;      //超差温度下限
        ValueCondition OverTempratureTopLimit = item.Conditions[3] as ValueCondition;      //超差温度上限
        ValueCondition PressureTempratureLowLimit = item.Conditions[4] as ValueCondition;   //打压温度下限
        ValueCondition PressureTempratureTopLimit = item.Conditions[5] as ValueCondition;   //打压温度上限

        RealTimeMsg msg1 = new RealTimeMsg("获取电机温度");
        item.AddRealTimeMsgs(msg1);
        while (true)
        {
            msg1.ContentRunning();
            double motor_Temperature = double.NaN;
            if (item.GetDevice("P21").GetMotor_Temperature(out motor_Temperature))
            {
                msg1.Content = rData[0].Value = motor_Temperature.ToString("F2");
                if (MachineTempratureTopLimit.IsTrue(motor_Temperature) && MachineTempratureLowLimit.IsTrue(motor_Temperature))
                {
                    break;
                }
                else if (OverTempratureLowLimit.IsTrue(motor_Temperature) || OverTempratureTopLimit.IsTrue(motor_Temperature))
                {
                    result.AddTestErrMsgs(new ErrMsg(30004, "电机温度异常"));
                    break;
                }
                else
                {

                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("气泵是否打过压");
                    if (key.HasValue && key.Value && PressureTempratureLowLimit.IsTrue(motor_Temperature) && PressureTempratureLowLimit.IsTrue(motor_Temperature))
                    {
                        break;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(30004, "读取电机温度失败"));
                        break;
                    }
                }
            }
            else
            {
                bool? key = item.Parent.VM.OpenInfoConfirmWindow("读取电机温度失败,重试？");
                if (key.HasValue && key.Value)
                {
                    continue;
                }
                else
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "读取电机温度失败"));
                    return result;
                }
            }
        }
        return result;
    }
    /// <summary>
    /// 气泵测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic GasPumpTest(dynamic item)
    {
        item.GetDevice("P21").SetOpenMaxControlPressureSpeed(false);
        try
        {
            Result<List<DataBase>> result = new Result<List<DataBase>>(true);
            List<DataBase> rData = new List<DataBase>()
        {
            new TextData("正压泵测试电流值"),
            new TextData("正压传感器误差值"),
            new TextData("负压泵测试电流值"),
            new TextData("负压传感器误差值")
        };
            result.Data = rData;


            ValueData VP1 = new ValueData("正压控压压力变化", 0, "kPa");
            ListValueData VP1s = new ListValueData("正压控压压力变化");
            rData.Add(VP1s);

            ValueData VP2 = new ValueData("负压控压压力变化", 0, "kPa");
            ListValueData VP2s = new ListValueData("负压控压压力变化");
            rData.Add(VP2s);

            item.ClearRealTimeMsgs();
            //获取条件
            string orgDeviceMode = item.Root.DUT.DeviceMode;
            string controllerVersion;
            if (!item.GetDevice("P21").GetVersion_Controller(out controllerVersion))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "获取控制板版本失败"));
                return result;
            }
            if (item.Conditions == null)
            {
                result.AddTestErrMsgs(ErrMsg._10002);
                return result;
            }
            ValueCondition PositivePumpCurrentHigh;   //正压泵电流上限
            ValueCondition PositivePumpCurrentLow;    //正压泵电流下限

            ValueCondition PositivePumpTestTime;    //正压泵测试时间
            ValueCondition PositivePumpTestFranchise;    //正压泵测试超差标准
            ValueCondition NegativePumpTestTime;    //负压泵测试时间
            ValueCondition NegativePumpTestFranchise;    //负压泵测试超差标准


            ValueCondition PositiveControlTime;    //正压控压时间
            ValueCondition NegativeControlTime;     //负压控压时间

            RangeCondition PositivePressureRateRange;    //正压泵电流的压力比率范围
            RangeCondition NegativePressureRateRange;    //负压泵电流的压力比率范围
            RealTimeMsg msg_10MDevice = new RealTimeMsg("设备类型");
            item.AddRealTimeMsgs(msg_10MDevice);

            if (controllerVersion.Contains("MP") || controllerVersion.Contains("HP"))
            {
                if (orgDeviceMode.Contains("10M"))
                {
                    PositivePumpCurrentHigh = item.Conditions[1] as ValueCondition;   //正压泵电流上限
                    PositivePumpCurrentLow = item.Conditions[2] as ValueCondition;    //正压泵电流下限

                    PositivePumpTestTime = item.Conditions[4] as ValueCondition;    //正压泵测试时间
                    PositivePumpTestFranchise = item.Conditions[5] as ValueCondition;    //正压泵测试超差标准
                    NegativePumpTestTime = item.Conditions[6] as ValueCondition;    //负压泵测试时间
                    NegativePumpTestFranchise = item.Conditions[7] as ValueCondition;    //负压泵测试超差标准


                    PositiveControlTime = item.Conditions[8] as ValueCondition;    //正压控压时间
                    NegativeControlTime = item.Conditions[9] as ValueCondition;     //负压控压时间

                    PositivePressureRateRange = item.Conditions[10] as RangeCondition;    //正压泵电流的压力比率范围
                    NegativePressureRateRange = item.Conditions[11] as RangeCondition;    //负压泵电流的压力比率范围
                    msg_10MDevice.Content = $"当前设备类型:{orgDeviceMode},【正压泵电流上限】，【正压泵测试时间】指标将按照10M机型指标进行测试";
                    //PositivePumpCurrentHigh = item.Conditions[1] as ValueCondition;   //正压泵电流上限
                    msg_10MDevice.Content += $"\r\n当前正压泵电流上限为：{PositivePumpCurrentHigh}";
                    //PositivePumpTestTime = item.Conditions[4] as ValueCondition;//正压泵测试时间
                    msg_10MDevice.Content += $"\r\n当前正压泵测试时间为：{PositivePumpTestTime}";
                }
                else
                {
                    PositivePumpCurrentHigh = item.Conditions[0] as ValueCondition;   //正压泵电流上限
                    PositivePumpCurrentLow = item.Conditions[2] as ValueCondition;    //正压泵电流下限

                    PositivePumpTestTime = item.Conditions[3] as ValueCondition;    //正压泵测试时间
                    PositivePumpTestFranchise = item.Conditions[5] as ValueCondition;    //正压泵测试超差标准
                    NegativePumpTestTime = item.Conditions[6] as ValueCondition;    //负压泵测试时间
                    NegativePumpTestFranchise = item.Conditions[7] as ValueCondition;    //负压泵测试超差标准


                    PositiveControlTime = item.Conditions[8] as ValueCondition;    //正压控压时间
                    NegativeControlTime = item.Conditions[9] as ValueCondition;     //负压控压时间

                    PositivePressureRateRange = item.Conditions[10] as RangeCondition;    //正压泵电流的压力比率范围
                    NegativePressureRateRange = item.Conditions[11] as RangeCondition;    //负压泵电流的压力比率范围
                }
            }
            else
            {
                PositivePumpCurrentHigh = item.Conditions[0] as ValueCondition;   //正压泵电流上限
                PositivePumpCurrentLow = item.Conditions[1] as ValueCondition;    //正压泵电流下限

                PositivePumpTestTime = item.Conditions[2] as ValueCondition;    //正压泵测试时间
                PositivePumpTestFranchise = item.Conditions[3] as ValueCondition;    //正压泵测试超差标准
                NegativePumpTestTime = item.Conditions[4] as ValueCondition;    //负压泵测试时间
                NegativePumpTestFranchise = item.Conditions[5] as ValueCondition;    //负压泵测试超差标准


                PositiveControlTime = item.Conditions[6] as ValueCondition;    //正压控压时间
                NegativeControlTime = item.Conditions[7] as ValueCondition;     //负压控压时间

                PositivePressureRateRange = item.Conditions[8] as RangeCondition;    //正压泵电流的压力比率范围
                NegativePressureRateRange = item.Conditions[9] as RangeCondition;    //负压泵电流的压力比率范围
            }
            List<double> PositivePumpCurrents = new List<double>();
            List<double> NegativePumpCurrents = new List<double>();
            Pressure orgPressure = new Pressure(0, PressureUnit.kPa);
            double pumpAverageCurrent = 0;
            DateTime orgTime = DateTime.Now;
            List<double> lastCurrents = new List<double>();

            #region 参数初始化

            int PositivePressureTime = Convert.ToInt32(PositivePumpTestTime.Value);
            double PositiveFranchise = PositivePumpTestFranchise.Value;
            int NegativePressureTime = Convert.ToInt32(NegativePumpTestTime.Value);
            double NegativeFranchise = NegativePumpTestFranchise.Value;
            //输出压力的设定点上限
            Pressure controlRange_UpperLimitpressure = new Pressure(0, PressureUnit.kPa);
            //输出压力的设定点下限
            Pressure controlRange_LowerLimitpressure = new Pressure(0, PressureUnit.kPa);
            //内部模块压力值
            Pressure getInternalModulePressure = new Pressure(0, PressureUnit.kPa);
            //压力比率
            double rate = 0;
            #endregion
            //BP版不进行气泵正压测试
            if (!controllerVersion.Contains("BP"))
            {
                RealTimeMsg msg0 = new RealTimeMsg("正压泵测试");
                item.AddRealTimeMsgs(msg0);

                #region 气泵正压测试
                ErrMsg errMsg1 = new ErrMsg(30004, "正压泵测试泵电流超出范围");
                ErrMsg errMsg2 = new ErrMsg(30004, "传感器超差！正压测试失败");

                RealTimeMsg msg1 = new RealTimeMsg("读取正压输出压力的设定点上限");
                item.AddRealTimeMsgs(msg1);
                RealTimeMsg msg2 = new RealTimeMsg("气泵正压测试启动");
                item.AddRealTimeMsgs(msg2);
                RealTimeMsg msg4 = new RealTimeMsg("正压电流测试");
                item.AddRealTimeMsgs(msg4);
                RealTimeMsg msg6 = new RealTimeMsg("正压压力范围");
                item.AddRealTimeMsgs(msg6);
                RealTimeMsg msg5 = new RealTimeMsg("正压传感器测试");
                item.AddRealTimeMsgs(msg5);
                while (true)
                {
                    if (!item.IsRunning)
                    {
                        result.AddTestErrMsgs(new ErrMsg(00005, "测试被操作员手动终止"));
                        return result;
                    }
                    msg0.Content = "正压测试正在进行";
                    msg1.ContentRunning();
                    msg2.ContentRunning();
                    msg5.Content = "正压传感器测试未完成";

                    if (!item.GetDevice("P21").GetPressureControlRange_UpperLimit(out controlRange_UpperLimitpressure))
                    {
                        bool? key = item.Parent.VM.OpenInfoConfirmWindow("读取输出压力的设定点上限失败,重试？");
                        if (key.HasValue && key.Value)
                        {
                            continue;
                        }
                        else
                        {
                            result.AddTestErrMsgs(new ErrMsg(30004, "读取输出压力的设定点上限失败"));
                            return result;
                        }
                    }
                    (rData[0] as TextData).Value = msg1.Content = controlRange_UpperLimitpressure.ToString();
                    System.Threading.Thread.Sleep(500);


                    if (!item.GetDevice("P21").TestPositivePump(PositivePressureTime, PositiveFranchise))
                    {
                        bool? key = item.Parent.VM.OpenInfoConfirmWindow("气泵正压测试启动失败,重试？");
                        if (key.HasValue && key.Value)
                        {
                            continue;
                        }
                        else
                        {
                            result.AddTestErrMsgs(new ErrMsg(30004, "气泵正压测试启动失败"));
                            return result;
                        }
                    }
                    else
                    {
                        msg2.Content = "完成";
                        System.Threading.Thread.Sleep(500);

                        RealTimeMsg msg3 = new RealTimeMsg("获取气泵测试状态");
                        item.AddRealTimeMsgs(msg3);
                        DateTime starTime = DateTime.Now;

                        while (true)
                        {
                            if (!item.IsRunning)
                            {
                                result.AddTestErrMsgs(new ErrMsg(00005, "测试被操作员手动终止"));
                                return result;
                            }
                            //气泵测试
                            PumpTestState PumpTestState = new PumpTestState();
                            if (item.GetDevice("P21").GetPumpTestState(out PumpTestState))
                            {
                                if (PumpTestState.TestState == PumpTestProcessState.ShutDown)
                                {
                                    msg3.Content = "内部高量程模块的上限小于机型的泵能力上限的90%,泵测试中断";
                                    msg0.Content = "正压测试失败，设备返回的状态为 ShutDown";
                                    msg5.Content = "正压传感器测试未完成";
                                    result.AddTestErrMsgs(new ErrMsg(30004, "内部高量程模块的上限小于机型的泵能力上限的90%,泵测试中断"));
                                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("内部高量程模块的上限小于机型的泵能力上限的90%,泵测试中断");
                                    return result;
                                }
                                if (PumpTestState.TestState == PumpTestProcessState.Completed)
                                {
                                    msg3.Content = "完成，气泵测试完成，获取具体的子项的结果";
                                    //正压测试
                                    if (PumpTestState.PositivePresTest == PumpTestResultState.Failed)
                                    {
                                        msg0.Content = "但其中正压测试失败，设备返回的状态为 PumpTestResultState.Failed";
                                        result.AddTestErrMsgs(new ErrMsg(30004, "正压测试失败，设备返回的状态为 PumpTestResultState.Failed"));
                                        item.GetDevice("P21").TestPumpStop();
                                    }
                                    else if (PumpTestState.PositivePresTest == PumpTestResultState.NoFinished)
                                    {
                                        msg0.Content = "正压测试正在进行 NoFinished";
                                    }
                                    else
                                    {
                                        msg0.Content = "正压测试成功";
                                    }
                                    int trynum = 1;
                                tryagain:
                                    //传感器测试
                                    if (PumpTestState.PositivePersSensorTest == PumpTestResultState.Failed)
                                    {
                                        (rData[1] as TextData).Value = PumpTestState.PositiveSensorError.ToString("P");

                                        msg5.Content = string.Format(" 正压传感器已超差,误差为{0}", PumpTestState.PositiveSensorError.ToString("P"));
                                        if (!result.ErrMsgs.Contains(errMsg2))
                                        {
                                            result.AddTestErrMsgs(errMsg2);
                                        }
                                    }
                                    else if (PumpTestState.PositivePersSensorTest == PumpTestResultState.Succeed)
                                    {
                                        (rData[1] as TextData).Value = PumpTestState.PositiveSensorError.ToString("P");
                                        msg5.Content = string.Format(" 正压传感器未超差,误差为{0}", PumpTestState.PositiveSensorError.ToString("P"));
                                    }
                                    else
                                    {
                                        (rData[1] as TextData).Value = PumpTestState.PositiveSensorError.ToString("P");

                                        msg5.Content = "气泵测试已经结果，但返回的结果中，显示正压传感器测试进行中";
                                        if (++trynum < 3)
                                        {
                                            item.GetDevice("P21").GetPumpTestState(out PumpTestState);
                                            goto tryagain;
                                        }

                                    }
                                    break;
                                }

                                if (PumpTestState.TestState == PumpTestProcessState.InProgress)
                                {
                                    msg3.Content = "测试中 InProgress";
                                    System.Threading.Thread.Sleep(500);
                                    //电流测试
                                    item.GetDevice("P21").GetPressure_IPM(out getInternalModulePressure);

                                    VP1.Value = getInternalModulePressure.Value;
                                    VP1s.AppendAsync(VP1.WithDateTime());

                                    rate = getInternalModulePressure.Value / controlRange_UpperLimitpressure.Value;
                                    msg6.Content = string.Format("{0}(最小压力值)  < {1} < {2}(最大压力值)", controlRange_UpperLimitpressure.Value * PositivePressureRateRange.Lower, getInternalModulePressure.Value, controlRange_UpperLimitpressure.Value * PositivePressureRateRange.Upper);

                                    if (PositivePressureRateRange.IsTrue(rate))
                                    {
                                        if (Math.Abs(getInternalModulePressure.Value) > Math.Abs(orgPressure.Value))
                                        {
                                            if (PositivePumpCurrents.Count == 0)
                                            {
                                                orgTime = DateTime.Now;
                                            }
                                            if ((DateTime.Now - orgTime).TotalSeconds > 10)
                                            {
                                                orgPressure = getInternalModulePressure;
                                                double pumpCurrent = double.NaN;
                                                if (!item.GetDevice("P21").GetPumpCurrent(out pumpCurrent))
                                                {
                                                    msg4.Content = "读取泵电流失败";
                                                    result.AddTestErrMsgs(new ErrMsg(30004, "读取泵电流失败"));
                                                    return result;
                                                }
                                                pumpCurrent = Math.Abs(pumpCurrent);
                                                PositivePumpCurrents.Add(pumpCurrent);

                                                PositivePumpCurrents.RemoveAt(0);

                                                pumpAverageCurrent = 0;
                                                foreach (double dataItem in PositivePumpCurrents)
                                                {
                                                    pumpAverageCurrent += dataItem;
                                                }
                                                pumpAverageCurrent = pumpAverageCurrent / PositivePumpCurrents.Count;


                                                if (!PositivePumpCurrentLow.IsTrue(pumpAverageCurrent) || !PositivePumpCurrentHigh.IsTrue(pumpAverageCurrent))
                                                {
                                                    msg4.Content = string.Format("平均电流值(单位:A){0}(最小电流值)  < {1} < {2}(最大电流值)   泵电流超出范围", PositivePumpCurrentLow.Value, pumpAverageCurrent.ToString("F3"), PositivePumpCurrentHigh.Value);
                                                    if (!result.ErrMsgs.Contains(errMsg1))
                                                    {
                                                        result.AddTestErrMsgs(errMsg1);
                                                    }
                                                }
                                                else
                                                {
                                                    msg4.Content = string.Format("平均电流值(单位:A){0}(最小电流值)  < {1} < {2}(最大电流值)   电流值正常", PositivePumpCurrentLow.Value, pumpAverageCurrent.ToString("F3"), PositivePumpCurrentHigh.Value);
                                                }
                                            }
                                            else
                                            {
                                                orgPressure = getInternalModulePressure;
                                                double pumpCurrent = double.NaN;
                                                if (!item.GetDevice("P21").GetPumpCurrent(out pumpCurrent))
                                                {
                                                    msg4.Content = "读取泵电流失败";
                                                    result.AddTestErrMsgs(new ErrMsg(30004, "读取泵电流失败"));
                                                    return result;
                                                }
                                                pumpCurrent = Math.Abs(pumpCurrent);
                                                PositivePumpCurrents.Add(pumpCurrent);
                                                msg4.Content = string.Format("压力已达标,计时{0}秒", (DateTime.Now - orgTime).TotalSeconds);
                                            }
                                        }
                                    }
                                }
                            }
                            else
                            {
                                msg0.Content = "读取气泵正压测试状态失败";
                                bool? key = item.Parent.VM.OpenInfoConfirmWindow("读取气泵正压测试状态失败,重试？");
                                if (key.HasValue && key.Value)
                                {
                                    continue;
                                }
                                else
                                {
                                    result.AddTestErrMsgs(new ErrMsg(30004, "读取气泵正压测试状态失败"));
                                    return result;
                                }
                            }

                            TimeSpan span = DateTime.Now - starTime;
                            if (!PositiveControlTime.IsTrue(span.TotalSeconds))
                            {
                                msg0.Content = $"当前状态{PumpTestState.TestState}，还在测试中气泵正压测试{span.TotalSeconds} 超时 {PositiveControlTime}";
                                result.AddTestErrMsgs(new ErrMsg(30004, $"气泵正压测试{span.TotalSeconds} 超时 {PositiveControlTime}，请检查气泵是否正常工作"));
                                break;
                            }
                        }
                        break;
                    }
                }
                #endregion

                msg0.Content = "完成";
            }

            if(controllerVersion.Contains("BP"))
            {
                RealTimeMsg msg_BPDevice = new RealTimeMsg("当前设备类型");
                item.AddRealTimeMsgs(msg_BPDevice);
                msg_BPDevice.Content = $"当前设备类型:{orgDeviceMode},BP系列设备不进行正压气泵测试。";
                item.AddRealTimeMsgs(new RealTimeMsg());
            }

            item.AddRealTimeMsgs(new RealTimeMsg());

            ErrMsg errMsg3 = new ErrMsg(30004, "传感器超差！负压测试失败");
            (rData[0] as TextData).Value = String.Join("\r\n", PositivePumpCurrents);
            item.GetDevice("P21").SetVentMode();
            System.Threading.Thread.Sleep(10000);

            RealTimeMsg msg10 = new RealTimeMsg("负压泵测试");
            item.AddRealTimeMsgs(msg10);
            orgPressure = new Pressure(0, PressureUnit.kPa);
            #region 气泵负压测试
            RealTimeMsg msg11 = new RealTimeMsg("读取负压输出压力的设定点下限");
            item.AddRealTimeMsgs(msg11);
            RealTimeMsg msg12 = new RealTimeMsg("气泵负压测试启动");
            item.AddRealTimeMsgs(msg12);
            RealTimeMsg msg15 = new RealTimeMsg("负压传感器测试");
            item.AddRealTimeMsgs(msg15);
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(new ErrMsg(00005, "测试被操作员手动终止"));
                    return result;
                }
                msg10.Content = "负压测试正在进行";
                msg11.ContentRunning();
                msg12.ContentRunning();
                msg15.Content = "负压传感器测试未完成";

                if (!item.GetDevice("P21").GetPressureControlRange_LowerLimit(out controlRange_LowerLimitpressure))
                {
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("读取输出压力的设定点下限失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(30004, "读取输出压力的设定点下限失败"));
                        return result;
                    }
                }
                (rData[2] as TextData).Value = msg11.Content = controlRange_LowerLimitpressure.ToString();
                System.Threading.Thread.Sleep(500);


                if (!item.GetDevice("P21").TestNegativePump(NegativePressureTime, NegativeFranchise))
                {
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("气泵负压测试启动失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(30004, "气泵负压测试启动失败"));
                        return result;
                    }
                }
                else
                {
                    msg12.Content = "完成";
                    System.Threading.Thread.Sleep(500);
                    RealTimeMsg msg13 = new RealTimeMsg("获取气泵测试状态");
                    item.AddRealTimeMsgs(msg13);
                    DateTime starTime = DateTime.Now;

                    while (true)
                    {
                        if (!item.IsRunning)
                        {
                            result.AddTestErrMsgs(new ErrMsg(00005, "测试被操作员手动终止"));
                            return result;
                        }
                        //气泵测试
                        PumpTestState PumpTestState = new PumpTestState();
                        if (item.GetDevice("P21").GetPumpTestState(out PumpTestState))
                        {
                            if (PumpTestState.TestState == PumpTestProcessState.ShutDown)
                            {
                                msg13.Content = "内部高量程模块的上限小于机型的泵能力上限的90%,泵测试中断";
                                msg10.Content = "负压测试失败，设备返回的结果 ShutDown";
                                msg15.Content = "负压传感器测试未完成";
                                result.AddTestErrMsgs(new ErrMsg(30004, "内部高量程模块的上限小于机型的泵能力上限的90%,泵测试中断"));
                                bool? key = item.Parent.VM.OpenInfoConfirmWindow("内部高量程模块的上限小于机型的泵能力上限的90%,泵测试中断");
                                return result;
                            }
                            if (PumpTestState.TestState == PumpTestProcessState.Completed)
                            {
                                msg13.Content = "完成，气泵测试设备返回完成，开始获取具体子项的结果。";
                                //负压测试
                                if (PumpTestState.NegativePresTest == PumpTestResultState.Failed)
                                {
                                    msg10.Content = "负压测试失败，设备返回 的结果 PumpTestResultState.Failed";
                                    result.AddTestErrMsgs(new ErrMsg(30004, "负压测试失败"));
                                    item.GetDevice("P21").TestPumpStop();
                                }
                                else if (PumpTestState.NegativePresTest == PumpTestResultState.NoFinished)
                                {
                                    msg10.Content = "负压测试正在进行 NoFinished";
                                }
                                else
                                {
                                    msg10.Content = "负压测试成功";
                                }

                                //传感器测试
                                if (PumpTestState.NegativePresSensorTest == PumpTestResultState.Failed)
                                {
                                    (rData[3] as TextData).Value = PumpTestState.NegativeSensorError.ToString("P");

                                    msg15.Content = string.Format(" 负压传感器已超差,误差为{0}", PumpTestState.NegativeSensorError.ToString("P"));
                                    if (!result.ErrMsgs.Contains(errMsg3))
                                    {
                                        result.AddTestErrMsgs(errMsg3);
                                    }
                                }
                                else if (PumpTestState.NegativePresSensorTest == PumpTestResultState.Succeed)
                                {
                                    (rData[3] as TextData).Value = PumpTestState.NegativeSensorError.ToString("P");

                                    msg15.Content = string.Format(" 负压传感器未超差,误差为{0}", PumpTestState.NegativeSensorError.ToString("P"));
                                }
                                else
                                {
                                    (rData[3] as TextData).Value = PumpTestState.NegativeSensorError.ToString("P");
                                    msg15.Content = "负压测试已经结果，但负压传感器测试进行中";
                                }
                                break;
                            }

                            if (PumpTestState.TestState == PumpTestProcessState.InProgress)
                            {
                                msg13.Content = "测试中 InProgress";
                                //电流测试
                                item.GetDevice("P21").GetPressure_IPM(out getInternalModulePressure);
                                VP2.Value = getInternalModulePressure.Value;
                                VP2s.AppendAsync(VP2.WithDateTime());

                            }
                        }
                        else
                        {
                            msg10.Content = "读取气泵负压测试状态失败";
                            bool? key = item.Parent.VM.OpenInfoConfirmWindow("读取气泵负压测试状态失败,重试？");
                            if (key.HasValue && key.Value)
                            {
                                continue;
                            }
                            else
                            {
                                result.AddTestErrMsgs(new ErrMsg(30004, "读取气泵负压测试状态失败"));
                                return result;
                            }
                        }

                        TimeSpan span = DateTime.Now - starTime;
                        if (!NegativeControlTime.IsTrue(span.TotalSeconds))
                        {
                            msg10.Content = $"气泵负压测试{span.TotalSeconds}超时{NegativeControlTime}";
                            result.AddTestErrMsgs(new ErrMsg(30004, $"气泵负压测试{span.TotalSeconds}超时{NegativeControlTime}，请检查气泵是否正常工作"));
                            break;
                        }
                    }
                    break;
                }
            }
            #endregion
            msg10.Content = "完成";
            (rData[2] as TextData).Value = String.Join("\r\n", NegativePumpCurrents);


            return result;
        }
        finally
        {
            item.GetDevice("P21").TestPumpStop();
            item.GetDevice("P21").SetVentMode();
        }
    }
    /// <summary>
    /// 进气传感器校准
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestCalibrationSensor(dynamic item)
    {
        try
        {
            Result<TextData> result = new Result<TextData>(true);
            result.Data = new TextData("进气传感器校准");
            item.ClearRealTimeMsgs();
            int trynum = 0;

        tryagain:

            RealTimeMsg msg1 = new RealTimeMsg();
            msg1.Name = "开始进气传感器校准";
            item.AddRealTimeMsgs(msg1);
            if (!item.GetDevice("P21").CalibrationSensor())
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "指令执行失败，开始进气传感器校准失败"));
                return result;
            }
            msg1.Content = "已开始";


            RealTimeMsg msg2 = new RealTimeMsg();
            msg2.Name = "进气传感器校准";
            item.AddRealTimeMsgs(msg2);
            IntakeSensorCalibrationData state = new IntakeSensorCalibrationData();

            bool isFinished = false;
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(new ErrMsg(00005, "测试被操作员手动终止"));
                    return result;
                }
                if (!item.GetDevice("P21").GetCalibrationSensorState(out state))
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "指令执行失败，获取进气传感器校准状态失败"));
                    return result;
                }

                Task.Delay(1000).Wait();
                switch (state.ResultType)
                {
                    case CalibrationSensorStateTest.Complete:
                        msg2.Content = "校准完成";
                        item.GetDevice("P21").StopCalibrationSensor();
                        DateTime currentTime = DateTime.MinValue;
                        item.GetDevice("P21").GetSystemTime(out currentTime);
                        item.GetDevice("P21").SetCalibrationSensorDate(currentTime);
                        isFinished = true;
                        break;
                    case CalibrationSensorStateTest.Failed:
                        msg2.Content = "校准失败,校准过程异常,设备返回了异常的状态标识。";
                        item.GetDevice("P21").StopCalibrationSensor();
                        item.AddRealTimeMsgs(new RealTimeMsg("提示", "校准失败,校准过程异常"));
                        //result.AddTestErrMsgs(new ErrMsg(30004, "校准失败,校准过程异常"));
                        isFinished = true;
                        if (++trynum < 2)
                        {
                            item.GetDevice("P21").StopCalibrationSensor();
                            item.AddRealTimeMsgs(new RealTimeMsg("重试", $"第{trynum}次"));
                            Task.Delay(1000).Wait();
                            goto tryagain;
                        }
                        else
                        {
                            result.AddTestErrMsgs(new ErrMsg(30004, "校准失败,校准过程异常"));
                        }
                        item.Root.IsRunning = false;
                        break;
                    case CalibrationSensorStateTest.Process:
                        msg2.Content = string.Format("{0}%", state.ProcessValue);
                        break;
                    case CalibrationSensorStateTest.UnKnown:
                        msg2.Content = "校准未开始";
                        break;
                }
                if (isFinished)
                {
                    break;
                }
            }
            result.Data.Value = msg2.Content;

            return result;
        }
        finally
        {
            item.GetDevice("P21").StopCalibrationSensor();
            System.Threading.Thread.Sleep(1000);
            item.GetDevice("P21").SetVentMode();
            System.Threading.Thread.Sleep(10000);
        }
    }
    /// <summary>
    /// 加压流程测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestFlow(dynamic item)
    {
        try
        {
            Result<List<DataBase>> result = new Result<List<DataBase>>(true);

            List<DataBase> rData = new List<DataBase>()
            {
             new TextData("加压流程")
            };
            result.Data = rData;

            item.ClearRealTimeMsgs();

            //获取条件
            if (item.Conditions == null)
            {
                result.AddTestErrMsgs(ErrMsg._10002);
                return result;
            }
            //控压最大用时
            ValueCondition PressureFirst = item.Conditions[0] as ValueCondition;    //第一个压力值
            ValueCondition PressureSecond = item.Conditions[1] as ValueCondition;    //第二个压力值
            ValueCondition ControlErrorFirst = item.Conditions[2] as ValueCondition;    //第一个压力值允差
            ValueCondition ControlErrorSecond = item.Conditions[3] as ValueCondition;    //第二个压力值允差
            ValueCondition ControlTime = item.Conditions[4] as ValueCondition;    //待机时间(S)



            Pressure PressureFirstValue = new Pressure(PressureFirst.Value, PressureUnit.kPa);
            Pressure PressureSecondValue = new Pressure(PressureSecond.Value, PressureUnit.kPa);
            Pressure pressure = new Pressure(0, PressureUnit.kPa);

            item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_H, OpenCloseState.Open);
            item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_L, OpenCloseState.Open);

            #region 切换高压量程
            RealTimeMsg msg10 = new RealTimeMsg(">>切换高压量程");
            item.AddRealTimeMsgs(msg10);
            while (true)
            {
                msg10.ContentRunning();
                if (item.GetDevice("P21").SetControlPressureModel(PressureSwitchTripType.High))
                {
                    msg10.Content = "完成";
                    break;
                }
                msg10.Content = "失败";
                bool? key = item.Parent.VM.OpenInfoConfirmWindow("切换高压量程失败,重试？");
                if (key.HasValue && key.Value)
                {
                    continue;
                }
                else
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "切换高压量程失败"));
                    return result;
                }
            }
            System.Threading.Thread.Sleep(2000);
            msg10.Content = "√";
            #endregion

            #region 设置内部模块单位
            RealTimeMsg msg1H = new RealTimeMsg("设置内部模块单位");
            item.AddRealTimeMsgs(msg1H);
            while (true)
            {
                msg1H.ContentRunning();
                if (item.GetDevice("P21").SetPressureUnit_IPM())
                {
                    msg1H.Content = "√";
                    break;
                }
                msg1H.Content = "失败";
                bool? key = item.Parent.VM.OpenInfoConfirmWindow("设定内部模块压力单位失败,重试？");
                if (key.HasValue && key.Value)
                {
                    continue;
                }
                else
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "设置内部模块单位通讯失败"));
                    return result;
                }
            }
            #endregion

            RealTimeMsg msg1 = new RealTimeMsg(string.Format(">>控压{0}", PressureFirstValue.ToString()));
            item.AddRealTimeMsgs(msg1);
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(new ErrMsg(00005, "测试被操作员手动终止"));
                    return result;
                }
                if (!item.GetDevice("P21").SetTargetPressure(PressureFirstValue))
                {
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("设定" + PressureFirstValue.ToString() + "压力值失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "设定压力点失败"));
                        return result;
                    }
                }
                else
                {
                    break;
                }
            }

            ValueData VP1 = new ValueData("控压压力变化", 0, "kPa");
            ListValueData VP1s = new ListValueData("控压压力变化");
            result.Data.Add(VP1s);

            RealTimeMsg msg02 = new RealTimeMsg("当前模块波动度与稳定时间");
            item.AddRealTimeMsgs(msg02);
            if (!item.GetDevice("P21").GetControllerModuleConfig(out string ControlState))
            {
                return result.AddTestErrMsgs(new ErrMsg(20003, "获取当前模块波动度与稳定时间失败"));
            }
            msg02.Content = ControlState;
            DateTime StarTimePressUp = DateTime.Now;
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(new ErrMsg(00005, "测试被操作员手动终止"));
                    item.IsRunning = false;
                    item.Root.IsRunning = false;
                    return result;
                }
                item.GetDevice("P21").GetPressure_IPM(out pressure);
                msg1.Content = pressure.ToString();


                VP1.Value = pressure.Value;
                VP1s.AppendAsync(VP1.WithDateTime());
                System.Threading.Thread.Sleep(500);

                if (pressure > new Pressure(PressureFirstValue.Value * ControlErrorFirst.Value, PressureUnit.kPa))
                {
                    msg1.Content = pressure.ToString() + $"   √ 耗时{(DateTime.Now - StarTimePressUp).TotalSeconds} s";

                    break;
                }
            }

            StarTimePressUp = DateTime.Now;
            RealTimeMsg msg2 = new RealTimeMsg(">>切测量模式");
            item.AddRealTimeMsgs(msg2);

            #region 切测量状态
            System.Threading.Thread.Sleep(2000);
            RealTimeMsg msg5 = new RealTimeMsg("设置控制器测量模式");
            item.AddRealTimeMsgs(msg5);
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }

                if (item.GetDevice("P21").SetTestMode())
                {
                    break;
                }
                bool? key = item.Parent.VM.OpenInfoConfirmWindow("设置控制器测量模式失败,重试？");
                if (key.HasValue && key.Value)
                {
                    continue;
                }
                else
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "设置控制器测量模式失败"));
                    return result;
                }
            }
            msg5.Content = "完成";
            #endregion

            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(new ErrMsg(00005, "测试被操作员手动终止"));
                    return result;
                }
                TimeSpan firstSpan = DateTime.Now - StarTimePressUp;
                double span = Math.Round(firstSpan.TotalSeconds, 2);

                item.GetDevice("P21").GetPressure_IPM(out pressure);
                msg2.Content = string.Format(" 时间{0}s   压力{1}", Math.Round(span, 3), pressure.ToString());
                if (!ControlTime.IsTrue(span))
                {
                    break;
                }
            }


            item.AddRealTimeMsgs(new RealTimeMsg());

            RealTimeMsg msg3 = new RealTimeMsg(string.Format(">>控压{0}", PressureSecondValue.ToString()));
            item.AddRealTimeMsgs(msg3);
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(new ErrMsg(00005, "测试被操作员手动终止"));
                    return result;
                }
                if (!item.GetDevice("P21").SetTargetPressure(PressureSecondValue))
                {
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("设定" + PressureSecondValue.ToString() + "压力值失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "设定压力点失败"));
                        return result;
                    }
                }
                else
                {
                    break;
                }
            }


            StarTimePressUp = DateTime.Now;
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(new ErrMsg(00005, "测试被操作员手动终止"));
                    item.IsRunning = false;
                    item.Root.IsRunning = false;
                    return result;
                }
                item.GetDevice("P21").GetPressure_IPM(out pressure);
                msg3.Content = pressure.ToString();
                VP1.Value = pressure.Value;
                VP1s.AppendAsync(VP1.WithDateTime());
                System.Threading.Thread.Sleep(500);
                if (pressure < new Pressure(ControlErrorSecond.Value, PressureUnit.kPa))
                {
                    msg3.Content = pressure.ToString() + $"   √ 耗时{(DateTime.Now - StarTimePressUp).TotalSeconds} s";
                    break;
                }
            }

            #region 切测量状态
            System.Threading.Thread.Sleep(2000);
            RealTimeMsg msg6 = new RealTimeMsg("设置控制器测量模式");
            item.AddRealTimeMsgs(msg6);
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }

                if (item.GetDevice("P21").SetTestMode())
                {
                    break;
                }
                bool? key = item.Parent.VM.OpenInfoConfirmWindow("设置控制器测量模式失败,重试？");
                if (key.HasValue && key.Value)
                {
                    continue;
                }
                else
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "设置控制器测量模式失败"));
                    return result;
                }
            }
            msg6.Content = "完成";
            #endregion
            StarTimePressUp = DateTime.Now;
            while (true)
            {
                TimeSpan firstSpan = DateTime.Now - StarTimePressUp;
                double span = firstSpan.TotalSeconds;

                item.GetDevice("P21").GetPressure_IPM(out pressure);
                msg6.Content = string.Format("时间{0}秒   压力{1}", Math.Round(span, 3), pressure.ToString());
                if (!ControlTime.IsTrue(span))
                {
                    break;
                }
            }
            return result;

        }
        finally
        {
            item.GetDevice("P21").SetVentMode();
            Xmas11.Comm.Data.Common.PressureStableState state = Xmas11.Comm.Data.Common.PressureStableState.UnKnown;

            while (true)
            {
                if (item.GetDevice("P21").GetPressureStableState(out state) && state == PressureStableState.Stable)
                {
                    break;
                }
            }
            item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_H, OpenCloseState.Close);
            item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_L, OpenCloseState.Close);
        }
    }
    /// <summary>
    /// 自整定
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestSelfTuning(dynamic item)
    {
        try
        {
            Result<TextData> result = new Result<TextData>(true);
            result.Data = new TextData("自整定");
            item.ClearRealTimeMsgs();
            int trynum = 1;
        tryagain:
            System.Threading.Thread.Sleep(3000);

            RealTimeMsg msg111 = new RealTimeMsg("电池电量");
            item.AddRealTimeMsgs(msg111);
            if (!item.GetDevice("P21").GetBatteryValue(out double Bval))
                return result.AddTestErrMsgs(new ErrMsg(30001, "获取电池电量失败"));
            msg111.Content = $"{Math.Round(Bval, 2) * 100}%";

            RealTimeMsg msg1 = new RealTimeMsg();
            msg1.Name = "开始自整定";
            item.AddRealTimeMsgs(msg1);
            if (!item.GetDevice("P21").SelfTuning())
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "指令执行异常，启动自整定失败"));
                return result;
            }
            msg1.Content = "已开始";


            RealTimeMsg msg2 = new RealTimeMsg();
            msg2.Name = "自整定";
            item.AddRealTimeMsgs(msg2);
            SelfTuningData state = new SelfTuningData();
            System.Threading.Thread.Sleep(3000);

            bool isFinished = false;
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(new ErrMsg(00005, "测试被操作员手动终止"));
                    return result;
                }
                if (!item.GetDevice("P21").GetSelfTuningState(out state))
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "获取自整定状态失败"));
                    return result;
                }

                switch (state.ResultType)
                {
                    case SelfTuningTestType.Completed:
                        msg2.Content = "自整定完成";
                        item.GetDevice("P21").StopSelfTuning();
                        DateTime currentTime = DateTime.MinValue;
                        item.GetDevice("P21").GetSystemTime(out currentTime);
                        item.GetDevice("P21").SetCalibrationAutoDate(currentTime);
                        isFinished = true;
                        break;
                    case SelfTuningTestType.Failed:
                        if (trynum++ < 2)
                        {
                            item.GetDevice("P21").StopSelfTuning();
                            goto tryagain;
                        }
                        msg2.Content = "设备返回了失败的标志，自整定没有完成，自整定过程异常";
                        item.GetDevice("P21").StopSelfTuning();
                        result.AddTestErrMsgs(new ErrMsg(30004, "自整定失败,自整定过程异常"));
                        item.Root.IsRunning = false;
                        isFinished = true;
                        break;
                    case SelfTuningTestType.InProgress:
                        msg2.Content = string.Format("自整定状态{0}%  ;\r\n 设定点:{1}  ;\r\n进气阀控制量:{2}  ;\r\n放气阀控制量:{3}\r\n", state.ProcessValue, state.SetPoint, state.IntakeValveControls, state.OuttakeValveControls);
                        break;
                    case SelfTuningTestType.Unknown:
                        msg2.Content = "自整定未开始";
                        break;
                }
                if (isFinished)
                {
                    break;
                }
            }
            result.Data.Value = msg2.Content;

            return result;
        }
        finally
        {
            RealTimeMsg msg111 = new RealTimeMsg("电池电量");
            item.AddRealTimeMsgs(msg111);
            item.GetDevice("P21").GetBatteryValue(out double Bval);
            msg111.Content = $"{Math.Round(Bval, 2) * 100}%";

            item.GetDevice("P21").StopSelfTuning();
            if (item.Root.DUT.DeviceMode == "ConST811AD" || item.Root.DUT.DeviceMode == "ConST811AL")
            {
                item.Parent.VM.OpenInfoConfirmWindow(string.Format("当前设备为{0}型号,\r\n请拧上侧面参考端堵头（中间那个）。\r\n拧上后，再点击确认进行下一项测试。", item.Root.DUT.DeviceMode == "ConST811AD" ? "差压" : "微差压"));
            }
        }
    }


    /// <summary>
    /// 自整定
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public string TestSelfTuningMH(dynamic item)
    {
        string R1 = "";
        try
        {
            item.AddRealTimeMsgs(new RealTimeMsg());
            RealTimeMsg msg1 = new RealTimeMsg();
            msg1.Name = "开始自整定";
            item.AddRealTimeMsgs(msg1);
            if (!item.GetDevice("P21").SelfTuning())
            {
                R1 = "指令执行异常，启动自整定失败";
            }
            msg1.Content = "已开始";


            RealTimeMsg msg2 = new RealTimeMsg();
            msg2.Name = "自整定";
            item.AddRealTimeMsgs(msg2);
            SelfTuningData state = new SelfTuningData();
            System.Threading.Thread.Sleep(3000);

            bool isFinished = false;
            while (true)
            {
                if (!item.IsRunning)
                {
                    R1 = "测试被操作员手动终止";
                }
                if (!item.GetDevice("P21").GetSelfTuningState(out state))
                {
                    R1 = "获取自整定状态失败";
                }

                switch (state.ResultType)
                {
                    case SelfTuningTestType.Completed:
                        msg2.Content = "自整定完成";
                        item.GetDevice("P21").StopSelfTuning();
                        DateTime currentTime = DateTime.MinValue;
                        item.GetDevice("P21").GetSystemTime(out currentTime);
                        item.GetDevice("P21").SetCalibrationAutoDate(currentTime);
                        isFinished = true;
                        break;
                    case SelfTuningTestType.Failed:
                        msg2.Content = "设备返回了失败的标志，自整定没有完成，自整定过程异常";
                        item.GetDevice("P21").StopSelfTuning();
                        item.Root.IsRunning = false;
                        isFinished = true;
                        R1 = msg2.Content;
                        break;
                    case SelfTuningTestType.InProgress:
                        msg2.Content = string.Format("自整定状态{0}%  ;\r\n 设定点:{1}  ;\r\n进气阀控制量:{2}  ;\r\n放气阀控制量:{3}\r\n", state.ProcessValue, state.SetPoint, state.IntakeValveControls, state.OuttakeValveControls);
                        break;
                    case SelfTuningTestType.Unknown:
                        msg2.Content = "自整定未开始";
                        break;
                }
                if (isFinished)
                {
                    break;
                }
            }
        }
        finally
        {
            item.GetDevice("P21").StopSelfTuning();
        }
        return R1;

    }


    /// <summary>
    /// 压力控制测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic PressureControlTest(dynamic item)
    {
        try
        {
            Result<List<TextData>> result = new Result<List<TextData>>(true);
            item.ClearRealTimeMsgs();
            //获取条件
            if (item.Conditions == null)
            {
                result.AddTestErrMsgs(ErrMsg._10002);
                return result;
            }
            //控压最大用时
            ValueCondition PositivePressControlTime2 = item.Conditions[4] as ValueCondition;    //正压5%HP->105%HP控压时间
            ValueCondition PositivePressControlTime = item.Conditions[0] as ValueCondition;    //正压控压时间
            ValueCondition NegativePressControlTime2 = item.Conditions[5] as ValueCondition;    //负压5%HP->105%HP控压时间
            ValueCondition NegativePressControlTime = item.Conditions[1] as ValueCondition;    //负压控压时间

            ValueCondition PositivePressControlToleranceValue = item.Conditions[2] as ValueCondition;    //正压设定点控压允差
            ValueCondition NegativePressControlToleranceValue = item.Conditions[3] as ValueCondition;    //负压设定点控压允差
            ValueCondition ZeroPressControlToleranceValue = item.Conditions[6] as ValueCondition;    //0%设定点控压允差
            #region 初始化参数
            int j = 0;
            int i = 0;
            double resultValue = double.NaN;
            Pressure setInnerPressure = new Pressure(0, PressureUnit.kPa);
            Pressure InnerModulePressureUpper = new Pressure(0, PressureUnit.kPa);
            Pressure InnerModulePressureLowerer = new Pressure(0, PressureUnit.kPa);
            double pressureStabilityValue = 0.003; //压力稳定误差
            DateTime StarTimePressUp = DateTime.Now; //正压起始时间
            DateTime StarTimePressDown = DateTime.Now; //负压起始时间
            List<double> postiveSetPoint = new List<double>() { 0, 0.05, 1, 0.95, 0 };   //正压设定点上限的百分比
            List<double> negativeSetPoint = new List<double>() { 0, 0.05, 1, 0.9, 0 };  //负压设定点下限的百分比
            bool isControlLangRange = false;
            #endregion
            int IsAddTime = 0;
            bool isagain = false;
            bool isReset = false;
            RealTimeMsg msg111 = new RealTimeMsg("电池电量");
            item.AddRealTimeMsgs(msg111);
            if (!item.GetDevice("P21").GetBatteryValue(out double Bval))
                return result.AddTestErrMsgs(new ErrMsg(30001, "获取电池电量失败"));
            msg111.Content = $"{Math.Round(Bval, 2) * 100}%";

            item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_H, OpenCloseState.Open);
            item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_L, OpenCloseState.Open);
            if (item.GetDevice("P21").IsDoubleRange())
            {
                item.AddRealTimeMsgs(new RealTimeMsg("双量程"));
                List<TextData> rData = new List<TextData>()
                {
                new TextData("低压模块量程上限"),
                new TextData("低压模块设定点下限"),
                new TextData("高压模块量程上限"),
                new TextData("高压模块设定点下限")
                 };
                result.Data = rData;

                int tryAgainCount = 0;
            tryagain1:
                tryAgainCount++;
                if (!isagain)
                    IsAddTime = 0;
                item.GetDevice("P21").SetVentMode();
                System.Threading.Thread.Sleep(3000);
                #region 切换低压量程
                RealTimeMsg msg0 = new RealTimeMsg(">>切换低压量程");
                item.AddRealTimeMsgs(msg0);
                while (true)
                {
                    msg0.ContentRunning();
                    if (item.GetDevice("P21").SetControlPressureModel(PressureSwitchTripType.Low))
                    {
                        msg0.Content = "完成";
                        break;
                    }
                    msg0.Content = "失败";
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("切换低压量程失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "切换低压量程失败"));
                        return result;
                    }
                }
                System.Threading.Thread.Sleep(5000);

                msg0.Content = "完成";
                #endregion

                #region 低压测试

                #region 设置内部模块单位
                RealTimeMsg msg1 = new RealTimeMsg("设置内部模块单位kPa");
                item.AddRealTimeMsgs(msg1);
                while (true)
                {
                    msg1.ContentRunning();
                    if (item.GetDevice("P21").SetPressureUnit_IPM())
                    {
                        msg1.Content = "完成";
                        break;
                    }
                    msg1.Content = "失败";
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("设定内部模块压力单位失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "设置内部模块单位通讯失败"));
                        return result;
                    }
                }
                #endregion

                #region 设置压力稳定度
                RealTimeMsg msg4 = new RealTimeMsg("设置压力稳定度");
                item.AddRealTimeMsgs(msg4);
                while (true)
                {
                    msg4.ContentRunning();
                    if (!item.GetDevice("P21").SetPressureStability(pressureStabilityValue))
                    {
                        msg4.Content = "失败";
                        bool? key = item.Parent.VM.OpenInfoConfirmWindow("设置压力稳定度失败,重试？");
                        if (key.HasValue && key.Value)
                        {
                            continue;
                        }
                        else
                        {
                            result.AddTestErrMsgs(new ErrMsg(20003, "设置压力稳定度失败"));
                            return result;
                        }
                    }
                    else
                    {
                        msg4.Content = "完成";
                        break;
                    }
                }
                #endregion

                #region 设置控压速率
                RealTimeMsg msg3 = new RealTimeMsg("设置控压速率最大");
                item.AddRealTimeMsgs(msg3);
                while (true)
                {
                    msg3.ContentRunning();
                    if (!item.GetDevice("P21").SetOpenMaxControlPressureSpeed(false))
                    {
                        msg3.Content = "失败";
                        bool? key = item.Parent.VM.OpenInfoConfirmWindow("设置控压速率失败,重试？");
                        if (key.HasValue && key.Value)
                        {
                            continue;
                        }
                        else
                        {
                            result.AddTestErrMsgs(new ErrMsg(20003, "设置控压速率失败"));
                            return result;
                        }
                    }
                    else
                    {
                        msg3.Content = "完成";
                        break;
                    }
                }
                #endregion

                #region 获取内部模块正压满量程
                RealTimeMsg msg2 = new RealTimeMsg(">>获取内部模块正压满量程");
                item.AddRealTimeMsgs(msg2);
                while (true)
                {
                    msg2.ContentRunning();
                    if (!item.GetDevice("P21").GetPressureControlRange_UpperLimit(out InnerModulePressureUpper))
                    {
                        msg2.Content = "失败";
                        bool? key = item.Parent.VM.OpenInfoConfirmWindow("获取内部模块正压满量程失败,重试？");
                        if (key.HasValue && key.Value)
                        {
                            continue;
                        }
                        else
                        {
                            result.AddTestErrMsgs(new ErrMsg(20003, "获取内部模块正压满量程失败"));
                            return result;
                        }
                    }
                    else
                    {
                        msg2.Content = rData[0].Value = InnerModulePressureUpper.ToString();
                        break;
                    }

                }
                #endregion

                #region 正压控压过程
                while (true)
                {
                    if (!item.IsRunning)
                    {
                        result.AddTestErrMsgs(new ErrMsg(00005, "测试被操作员手动终止"));
                        return result;
                    }
                    if (i < postiveSetPoint.Count)
                    {
                        StarTimePressUp = DateTime.Now;
                        item.GetDevice("P21").GetPressureControlRange_UpperLimit(out InnerModulePressureUpper);
                        resultValue = InnerModulePressureUpper.Value * postiveSetPoint[i];
                        RealTimeMsg msg6 = new RealTimeMsg(string.Format("压力点 {0} ", postiveSetPoint[i] + "*FS"));
                        item.AddRealTimeMsgs(msg6);
                        msg6.Content = string.Format("{0}{1}", resultValue, InnerModulePressureUpper.Unit);
                        setInnerPressure = new Pressure(resultValue, InnerModulePressureUpper.Unit);
                        if (!item.GetDevice("P21").SetTargetPressure(setInnerPressure))
                        {
                            bool? key = item.Parent.VM.OpenInfoConfirmWindow("设定" + msg6.Content + "压力值失败,重试？");
                            if (key.HasValue && key.Value)
                            {
                                continue;
                            }
                            else
                            {
                                result.AddTestErrMsgs(new ErrMsg(20003, "设定压力点失败"));
                                return result;
                            }
                        }
                    }
                    if (postiveSetPoint[i] == 1)
                    {
                        isControlLangRange = true;
                    }
                    else
                    {
                        isControlLangRange = false;
                    }
                    RealTimeMsg msg5 = new RealTimeMsg("控压情况");
                    item.AddRealTimeMsgs(msg5);
                    while (true)
                    {

                        PressureStableState state = PressureStableState.UnKnown;
                        Pressure pressure = new Pressure(0, PressureUnit.kPa);
                        item.GetDevice("P21").GetPressure_IPM(out pressure);

                        double rate = 0;
                        if (resultValue != 0)
                        {
                            rate = Math.Abs(pressure.Value / resultValue);
                        }

                        var limitValue = Math.Abs(pressure.Value - resultValue) / (resultValue == 0 ? InnerModulePressureUpper.Value : resultValue) * 100;
                        var limitResult = resultValue == 0 ? ZeroPressControlToleranceValue.IsTrue(limitValue) : PositivePressControlToleranceValue.IsTrue(limitValue);
                        if (!item.GetDevice("P21").GetPressureStableState(out state) || state != PressureStableState.Stable || !limitResult)
                        {
                            TimeSpan firstSpan = DateTime.Now - StarTimePressUp;
                            double span = firstSpan.TotalSeconds;
                            if (isControlLangRange)
                            {
                                if (!PositivePressControlTime2.IsTrue(span - IsAddTime))
                                {
                                    msg5.Content = string.Format("控压失败！{0}{1}压力点控压时间超过{2}", resultValue, InnerModulePressureUpper.Unit, PositivePressControlTime2.Value + PositivePressControlTime2.Unit);

                                    if (rate < 0.95)
                                    {
                                        item.AddRealTimeMsgs(new RealTimeMsg($"打压超时{span}", $"当前压力为{pressure}不到目标值的95 %，直接停止测试。"));
                                        item.IsRunning = false;
                                        item.Root.IsRunning = false;
                                        result.AddTestErrMsgs(new ErrMsg(30004, string.Format("控压失败！{0}{1}压力点控压时间超过{2}", resultValue, InnerModulePressureUpper.Unit, PositivePressControlTime2.Value + PositivePressControlTime2.Unit)));
                                        return result;
                                    }

                                    if (IsAddTime == 30)
                                    {
                                        item.AddRealTimeMsgs(new RealTimeMsg($"打压超时{span}", $"当前压力为{pressure}时间延长后还是没到目标点，准备自整定。"));
                                        //这里进行自整定
                                        var R1 = TestSelfTuningMH(item);
                                        if (string.IsNullOrWhiteSpace(R1))
                                        {
                                            isagain = true;
                                            goto tryagain1;
                                        }
                                        else
                                        {
                                            item.AddRealTimeMsgs(new RealTimeMsg($"控压{resultValue}", $"尝试自整定，但整定失败{R1}，中止测试。"));
                                            result.AddTestErrMsgs(new ErrMsg(30004, $"尝试自整定，但整定失败{R1}，中止测试。"));

                                            item.IsRunning = false;
                                            item.Root.IsRunning = false;
                                            return result;
                                        }
                                    }
                                    else
                                    {
                                        if (isagain)
                                        {
                                            item.AddRealTimeMsgs(new RealTimeMsg($"打压超时{span}", $"当前压力为{pressure}达到目标值的95%以上，重试还是没有稳定。"));
                                            item.AddRealTimeMsgs(new RealTimeMsg($"控压{resultValue}", $"已经重试，但控压失败，中止测试。"));
                                            item.IsRunning = false;
                                            item.Root.IsRunning = false;
                                            return result.AddTestErrMsgs(new ErrMsg(30004, $"已经重试，但控压失败，中止测试。"));
                                        }
                                        else
                                        {
                                            item.AddRealTimeMsgs(new RealTimeMsg($"打压超时{span}", $"当前压力为{pressure}达到目标值的95%以上，增加30s控压时间。"));
                                            isagain = true;
                                            IsAddTime = 30;
                                            continue;
                                        }
                                    }

                                    i++;
                                    break;
                                }
                                //else
                                //{
                                //    if (IsAddTime == 30)
                                //    {
                                //        goto tryagain1;
                                //    }
                                //}
                            }
                            else
                            {
                                if (!PositivePressControlTime.IsTrue(span - IsAddTime))
                                {
                                    msg5.Content = string.Format("控压失败！{0}{1}压力点控压时间为 {2} s,应为{3}", resultValue, InnerModulePressureUpper.Unit, span.ToString("F2"), PositivePressControlTime2.Value + PositivePressControlTime2.Unit);

                                    if (resultValue == 0)
                                    {
                                        if (IsAddTime == 30)
                                        {
                                            item.AddRealTimeMsgs(new RealTimeMsg($"打压超时{span}", $"当前压力为{pressure}，已经增加时间直接停止测试。"));
                                            item.IsRunning = false;
                                            item.Root.IsRunning = false;
                                            result.AddTestErrMsgs(new ErrMsg(30004, string.Format("控压失败！{0}{1}压力点控压时间超过{2}", resultValue, InnerModulePressureUpper.Unit, PositivePressControlTime.Value + PositivePressControlTime.Unit)));
                                            return result;
                                        }
                                        else
                                        {
                                            if (isagain)
                                            {
                                                item.AddRealTimeMsgs(new RealTimeMsg($"打压超时{span}", $"当前压力为{pressure}，已经重试，直接停止测试。"));
                                                item.IsRunning = false;
                                                item.Root.IsRunning = false;
                                                return result.AddTestErrMsgs(new ErrMsg(30004, $"已经重试，但控压失败，中止测试。"));
                                            }

                                            item.AddRealTimeMsgs(new RealTimeMsg($"打压超时{span}", $"当前压力为{pressure}，增加30s控压时间。"));
                                            isagain = true;
                                            IsAddTime = 30;
                                            continue;
                                        }
                                    }
                                    else
                                    {
                                        if (rate < 0.95)
