    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic PressureControlTest_BP(dynamic item)
    {
        try
        {
            Result<List<TextData>> result = new Result<List<TextData>>(true);
            item.ClearRealTimeMsgs();
            System.Threading.Thread.Sleep(500);
            //获取条件
            if (item.Conditions == null)
            {
                result.AddTestErrMsgs(ErrMsg._10002);
                return result;
            }
            //控压最大用时
            ValueCondition PositivePressControlTime2 = item.Conditions[4] as ValueCondition;    //正压5%HP->105%HP控压时间
            ValueCondition PositivePressControlTime = item.Conditions[0] as ValueCondition;    //正压控压时间
            ValueCondition NegativePressControlTime2 = item.Conditions[5] as ValueCondition;    //负压5%HP->105%HP控压时间
            ValueCondition NegativePressControlTime = item.Conditions[1] as ValueCondition;    //负压控压时间
            ValueCondition PositivePressControlToleranceValue = item.Conditions[2] as ValueCondition;    //正压设定点控压允差
            ValueCondition NegativePressControlToleranceValue = item.Conditions[3] as ValueCondition;    //负压设定点控压允差
            #region 初始化参数
            int j = 0;
            int i = 0;
            double resultValue = double.NaN;
            Pressure setInnerPressure = new Pressure(0, PressureUnit.kPa);
            Pressure InnerModulePressureUpper = new Pressure(0, PressureUnit.kPa);
            Pressure InnerModulePressureLowerer = new Pressure(0, PressureUnit.kPa);
            double pressureStabilityValue = 0.003; //压力稳定误差
            DateTime StarTimePressUp = DateTime.Now; //正压起始时间
            DateTime StarTimePressDown = DateTime.Now; //负压起始时间
            List<double> postiveSetPoint = new List<double>() { 0, 0.05, 1, 0.95 };   //正压设定点 0，5%FS，100%，95%
            List<double> negativeSetPoint = new List<double>() { 0.05, 1, 0.9 };  //负压设定点0，5%-FS,-FS,90%-FS,0
            bool isControlLangRange = false;
            #endregion

            item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_H, OpenCloseState.Open);
            item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_L, OpenCloseState.Open);
            List<TextData> rData = new List<TextData>()
        {
            new TextData("内部模块量程上限"),
            new TextData("内部模块设定点下限")
        };
            result.Data = rData;

            #region 设置内部模块单位
            RealTimeMsg msg1 = new RealTimeMsg("设置内部模块单位");
            item.AddRealTimeMsgs(msg1);
            while (true)
            {
                msg1.ContentRunning();
                if (item.GetDevice("P21").SetPressureUnit_IPM())
                {
                    msg1.Content = "完成";
                    break;
                }
                msg1.Content = "失败";
                bool? key = item.Parent.VM.OpenInfoConfirmWindow("设定内部模块压力单位失败,重试？");
                if (key.HasValue && key.Value)
                {
                    continue;
                }
                else
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "设置内部模块单位通讯失败"));
                    return result;
                }
            }
            #endregion

            #region 设置压力稳定度
            RealTimeMsg msg4 = new RealTimeMsg("设置压力稳定度");
            item.AddRealTimeMsgs(msg4);
            while (true)
            {
                msg4.ContentRunning();
                if (!item.GetDevice("P21").SetPressureStability(pressureStabilityValue))
                {
                    msg4.Content = "失败";
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("设置压力稳定度失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "设置压力稳定度失败"));
                        break;
                    }
                }
                else
                {
                    msg4.Content = "完成";
                    break;
                }
            }
            #endregion

            #region 设置控压速率
            RealTimeMsg msg3 = new RealTimeMsg("设置控压速率");
            item.AddRealTimeMsgs(msg3);
            while (true)
            {
                msg3.ContentRunning();
                if (!item.GetDevice("P21").SetOpenMaxControlPressureSpeed(false))
                {
                    msg3.Content = "失败";
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("设置控压速率失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "设置控压速率失败"));
                        break;
                    }
                }
                else
                {
                    msg3.Content = "完成";
                    break;
                }
            }
            #endregion

            #region 获取内部模块正压满量程
            RealTimeMsg msg2 = new RealTimeMsg(">>获取内部模块正压满量程");
            item.AddRealTimeMsgs(msg2);
            while (true)
            {
                msg2.ContentRunning();
                if (!item.GetDevice("P21").GetPressureControlRange_UpperLimit(out InnerModulePressureUpper))
                {
                    msg2.Content = "失败";
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("获取内部模块正压满量程失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "获取内部模块正压满量程失败"));
                        return result;
                    }
                }
                else
                {
                    msg2.Content = rData[0].Value = InnerModulePressureUpper.ToString();
                    break;
                }

            }
            #endregion

            #region 正压控压过程
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(new ErrMsg(00005, "测试被操作员手动终止"));
                    return result;
                }
                if (i < postiveSetPoint.Count)
                {
                    StarTimePressUp = DateTime.Now;
                    item.GetDevice("P21").GetPressureControlRange_UpperLimit(out InnerModulePressureUpper);
                    resultValue = Math.Floor((100 + (InnerModulePressureUpper.Value - 100) * postiveSetPoint[i]));
                    RealTimeMsg msg6 = new RealTimeMsg(string.Format("压力点{0}", postiveSetPoint[i] + "*FS"));
                    item.AddRealTimeMsgs(msg6);
                    msg6.Content = string.Format("{0}{1}", resultValue, InnerModulePressureUpper.Unit);
                    setInnerPressure = new Pressure(resultValue, InnerModulePressureUpper.Unit);
                    if (!item.GetDevice("P21").SetTargetPressure(setInnerPressure))
                    {
                        bool? key = item.Parent.VM.OpenInfoConfirmWindow("设定" + msg6.Content + "压力值失败,重试？");
                        if (key.HasValue && key.Value)
                        {
                            continue;
                        }
                        else
                        {
                            result.AddTestErrMsgs(new ErrMsg(20003, "设定压力点失败"));
                            break;
                        }
                    }
                }
                if (postiveSetPoint[i] == 1)
                {
                    isControlLangRange = true;
                }
                else
                {
                    isControlLangRange = false;
                }
                RealTimeMsg msg5 = new RealTimeMsg("控压情况");
                item.AddRealTimeMsgs(msg5);
                while (true)
                {

                    PressureStableState state = PressureStableState.UnKnown;
                    Pressure pressure = new Pressure(0, PressureUnit.kPa);
                    item.GetDevice("P21").GetPressure_IPM(out pressure);
                    if (!item.GetDevice("P21").GetPressureStableState(out state) || state != PressureStableState.Stable || !PositivePressControlToleranceValue.IsTrue(Math.Abs(pressure.Value - resultValue)))
                    {
                        TimeSpan firstSpan = DateTime.Now - StarTimePressUp;
                        double span = firstSpan.TotalSeconds;
                        if (isControlLangRange)
                        {
                            if (!PositivePressControlTime2.IsTrue(span))
                            {
                                msg5.Content = string.Format("控压失败！{0}{1}压力点控压时间超过{2}", resultValue, InnerModulePressureUpper.Unit, PositivePressControlTime2.Value + PositivePressControlTime2.Unit);
                                result.AddTestErrMsgs(new ErrMsg(30004, string.Format("控压失败！{0}{1}压力点控压时间超过{2}", resultValue, InnerModulePressureUpper.Unit, PositivePressControlTime2.Value + PositivePressControlTime2.Unit)));
                                i++;
                                break;
                            }
                        }
                        else
                        {
                            if (!PositivePressControlTime.IsTrue(span))
                            {
                                msg5.Content = string.Format("控压失败！{0}{1}压力点控压时间超过{2}", resultValue, InnerModulePressureUpper.Unit, PositivePressControlTime.Value + PositivePressControlTime.Unit);
                                result.AddTestErrMsgs(new ErrMsg(30004, string.Format("控压失败！{0}{1}压力点控压时间超过{2}", resultValue, InnerModulePressureUpper.Unit, PositivePressControlTime.Value + PositivePressControlTime.Unit)));
                                i++;
                                break;
                            }
                        }
                    }
                    else
                    {
                        TimeSpan firstSpan = DateTime.Now - StarTimePressUp;
                        double span = firstSpan.TotalSeconds;
                        if (isControlLangRange)
                        {
                            if (!PositivePressControlTime2.IsTrue(span))
                            {
                                msg5.Content = string.Format("控压失败！{0}{1}压力点控压时间为{2}秒,应为{3}", resultValue, InnerModulePressureUpper.Unit, span.ToString("F2"), PositivePressControlTime2.Value + PositivePressControlTime2.Unit);
                                result.AddTestErrMsgs(new ErrMsg(30004, string.Format("控压失败！{0}{1}压力点控压时间为{2}秒,应为{3}", resultValue, InnerModulePressureUpper.Unit, span.ToString("F2"), PositivePressControlTime2.Value + PositivePressControlTime2.Unit)));

                            }
                            else
                            {
                                msg5.Content = string.Format("控压成功！{0}{1}压力点控压时间为{2}秒,应为{3}", resultValue, InnerModulePressureUpper.Unit, span.ToString("F2"), PositivePressControlTime2.Value + PositivePressControlTime2.Unit);
                            }
                        }
                        else
                        {
                            if (!PositivePressControlTime.IsTrue(span))
                            {
                                msg5.Content = string.Format("控压失败！{0}{1}压力点控压时间为{2}秒,应为{3}", resultValue, InnerModulePressureUpper.Unit, span.ToString("F2"), PositivePressControlTime.Value + PositivePressControlTime.Unit);
                                result.AddTestErrMsgs(new ErrMsg(30004, string.Format("控压失败！{0}{1}压力点控压时间为{2}秒,应为{3}", resultValue, InnerModulePressureUpper.Unit, span.ToString("F2"), PositivePressControlTime.Value + PositivePressControlTime.Unit)));

                            }
                            else
                            {
                                msg5.Content = string.Format("控压成功！{0}{1}压力点控压时间为{2}秒,应为{3}", resultValue, InnerModulePressureUpper.Unit, span.ToString("F2"), PositivePressControlTime.Value + PositivePressControlTime.Unit);
                            }
                        }
                        i++;
                        break;
                    }
                    System.Threading.Thread.Sleep(500);
                }
                if (i >= postiveSetPoint.Count)
                    break;
            }
            item.GetDevice("P21").SetVentMode();
            #endregion

            #region 获取内部模块设定点下限
            RealTimeMsg msg12 = new RealTimeMsg(">>获取内部模块量程下限");
            item.AddRealTimeMsgs(msg12);
            while (true)
            {
                if (!item.GetDevice("P21").GetPressureControlRange_LowerLimit(out InnerModulePressureLowerer))
                {
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("获取内部模块量程下限失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "获取内部模块量程下限失败，任务中断"));
                        return result;
                    }
                }
                else
                {
                    rData[1].Value = msg12.Content = InnerModulePressureLowerer.ToString();
                    break;
                }

            }
            #endregion

            Pressure modelLowerLimit = new Pressure(0, PressureUnit.kPa);
            item.GetDevice("P21").GetPressureLowerer_IPM(out modelLowerLimit);

            #region 负压控压过程
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(new ErrMsg(00005, "测试被操作员手动终止"));
                    return result;
                }
                if (j < negativeSetPoint.Count)
                {
                    StarTimePressDown = DateTime.Now;
                    resultValue = Math.Ceiling(100 + (InnerModulePressureLowerer.Value - 100) * negativeSetPoint[j]);
                    RealTimeMsg msg6 = new RealTimeMsg(string.Format("压力点{0}", negativeSetPoint[j] + "*FS"));
                    item.AddRealTimeMsgs(msg6);
                    msg6.Content = string.Format("{0}{1}", resultValue.ToString("F2"), InnerModulePressureLowerer.Unit.ToString());
                    setInnerPressure = new Pressure(resultValue, InnerModulePressureLowerer.Unit);
                    if (!item.GetDevice("P21").SetTargetPressure(setInnerPressure))
                    {
                        bool? key = item.Parent.VM.OpenInfoConfirmWindow("设定" + msg6.Content + "压力值失败,重试？");
                        if (key.HasValue && key.Value)
                        {
                            continue;
                        }
                        else
                        {
                            result.AddTestErrMsgs(new ErrMsg(20003, "设定压力点失败"));
                            break;
                        }
                    }
                }
                else
                    break;
                if (negativeSetPoint[j] == 1)
                {
                    isControlLangRange = true;
                }
                else
                {
                    isControlLangRange = false;
                }
                RealTimeMsg msg5 = new RealTimeMsg("控压情况");
                item.AddRealTimeMsgs(msg5);
                while (true)
                {

                    Xmas11.Comm.Data.Common.PressureStableState state = Xmas11.Comm.Data.Common.PressureStableState.UnKnown;
                    Xmas11.Domain.Mechanics.Pressure pressure = new Pressure(0, PressureUnit.kPa);
                    item.GetDevice("P21").GetPressure_IPM(out pressure);
                    if (!item.GetDevice("P21").GetPressureStableState(out state) || state != PressureStableState.Stable || !NegativePressControlToleranceValue.IsTrue(Math.Abs(pressure.Value - resultValue)))
                    {
                        TimeSpan firstSpan = DateTime.Now - StarTimePressDown;
                        double span = firstSpan.TotalSeconds;
                        if (isControlLangRange)
                        {
                            if (!NegativePressControlTime2.IsTrue(span))
                            {
                                msg5.Content = string.Format("控压失败！{0}{1}压力点控压时间超过{2}", resultValue, InnerModulePressureLowerer.Unit, NegativePressControlTime2.Value + NegativePressControlTime2.Unit);
                                result.AddTestErrMsgs(new ErrMsg(30004, string.Format("控压失败！{0}{1}压力点控压时间超过{2}", resultValue, InnerModulePressureLowerer.Unit, NegativePressControlTime2.Value + NegativePressControlTime2.Unit)));
                                j++;
                                break;
                            }
                        }
                        else
                        {
                            if (!NegativePressControlTime.IsTrue(span))
                            {
                                msg5.Content = string.Format("控压失败！{0}{1}压力点控压时间超过{2}", resultValue, InnerModulePressureLowerer.Unit, NegativePressControlTime.Value + NegativePressControlTime.Unit);
                                result.AddTestErrMsgs(new ErrMsg(30004, string.Format("控压失败！{0}{1}压力点控压时间超过{2}", resultValue, InnerModulePressureLowerer.Unit, NegativePressControlTime.Value + NegativePressControlTime.Unit)));
                                j++;
                                break;
                            }
                        }
                    }
                    else
                    {
                        TimeSpan firstSpan = DateTime.Now - StarTimePressDown;
                        double span = firstSpan.TotalSeconds;
                        if (isControlLangRange)
                        {
                            if (!NegativePressControlTime2.IsTrue(span))
                            {
                                msg5.Content = string.Format("控压失败！{0}{1}压力点控压时间为{2}秒,应为{3}", resultValue, InnerModulePressureLowerer.Unit, span.ToString("F2"), NegativePressControlTime2.Value + NegativePressControlTime2.Unit);
                                result.AddTestErrMsgs(new ErrMsg(30004, string.Format("控压失败！{0}{1}压力点控压时间为{2}秒,应为{3}", resultValue, InnerModulePressureLowerer.Unit, span.ToString("F2"), NegativePressControlTime2.Value + NegativePressControlTime2.Unit)));

                            }
                            else
                            {
                                msg5.Content = string.Format("控压成功！{0}{1}压力点控压时间为{2}秒,应为{3}", resultValue, InnerModulePressureLowerer.Unit, span.ToString("F2"), NegativePressControlTime2.Value + NegativePressControlTime2.Unit);
                            }
                        }
                        else
                        {
                            if (!NegativePressControlTime.IsTrue(span))
                            {
                                msg5.Content = string.Format("控压失败！{0}{1}压力点控压时间为{2}秒,应为{3}", resultValue, InnerModulePressureLowerer.Unit, span.ToString("F2"), NegativePressControlTime.Value + NegativePressControlTime.Unit);
                                result.AddTestErrMsgs(new ErrMsg(30004, string.Format("控压失败！{0}{1}压力点控压时间为{2}秒,应为{3}", resultValue, InnerModulePressureLowerer.Unit, span.ToString("F2"), NegativePressControlTime.Value + NegativePressControlTime.Unit)));

                            }
                            else
                            {
                                msg5.Content = string.Format("控压成功！{0}{1}压力点控压时间为{2}秒,应为{3}", resultValue, InnerModulePressureLowerer.Unit, span.ToString("F2"), NegativePressControlTime.Value + NegativePressControlTime.Unit);
                            }
                        }
                        j++;
                        break;
                    }
                    System.Threading.Thread.Sleep(100);
                }
            }
            item.GetDevice("P21").SetVentMode();
            #endregion


            System.Threading.Thread.Sleep(1000);

            return result;

        }
        finally
        {
            item.GetDevice("P21").SetOpenMaxControlPressureSpeed(false);
            item.GetDevice("P21").SetVentMode();
            item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_H, OpenCloseState.Close);
            item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_L, OpenCloseState.Close);
        }
    }
    #region BP泄露
    /// <summary>
    /// 压力泄露测试及压力排空测试--BP单量程
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic LeakTestSingle_BP(dynamic item)
    {
        Result<List<TextData>> result = new Result<List<TextData>>(true);
        List<TextData> rData = new List<TextData>()
        {
            new TextData("上限30秒泄露率"),
            new TextData("正压气源压力30秒泄露率"),
            new TextData("下限30秒泄露率"),
            new TextData("负压气源压力30秒泄露率"),
            new TextData("上限30秒泄露量(新)"),
            new TextData("正压气源压力30秒泄露量(新)"),
            new TextData("下限30秒泄露量(新)"),
            new TextData("负压气源压力30秒泄露量(新)"),
             new TextData("压力值与温度值")
        };
        result.Data = rData;
        StringBuilder tvalue = new StringBuilder(1024);
        tvalue.Append("压力值,高压温度,低压温度,泵温度,电测板温度^");
        string tstr = "";

        try
        {
            item.ClearRealTimeMsgs();
            System.Threading.Thread.Sleep(500);
            //获取条件
            if (item.Conditions == null)
            {
                result.AddTestErrMsgs(ErrMsg._10002);
                return result;
            }
            ValueCondition PositivePressureVelocity30S = item.Conditions[0] as ValueCondition;  //正压30秒速率
            ValueCondition PositiveSupplyVelocity30S = item.Conditions[1] as ValueCondition;  //正压气源30秒速率
            ValueCondition NegativePressureVelocity30S = item.Conditions[2] as ValueCondition;  //负压30秒速率
            ValueCondition NegativeSupplyVelocity30S = item.Conditions[3] as ValueCondition;  //负压气源30秒速率

            ValueCondition PositiveControlTime = item.Conditions[4] as ValueCondition;  //正压控稳时间
            ValueCondition NegativeControlTime = item.Conditions[5] as ValueCondition;  //负压控稳时间

            RangeCondition VentPressureValue = item.Conditions[6] as RangeCondition;  //排空后压力
            if (VentPressureValue is null)
                VentPressureValue = item.Conditions[9] as RangeCondition;  //排空后压力

            item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_H, OpenCloseState.Open);
            item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_L, OpenCloseState.Open);
            double DevicePressureRange = double.MinValue;

            Pressure getInternalModulePressureOrg = new Pressure(0, PressureUnit.kPa);
            Pressure AtmosSensor = new Pressure(0, PressureUnit.kPa);
            item.GetDevice("P21").GetAtmosSensor(out AtmosSensor);
            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region 设置内部模块单位
            RealTimeMsg msg1 = new RealTimeMsg("设置内部模块单位");
            item.AddRealTimeMsgs(msg1);
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg1.ContentRunning();
                if (item.GetDevice("P21").SetPressureUnit_IPM())
                {
                    msg1.Content = "完成";
                    break;
                }
                msg1.Content = "失败";
                bool? key = item.Parent.VM.OpenInfoConfirmWindow("设定内部模块压力单位失败,重试？");
                if (key.HasValue && key.Value)
                {
                    continue;
                }
                else
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "设置内部模块单位通讯失败"));
                    return result;
                }
            }
            msg1.Content = "完成";
            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region 获取模块压力量程
            RealTimeMsg msg2 = new RealTimeMsg("获取压力控制量程范围");
            item.AddRealTimeMsgs(msg2);
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg2.ContentRunning();
                PressureRange pressureRange = new PressureRange();
                if (item.GetDevice("P21").GetSetPointLimitPressureRange(out pressureRange))
                {
                    DevicePressureRange = Math.Abs(pressureRange.LowerValue) + Math.Abs(pressureRange.UpperValue);
                    msg2.Content = pressureRange.ToString();
                }
                else
                {
                    msg2.Content = "失败";
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("获取压力控制量程范围失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "获取压力控制量程范围失败"));
                        return result;
                    }
                }
                break;
            }

            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region 正压
            Pressure InnerModulePressureUpper = new Pressure(0, PressureUnit.kPa);//量程上限
            Pressure getInternalModulePressure30SFirst = new Pressure(0, PressureUnit.kPa);
            Pressure getInternalModulePressure30SSecond = new Pressure(0, PressureUnit.kPa);
            Pressure getSourcePressure30SFirst = new Pressure(0, PressureUnit.kPa);
            Pressure getSourcePressure30SSecond = new Pressure(0, PressureUnit.kPa);
            double positiveinternalPressureRate = double.MaxValue;
            double positiveSupplyPressureRate = double.MaxValue;

            #region 获取内部模块量程上限
            RealTimeMsg msg3 = new RealTimeMsg("获取内部模块量程上限");
            item.AddRealTimeMsgs(msg3);
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg3.ContentRunning();
                if (!item.GetDevice("P21").GetPressureControlRange_UpperLimit(out InnerModulePressureUpper))
                {
