                item.GetDevice("P21").GetPressureStableState(out state);
                rate = Math.Abs((getInternalModulePressureOrg.Value - InnerModulePressureUpper.Value) / InnerModulePressureUpper.Value);

                if (item.GetDevice("P21").GetPressure_IPM(out getInternalModulePressureOrg) && state == PressureStableState.Stable && rate <= 0.05)
                {
                    msg4.Content = "打压完成";
                    TimeSpan firstSpan = DateTime.Now - starTime;
                    double span = firstSpan.TotalSeconds;
                    if (!PositiveControlTime.IsTrue(span))
                    {
                        msg4.Content = string.Format("打压失败");
                        result.AddTestErrMsgs(new ErrMsg(30004, "打压失败 "));
                        return result;
                    }
                    else
                    {
                        msg4.Content = string.Format("控压成功！");
                    }

                    break;
                }
                else
                {
                    TimeSpan firstSpan = DateTime.Now - starTime;
                    double span = firstSpan.TotalSeconds;
                    if (!PositiveControlTime.IsTrue(span))
                    {
                        msg4.Content = string.Format("打压失败");
                        result.AddTestErrMsgs(new ErrMsg(30004, "打压失败"));
                        return result;
                        break;
                    }
                }
            }
            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region 切测量状态
            System.Threading.Thread.Sleep(2000);

            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                if (item.GetDevice("P21").SetTestMode())
                {
                    break;
                }
                bool? key = item.Parent.VM.OpenInfoConfirmWindow("设置控制器测量模式失败,重试？");
                if (key.HasValue && key.Value)
                {
                    continue;
                }
                else
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "设置控制器测量模式失败"));
                    break;
                }
            }
            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region 计时30秒
            RealTimeMsg msg6 = new RealTimeMsg("计时30秒时间显示");
            item.AddRealTimeMsgs(msg6);
            DateTime positive30S = DateTime.Now;
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }

                TimeSpan timeSpan = DateTime.Now - positive30S;
                msg6.Content = string.Format("总共用时30秒，当前用时{0}秒", timeSpan.TotalSeconds.ToString("F2"));
                if (WaitTimeP.IsTrue(timeSpan.TotalSeconds))
                {
                    break;
                }
                System.Threading.Thread.Sleep(50);
            }
            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region 读正压模块压力30秒第一个值

            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                if (item.GetDevice("P21").GetPressure_IPM(out getInternalModulePressure30SFirst))
                {
                    break;
                }
                else
                {
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("获取内部模块压力失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "获取内部模块压力失败"));
                        break;
                    }
                }
            }



            #endregion

            #region 读正压气源压力30秒后第一个值
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                if (!item.GetDevice("P21").GetSupplyPressure(out getSourcePressure30SFirst))//30秒前正压气源值
                {
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("获取正压气源压力失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "获取正压气源压力失败"));
                        break;
                    }
                }
                else
                {
                    break;
                }
            }
            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region 计时30秒
            RealTimeMsg msg8 = new RealTimeMsg("计时30秒时间显示");
            item.AddRealTimeMsgs(msg8);
            positive30S = DateTime.Now;
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }

                TimeSpan timeSpan = DateTime.Now - positive30S;
                msg8.Content = string.Format("总共用时30秒，当前用时{0}秒", timeSpan.TotalSeconds.ToString("F2"));
                if (timeSpan.TotalSeconds > 30)
                {
                    break;
                }
                System.Threading.Thread.Sleep(50);
            }
            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region 读正压模块压力30秒后第二个值

            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                if (item.GetDevice("P21").GetPressure_IPM(out getInternalModulePressure30SSecond))
                {
                    break;
                }
                else
                {
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("获取内部模块压力失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "获取内部模块压力失败"));
                        break;
                    }
                }
            }



            #endregion

            #region 读正压气源压力30秒后第二个值
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                if (!item.GetDevice("P21").GetSupplyPressure(out getSourcePressure30SSecond))//30秒前正压气源值
                {
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("获取正压气源压力失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "获取正压气源压力失败"));
                        break;
                    }
                }
                else
                {
                    break;
                }
            }
            #endregion

            #region 计算内部模块压力泄露速率
            RealTimeMsg msg10 = new RealTimeMsg("正压30秒泄露率");
            item.AddRealTimeMsgs(msg10);
            positiveinternalPressureRate = Math.Abs((Math.Abs(getInternalModulePressure30SSecond.Value - getInternalModulePressure30SFirst.Value)) / getInternalModulePressure30SFirst.Value);

            msg10.Content = positiveinternalPressureRate.ToString("F4");
            if (PositivePressureVelocity30S.IsTrue(positiveinternalPressureRate))
            {
                msg10.Content += "  合格";
            }
            else
            {
                msg10.Content += "  不合格";

                result.AddTestErrMsgs(new ErrMsg(30004, "正压30秒泄露率不合格"));
            }
            #endregion

            #region 计算内部压源压力泄露速率
            RealTimeMsg msg14 = new RealTimeMsg("正压压源30秒泄露率");
            item.AddRealTimeMsgs(msg14);
            positiveSupplyPressureRate = Math.Abs((Math.Abs(getSourcePressure30SSecond.Value - getSourcePressure30SFirst.Value)) / getSourcePressure30SFirst.Value);
            msg14.Content = positiveSupplyPressureRate.ToString("F4");
            if (PositiveSupplyVelocity30S.IsTrue(positiveSupplyPressureRate))
            {
                msg14.Content += "  合格";
            }
            else
            {
                msg14.Content += "  不合格";

                result.AddTestErrMsgs(new ErrMsg(30004, "正压压源30秒泄露率不合格"));
            }
            #endregion

            item.AddRealTimeMsgs(new RealTimeMsg("正压泄露测试", "完成"));

            #region  排空
            RealTimeMsg msgVent = new RealTimeMsg("正压排空测试");
            item.AddRealTimeMsgs(msgVent);
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                RealTimeMsg msgGetPressure = new RealTimeMsg("读取当前压力值");
                item.AddRealTimeMsgs(msgGetPressure);
                Pressure getInternalModulePressure = new Pressure(0, PressureUnit.kPa);
                if (!item.GetDevice("P21").GetPressure_IPM(out getInternalModulePressure))
                {
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("读取当前压力失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "读取排空压力失败"));
                        break;
                    }
                }
                msgGetPressure.Content = getInternalModulePressure.ToString();

                RealTimeMsg msgStartVent = new RealTimeMsg("开始排空");
                item.AddRealTimeMsgs(msgStartVent);
                if (!item.GetDevice("P21").SetVentMode())
                {
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("排空失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "排空失败"));
                        break;
                    }
                }
                msgStartVent.Content = "完成";
                break;
            }
            System.Threading.Thread.Sleep(3000);

            state = Xmas11.Comm.Data.Common.PressureStableState.UnKnown;

            while (true)
            {
                if (item.GetDevice("P21").GetPressureStableState(out state) && state == PressureStableState.Stable)
                {
                    break;
                }
            }
            while (true)
            {
                Pressure getInternalModulePressure5Second = new Pressure(0, PressureUnit.kPa);
                if (!item.GetDevice("P21").GetPressure_IPM(out getInternalModulePressure5Second))
                {
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("获取内部模块失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "获取内部模块失败"));
                        break;
                    }
                }
                item.AddRealTimeMsgs(new RealTimeMsg("排空后压力", getInternalModulePressure5Second.ToString()));

                if (!VentPressureValue.IsTrue(getInternalModulePressure5Second.Value))
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, string.Format("排空后压力未降到{0}KPa一下", VentPressureValue.Value.ToString())));
                    item.AddRealTimeMsgs(new RealTimeMsg("排空未成功"));
                }
                else
                {
                    item.AddRealTimeMsgs(new RealTimeMsg("排空成功"));
                }
                break;
            }
            #endregion
            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }


            System.Threading.Thread.Sleep(2000);
            return result;
        }
        finally
        {
            item.GetDevice("P21").SetVentMode();
            Xmas11.Comm.Data.Common.PressureStableState state = Xmas11.Comm.Data.Common.PressureStableState.UnKnown;

            while (true)
            {
                if (item.GetDevice("P21").GetPressureStableState(out state) && state == PressureStableState.Stable)
                {
                    break;
                }
            }
            if (result.ErrMsgs.Count > 0)
            {
                rData[0].Value = rData[1].Value = "不合格";
                foreach (ErrMsg msg in result.ErrMsgs)
                {
                    result.Conclusion += " " + msg.ToString();
                }
            }
            else
            {
                rData[0].Value = rData[1].Value = "合格";
            }
            item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_H, OpenCloseState.Close);
            item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_L, OpenCloseState.Close);
        }

    }




    /// <summary>
    /// 压力泄露测试及压力排空测试--DP复合量程低压
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic LeakTestComposition_Low_DP(dynamic item)
    {
        Result<List<TextData>> result = new Result<List<TextData>>(true);
        List<TextData> rData = new List<TextData>()
        {
            new TextData("正压30秒泄露率"),
            new TextData("正压气源压力30秒泄露率"),
            new TextData("负压30秒泄露率"),
            new TextData("负压气源压力30秒泄露率"),
            new TextData("正压30秒泄露量(新)"),
            new TextData("正压气源压力30秒泄露量(新)"),
            new TextData("负压30秒泄露量(新)"),
            new TextData("负压气源压力30秒泄露量(新)"),
             new TextData("压力值与温度值")
        };
        result.Data = rData;
        StringBuilder tvalue = new StringBuilder(1024);
        tvalue.Append("压力值,高压温度,低压温度,泵温度,电测板温度^");
        string tstr = "";

        try
        {
            bool key1 = item.Parent.VM.OpenInfoConfirmWindow("如果当前测试的设备为DP/LP类型\r\n请将低压模块更换为10kPa量程进行测试； 确认：更换完成，继续测试，取消：终止测试");
            if (key1 != true)
            {
                item.Root.IsRunning = false;
                return result;
            }
            item.ClearRealTimeMsgs();
            System.Threading.Thread.Sleep(500);
            //获取条件
            if (item.Conditions == null)
            {
                result.AddTestErrMsgs(ErrMsg._10002);
                return result;
            }
            ValueCondition PositivePressureVelocity30S = item.Conditions[0] as ValueCondition;  //正压30秒速率
            ValueCondition PositiveSupplyVelocity30S = item.Conditions[1] as ValueCondition;  //正压气源30秒速率
            ValueCondition NegativePressureVelocity30S = item.Conditions[2] as ValueCondition;  //负压30秒速率
            ValueCondition NegativeSupplyVelocity30S = item.Conditions[3] as ValueCondition;  //负压气源30秒速率


            ValueCondition PositiveControlTime = item.Conditions[4] as ValueCondition;  //正压控稳时间
            ValueCondition NegativeControlTime = item.Conditions[5] as ValueCondition;  //负压控稳时间

            ValueCondition VentPressureValue = item.Conditions[6] as ValueCondition;  //排空后压力上限

            item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_H, OpenCloseState.Open);
            item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_L, OpenCloseState.Open);
            double DevicePressureRange = double.MinValue;
            Pressure AtmosSensor = new Pressure(0, PressureUnit.kPa);
            item.GetDevice("P21").GetAtmosSensor(out AtmosSensor);
            Pressure getInternalModulePressureOrg = new Pressure(0, PressureUnit.kPa);
            #region 切换低压量程
            RealTimeMsg msg0 = new RealTimeMsg("切换低压量程");
            item.AddRealTimeMsgs(msg0);
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg0.ContentRunning();
                if (item.GetDevice("P21").SetControlPressureModel(PressureSwitchTripType.Low))
                {
                    msg0.Content = "完成";
                    break;
                }
                msg0.Content = "失败";
                bool? key = item.Parent.VM.OpenInfoConfirmWindow("切换低压量程失败,重试？");
                if (key.HasValue && key.Value)
                {
                    continue;
                }
                else
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "切换低压量程失败"));
                    return result;
                }
            }
            System.Threading.Thread.Sleep(5000);
            msg0.Content = "完成";
            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region 设置内部模块单位
            RealTimeMsg msg1 = new RealTimeMsg("设置内部模块单位");
            item.AddRealTimeMsgs(msg1);
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg1.ContentRunning();
                if (item.GetDevice("P21").SetPressureUnit_IPM())
                {
                    msg1.Content = "完成";
                    break;
                }
                msg1.Content = "失败";
                bool? key = item.Parent.VM.OpenInfoConfirmWindow("设定内部模块压力单位失败,重试？");
                if (key.HasValue && key.Value)
                {
                    continue;
                }
                else
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "设置内部模块单位通讯失败"));
                    return result;
                }
            }
            msg1.Content = "完成";
            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region 获取模块压力量程
            RealTimeMsg msg2 = new RealTimeMsg("获取压力控制量程范围");
            item.AddRealTimeMsgs(msg2);
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                msg2.ContentRunning();
                PressureRange pressureRange = new PressureRange();
                if (item.GetDevice("P21").GetSetPointLimitPressureRange(out pressureRange))
                {
                    DevicePressureRange = Math.Abs(pressureRange.LowerValue) + Math.Abs(pressureRange.UpperValue);
                    msg2.Content = pressureRange.ToString();
                }
                else
                {
                    msg2.Content = "失败";
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("获取压力控制量程范围失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "获取压力控制量程范围失败"));
                        return result;
                    }
                }
                break;
            }

            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }


            Pressure InnerModulePressureUpper = new Pressure(0, PressureUnit.kPa);//量程上限
            Pressure getInternalModulePressure30SFirst = new Pressure(0, PressureUnit.kPa);
            Pressure getInternalModulePressure30SSecond = new Pressure(0, PressureUnit.kPa);
            Pressure getSourcePressure30SFirst = new Pressure(0, PressureUnit.kPa);
            Pressure getSourcePressure30SSecond = new Pressure(0, PressureUnit.kPa);
            double positiveinternalPressureRate = double.MaxValue;
            double positiveSupplyPressureRate = double.MaxValue;
            double rate = 0;
            PressureStableState state = PressureStableState.UnKnown;
            Xmas11.Comm.Data.Common.PressureStableState state4 = Xmas11.Comm.Data.Common.PressureStableState.UnKnown;
            DateTime starTime = DateTime.Now;



            Pressure modelLowerLimit = new Pressure(0, PressureUnit.kPa);
            item.GetDevice("P21").GetPressureLowerer_IPM(out modelLowerLimit);
            if (modelLowerLimit.Value < 0)
            {
                #region  负压 


                Pressure InnerModulePressureLowerer = new Pressure(0, PressureUnit.kPa);//量程下限
                getInternalModulePressure30SFirst = new Pressure(0, PressureUnit.kPa);
                getInternalModulePressure30SSecond = new Pressure(0, PressureUnit.kPa);
                getSourcePressure30SFirst = new Pressure(0, PressureUnit.kPa);
                getSourcePressure30SSecond = new Pressure(0, PressureUnit.kPa);
                double negativeinternalPressureRate = double.MaxValue;
                double negativeSupplyPressureRate = double.MaxValue;


                #region 获取内部模块量程下限
                RealTimeMsg msg23 = new RealTimeMsg("获取内部模块量程上限");
                item.AddRealTimeMsgs(msg23);
                while (true)
                {
                    if (!item.IsRunning)
                    {
                        result.AddTestErrMsgs(ErrMsg._09999);
                        return result;
                    }
                    msg23.ContentRunning();
                    if (!item.GetDevice("P21").GetPressureControlRange_LowerLimit(out InnerModulePressureLowerer))
                    {
                        msg23.Content = "获取内部模块量程下限失败";
                        bool? key = item.Parent.VM.OpenInfoConfirmWindow("获取内部模块量程下限失败,重试？");
                        if (key.HasValue && key.Value)
                        {
                            continue;
                        }
                        else
                        {
                            result.AddTestErrMsgs(new ErrMsg(20003, "获取内部模块量程下限失败"));
                            break;
                        }
                    }
                    else
                    {
                        msg23.Content = InnerModulePressureLowerer.ToString();
                        break;
                    }

                }

                #endregion

                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }

                #region 设定压力目标并输出

                RealTimeMsg msg24 = new RealTimeMsg(string.Format("设定压力目标并输出{0}", InnerModulePressureLowerer.ToString()));
                item.AddRealTimeMsgs(msg24);
                starTime = DateTime.Now;
                while (true)
                {
                    if (!item.IsRunning)
                    {
                        result.AddTestErrMsgs(ErrMsg._09999);
                        return result;
                    }
                    if (!item.GetDevice("P21").SetTargetPressure(InnerModulePressureLowerer))
                    {
                        bool? key = item.Parent.VM.OpenInfoConfirmWindow("设置压力目标失败,重试？");
                        if (key.HasValue && key.Value)
                        {
                            continue;
                        }
                        else
                        {
                            result.AddTestErrMsgs(new ErrMsg(20003, "设置压力目标失败"));
                            break;
                        }
                    }
                    else
                    {
                        break;
                    }
                }
                while (true)
                {
                    if (!item.IsRunning)
                    {
                        result.AddTestErrMsgs(ErrMsg._09999);
                        return result;
                    }
                    item.GetDevice("P21").GetPressureStableState(out state);
                    rate = Math.Abs((getInternalModulePressureOrg.Value - InnerModulePressureLowerer.Value) / InnerModulePressureLowerer.Value);
                    if (item.GetDevice("P21").GetPressure_IPM(out getInternalModulePressureOrg) && state == PressureStableState.Stable && rate <= 0.05)
                    {
                        msg24.Content = "打压完成";
                        TimeSpan firstSpan = DateTime.Now - starTime;
                        double span = firstSpan.TotalSeconds;
                        if (!PositiveControlTime.IsTrue(span))
                        {
                            msg24.Content = string.Format("打压失败");
                            result.AddTestErrMsgs(new ErrMsg(30004, "打压失败 "));
                        }
                        else
                        {
                            msg24.Content = string.Format("控压成功！");
                        }

                        break;
                    }
                    else
                    {
                        TimeSpan firstSpan = DateTime.Now - starTime;
                        double span = firstSpan.TotalSeconds;
                        if (!PositiveControlTime.IsTrue(span))
                        {
                            msg24.Content = string.Format("打压失败");
                            result.AddTestErrMsgs(new ErrMsg(30004, "打压失败"));
                            break;
                        }
                    }
                }
                #endregion

                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }

                #region 切测量状态
