                (rData[6] as TextData).Value = string.Format("{0}(ml/min)", Util.LeakTestValueFormula(LeakDeviceModel.MP_DP_LLP, LeakPosition.NegativeExport, Math.Abs(getInternalModulePressure30SSecond.ToUnit(PressureUnit.kPa).Value - getInternalModulePressure30SFirst.ToUnit(PressureUnit.kPa).Value), 30, AtmosSensor.ToUnit(PressureUnit.kPa).Value));
