                (rData[2] as TextData).Value = (negativeinternalPressureRate*100).ToString("F4") + "%";
                msg30.Content = (negativeinternalPressureRate * 100).ToString("F4") + "%";
                if (NegativePressureVelocity30S.IsTrue(negativeinternalPressureRate * 100))
                {
                    msg30.Content += "  合格";
