                #endregion

                #region 计算内部压源压力泄露速率
                (rData[7] as TextData).Value = string.Format("{0}(ml/min)", Util.LeakTestValueFormula(LeakDeviceModel.MP_DP_LLP, LeakPosition.NegativeSource, Math.Abs(getSourcePressure30SSecond.ToUnit(PressureUnit.kPa).Value - getSourcePressure30SFirst.ToUnit(PressureUnit.kPa).Value), 30, AtmosSensor.ToUnit(PressureUnit.kPa).Value));
