    #region LLP泄露
    public dynamic PRELeakTestComposition_Low_LLP(dynamic item)
    {
        Result<List<TextData>> result = new Result<List<TextData>>(true);
        List<TextData> rData = new List<TextData>() { new TextData("StandardValue"), new TextData("MeasuredValue") };
        result.Data = rData;
        try
        {
            result.Data = rData;

            item.ClearRealTimeMsgs();
            System.Threading.Thread.Sleep(500);
            //获取条件
            if (item.Conditions == null)
            {
                result.AddTestErrMsgs(ErrMsg._10002);
                return result;
            }
            ValueCondition PositivePressureVelocity30S = item.Conditions[0] as ValueCondition;  //正压30秒泄露量
            ValueCondition PositiveSupplyVelocity30S = item.Conditions[1] as ValueCondition;  //正压气源30秒速率
            ValueCondition NegativePressureVelocity30S = item.Conditions[2] as ValueCondition;  //负压30秒泄露量
