                    }
                }
                else
                {
                    break;
                }

            }
            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }

            #region 设定压力目标并输出
            RealTimeMsg msg4 = new RealTimeMsg(string.Format("设定压力目标并输出{0}", InnerModulePressureUpper.ToString()));
            item.AddRealTimeMsgs(msg4);
            DateTime starTime = DateTime.Now;
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                if (!item.GetDevice("P21").SetTargetPressure(InnerModulePressureUpper))
