                        result.AddTestErrMsgs(new ErrMsg(20003, "设置控制器测量模式失败"));
                        return result;
                    }
                }
                #endregion

                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }



                #region 计时45秒
                RealTimeMsg msg26 = new RealTimeMsg("计时45秒时间显示");
                item.AddRealTimeMsgs(msg26);
                DateTime negative30S = DateTime.Now;
                while (true)
                {
                    if (!item.IsRunning)
                    {
                        result.AddTestErrMsgs(ErrMsg._09999);
                        return result;
                    }

                    TimeSpan timeSpan = DateTime.Now - negative30S;
                    msg26.Content = string.Format("总共用时45秒，当前用时{0}秒", timeSpan.TotalSeconds.ToString("F2"));
                    if (timeSpan.TotalSeconds > 45)
                    {
                        break;
                    }
                    System.Threading.Thread.Sleep(50);
                }
                #endregion

                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }

                #region 读负压模块压力45秒第一个值

                while (true)
                {
                    if (!item.IsRunning)
                    {
                        result.AddTestErrMsgs(ErrMsg._09999);
                        return result;
                    }
                    if (item.GetDevice("P21").GetPressure_IPM(out getInternalModulePressure30SFirst))
                    {
                        break;
                    }
                    else
                    {
                        bool? key = item.Parent.VM.OpenInfoConfirmWindow("获取内部模块压力失败,重试？");
                        if (key.HasValue && key.Value)
                        {
                            continue;
                        }
                        else
                        {
                            result.AddTestErrMsgs(new ErrMsg(20003, "获取内部模块压力失败"));
                            break;
                        }
                    }
                }



                #endregion


                #region 读负压气源压力30秒后第一个值
                while (true)
                {
                    if (!item.IsRunning)
                    {
                        result.AddTestErrMsgs(ErrMsg._09999);
                        return result;
                    }
                    if (!item.GetDevice("P21").GetVacuumPressure(out getSourcePressure30SFirst))//30秒前正压气源值
                    {
                        bool? key = item.Parent.VM.OpenInfoConfirmWindow("获取负压气源压力失败,重试？");
                        if (key.HasValue && key.Value)
                        {
                            continue;
                        }
                        else
                        {
                            result.AddTestErrMsgs(new ErrMsg(20003, "获取负压气源压力失败"));
                            break;
                        }
                    }
                    else
                    {
                        break;
                    }
                }
                #endregion

                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }

                #region 计时30秒
                RealTimeMsg msg28 = new RealTimeMsg("计时30秒时间显示");
                item.AddRealTimeMsgs(msg28);
                negative30S = DateTime.Now;
                while (true)
                {
                    if (!item.IsRunning)
                    {
                        result.AddTestErrMsgs(ErrMsg._09999);
                        return result;
                    }

                    TimeSpan timeSpan = DateTime.Now - negative30S;
                    msg28.Content = string.Format("总共用时30秒，当前用时{0}秒", timeSpan.TotalSeconds.ToString("F2"));
                    if (timeSpan.TotalSeconds > 30)
                    {
                        break;
                    }
                    System.Threading.Thread.Sleep(50);
                }
                #endregion

                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }

                #region 读负压模块压力30秒后第二个值

                while (true)
                {
                    if (!item.IsRunning)
                    {
                        result.AddTestErrMsgs(ErrMsg._09999);
                        return result;
                    }
                    if (item.GetDevice("P21").GetPressure_IPM(out getInternalModulePressure30SSecond))
                    {
                        break;
                    }
                    else
                    {
                        bool? key = item.Parent.VM.OpenInfoConfirmWindow("获取内部模块压力失败,重试？");
                        if (key.HasValue && key.Value)
                        {
                            continue;
                        }
                        else
                        {
                            result.AddTestErrMsgs(new ErrMsg(20003, "获取内部模块压力失败"));
                            break;
                        }
                    }
                }



                #endregion

                #region 读负压气源压力30秒后第二个值
                while (true)
                {
                    if (!item.IsRunning)
                    {
                        result.AddTestErrMsgs(ErrMsg._09999);
                        return result;
                    }
                    if (!item.GetDevice("P21").GetVacuumPressure(out getSourcePressure30SSecond))//30秒前正压气源值
                    {
                        bool? key = item.Parent.VM.OpenInfoConfirmWindow("获取负压气源压力失败,重试？");
                        if (key.HasValue && key.Value)
                        {
                            continue;
                        }
                        else
                        {
                            result.AddTestErrMsgs(new ErrMsg(20003, "获取负压气源压力失败"));
                            break;
                        }
                    }
                    else
                    {
                        break;
                    }
                }
                #endregion

                #region 计算内部模块压力泄露量
                RealTimeMsg msg30 = new RealTimeMsg("负压30秒泄露量");
                item.AddRealTimeMsgs(msg30);
                negativeinternalPressureRate = Math.Abs(getInternalModulePressure30SSecond.Value - getInternalModulePressure30SFirst.Value);

                msg30.Content = negativeinternalPressureRate.ToString("F4");
                if (NegativePressureVelocity30S.IsTrue(negativeinternalPressureRate))
                {
                    msg30.Content += "  合格";
                }
                else
                {
                    msg30.Content += "  不合格";

                    result.AddTestErrMsgs(new ErrMsg(30004, "负压30秒泄露量不合格"));
                }
                #endregion

                #region 计算内部压源压力泄露速率
                RealTimeMsg msg34 = new RealTimeMsg("负压压源30秒泄露率");
                item.AddRealTimeMsgs(msg34);
                negativeSupplyPressureRate = Math.Abs((Math.Abs(getSourcePressure30SSecond.Value - getSourcePressure30SFirst.Value)) / getSourcePressure30SFirst.Value);

                msg34.Content = negativeSupplyPressureRate.ToString("F4");
                if (NegativeSupplyVelocity30S.IsTrue(negativeSupplyPressureRate))
                {
                    msg34.Content += "  合格";
                }
                else
                {
                    msg34.Content += "  不合格";
                    result.AddTestErrMsgs(new ErrMsg(30004, "负压压源30秒泄露率不合格"));
                }
                #endregion

                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                item.AddRealTimeMsgs(new RealTimeMsg("负压泄露测试", "完成"));

                #region  排空
                RealTimeMsg msgVent2 = new RealTimeMsg("负压排空测试");
                item.AddRealTimeMsgs(msgVent2);
                while (true)
                {
                    if (!item.IsRunning)
                    {
                        result.AddTestErrMsgs(ErrMsg._09999);
                        return result;
                    }
                    RealTimeMsg msgGetPressure = new RealTimeMsg("读取当前压力值");
                    item.AddRealTimeMsgs(msgGetPressure);
                    Pressure getInternalModulePressure = new Pressure(0, PressureUnit.kPa);
                    if (!item.GetDevice("P21").GetPressure_IPM(out getInternalModulePressure))
                    {
                        bool? key = item.Parent.VM.OpenInfoConfirmWindow("读取当前压力失败,重试？");
                        if (key.HasValue && key.Value)
                        {
                            continue;
                        }
                        else
                        {
                            result.AddTestErrMsgs(new ErrMsg(20003, "读取排空压力失败"));
                            break;
                        }
                    }
                    msgGetPressure.Content = getInternalModulePressure.ToString();
                    RealTimeMsg msgStartVent = new RealTimeMsg("开始排空");
                    item.AddRealTimeMsgs(msgStartVent);
                    if (!item.GetDevice("P21").SetVentMode())
                    {
                        bool? key = item.Parent.VM.OpenInfoConfirmWindow("排空失败,重试？");
                        if (key.HasValue && key.Value)
                        {
                            continue;
                        }
                        else
                        {
                            result.AddTestErrMsgs(new ErrMsg(20003, "排空失败"));
                            break;
                        }
                    }
                    msgStartVent.Content = "完成";
                    break;
                }
                System.Threading.Thread.Sleep(3000);

                state = Xmas11.Comm.Data.Common.PressureStableState.UnKnown;

                while (true)
                {
                    if (item.GetDevice("P21").GetPressureStableState(out state) && state == PressureStableState.Stable)
                    {
                        break;
                    }
                }
                while (true)
                {
                    Pressure getInternalModulePressure5Second = new Pressure(0, PressureUnit.kPa);
                    if (!item.GetDevice("P21").GetPressure_IPM(out getInternalModulePressure5Second))
                    {
                        bool? key = item.Parent.VM.OpenInfoConfirmWindow("获取内部模块失败,重试？");
                        if (key.HasValue && key.Value)
                        {
                            continue;
                        }
                        else
                        {
                            result.AddTestErrMsgs(new ErrMsg(20003, "获取内部模块失败"));
                            break;
                        }
                    }
                    item.AddRealTimeMsgs(new RealTimeMsg("排空后压力", getInternalModulePressure5Second.ToString()));

                    if (!VentPressureValue.IsTrue(getInternalModulePressure5Second.Value))
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, string.Format("排空后压力未降到{0}KPa一下", VentPressureValue.Value.ToString())));
                        item.AddRealTimeMsgs(new RealTimeMsg("排空未成功"));
                    }
                    else
                    {
                        item.AddRealTimeMsgs(new RealTimeMsg("排空成功"));
                    }
                    break;
                }
                #endregion
                #endregion
            }
            System.Threading.Thread.Sleep(2000);
            return result;
        }
        finally
        {
            item.GetDevice("P21").SetVentMode();
            Xmas11.Comm.Data.Common.PressureStableState state = Xmas11.Comm.Data.Common.PressureStableState.UnKnown;

            while (true)
            {
                if (item.GetDevice("P21").GetPressureStableState(out state) && state == PressureStableState.Stable)
                {
                    break;
                }
            }
            if (result.ErrMsgs.Count > 0)
            {
                rData[0].Value = rData[1].Value = "不合格";
                foreach (ErrMsg msg in result.ErrMsgs)
                {
                    result.Conclusion += " " + msg.ToString();
                }
            }
            else
            {
                rData[0].Value = rData[1].Value = "合格";
            }
            item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_H, OpenCloseState.Close);
            item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_L, OpenCloseState.Close);
        }

    }
    /// <summary>
    /// 压力控制测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic PREPressureControlTest(dynamic item)
    {
        Result<List<TextData>> result = new Result<List<TextData>>(true);
        List<TextData> rData = new List<TextData>() { new TextData("StandardValue"), new TextData("MeasuredValue") };
        result.Data = rData;
        try
        {
            item.ClearRealTimeMsgs();
            System.Threading.Thread.Sleep(500);
            //获取条件
            if (item.Conditions == null)
            {
                result.AddTestErrMsgs(ErrMsg._10002);
                return result;
            }
            //控压最大用时
            ValueCondition PositivePressControlTime2 = item.Conditions[4] as ValueCondition;    //正压5%HP->105%HP控压时间
            ValueCondition PositivePressControlTime = item.Conditions[0] as ValueCondition;    //正压控压时间
            ValueCondition NegativePressControlTime = item.Conditions[1] as ValueCondition;    //负压控压时间
            ValueCondition PositivePressControlToleranceValue = item.Conditions[2] as ValueCondition;    //正压设定点控压允差
            ValueCondition NegativePressControlToleranceValue = item.Conditions[3] as ValueCondition;    //负压设定点控压允差

            ValueCondition WaitTimeN = item.Conditions[7] as ValueCondition;  //负压等待
            ValueCondition WaitTimeP = item.Conditions[8] as ValueCondition;  //正压等待
            #region 初始化参数
            int j = 0;
            int i = 0;
            double resultValue = double.NaN;
            Pressure setInnerPressure = new Pressure(0, PressureUnit.kPa);
            Pressure InnerModulePressureUpper = new Pressure(0, PressureUnit.kPa);
            Pressure InnerModulePressureLowerer = new Pressure(0, PressureUnit.kPa);
            double pressureStabilityValue = 0.003; //压力稳定误差
            DateTime StarTimePressUp = DateTime.Now; //正压起始时间
            DateTime StarTimePressDown = DateTime.Now; //负压起始时间
            List<double> postiveSetPoint = new List<double>() { 0, 0.05, 1, 0.95, 0 };   //正压设定点 0，5%FS，105%，100%,0
            List<double> negativeSetPoint = new List<double>() { 0, 0.05, 1, 0.9, 0 };  //负压设定点0，5%-FS,-FS,90%-FS,0
            bool isControlLangRange = false;
            #endregion
            item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_H, OpenCloseState.Open);
            item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_L, OpenCloseState.Open);
            if (item.GetDevice("P21").IsDoubleRange())
            {
                item.GetDevice("P21").SetVentMode();
                System.Threading.Thread.Sleep(3000);
                #region 切换低压量程
                RealTimeMsg msg0 = new RealTimeMsg(">>切换低压量程");
                item.AddRealTimeMsgs(msg0);
                while (true)
                {
                    msg0.ContentRunning();
                    if (item.GetDevice("P21").SetControlPressureModel(PressureSwitchTripType.Low))
                    {
                        msg0.Content = "完成";
                        break;
                    }
                    msg0.Content = "失败";
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("切换低压量程失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "切换低压量程失败"));
                        return result;
                    }
                }
                System.Threading.Thread.Sleep(2000);
                msg0.Content = "完成";
                #endregion
                System.Threading.Thread.Sleep(3000);

                #region 低压测试

                #region 设置内部模块单位
                RealTimeMsg msg1 = new RealTimeMsg("设置内部模块单位");
                item.AddRealTimeMsgs(msg1);
                while (true)
                {
                    msg1.ContentRunning();
                    if (item.GetDevice("P21").SetPressureUnit_IPM())
                    {
                        msg1.Content = "完成";
                        break;
                    }
                    msg1.Content = "失败";
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("设定内部模块压力单位失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "设置内部模块单位通讯失败"));
                        return result;
                    }
                }
