                                    result.AddTestErrMsgs(new ErrMsg(30004, string.Format("控压失败！{0}{1}压力点控压时间超过{2}", resultValue, InnerModulePressureUpper.Unit, PositivePressControlTime.Value + PositivePressControlTime.Unit)));
                                    i++;
                                    break;
