                                    result.AddTestErrMsgs(new ErrMsg(30004, string.Format("控压失败！{0}{1}压力点控压时间为{2}秒,应为{3}", resultValue, InnerModulePressureUpper.Unit, span.ToString("F2"), PositivePressControlTime.Value + PositivePressControlTime.Unit)));

