                result.AddTestErrMsgs(new ErrMsg(30004, "正压30秒泄露率不合格"));
            }
            #endregion

            #region 计算内部压源压力泄露速率
            (rData[5] as TextData).Value = string.Format("{0}(ml/min)", Util.LeakTestValueFormula(LeakDeviceModel.MP_DP_LLP, LeakPosition.PositiveSource, Math.Abs(getSourcePressure30SSecond.ToUnit(PressureUnit.kPa).Value - getSourcePressure30SFirst.ToUnit(PressureUnit.kPa).Value), 30, AtmosSensor.ToUnit(PressureUnit.kPa).Value));
            RealTimeMsg msg14 = new RealTimeMsg("正压压源30秒泄露率");
            item.AddRealTimeMsgs(msg14);
            positiveSupplyPressureRate = Math.Abs((Math.Abs(getSourcePressure30SSecond.Value - getSourcePressure30SFirst.Value)) / getSourcePressure30SFirst.Value);
            (rData[1] as TextData).Value = (positiveSupplyPressureRate * 100).ToString("F4") +"%";
            msg14.Content = (positiveSupplyPressureRate * 100).ToString("F4") + "%";
            if (PositiveSupplyVelocity30S.IsTrue(positiveSupplyPressureRate * 100))
            {
                msg14.Content += "  合格";
            }
            else
            {
                msg14.Content += "  不合格";

                result.AddTestErrMsgs(new ErrMsg(30004, "正压压源30秒泄露率不合格"));
            }
            #endregion

            item.AddRealTimeMsgs(new RealTimeMsg("正压泄露测试", "完成"));

            #region  排空
            RealTimeMsg msgVent = new RealTimeMsg("正压排空测试");
            item.AddRealTimeMsgs(msgVent);
            while (true)
            {
                if (!item.IsRunning)
                {
                    result.AddTestErrMsgs(ErrMsg._09999);
                    return result;
                }
                RealTimeMsg msgGetPressure = new RealTimeMsg("读取当前压力值");
                item.AddRealTimeMsgs(msgGetPressure);
                Pressure getInternalModulePressure = new Pressure(0, PressureUnit.kPa);
                if (!item.GetDevice("P21").GetPressure_IPM(out getInternalModulePressure))
                {
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("读取当前压力失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "读取排空压力失败"));
                        break;
                    }
                }
                msgGetPressure.Content = getInternalModulePressure.ToString();

                RealTimeMsg msgStartVent = new RealTimeMsg("开始排空");
                item.AddRealTimeMsgs(msgStartVent);
                if (!item.GetDevice("P21").SetVentMode())
                {
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("排空失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "排空失败"));
                        break;
                    }
                }
                msgStartVent.Content = "完成";
                break;
            }
            System.Threading.Thread.Sleep(3000);

            while (true)
            {
                if (item.GetDevice("P21").GetPressureStableState(out state4) && state4 == PressureStableState.Stable)
                {
                    break;
                }
            }
            while (true)
            {
                Pressure getInternalModulePressure5Second = new Pressure(0, PressureUnit.kPa);
                if (!item.GetDevice("P21").GetPressure_IPM(out getInternalModulePressure5Second))
                {
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("获取内部模块失败,重试？");
                    if (key.HasValue && key.Value)
                    {
                        continue;
                    }
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "获取内部模块失败"));
                        break;
                    }
                }
                item.AddRealTimeMsgs(new RealTimeMsg("排空后压力", getInternalModulePressure5Second.ToString()));

                if (!VentPressureValue.IsTrue(getInternalModulePressure5Second.Value))
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, string.Format("排空后压力未降到{0}KPa一下", VentPressureValue.Value.ToString())));
                    item.AddRealTimeMsgs(new RealTimeMsg("排空未成功"));
                }
                else
                {
                    item.AddRealTimeMsgs(new RealTimeMsg("排空成功"));
                }
                break;
            }
            #endregion
            #endregion

            if (!item.IsRunning)
            {
                result.AddTestErrMsgs(ErrMsg._09999);
                return result;
            }


            System.Threading.Thread.Sleep(2000);
            return result;
        }
        finally
        {
            (rData[8] as TextData).Value = tvalue.ToString();

            item.GetDevice("P21").SetVentMode();
            Xmas11.Comm.Data.Common.PressureStableState state4 = Xmas11.Comm.Data.Common.PressureStableState.UnKnown;

            while (true)
            {
                if (item.GetDevice("P21").GetPressureStableState(out state4) && state4 == PressureStableState.Stable)
                {
                    break;
                }
            }
            item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_H, OpenCloseState.Close);
            item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_L, OpenCloseState.Close);
        }

    }

    #endregion

    /// <summary>
    /// V6阀状态测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic V6ValveOpenTest(dynamic item)
    {
        Result<List<DataBase>> result = new Result<List<DataBase>>(true);
        List<DataBase> rData = new List<DataBase>() { };
        result.Data = rData;

        item.ClearRealTimeMsgs();
        ValueCondition controlPressureTime = item.Conditions[0] as ValueCondition;    //控压时间
        string orgDeviceMode = item.Root.DUT.DeviceMode;
        RealTimeMsg msg_10MDevice = new RealTimeMsg("设备类型");
        item.AddRealTimeMsgs(msg_10MDevice);
        if (orgDeviceMode.Contains("10M"))
        {
            msg_10MDevice.Content = $"当前设备为:{orgDeviceMode},将采用10M机型的指标。";
            controlPressureTime = item.Conditions[1] as ValueCondition;    //控压时间
            msg_10MDevice.Content = $"控压时长指标为:{controlPressureTime}";

        }
        item.AddRealTimeMsgs(new RealTimeMsg("内部模块量程上限"));
        RealTimeMsg msg111 = new RealTimeMsg("电池电量");
        item.AddRealTimeMsgs(msg111);
        item.GetDevice("P21").GetBatteryValue(out double Bval);
        msg111.Content = $"{Math.Round(Bval, 2) * 100}%";
        System.Threading.Thread.Sleep(500);

        item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_H, OpenCloseState.Close);
        item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_L, OpenCloseState.Close);
        #region 设置内部模块单位
        RealTimeMsg msg1 = new RealTimeMsg("设置内部模块单位");
        item.AddRealTimeMsgs(msg1);
        while (true)
        {
            msg1.ContentRunning();
            if (item.GetDevice("P21").SetPressureUnit_IPM())
            {
                msg1.Content = "完成";
                break;
            }
            msg1.Content = "失败";
            bool? key = item.Parent.VM.OpenInfoConfirmWindow("设定内部模块压力单位失败,重试？");
            if (key.HasValue && key.Value)
            {
                continue;
            }
            else
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "设置内部模块单位通讯失败"));
                return result;
            }
        }
        #endregion

        int Count = 0;
        double internalV6Rate = double.MaxValue;
        Pressure innerPressureUpper = new Pressure(0, PressureUnit.kPa);

        #region 测试V1和V6阀
        RealTimeMsg msg2 = new RealTimeMsg("内部模块量程上限");
        item.AddRealTimeMsgs(msg2);
        while (true)
        {
            msg2.ContentRunning();
            if (item.GetDevice("P21").GetPressureControlRange_UpperLimit(out innerPressureUpper))
            {
                msg2.Content = innerPressureUpper.ToString();
                break;
            }

            msg2.Content = "读取内部模块量程失败";

            bool? key = item.Parent.VM.OpenInfoConfirmWindow("读取内部模块量程失败,重试？");
            if (key.HasValue && key.Value)
            {
                continue;
            }
            else
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "读取内部模块量程失败"));
                break;
            }
        }

        while (true)
        {
            if (item.GetDevice("P21").SetTargetPressure(innerPressureUpper))
            {
                break;
            }
            bool? key = item.Parent.VM.OpenInfoConfirmWindow("设定内部模块压力失败,重试？");
            if (key.HasValue && key.Value)
            {
                continue;
            }
            else
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "设定内部模块压力失败"));
                break;
            }
        }
        RealTimeMsg msg3 = new RealTimeMsg("当前压力值");
        item.AddRealTimeMsgs(msg3);
        DateTime starTime = DateTime.Now;
        while (true)
        {
            Pressure getInternalModulePressure = new Pressure(0, PressureUnit.kPa);

            if (!item.GetDevice("P21").GetPressure_IPM(out getInternalModulePressure))
            {
                bool? key = item.Parent.VM.OpenInfoConfirmWindow("获取内部模块压力失败,重试？");
                if (key.HasValue && key.Value)
                {
                    continue;
                }
                else
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "获取内部模块压力失败"));
                    break;
                }
            }
            msg3.Content = getInternalModulePressure.ToString();
            internalV6Rate = (Math.Abs(getInternalModulePressure.Value - innerPressureUpper.Value)) / innerPressureUpper.Value;
            if (internalV6Rate < 0.001)
                Count++;
            if (Count > 10)
                break;
            TimeSpan span = DateTime.Now - starTime;
            if (span.TotalSeconds > controlPressureTime.Value)
            {
                result.AddTestErrMsgs(new ErrMsg(30003, $"控压超时,{controlPressureTime.Value}{controlPressureTime.Unit}没有控压到目标值的0.001"));
                break;
            }
            System.Threading.Thread.Sleep(100);
        }
        System.Threading.Thread.Sleep(1000);

        RealTimeMsg msg4 = new RealTimeMsg("正在排空气体");
        item.AddRealTimeMsgs(msg4);
        while (true)
        {
            bool setVentModeResult = item.GetDevice("P21").SetVentMode();
            System.Threading.Thread.Sleep(3000);
            DevicePressureControlMode controlMode = DevicePressureControlMode.UnKnown;
            if (setVentModeResult && item.GetDevice("P21").GetPressureControlMode(out controlMode) && controlMode == DevicePressureControlMode.VENT)
            {
                msg4.Content = "完成";
                break;
            }
            else
            {
                bool? key = item.Parent.VM.OpenInfoConfirmWindow("设定排空模式失败,重试？");
                if (key.HasValue && key.Value)
                {
                    continue;
                }
                else
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "设定排空模式失败"));
                    break;
                }
            }
        }


        RealTimeMsg msg5 = new RealTimeMsg("设定测试模式");
        item.AddRealTimeMsgs(msg5);
        while (true)
        {
            bool setTestModeResult = item.GetDevice("P21").SetTestMode();
            System.Threading.Thread.Sleep(5000);
            DevicePressureControlMode controlMode = DevicePressureControlMode.UnKnown;
            if (setTestModeResult && item.GetDevice("P21").GetPressureControlMode(out controlMode) && controlMode == DevicePressureControlMode.MEASURE)
            {
                msg5.Content = "完成";
                break;
            }
            else
            {
                bool? key = item.Parent.VM.OpenInfoConfirmWindow("设定测试模式失败,重试？");
                if (key.HasValue && key.Value)
                {
                    continue;
                }
                else
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "设定测试模式失败"));
                    break;
                }
            }
        }

        RealTimeMsg msg6 = new RealTimeMsg("打开V1和V6阀");
        item.AddRealTimeMsgs(msg6);
        int tryCount = 0;
        while (true)
        {
            if (item.GetDevice("P21").SetValveStata(33))
            {
                System.Threading.Thread.Sleep(5000);
                int valveStateValue = 0;
                if (item.GetDevice("P21").GetValveStateValue(out valveStateValue) && valveStateValue == 33)
                {
                    msg6.Content = "成功";
                    break;
                }
                else
                {
                    item.GetDevice("P21").SetValveStata(33);
                }
            }
            if (tryCount > 3)
            {
                bool? key = item.Parent.VM.OpenInfoConfirmWindow("开启V1和V6阀失败,重试？");
                if (key.HasValue && key.Value)
                {
                    tryCount = 0;
                    continue;
                }
                else
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "开启V1和V6阀失败"));
                    break;
                }
            }
            tryCount++;

        }
        RealTimeMsg msg7 = new RealTimeMsg("正在获取正压气源压力");
        item.AddRealTimeMsgs(msg7);
        System.Threading.Thread.Sleep(5000);


        while (true)
        {

            Pressure positiveSupplyPressure = new Pressure(0, PressureUnit.kPa);
            if (item.GetDevice("P21").GetSupplyPressure(out positiveSupplyPressure))
            {
                msg7.Content = positiveSupplyPressure.ToString();
                if (positiveSupplyPressure.Value > 10)
                {
                    item.AddRealTimeMsgs(new RealTimeMsg("未通过，正压气源压力没有完全排空，内压在10KPa以上...", positiveSupplyPressure.ToString()));
                    result.AddTestErrMsgs(new ErrMsg(30003, "5s内未降到10KPa以下"));
                }
                else
                {
                    item.AddRealTimeMsgs(new RealTimeMsg("通过，正压气源压力在10KPa以下...", positiveSupplyPressure.ToString()));
                }
                break;
            }
            bool? key = item.Parent.VM.OpenInfoConfirmWindow("获取正压气源失败,重试？");
            if (key.HasValue && key.Value)
            {
                tryCount = 0;
                continue;
            }
            else
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "获取正压气源失败"));
                break;
            }
        }

        #endregion
        item.AddRealTimeMsgs(new RealTimeMsg());
        int Isaddtime = 0;
        #region 控到量程上限再到-85KPa

        item.GetDevice<ConST811A>("P21").GetSetPointLimitPressureRange(out PressureRange ModulePressure);
        RealTimeMsg msg81 = new RealTimeMsg("控压范围", ModulePressure.ToString());
        item.AddRealTimeMsgs(msg81);

        #region 控制到量程上限
        int trynum = 0;
    tryagain:
        RealTimeMsg msg8 = new RealTimeMsg("控压到量程上限");
        item.AddRealTimeMsgs(msg8);
        while (true)
        {
            msg8.ContentRunning();
            if (item.GetDevice("P21").SetTargetPressure(ModulePressure.UpperValue))
            {
                break;
            }
            bool? key = item.Parent.VM.OpenInfoConfirmWindow("设定压力模块量程上限失败,重试？");
            if (key.HasValue && key.Value)
            {
                continue;
            }
            else
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "设定压力模块量程上限失败"));
                break;
            }
        }
        msg8.Content = "完成";


        RealTimeMsg msg9 = new RealTimeMsg("获取压力状态");
        ListValueData pList1 = new ListValueData("控压到量程上限");
        item.AddRealTimeMsgs(msg9);
        System.Threading.Thread.Sleep(2000);
        DateTime beginTime = DateTime.Now;
        Pressure pressure = new Pressure();
        while (true)
        {
            item.GetDevice("P21").GetPressure_IPM(out pressure);
            var rate = Math.Abs(pressure.Value / ModulePressure.UpperValue);
            TimeSpan span = DateTime.Now - beginTime;
            if (span.TotalSeconds > controlPressureTime.Value)
            {
                if (trynum < 1)
                {
                    trynum++;
                    System.Threading.Thread.Sleep(1000);
                    goto tryagain;
                }

                result.AddTestErrMsgs(new ErrMsg(30004, $"压力模块量程上限{innerPressureUpper}控稳超时,{controlPressureTime.Value}s没有控稳。"));
                break;
            }
            Xmas11.Comm.Data.Common.PressureStableState pressureStableState = Xmas11.Comm.Data.Common.PressureStableState.UnKnown;
            if (item.GetDevice("P21").GetPressureStableState(out pressureStableState))
            {
                msg9.Content = pressureStableState.ToString();
                if (pressureStableState == Xmas11.Comm.Data.Common.PressureStableState.Stable)
                {
                    msg9.Content += $" 耗时{span.TotalSeconds}s";
                    break;
                }
                else
                {
                    msg9.Content += $"{pressure}, 耗时{span.TotalSeconds}s";
                    ValueData pValue = new ValueData("当前压力", pressure.Value, pressure.Unit.Symbol);
                    pList1.Append(pValue.WithDateTime());
                }
            }
            else
            {
                bool? key = item.Parent.VM.OpenInfoConfirmWindow("读取压力稳定状态失败,重试？");
                if (key.HasValue && key.Value)
                {
                    continue;
                }
                else
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "读取压力稳定状态失败"));
                    break;
                }
            }
        }
        #endregion

        item.GetDevice("P21").SetVentMode();
        System.Threading.Thread.Sleep(5000);

        #region 控制到-85Kpa
        RealTimeMsg msg10 = new RealTimeMsg("控压到量程下限");
        item.AddRealTimeMsgs(msg10);
        if (!item.GetDevice("P21").SetTargetPressure(new Pressure(-85, PressureUnit.kPa)))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "设置-85KPa压力通讯错误"));
        }
        msg10.Content = "完成";

        RealTimeMsg msg11 = new RealTimeMsg("获取压力状态");
        ListValueData pList2 = new ListValueData("控压到量程下限");
        item.AddRealTimeMsgs(msg11);
        System.Threading.Thread.Sleep(2000);
        beginTime = DateTime.Now;
        while (true)
        {
            TimeSpan span = DateTime.Now - beginTime;
            item.GetDevice("P21").GetPressure_IPM(out pressure);
            if (span.TotalSeconds > 35)
            {
                result.AddTestErrMsgs(new ErrMsg(30004, "-85KPa控稳超时,35s没有控稳。"));
                break;
            }
            Xmas11.Comm.Data.Common.PressureStableState pressureStableState = Xmas11.Comm.Data.Common.PressureStableState.UnKnown;
            if (item.GetDevice("P21").GetPressureStableState(out pressureStableState))
            {
                msg11.Content = pressureStableState.ToString();
                if (pressureStableState == Xmas11.Comm.Data.Common.PressureStableState.Stable)
                {
                    msg11.Content += $" 耗时{span.TotalSeconds}s";
                    break;
                }
                else
                {
                    msg11.Content += $"{pressure}, 耗时{span.TotalSeconds}s";
                    ValueData pValue = new ValueData("当前压力", pressure.Value, pressure.Unit.Symbol);
                    pList2.Append(pValue.WithDateTime());
                }
            }
            else
            {
                bool? key = item.Parent.VM.OpenInfoConfirmWindow("读取压力稳定状态失败,重试？");
                if (key.HasValue && key.Value)
                {
                    continue;
                }
                else
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "读取压力稳定状态失败"));
                    return result;
                }
            }

        }
        #endregion

        #endregion
        item.AddRealTimeMsgs(new RealTimeMsg("测试完成..."));
        item.GetDevice("P21").SetVentMode();

        System.Threading.Thread.Sleep(2000);
        item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_H, OpenCloseState.Close);
        item.GetDevice("P21").SetModuleStableEnable(StableModuleType.InnerModule_L, OpenCloseState.Close);

        RealTimeMsg msg1112 = new RealTimeMsg("电池电量");
        item.AddRealTimeMsgs(msg1112);
        item.GetDevice("P21").GetBatteryValue(out Bval);
        msg1112.Content = $"{Math.Round(Bval, 2) * 100}%";

        rData.Add(pList1);
        rData.Add(pList2);
        return result;
    }
    /// <summary>
    /// 大气压传感器测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic AtmosSensorTest(dynamic item)
    {
        Result<List<TextData>> result = new Result<List<TextData>>(true);
        List<TextData> rData = new List<TextData>() { new TextData("环境大气压"), new TextData("设备大气压") };
        result.Data = rData;

        item.ClearRealTimeMsgs();
        System.Threading.Thread.Sleep(500);
        //获取参数
        if (item.Parameters == null)
        {
            result.AddTestErrMsgs(new ErrMsg(10001, "参数为空"));
            return result;
        }
        TextParameter parameterSN = item.Parameters[0] as TextParameter;
        //获取条件
        if (item.Conditions == null)
        {
            result.AddTestErrMsgs(ErrMsg._10002);
            return result;
        }
        ValueCondition condition = item.Conditions[0] as ValueCondition;

        RealTimeMsg msg3 = new RealTimeMsg("设备大气压传感器SN号");
        item.AddRealTimeMsgs(msg3);
        string AtmosSensorSN = string.Empty;
        int trynum = 1;
        while (true)
        {
            msg3.ContentRunning();
            if (!item.GetDevice("P21").GetAtmosSensorSN(out AtmosSensorSN))
            {
                if (trynum++ > 3)
                {
                    bool? key = item.Parent.VM.OpenInfoConfirmWindow("获取设备大气压模块传感器编号失败,重试？");
                    if (key.HasValue && key.Value)
                        continue;
                    else
                    {
                        result.AddTestErrMsgs(new ErrMsg(10003, "获取设备大气压模块传感器编号指令执行失败"));
                        return result;
                    }
                }
            }
            else
            {
                msg3.Content = $"{AtmosSensorSN}";

                if (string.IsNullOrWhiteSpace(AtmosSensorSN))
                {
                    RealTimeMsg msg51 = new RealTimeMsg("设置大气压传感器编号");
                    item.AddRealTimeMsgs(msg51);
                    string setSn = "BMP" + DateTime.Now.ToString("yyMMddHHmmss");
                    if (!item.GetDevice("P21").SetAtmosSensorSN(setSn))
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "设置大气压传感器编号失败"));
                        return result;
                    }
                    msg51.Content = $"{setSn}, √";

                    RealTimeMsg msg52 = new RealTimeMsg("读大气压传感器编号");
                    item.AddRealTimeMsgs(msg52);
                    if (!item.GetDevice("P21").GetAtmosSensorSN(out AtmosSensorSN))
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "读大气压传感器编号失败"));
                        return result;
                    }
                    msg52.Content = $"{AtmosSensorSN}, √";
                }

                if (AtmosSensorSN.StartsWith("BMP") && AtmosSensorSN.Length == 15)
                {
                    if (MeterERP_MeterBaseInfoDAO.AddToRemote(AtmosSensorSN, parameterSN.Value))
                    {
                        result.AddTestErrMsgs(new ErrMsg(10003, $"将大气压传感器编号{AtmosSensorSN}组装到整机编号{parameterSN.Value}上失败。\r\n请重新写入大气压传感编号再测试。"));
                    }
                }
                else
                {
                    //result.AddTestErrMsgs(new ErrMsg(10003, $"设备大气压模块传感器编号{AtmosSensorSN}不合法，\r\n应该以BMP开头，长度是15位的字母与数字。\r\n如果没有编号或者是乱码，请重新写入大气压传感编号再测试。"));
                    //return result;

                    RealTimeMsg msg51 = new RealTimeMsg("设置大气压传感器编号");
                    item.AddRealTimeMsgs(msg51);
                    string setSn = "BMP" + DateTime.Now.ToString("yyMMddHHmmss");
                    if (!item.GetDevice("P21").SetAtmosSensorSN(setSn))
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "设置大气压传感器编号失败"));
                        return result;
                    }
                    msg51.Content = $"{setSn}, √";

                    RealTimeMsg msg52 = new RealTimeMsg("读大气压传感器编号");
                    item.AddRealTimeMsgs(msg52);
                    if (!item.GetDevice("P21").GetAtmosSensorSN(out AtmosSensorSN))
                    {
                        result.AddTestErrMsgs(new ErrMsg(20003, "读大气压传感器编号失败"));
                        return result;
                    }
                    msg52.Content = $"{AtmosSensorSN}, √";
                }
                break;
            }
        }


        //获取数据库大气压数据最新的一个数据
        //Environment_BarometricPressure
        //NowAtmosphericStr对应BP字段
        RealTimeMsg msg1 = new RealTimeMsg("环境标准大气压");
        item.AddRealTimeMsgs(msg1);

        List<double> enviromentAtmo = new List<double>();
        RealTimeWatch watch_Getatoms = new RealTimeWatch();
        string Errormsg = string.Empty;//大气压获取错误信息
        watch_Getatoms.Reset();
        while (true)
        {
            if (watch_Getatoms.TotalSeconds > 5)
            {
                watch_Getatoms.Stop();
                break;
            }
            enviromentAtmo = Helper.GetNewAtoms_SecondFloor(out Errormsg);
            if (enviromentAtmo != null && string.IsNullOrEmpty(Errormsg))
                break;
            Thread.Sleep(500);
        }
        if (!string.IsNullOrEmpty(Errormsg))
        {
            return result.AddTestErrMsgs(new ErrMsg(30001, Errormsg));
        }
        if (enviromentAtmo == null)
        {
            string msgstr = $"没有正确获取到最新的产线大气压，请排查144.190这台电脑是否正常打开了大气压采集软件。如果正常打开，请确认3个温度计是否都在线，如果没有3个，可能是温度计没电了，更换新电池。";
            item.AddRealTimeMsgs(new RealTimeMsg(msgstr));
            result.AddTestErrMsgs(new ErrMsg(10003, msgstr));
        }


        msg1.Content = (new Pressure(Math.Round(enviromentAtmo.Average(), 5), PressureUnit.kPa)).ToString();
        rData[0].Value = (new Pressure(Math.Round(enviromentAtmo.Average(), 5), PressureUnit.kPa)).ToString();

        RealTimeMsg msg2 = new RealTimeMsg("设备大气压");
        item.AddRealTimeMsgs(msg2);
        while (true)
        {
            msg2.ContentRunning();
            Xmas11.Domain.Mechanics.Pressure AtmosSensor = new Pressure(0, PressureUnit.kPa);
            if (item.GetDevice("P21").GetAtmosSensor(out AtmosSensor))
            {
                msg2.Content = AtmosSensor.ToString();
                rData[1].Value = AtmosSensor.ToString();
                var minvalue = enviromentAtmo.Average() - AtmosSensor.Value;
                var minvalue2 = enviromentAtmo.Select(w => w - AtmosSensor.Value).ToList();

                if (!condition.IsTrue(Math.Abs(minvalue)) && !condition.IsTrue(Math.Abs(minvalue2.Min())))
                {
                    result.AddTestErrMsgs(new ErrMsg(30004, $"设备大气压{AtmosSensor}与环境大气压{enviromentAtmo.Average()}差值{Math.Round(minvalue, 5)} kPa 过大，超过了指标{condition}"));
                }

                System.Threading.Thread.Sleep(500);
                break;
            }
            bool? key = item.Parent.VM.OpenInfoConfirmWindow("获取设备大气压失败,重试？");
            if (key.HasValue && key.Value)
                continue;
            else
            {
                return result.AddTestErrMsgs(new ErrMsg(10003, "获取大气压失败"));
            }
        }

        return result;
    }

    #region 气容测试
    /// <summary>
    /// 正压泄露测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic QRLeakTest(dynamic item)
    {
        item.ClearRealTimeMsgs();

        Result<List<DataBase>> result = new Result<List<DataBase>>(true);
        List<DataBase> rData = new List<DataBase>();
        ValueData valueDataCP = new ValueData("实时压力");
        ListValueData listValueDataCP = new ListValueData("实时压力");
        rData.Add(listValueDataCP);
        result.Data = rData;
        Stopwatch stopwatch = new Stopwatch();
        ValueParameter T_Input = item.Parameters[0] as ValueParameter; //充压超时
        ValueParameter T_Wait = item.Parameters[1] as ValueParameter; //稳压
        ValueParameter T_Get = item.Parameters[2] as ValueParameter; //采样

        ValueCondition P_Input = item.Conditions[0] as ValueCondition; //检测压力
        ValueCondition GoodRate = item.Conditions[1] as ValueCondition; //合格指标
        try
        {

            bool? key0 = ScriptHelper.OpenInfoImgConfirmWindow("测试前准备确认:\r\n\r\n1、按照图示，将811A右侧与中间接口使用三通和软管与810连接\r\n2、将810通过USB线，连接到电脑，需要通讯。\r\n以上 2 个条件任一条件不满足，都不能进行测试。", "pack://application:,,,/Bots.TestBench.UI.P21;Component/images/ConST811A-810.png");
            if (key0 != true)
            {
                item.IsRunning = false;
                return result.SetConclusion("条件不满足，手动中止。", ErrMsg._501002);
            }

            if (!item.GetDevice<ConST810>("P06").IsOpen)
            {
                bool? key = ScriptHelper.OpenInfoConfirmWindow(item, "当前测试项需要连接810，对气容进行气密测试。\r\n请将810开机后连接到电脑上，将811A右侧与中间接口使用三通和软管与810连接。\r\n点击确定进行下一步，点击取消中止测试");
                if (key != true)
                {
                    return result.SetConclusion($"与810通讯失败，需要810做为气源。", ErrMsg._30001);
                }
                else if (!item.GetDevice<ConST810>("P06").IsOpen)
                {
                    return result.SetConclusion($"与810通讯失败，需要810做为气源。", ErrMsg._30001);
                }
            }


            //被检切测量
            if (!item.GetDevice<ConST811A>("P21").SetTestMode())
            {
                return result.AddTestErrMsgs(new ErrMsg(20001, "切为测量模式失败"));
            }

            #region 切换低压量程
            RealTimeMsg msg0 = new RealTimeMsg(">>切换低压量程");
            item.AddRealTimeMsgs(msg0);
            while (true)
            {
                msg0.ContentRunning();
                if (item.GetDevice("P21").SetControlPressureModel(PressureSwitchTripType.Low))
                {
                    msg0.Content = "完成";
                    break;
                }
                msg0.Content = "失败";
                bool? key = item.Parent.VM.OpenInfoConfirmWindow("切换低压量程失败,重试？");
                if (key.HasValue && key.Value)
                {
                    continue;
                }
                else
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "切换低压量程失败"));
                    return result;
                }
            }
            System.Threading.Thread.Sleep(5000);

            msg0.Content = "完成";
            #endregion

            //打压
            #region 设置内部模块单位
            RealTimeMsg msg1 = new RealTimeMsg("设置内部模块单位");
            item.AddRealTimeMsgs(msg1);
            if (!item.GetDevice<ConST810>("P06").SetPressureUnit_IPM())
            {
                return result.SetConclusion("设置内部模块压力单位失败", ErrMsg._30001);
            }
            msg1.Name = "内部模块单位";
            msg1.Content = "kPa";
            #endregion

            #region 获取内部模块量程，太大的量程不能用，因为精度不够，上一步切低压是为了起保护作用。
            RealTimeMsg msg12 = new RealTimeMsg("模块量程");
            item.AddRealTimeMsgs(msg12);
            if (!item.GetDevice<ConST810>("P06").GetPressureControlRange_UpperLimit(out Pressure pressurerange))
            {
                return result.SetConclusion("获取内部模块压力单位失败", ErrMsg._30001);
            }
            msg12.Content = pressurerange.ToString();
            if (pressurerange.Value > 280)
            {
                return result.SetConclusion("当前设备的模块量程太大,不能精确的测试泄露，请更换一个小量程的模块再测试。", ErrMsg._30001);
            }
            #endregion

            #region 设置内部模块显示位宽
            RealTimeMsg msg13 = new RealTimeMsg("设置内部模块最大分辨率");
            item.AddRealTimeMsgs(msg13);
            if (!item.GetDevice<ConST810>("P06").SetDisplayWidth_IPM(8))
            {
                return result.SetConclusion("设置内部模块最大分辨率失败", ErrMsg._30001);
            }
            msg13.Content = " √ ";
            #endregion

            RealTimeMsg msg2 = new RealTimeMsg("设置设定压力点");
            item.AddRealTimeMsgs(msg2);
            Pressure setInnerPressure = new Pressure(P_Input.Value, PressureUnit.kPa);
            msg2.Content = setInnerPressure.ToString();
            if (!item.GetDevice<ConST810>("P06").SetTargetPressure(setInnerPressure))
            {
                return result.SetConclusion($"设定压力点失败{setInnerPressure}", ErrMsg._30001);
            }
            msg2.Name = $"控压点{setInnerPressure}";
            msg2.Content = " √ ";

            double Maxvalue = 0;
            stopwatch.Start();
            RealTimeMsg msg3 = new RealTimeMsg("造压中");
            item.AddRealTimeMsgs(msg3);
            while (true)
            {
                if (!item.IsRunning)
                    return result.SetConclusion("测试被操作员手动终止", ErrMsg._09999);
                Xmas11.Comm.Data.Common.PressureStableState state = Xmas11.Comm.Data.Common.PressureStableState.UnKnown;
                Xmas11.Domain.Mechanics.Pressure pressure = new Pressure(0, PressureUnit.kPa);
                if (!item.GetDevice<ConST810>("P06").GetPressure_IPM(out pressure))
                    return result.AddTestErrMsgs(new ErrMsg(20001, "读取当前压力值失败"));

                valueDataCP.Value = pressure.Value;
                listValueDataCP.AppendAsync(valueDataCP.WithDateTime());

                if (Maxvalue < pressure.Value)
                    Maxvalue = pressure.Value;

                if (!item.GetDevice<ConST810>("P06").GetPressureStableState(out state))
                    return result.AddTestErrMsgs(new ErrMsg(20001, "读取当前稳定失败"));

                msg3.Content = string.Format("{0}，控压时间 {1} 秒", pressure, (stopwatch.ElapsedMilliseconds / 1000).ToString());

                if (pressure.Value > P_Input.Value * 0.95 && state == Xmas11.Comm.Data.Common.PressureStableState.Stable)
                {
                    break;
                }
                if (T_Input.Value < (stopwatch.ElapsedMilliseconds / 1000))
                {
                    if (Maxvalue > 4)
                    {
                        result.SetConclusion($"控压失败！{setInnerPressure}压力点控压超时{T_Input}，最大压力为{Maxvalue}，气容可能泄露，打不了稳压。请尝试手动控到5kPa左右，然后直接切到测量档位，观察压力的变化情况。");
                    }
                    else
                    {
                        result.SetConclusion($"控压失败！{setInnerPressure}压力点控压超时{T_Input}，请尝试手动控到5kPa左右，然后直接切到测量档位，观察压力的变化情况。确认气容是否泄露严重。");
                    }
                    return result.AddTestErrMsgs(new ErrMsg(20001, $"控压失败！{setInnerPressure}压力点控压超时{T_Input}"));
                }
                System.Threading.Thread.Sleep(1000);
            }
            stopwatch.Stop();
            msg3.Name = "造压完成";
            if (!item.GetDevice<ConST810>("P06").ChangeToPressureMeasure())
            {
                return result.AddTestErrMsgs(new ErrMsg(20001, "切为测量模式失败"));
            }
            //等待
            RealTimeMsg msg4 = new RealTimeMsg("稳压等待");
            item.AddRealTimeMsgs(msg4);
            for (int i = 1; i <= T_Wait.Value; i++)
            {
                if (!item.IsRunning)
                    return result.SetConclusion("测试被操作员手动终止", ErrMsg._09999);
                Xmas11.Domain.Mechanics.Pressure pressure = new Pressure(0, PressureUnit.kPa);
                if (!item.GetDevice<ConST810>("P06").GetPressure_IPM(out pressure))
                    return result.AddTestErrMsgs(new ErrMsg(20001, "读取当前压力值失败"));
                valueDataCP.Value = pressure.Value;
                listValueDataCP.AppendAsync(valueDataCP.WithDateTime());

                msg4.Content = $" {i} s --> {pressure}";
                System.Threading.Tasks.Task.Delay(1000).Wait();
            }

            //采集
            RealTimeMsg msg5 = new RealTimeMsg("泄露采样");
            item.AddRealTimeMsgs(msg5);
            double firstvalue = valueDataCP.Value;
            msg5.Content = $"{valueDataCP}kPa";
            for (int i = 1; i <= T_Get.Value; i++)
            {
                if (!item.IsRunning)
                    return result.SetConclusion("测试被操作员手动终止", ErrMsg._09999);
                Xmas11.Domain.Mechanics.Pressure pressure = new Pressure(0, PressureUnit.kPa);
                if (!item.GetDevice<ConST810>("P06").GetPressure_IPM(out pressure))
                    return result.AddTestErrMsgs(new ErrMsg(20001, "读取当前压力值失败"));
                valueDataCP.Value = pressure.Value;
                listValueDataCP.AppendAsync(valueDataCP.WithDateTime());

                msg5.Content = $"{i} s   {firstvalue}kPa --> {pressure}";
                System.Threading.Tasks.Task.Delay(1000).Wait();
            }
            double secondvalue = valueDataCP.Value;

            //判定
            double gapvalue = Math.Abs(secondvalue - firstvalue);
            double Gaprate = Math.Round(gapvalue / firstvalue, 4);
            RealTimeMsg msg6 = new RealTimeMsg("压力变化");
            item.AddRealTimeMsgs(msg6);
            msg6.Content = $"变化量{Math.Round(gapvalue, 4)}，变化率{Gaprate}";

            if (!GoodRate.IsTrue(Gaprate * 100))
            {
                return result.SetConclusion("泄露率不合格", ErrMsg._20001);
            }

            return result;
        }
        finally
        {
            stopwatch.Stop();
            item.GetDevice<ConST810>("P06").SetVentMode();
        }
    }
    #endregion
    #endregion 整机自检

