    /// <summary>
    /// 设置设备出厂日期
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic SetDeviceFactoryDate(dynamic item)
    {
        Result<List<TextData>> result = new Result<List<TextData>>(true);
        List<TextData> rData = new List<TextData>() { new TextData("出厂日期"), new TextData("其他日期") };
        result.Data = rData;
        item.ClearRealTimeMsgs();
        System.Threading.Thread.Sleep(500);

        RealTimeMsg msg1 = new RealTimeMsg();
        msg1.Name = "设置出厂日期";
        item.AddRealTimeMsgs(msg1);
        DateTime now = DateTime.UtcNow;
        if (!item.GetDevice("P21").SetDeviceFactoryDate(now))
        {
            msg1.Content = "通讯异常";
            result.AddTestErrMsgs(new ErrMsg(20001, "通讯异常"));
            result.Conclusion += "通讯异常";
            return result;
        }
        System.Threading.Thread.Sleep(1000);
        if (!item.GetDevice("P21").SetDeviceFactoryDate(now))
        {
            msg1.Content = "通讯异常";
            result.AddTestErrMsgs(new ErrMsg(20001, "通讯异常"));
            result.Conclusion += "通讯异常";
            return result;
        }
        msg1.Content = now.ToString();
        System.Threading.Thread.Sleep(1000);

        RealTimeMsg msg2 = new RealTimeMsg();
        msg2.Name = "获取出厂日期";
        item.AddRealTimeMsgs(msg2);
        DateTime returnTime = DateTime.MinValue;

        if (!item.GetDevice("P21").GetDeviceFactoryDate(out returnTime))
        {
            msg2.Content = "通讯异常";
            result.AddTestErrMsgs(new ErrMsg(20001, "通讯异常"));
            result.Conclusion += "通讯异常";
            return result;
        }
        DateTime stdTime = new DateTime(returnTime.Year, returnTime.Month, returnTime.Day, returnTime.Hour, returnTime.Minute, returnTime.Second, DateTimeKind.Utc);
        rData[0].Value = msg2.Content = stdTime.ToString();
        if (stdTime.Subtract(now).TotalDays > 1)
        {
            result.AddTestErrMsgs(new ErrMsg(30003, string.Format("写入时间{0}与读取时间{1}相差大于1天", now.ToString(), stdTime.ToString())));
        }

        if (item.GetDevice("P21").IsDoubleRange())
        {
            #region 初始化校准日期
            //高低压模块校准日期设为0000000000
            string tagetSTR = "0000000000";
            RealTimeMsg msg3 = new RealTimeMsg();
            msg3.Name = "获取高压模块校准日期";
            item.AddRealTimeMsgs(msg3);
            string CelHTime1 = string.Empty;

            if (!item.GetDevice("P21").GetModelCalibrationDate(PressureSwitchTripType.High, out CelHTime1))
            {
                msg3.Content = "通讯异常";
                result.AddTestErrMsgs(new ErrMsg(20001, "通讯异常"));
                result.Conclusion += "通讯异常";
                return result;
            }
            msg3.Content = CelHTime1.ToString();
            if (!item.GetDevice("P21").SetModelCalibrationDate(PressureSwitchTripType.High, tagetSTR))
            {
                msg3.Content = "通讯异常";
                result.AddTestErrMsgs(new ErrMsg(20001, "通讯异常"));
                result.Conclusion += "通讯异常";
                return result;
            }

            RealTimeMsg msg4 = new RealTimeMsg();
            msg4.Name = "获取高压模块校准日期";
            item.AddRealTimeMsgs(msg4);
            string CelHTime2 = string.Empty;
            if (!item.GetDevice("P21").GetModelCalibrationDate(PressureSwitchTripType.High, out CelHTime2))
            {
                msg4.Content = "通讯异常";
                result.AddTestErrMsgs(new ErrMsg(20001, "通讯异常"));
                result.Conclusion += "通讯异常";
                return result;
            }
            msg4.Content = CelHTime2.ToString();


            RealTimeMsg msg5 = new RealTimeMsg();
            msg5.Name = "获取低压模块校准日期";
            item.AddRealTimeMsgs(msg5);
            string CelLTime1 = string.Empty;

            if (!item.GetDevice("P21").GetModelCalibrationDate(PressureSwitchTripType.Low, out CelLTime1))
            {
                msg5.Content = "通讯异常";
                result.AddTestErrMsgs(new ErrMsg(20001, "通讯异常"));
                result.Conclusion += "通讯异常";
                return result;
            }
            msg5.Content = CelLTime1.ToString();
            if (!item.GetDevice("P21").SetModelCalibrationDate(PressureSwitchTripType.Low, tagetSTR))
            {
                msg5.Content = "通讯异常";
                result.AddTestErrMsgs(new ErrMsg(20001, "通讯异常"));
                result.Conclusion += "通讯异常";
                return result;
            }

            RealTimeMsg msg6 = new RealTimeMsg();
            msg6.Name = "获取低压模块校准日期";
            item.AddRealTimeMsgs(msg6);
            string CelLTime2 = string.Empty;
            if (!item.GetDevice("P21").GetModelCalibrationDate(PressureSwitchTripType.Low, out CelLTime2))
            {
                msg6.Content = "通讯异常";
                result.AddTestErrMsgs(new ErrMsg(20001, "通讯异常"));
                result.Conclusion += "通讯异常";
                return result;
            }
            msg6.Content = CelLTime2.ToString();
            #endregion 初始化校准日期
        }

        System.Threading.Thread.Sleep(2000);

        return result;
    }
    /// <summary>
    /// 型号读取测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestGetDevType(dynamic item)
    {
        Result<List<TextData>> result = new Result<List<TextData>>(true);
        List<TextData> rData = new List<TextData> { new TextData("发货单整机型号"), new TextData("实际整机型号") };
        result.Data = rData;


        //获取参数
        if (item.Parameters == null)
        {
            result.AddTestErrMsgs(new ErrMsg(10001, "参数为空"));
            result.Conclusion += "参数为空";
            return result;
        }
        TextParameter parameter1 = item.Parameters[0] as TextParameter;

        item.ClearRealTimeMsgs();
        System.Threading.Thread.Sleep(500);
        try
        {
            RealTimeMsg msg1111 = new RealTimeMsg("获取设备高压量程");
            item.AddRealTimeMsgs(msg1111);
            PressureRange mls = new PressureRange();
            if (!item.GetDevice("P21").GetHighPressureModelRange(out mls))
            {
                result.AddTestErrMsgs(new ErrMsg(20001, "获取设备高压量程"));
                result.Conclusion += "获取设备高压量程";
                return result;
            }
            //msg1111.Content = $"{mls.DeviceModel}/{mls.Enable}/{mls.LowerValue}/{mls.UpperValue}";
            msg1111.Content = $"{mls.LowerValue}/{mls.UpperValue}";
        }
        catch (Exception)
        {
        }


        //if (mls.DeviceModel.ToString().Contains("-6M"))
        //{
        //    if (mls.LowerValue > 50)
        //    {
        //        result.AddTestErrMsgs(new ErrMsg(20001, "设备正压量程应该是50kPa"));
        //        result.Conclusion += "设备正压量程应该是50kPa";
        //        return result;
        //    }
        //}
        try
        {
            RealTimeMsg msg11112 = new RealTimeMsg("获取设备低压量程");
            item.AddRealTimeMsgs(msg11112);
            PressureRange mls2 = new PressureRange();
            if (!item.GetDevice("P21").GetHighPressureModelRange(out mls2))
            {
                result.AddTestErrMsgs(new ErrMsg(20001, "获取设备低压量程"));
                result.Conclusion += "获取设备低压量程";
                return result;
            }
            //msg1111.Content = $"{mls.DeviceModel}/{mls.Enable}/{mls.LowerValue}/{mls.UpperValue}";
            msg11112.Content = $"{mls2.LowerValue}/{mls2.UpperValue}";
        }
        catch (Exception)
        {
        }


        RealTimeMsg msg1 = new RealTimeMsg("获取发货单整机型号");
        item.AddRealTimeMsgs(msg1);

        string DevTypeSTD = string.Empty;//标准信息
        string DevTypeUUD = string.Empty;//实际信息

        RealTimeMsg msg2 = new RealTimeMsg();
        msg2.Content = "发指令读取整机型号";

        item.AddRealTimeMsgs(msg2);

        if (!item.GetDevice("P21").GetAllDevType(out DevTypeUUD))
        {
            result.AddTestErrMsgs(new ErrMsg(20001, "读取整机型号失败"));
            result.Conclusion += "读取整机型号失败";

            return result;
        }

        msg2.Name = "整机型号";
        msg2.Content = DevTypeUUD;
        rData[1].Value = DevTypeUUD;
        item.Root.DUT.DeviceSalesType = DevTypeUUD;
        DevTypeUUD = DevTypeUUD.Replace(".", "").Replace("_", "");
        if (item.Root.DUT.IsSpecialty)
        {
            result.Conclusion = "当前设备是特制订单下的设备，设备类型保持原有信息。";
            return result;
        }

        DevTypeSTD = item.Root.DUT.DeviceSalesType;
        msg1.Content = DevTypeSTD;

        rData[0].Value = DevTypeSTD;
        DevTypeSTD = DevTypeSTD.Replace(".", "").Replace("_", "");

        if (DevTypeSTD != DevTypeUUD)
        {
            System.Text.StringBuilder sb = new System.Text.StringBuilder();
            sb.AppendFormat("请确认设备类型:{0} 是否合格！", rData[1].Value);
            sb.AppendLine();
            sb.AppendFormat("发货单设备类型:{0}", rData[0].Value);
            sb.Append("\r\n单击‘是’按钮是设备类型测试通过。");

            bool? key = ScriptHelper.OpenInfoConfirmWindow(item, sb.ToString(), 30, 0);

            if (key != true)
            {
                result.AddTestErrMsgs(new ErrMsg(30003, string.Format("设备实际型号{0}和标准信息{1}不一致", DevTypeUUD, DevTypeSTD)));
                result.Conclusion += string.Format("设备实际型号{0}和标准信息{1}不一致", DevTypeUUD, DevTypeSTD);
                return result;
            }
        }

        if (item.Root.DUT.DeviceMode == "ConST811AG")
        {
            msg1 = new RealTimeMsg("获取发货单是否支持表绝压切换");
            item.AddRealTimeMsgs(msg1);
            string stressType = item.Root.DUT.OrderType == "3" ? "支持表/绝压切换" : item.Root.DUT.OrderSaleMode;
            msg1.Content = stressType;
            if (string.IsNullOrWhiteSpace(stressType))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "发货单数据异常"));
                return result;
            }
            msg1 = new RealTimeMsg("获取设备表绝压切换功能状态");
            item.AddRealTimeMsgs(msg1);
            if (!item.GetDUTDevice().GetControlFeatureConfig(out OpenCloseState state))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "获取设备表绝压切换功能状态失败"));
                return result;
            }
            msg1.Content = state.ToString();
            if ((state == OpenCloseState.Open && !stressType.Contains("支持表/绝压切换")) || (state == OpenCloseState.Close && stressType.Contains("支持表/绝压切换")))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "设备表绝压切换功能状态与发货单不匹配"));
                return result;
            }
        }
        return result;

    }
    /// <summary>
    /// 软件版本读取测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestGetSoftVersions(dynamic item)
    {
        Result<List<TextData>> result = new Result<List<TextData>>(true);
        List<TextData> rData = new List<TextData>() { new TextData("系统版本"), new TextData("电测版本"), new TextData("控制板版本") };
        result.Data = rData;

        //获取参数
        if (item.Parameters == null)
        {
            result.AddTestErrMsgs(ErrMsg._10001);
            return result;
        }
        TextParameter parameter1 = item.Parameters[0] as TextParameter;

        item.ClearRealTimeMsgs();

        System.Threading.Thread.Sleep(500);

        //是否检验通过
        bool isCheckPass = false;
        //主版本是否高于最新版本
        bool isGreaterHost = false;
        //电测板版本是否高于最新版本
        bool isGreaterELE = false;
        //控制板版本是否高于最新版本
        bool isGreaterCOL = false;

        #region 获取系统版本
        //获取系统版本
        string version;
        if (!item.GetDevice("P21").GetVersion(out version))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "读取系统版本失败"));
            return result;
        }
        rData[0].Value = version;
        RealTimeMsg msg1 = new RealTimeMsg("系统版本");
        msg1.Content = rData[0].Value;
        item.AddRealTimeMsgs(msg1);

        VersionValidResponse response = Bots.Service.ServiceHelper.DBService.VersionValid(rData[0].Value);
        string versionSTD = response.LatestVersion;
        string versionUUD = rData[0].Value;
        switch (response.Result)
        {
            case VersionValidResult.NonStandard:
                result.AddTestErrMsgs(new ErrMsg(30003, string.Format("验证主程序版本{0}格式不规范", versionUUD)));
                break;
            case VersionValidResult.UnKnown:
                result.AddTestErrMsgs(new ErrMsg(30003, string.Format("验证主程序版本{0}未匹配到服务器版本", versionUUD)));
                break;
            case VersionValidResult.Less:
                result.AddTestErrMsgs(new ErrMsg(30003, string.Format("验证主程序版本{0}不是最新版本{1}", versionUUD, versionSTD)));
                break;
            case VersionValidResult.Equal:
                isCheckPass = true;
                break;
            case VersionValidResult.Greater:
                isGreaterHost = true;
                break;
        }
        System.Threading.Thread.Sleep(500);
        #endregion


        #region 获取电测版本
        string coreVersion;

        if (!item.GetDevice("P21").GetVersion_Electricity(out coreVersion))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "获取电测版本失败"));
            return result;
        }
        rData[1].Value = coreVersion;
        RealTimeMsg msg2 = new RealTimeMsg("电测版本");
        msg2.Content = coreVersion;
        item.AddRealTimeMsgs(msg2);


        response = Bots.Service.ServiceHelper.DBService.VersionValid(rData[1].Value);
        string versionSTDELE = response.LatestVersion;
        string versionUUDELE = rData[1].Value;
        switch (response.Result)
        {
            case VersionValidResult.NonStandard:
                result.AddTestErrMsgs(new ErrMsg(30003, string.Format("验证电测版本{0}格式不规范", versionUUDELE)));
                break;
            case VersionValidResult.UnKnown:
                result.AddTestErrMsgs(new ErrMsg(30003, string.Format("验证电测版本{0}未匹配到服务器版本", versionUUDELE)));
                break;
            case VersionValidResult.Less:
                result.AddTestErrMsgs(new ErrMsg(30003, string.Format("验证电测版本{0}不是最新版本{1}", versionUUDELE, versionSTDELE)));
                break;
            case VersionValidResult.Equal:
                isCheckPass = true;
                break;
            case VersionValidResult.Greater:
                isGreaterELE = true;
                break;
        }

        #endregion


        #region 获取控制板固件版本
        string type;
        if (!item.GetDevice("P21").GetDevType(out type))
        {
            result.AddTestErrMsgs(new ErrMsg(20001, "获取整机设备类型失败"));
            return result;
        }

        //获取控制板固件版本
        string controllerVersion;
        if (!item.GetDevice("P21").GetVersion_Controller(out controllerVersion))
        {
            result.AddTestErrMsgs(new ErrMsg(20003, "获取控制板版本失败"));
            return result;
        }
        rData[2].Value = controllerVersion;
        RealTimeMsg msg3 = new RealTimeMsg("控制板版本");
        msg3.Content = rData[2].Value;
        item.AddRealTimeMsgs(msg3);

        response = Bots.Service.ServiceHelper.DBService.VersionValid(rData[2].Value);
        string versionSTDCOL = response.LatestVersion;
        string versionUUDCOL = rData[2].Value;
        switch (response.Result)
        {
            case VersionValidResult.NonStandard:
                result.AddTestErrMsgs(new ErrMsg(30003, string.Format("验证控制版本{0}格式不规范", versionUUDCOL)));
                break;
            case VersionValidResult.UnKnown:
                result.AddTestErrMsgs(new ErrMsg(30003, string.Format("验证控制版本{0}未匹配到服务器版本", versionUUDCOL)));
                break;
            case VersionValidResult.Less:
                result.AddTestErrMsgs(new ErrMsg(30003, string.Format("验证控制版本{0}不是最新版本{1}", versionUUDCOL, versionSTDCOL)));
                break;
            case VersionValidResult.Equal:
                isCheckPass = true;
                break;
            case VersionValidResult.Greater:
                isGreaterCOL = true;
                break;
        }

        #endregion

        if (isGreaterHost || isGreaterELE || isGreaterCOL)
        {
            System.Text.StringBuilder sb = new System.Text.StringBuilder();

            if (isGreaterHost)
            {

                sb.AppendFormat("请确认设备软件版本:{0},服务器端最新版本:{1}是否合格！", versionUUD, versionSTD);
                sb.AppendLine();
            }
            if (isGreaterCOL)
            {

                sb.AppendFormat("请确认设备控制板版本:{0},服务器端最新版本:{1}是否合格！", versionUUDCOL, versionSTDCOL);
                sb.AppendLine();
            }
            if (isGreaterELE)
            {

                sb.AppendFormat("请确认设备电测板版本:{0},服务器端最新版本:{1}是否合格！", versionUUDELE, versionSTDELE);
                sb.AppendLine();
            }
            sb.Append("\r\n单击‘是’按钮使软件版本测试通过。");

            bool? key = ScriptHelper.OpenInfoConfirmWindow(item, sb.ToString());

            if (key != true)
            {
                result.AddTestErrMsgs(new ErrMsg(30003, "验证设备版本高于最新版本"));
            }
            else
            {
                isCheckPass = true;
            }
        }
        return result;
    }
    /// <summary>
    /// 量程获取
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestGetPressureRange(dynamic item)
    {
        try
        {
            Result<List<TextData>> result = new Result<List<TextData>>(true);
            List<TextData> rData = new List<TextData>
            {
                new TextData("高压模块编号"),
                new TextData("低压模块编号"),
                new TextData("高压模块量程"),
                new TextData("低压模块量程")
            };
            result.Data = rData;
            item.ClearRealTimeMsgs();

            RealTimeMsg msg0 = new RealTimeMsg("获取设备模块状态");
            item.AddRealTimeMsgs(msg0);
            RealTimeMsg msg1 = new RealTimeMsg("获取模块编号");
            item.AddRealTimeMsgs(msg1);
            RealTimeMsg msg2 = new RealTimeMsg("获取模块量程");
            item.AddRealTimeMsgs(msg2);
            if (item.GetDevice("P21").IsDoubleRange())
            {
                msg0.Content = "设备带高低压双模块";
                string highSN;
                if (!item.GetDevice("P21").GetHighPressureModelSerialNumber(out highSN))
                {
                    result.AddTestErrMsgs(new ErrMsg(20001, "获取模块编号失败"));
                    return result;
                }
                string lowSN;
                if (!item.GetDevice("P21").GetLowPressureModelSerialNumber(out lowSN))
                {
                    result.AddTestErrMsgs(new ErrMsg(20001, "获取模块编号失败"));
                    return result;
                }
                msg1.Content = string.Format("高压:{0},低压:{1}", highSN, lowSN);

                PressureRange highRange = new PressureRange();
                if (!item.GetDevice("P21").GetHighPressureModelRange(out highRange))
                {
                    result.AddTestErrMsgs(new ErrMsg(20001, "获取模块量程失败"));
                    return result;
                }
                PressureRange lowRange = new PressureRange();
                if (!item.GetDevice("P21").GetLowPressureModelRange(out lowRange))
                {
                    result.AddTestErrMsgs(new ErrMsg(20001, "获取模块量程失败"));
                    return result;
                }
                msg2.Content = string.Format("高压:{0},低压:{1}", highRange.ToString(), lowRange.ToString());

                rData[0].Value = highSN;
                rData[1].Value = lowSN;
                rData[2].Value = highRange.ToString();
                rData[3].Value = lowRange.ToString();
            }
            else
            {
                msg0.Content = "设备为单模块";
                string highSN;
                if (!item.GetDevice("P21").GetControllerModuleSerialNumber(out highSN))
                {
                    result.AddTestErrMsgs(new ErrMsg(20001, "获取模块编号失败"));
                    return result;
                }
                msg1.Content = highSN;

                PressureRange range = new PressureRange();
                if (!item.GetDevice("P21").GetControllerModuleRange(out range))
                {
                    result.AddTestErrMsgs(new ErrMsg(20001, "获取模块量程失败"));
                    return result;
                }
                msg2.Content = range.ToString();

                rData[0].Name = "模块编号";
                rData[2].Name = "模块量程";
                rData[0].Value = highSN;
                rData[1].Value = highSN;
                rData[2].Value = range.ToString();
                rData[3].Value = range.ToString();

                rData.RemoveAt(1);
                rData.RemoveAt(2);
            }
            return result;
        }
        finally
        {
        }
    }
    /// <summary>
    /// 精度获取
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestGetPressureAccuracyLevel(dynamic item)
    {
        try
        {
            Result<List<TextData>> result = new Result<List<TextData>>(true);
            List<TextData> rData = new List<TextData> { new TextData("高压"), new TextData("低压") };
            result.Data = rData;
            item.ClearRealTimeMsgs();

            RealTimeMsg msg0 = new RealTimeMsg("获取设备模块状态");
            item.AddRealTimeMsgs(msg0);
            RealTimeMsg msg1 = new RealTimeMsg("获取模块精度");
            item.AddRealTimeMsgs(msg1);
            if (item.GetDevice("P21").IsDoubleRange())
            {
                msg0.Content = "设备带高低压双模块";
                double HPAccuracyLevel = 0;
                if (!item.GetDevice("P21").GetHighPressureModelAccuracyLevel(out HPAccuracyLevel))
                {
                    result.AddTestErrMsgs(new ErrMsg(20001, "获取模块精度失败"));
                    result.Conclusion += "获取模块精度失败";
                    return result;
                }
                double LPAccuracyLevel = 0;
                if (!item.GetDevice("P21").GetLowPressureModelAccuracyLevel(out LPAccuracyLevel))
                {
                    result.AddTestErrMsgs(new ErrMsg(20001, "获取模块精度失败"));
                    result.Conclusion += "获取模块精度失败";
                    return result;
                }
                msg1.Content = string.Format("高压:{0},低压:{1}", HPAccuracyLevel.ToString(), LPAccuracyLevel.ToString());
                rData[0].Value = HPAccuracyLevel.ToString();
                rData[1].Value = LPAccuracyLevel.ToString();
                List<double> DUTlevel = item.Root.DUT.DeviceOrderprecision;

                if (DUTlevel.Count == 0)
                {
                    bool? key = ScriptHelper.OpenInfoConfirmWindow(item, "当前设备没有从发货单中获取到精度信息，无法进行比较，请确认设备的精度等级是否符合要求：\r\n" + msg1.Content + "\r\n点击确定测试项通过，继续进行测试，否则当前测试项不通过。");
                    if (key != true)
                    {
                        result.AddTestErrMsgs(new ErrMsg(20001, "当前设备没有从发货单中获取到精度信息"));
                        result.Conclusion += "当前设备没有从发货单中获取到精度信息";
                        return result;
                    }
                    item.AddRealTimeMsgs(new RealTimeMsg("当前设备没有从发货单中获取到精度信息,手动判定通过"));
                    return result;
                }

                if (DUTlevel.Count == 1)
                {
                    bool? key = ScriptHelper.OpenInfoConfirmWindow(item, $"当前双模块设备从发货单中只获取到一个精度信息{DUTlevel.First().ToString()}，无法比较双模块，请确认设备的精度等级是否符合要求：\r\n" + msg1.Content + "\r\n点击确定测试项通过，继续进行测试，否则当前测试项不通过。");
                    if (key != true)
                    {
                        result.AddTestErrMsgs(new ErrMsg(20001, $"当前双模块设备从发货单中只获取到一个精度信息{DUTlevel.First().ToString()}"));
                        result.Conclusion += $"当前双模块设备从发货单中只获取到一个精度信息{DUTlevel.First().ToString()}";
                        return result;
                    }
                    item.AddRealTimeMsgs(new RealTimeMsg($"当前双模块设备从发货单中只获取到一个精度信息{DUTlevel.First().ToString()}，手动判定通过"));
                    return result;
                }

                if (DUTlevel[0] != HPAccuracyLevel)
                {
                    result.AddTestErrMsgs(new ErrMsg(20001, $"高压模块精度{HPAccuracyLevel}与发货单不符{DUTlevel[0]}"));
                    result.Conclusion += $"高压模块精度{HPAccuracyLevel}与发货单不符{DUTlevel[0]}";
                }
                if (DUTlevel[1] != LPAccuracyLevel)
                {
                    result.AddTestErrMsgs(new ErrMsg(20001, $"低压模块精度{HPAccuracyLevel}与发货单不符{DUTlevel[0]}"));
                    result.Conclusion += $"低压模块精度{HPAccuracyLevel}与发货单不符{DUTlevel[0]}";
                }
            }
            else
            {
                msg0.Content = "设备为单模块";
                double HPAccuracyLevel = 0;
                if (!item.GetDevice("P21").GetControllerModelAccuracyLevel(out HPAccuracyLevel))
                {
                    result.AddTestErrMsgs(new ErrMsg(20001, "获取模块精度失败"));
                    result.Conclusion += "获取模块精度失败";
                    return result;
                }
                msg1.Content = HPAccuracyLevel.ToString();
                rData[0].Name = "精度";
                rData[0].Value = rData[1].Value = HPAccuracyLevel.ToString();
                rData.RemoveAt(1);

                List<double> DUTlevel = item.Root.DUT.DeviceOrderprecision;
                if (DUTlevel.Count == 0)
                {
                    bool? key = ScriptHelper.OpenInfoConfirmWindow(item, "当前设备没有从发货单中获取到精度信息，无法进行比较，请确认设备的精度等级是否符合要求：\r\n" + msg1.Content + "\r\n点击确定测试项通过，继续进行测试，否则当前测试项不通过。");
                    if (key != true)
                    {
                        result.AddTestErrMsgs(new ErrMsg(20001, "当前设备没有从发货单中获取到精度信息"));
                        result.Conclusion += "当前设备没有从发货单中获取到精度信息";
                        return result;
                    }
                    item.AddRealTimeMsgs(new RealTimeMsg("当前设备没有从发货单中获取到精度信息,手动判定通过"));
                    return result;
                }
                if (DUTlevel[0] != HPAccuracyLevel)
                {
                    result.AddTestErrMsgs(new ErrMsg(20001, $"模块精度{HPAccuracyLevel}与发货单不符{DUTlevel[0]}"));
                    result.Conclusion += $"模块精度{HPAccuracyLevel}与发货单不符{DUTlevel[0]}";
                }
            }
            return result;
        }
        finally
        {
        }
    }
    /// <summary>
    /// 语言验证
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestLanguage(dynamic item)
    {
        try
        {
            Result<List<TextData>> result = new Result<List<TextData>>(true);
            List<TextData> rData = new List<TextData> { new TextData("发货单销售渠道对应语言"), new TextData("设备当前语言") };
            result.Data = rData;
            item.ClearRealTimeMsgs();

            RealTimeMsg msg101 = new RealTimeMsg("设置设备语言列表");
            item.AddRealTimeMsgs(msg101);
            if (!item.GetDevice("P21").SetLanguangeList())
            {
                return result.AddTestErrMsgs(new ErrMsg(20001, "设置设备语言列表失败"));
            }
            msg101.Content = "成功";


            RealTimeMsg msg10 = new RealTimeMsg("获取设备语言列表");
            item.AddRealTimeMsgs(msg10);
            string languagelist = "";
            if (!item.GetDevice("P21").GetCurrentLanguangeList(out languagelist))
            {
                return result.AddTestErrMsgs(new ErrMsg(20001, "获取设备语言列表失败"));
            }
            msg10.Content = languagelist;

            RealTimeMsg msg0 = new RealTimeMsg("获取设备销售渠道");
            item.AddRealTimeMsgs(msg0);
            msg0.Content = item.Root.DUT.MarketChannel;


            string currentLanguange = string.Empty;
            if (item.Root.DUT.MarketChannel == "Const")
            {
                rData[0].Value = "中文";
                if (item.GetDevice("P21").GetCurrentLanguange(out currentLanguange))
                {
                    if (currentLanguange == "zh-CN")
                    {
                        rData[1].Value = "中文";
                    }
                    else
                    {
                        rData[1].Value = currentLanguange;
                        result.AddTestErrMsgs(new ErrMsg(30003, "获取当前语言不匹配"));
                        return result;
                    }
                }
                else
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "获取当前语言失败"));
                    return result;
                }
            }
            else if (item.Root.DUT.MarketChannel == "ExportSales")
            {
                rData[0].Value = "英文";

                if (item.GetDevice("P21").GetCurrentLanguange(out currentLanguange))
                {
                    if (currentLanguange == "en-US")
                    {
                        rData[1].Value = "英文";
                    }
                    else
                    {
                        rData[1].Value = currentLanguange;
                        result.AddTestErrMsgs(new ErrMsg(30003, "获取当前语言不匹配"));
                        return result;
                    }
                }
                else
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "获取当前语言失败"));
                    return result;
                }
            }
            else
            {
                result.AddTestErrMsgs(new ErrMsg(30004, "销售渠道未获取"));
                return result;
            }


            return result;
        }
        finally
        {
        }
    }
