    /// <summary>
    /// 设置量程限制开启
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic CheckPressureModelLimit(dynamic item)
    {
        Result<BooleanData> result = new Result<BooleanData>(true);
        BooleanData rData = new BooleanData("量程限制开启");
        result.Data = rData;
        item.ClearRealTimeMsgs();

        if (item.Root.DUT["IsSpecialty"] == "True")
        {
            result.Conclusion = "当前设备是特制订单下的设备，关闭量程限制。";
            return result;
        }
        RealTimeMsg msg0 = new RealTimeMsg("验证量程限制开启");
        item.AddRealTimeMsgs(msg0);
        //单模块不进行量程限制
        if (!item.GetDevice("P21").IsDoubleRange())
        {
            msg0.Content = "单模块不进行量程限制";
            rData.Value = true;
            return result;
        }

        #region 验证量程限制开启
        while (true)
        {
            ModelLimitSetting setting = new ModelLimitSetting();

            if (!item.GetDevice("P21").GetPressureModelLimitInfo(out setting))
            {
                rData.Value = false;
                result.AddTestErrMsgs(new ErrMsg(20003, "获取量程限制信息失败"));
                return result;
            }
            if (setting.DeviceModel == DeviceModelEnum.ConST811A_U)
            {
                rData.Value = true;
                msg0.Content = "高精度版不进行量程限制设置";
                return result;
            }
            if (setting.Enable)
            {
                rData.Value = true;
                return result;
            }
            else
            {
                if (!item.GetDevice("P21").OpenPressureModelLimit())
                {
                    rData.Value = false;
                    result.AddTestErrMsgs(new ErrMsg(20003, "打开量程限制失败"));
                    return result;
                }
                RealTimeMsg msg10 = new RealTimeMsg();
                msg10.Name = "设备重启";
                item.AddRealTimeMsgs(msg10);
                item.GetDevice("P21").SetReboot();
                item.GetDevice("P21").Close();
                item.GetDevice("P21").SetCommConfigEmpty();
                DateTime start = DateTime.Now;
                TimeSpan timeSpan = new TimeSpan();
                while (true)
                {
                    timeSpan = DateTime.Now - start;
                    msg10.Content = string.Format("等待10秒,判断重启,当前等待时间:{0}秒", timeSpan.TotalSeconds);
                    System.Threading.Thread.Sleep(1000);
                    if (timeSpan.TotalSeconds > 10)
                    {
                        break;
                    }
                }
                msg10.Content = "开始判断";

                RealTimeMsg msg11 = new RealTimeMsg("尝试打开设备通讯");
                item.AddRealTimeMsgs(msg11);
                int tryCount = 0;
                while (true)
                {
                    tryCount++;
                    System.Threading.Thread.Sleep(1000);
                    if (!item.GetDevice("P21").Open())
                    {
                        if (tryCount < 20)
                        {
                            msg11.Content = "通讯失败.重试";
                            continue;
                        }
                        else
                        {
                            msg11.Content = "重启失败.";
                            item.Parent.VM.OpenInfoConfirmWindow("重启失败,请确认设备是否重启成功,若无异常,再重新测试!");
                            result.AddTestErrMsgs(new ErrMsg(20003, "开启量程限制失败"));
                            return result;
                        }
                    }
                    else
                    {
                        break;
                    }
                }
                msg11.Content = "重新通讯成功,重启完成";
            }
        }
        #endregion

    }
    /// <summary>
    /// 证书日期及编号检测
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic TestCertificateDateAndCertificateNumber(dynamic item)
    {
        try
        {


            Result<List<TextData>> result = new Result<List<TextData>>(true);
            List<TextData> rData = new List<TextData>() { new TextData("证书日期"), new TextData("证书编号") };
            result.Data = rData;
            item.ClearRealTimeMsgs();
            //获取参数
            if (item.Parameters == null)
            {
                result.AddTestErrMsgs(new ErrMsg(10001, "参数为空"));
                return result;
            }
            TextParameter SN = item.Parameters[0] as TextParameter;
            string MeterCode = SN.Value;
            TextParameter isCheckPar = item.Parameters[1] as TextParameter;
            bool isCheck = Convert.ToBoolean(isCheckPar.Value);

            #region 设定参数
            // 证书日期 
            DateTime CertificateDate = DateTime.MaxValue;
            // 证书编号
            string CertificateNumber = string.Empty;
            bool isGetCertificationData = CertificationHelper.GetLastCertificationDateAndNumber(MeterCode, out CertificateDate, out CertificateNumber);
            bool isPrintCertification = U8DataHelper.GetPrintCertificationState(MeterCode);
            #endregion 设定参数

            #region 证书数据检测
            //送检日期与当前日期时间不超过一个月，认定为合格
            if (isCheck && isGetCertificationData)
            {

                bool IsPass = true;
                string certDateStr = string.Empty;
                string certCodeStr = string.Empty;

                if (!string.IsNullOrEmpty(item.Root.DUT.DeviceCategory1))
                {
                    if (item.Root.DUT.DeviceCategory1 == SalesChannels.Const.ToString())
                    {
                        if (Convert.ToBoolean(item.Root.DUT.DeviceCategory2))
                        {
                            certDateStr = "送检证书";
                            certCodeStr = "送检证书";
                        }
                        else if (item.Root.DUT.DeviceCategory3 == "2")
                        {
                            certDateStr = "检测通过";
                            certCodeStr = "检测通过";
                        }
                        else
                        {
                            if (CertificateDate == DateTime.MaxValue)
                            {
                                certDateStr = "未找到证书";
                                certCodeStr = "未找到证书";
                                IsPass = false;
                            }
                            else
                            {
                                if (isPrintCertification)
                                {
                                    certDateStr = CertificateDate.ToString("yyyy-MM-dd");
                                    certCodeStr = CertificateNumber;
                                }
                                else
                                {
                                    certDateStr = "未找到证书";
                                    certCodeStr = "未找到证书";
                                    IsPass = false;
                                }
                            }
                        }
                    }
                    else
                    {
                        certDateStr = "ADT证书";
                        certCodeStr = "ADT证书";
                    }
                }
                else
                {
                    if (CertificateDate == DateTime.MaxValue)
                    {
                        certDateStr = "未找到证书";
                        certCodeStr = "未找到证书";
                        IsPass = false;
                    }
                    else
                    {
                        if (isPrintCertification)
                        {
                            certDateStr = CertificateDate.ToString("yyyy-MM-dd");
                            certCodeStr = CertificateNumber;
                        }
                        else
                        {
                            certDateStr = "未找到证书";
                            certCodeStr = "未找到证书";
                            IsPass = false;
                        }
                    }
                }

                if (IsPass)
                {

                    rData[0].Value = certDateStr;
                    rData[1].Value = certCodeStr;
                    RealTimeMsg msg1 = new RealTimeMsg("证书日期");
                    msg1.Content = certDateStr;
                    item.AddRealTimeMsgs(msg1);
                    RealTimeMsg msg2 = new RealTimeMsg("证书编号");
                    msg2.Content = certCodeStr;
                    item.AddRealTimeMsgs(msg2);
                }
                else
                {
                    System.Text.StringBuilder sb = new System.Text.StringBuilder();

                    sb.Append("请联系计量室情况，然后确认是否通过证书检测！");
                    sb.AppendLine();
                    sb.Append("确定通过，取消不通过；");

                    bool? key = item.Root.VM.OpenInfoConfirmWindow(sb.ToString());

                    if (key == true)
                    {
                        rData[0].Value = rData[1].Value = "检测通过";
                        RealTimeMsg msg1 = new RealTimeMsg("证书日期");
                        msg1.Content = rData[0].Value;
                        item.AddRealTimeMsgs(msg1);
                        RealTimeMsg msg2 = new RealTimeMsg("证书编号");
                        msg2.Content = rData[1].Value;
                        item.AddRealTimeMsgs(msg2);
                    }
                    else
                    {
                        rData[0].Value = certDateStr;
                        rData[1].Value = certCodeStr;
                        RealTimeMsg msg1 = new RealTimeMsg("证书日期");
                        msg1.Content = rData[0].Value;
                        item.AddRealTimeMsgs(msg1);
                        RealTimeMsg msg2 = new RealTimeMsg("证书编号");
                        msg2.Content = rData[1].Value;
                        item.AddRealTimeMsgs(msg2);
                    }
                }
            }
            else if (isGetCertificationData)
            {
                rData[0].Value = rData[1].Value = "检测通过";
                RealTimeMsg msg1 = new RealTimeMsg("证书日期");
                msg1.Content = rData[0].Value;
                item.AddRealTimeMsgs(msg1);
                RealTimeMsg msg2 = new RealTimeMsg("证书编号");
                msg2.Content = rData[1].Value;
                item.AddRealTimeMsgs(msg2);
            }
            #endregion 证书数据检测

            System.Threading.Thread.Sleep(2000);

            return result;
        }
        finally
        {
            item.Root.DUT.DeviceCategory2 = string.Empty;
            item.Root.DUT.DeviceCategory3 = string.Empty;
        }
    }
