    /// <summary>
    /// 初始化控制设置
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic ControlSetting(dynamic item)
    {
        Result result = new Result(true);
        try
        {
            item.ClearRealTimeMsgs();
            //获取参数
            if (item.Parameters == null)
            {
                result.AddTestErrMsgs(ErrMsg._10001);
                return result;
            }
            TextParameter parameter1 = item.Parameters[0] as TextParameter;//编号

            RealTimeMsg msg1 = new RealTimeMsg("测量通道开机档位设置为mA档");
            item.AddRealTimeMsgs(msg1);
            if (!item.GetDevice("P21").SetEleChannelItem_CURR(false))
            {
                result.SetConclusion("开机档位设置为mA档失败", ErrMsg._201011);
                msg1.Content = "失败";
            }
            else
            {
                msg1.Content = "完成";
            }
            string devType = string.Empty;
            item.GetDevice("P21").GetAllDevType(out devType);
            RealTimeMsg msg2 = new RealTimeMsg("设置压力类型");
            item.AddRealTimeMsgs(msg2);

            OpenCloseState state = OpenCloseState.UnKnown;
            item.GetDevice("P21").GetControlFeatureConfig(out state);
            bool isSupportPTypeInit = state == OpenCloseState.Open;

            if (devType.Contains("BP"))
            {
                item.GetDevice("P21").SetSupportPressureType();//打开支持压力类型切换
                if (!item.GetDevice("P21").SetPressureModelPressureType(1))
                {
                    result.SetConclusion("设置压力类型失败", ErrMsg._201011);
                    msg2.Content = "失败";
                }
                else
                {
                    msg2.Content = "A";
                }
                item.GetDevice("P21").SetChangePressType();
            }
            else
            {
                item.GetDevice("P21").SetSupportPressureType();//打开支持压力类型切换
                if (parameter1.Value.StartsWith("811AG") || parameter1.Value.StartsWith("811AD") || parameter1.Value.StartsWith("811AL"))
                {
                    if (!item.GetDevice("P21").SetPressureModelPressureType(0))
                    {
                        result.SetConclusion("设置压力类型失败", ErrMsg._201011);
                        msg2.Content = "失败";
                    }
                    else
                    {
                        msg2.Content = "G";
                    }
                }
                else
                {
                    if (!item.GetDevice("P21").SetPressureModelPressureType(1))
                    {
                        result.SetConclusion("设置压力类型失败", ErrMsg._201011);
                        msg2.Content = "失败";
                    }
                    else
                    {
                        msg2.Content = "A";
                    }
                }
                item.GetDevice("P21").SetChangePressType();
            }

            if (!isSupportPTypeInit)
                item.GetDevice("P21").SetSupportPressureType(false);

            RealTimeMsg msg3 = new RealTimeMsg("设置最大控压速率");
            item.AddRealTimeMsgs(msg3);
            if (!item.GetDevice("P21").SetOpenMaxControlPressureSpeed(false))
            {
                result.SetConclusion("设置最大控压速率失败", ErrMsg._201011);
                msg3.Content = "失败";
            }
            else
            {
                msg3.Content = "完成";
            }

            RealTimeMsg msg4 = new RealTimeMsg("设置稳定度和稳定时间");
            item.AddRealTimeMsgs(msg4);
            if (!item.GetDevice("P21").SetPressureStability(0.003))
            {
                result.SetConclusion("设置稳定度和稳定时间失败", ErrMsg._201011);
                msg4.Content = "失败";
            }
            else
            {
                msg4.Content = "±0.003%FS;5s";
            }
            RealTimeMsg msg5 = new RealTimeMsg("设置自动清零");
            item.AddRealTimeMsgs(msg5);
            if (msg2.Content == "G")
            {
                if (!item.GetDevice("P21").SetClearStateOfVent(true))
                {
                    result.SetConclusion("设置自动清零失败", ErrMsg._201011);
                    msg5.Content = "失败";
                }
                else
                {
                    msg5.Content = "开启";
                }
            }
            else
            {
                if (!item.GetDevice("P21").SetClearStateOfVent(false))
                {
                    result.SetConclusion("设置自动清零失败", ErrMsg._201011);
                    msg5.Content = "失败";
                }
                else
                {
                    msg5.Content = "关闭";
                }
            }

            RealTimeMsg msg7 = new RealTimeMsg("关闭气柱头校正");
            item.AddRealTimeMsgs(msg7);
            if (!item.GetDevice("P21").SetAirStigmaState(false))
            {
                result.SetConclusion("关闭气柱头校正失败", ErrMsg._201011);
                msg7.Content = "失败";
            }
            else
            {
                msg7.Content = "成功";
            }
            RealTimeMsg msg8 = new RealTimeMsg("设定点限制默认关闭");
            item.AddRealTimeMsgs(msg8);
            if (!item.GetDevice("P21").CloseSetPointLimitPressureRange())
            {
                result.SetConclusion("设定点限制默认关闭失败", ErrMsg._201011);
                msg8.Content = "失败";
            }
            else
            {
                msg8.Content = "成功";
            }

            RealTimeMsg msg6 = new RealTimeMsg("设置排空压力");
            item.AddRealTimeMsgs(msg6);
            Pressure press = new Pressure(1000, PressureUnit.kPa);

            #region 量程

            PressureRange highRange = new PressureRange();
            if (item.GetDevice("P21").IsDoubleRange())
            {
                if (!item.GetDevice("P21").GetHighPressureModelRange(out highRange))
                {
                    result.AddTestErrMsgs(new ErrMsg(20001, "获取模块量程失败"));
                    return result;
                }
            }
            else
            {
                if (!item.GetDevice("P21").GetControllerModuleRange(out highRange))
                {
                    result.AddTestErrMsgs(new ErrMsg(20001, "获取模块量程失败"));
                    return result;
                }
            }
            #endregion
            bool skip = false;
            if (devType.Contains("BP"))
            {
                press = new Pressure(110, PressureUnit.kPa);
            }
            else
            {
                if (parameter1.Value.StartsWith("811AG") || parameter1.Value.StartsWith("811AAM") || parameter1.Value.StartsWith("811AAL"))
                {
                    press = new Pressure(1000, PressureUnit.kPa);
                    if (highRange.UpperValue < 1000)
                    {
                        skip = true;
                    }
                }
                else if (parameter1.Value.StartsWith("811AD"))
                {
                    press = new Pressure(250, PressureUnit.kPa);
                }
                else
                {
                    press = new Pressure(10, PressureUnit.kPa);
                }
            }

            msg6.Name = $"设置排空压力{highRange.UpperValue}";

            if (!skip)
            {
                msg6.Name = $"设置排空压力{press}";
                if (!item.GetDevice("P21").SetVentPressure(press))
                {
                    result.SetConclusion("设置排空压力失败", ErrMsg._201011);
                    msg6.Content = "失败";
                }
                else
                {
                    msg6.Content = press.ToString();
                }
            }
            msg6.Content = " √ ";

            return result;
        }
        finally
        {
            System.Threading.Thread.Sleep(500);
        }
    }

