            if (!item.GetDevice("P21").SetSoundValue() || !item.GetDevice("P21").SetKeyToneStateOpen()
                || !item.GetDevice("P21").SetPromptSoundStateOpen() || !item.GetDevice("P21").SetAlarmSoundStateOpen()
                || !item.GetDevice("P21").SetStableSoundStateOpen())//|| !item.GetDevice("P21").SetPotoshopSoundStateOpen()
            {
                result.SetConclusion("系统设置声音失败", ErrMsg._201011);
                msg4.Content = "失败";
            }
            else
            {
                msg4.Content = "成功";
            }
            //RealTimeMsg msg5 = new RealTimeMsg("设置CSV文件小数点，显示模式为暗色");
            //item.AddRealTimeMsgs(msg5);
            //if(!item.GetDevice("P21").SetCSVFileFormat() || !item.GetDevice("P21").SetTheme())
            //{
            //    result.SetConclusion("设置CSV文件小数点，显示模式为暗色失败", ErrMsg._201011);
            //    msg5.Content = "失败";
            //}
            //else
            //{
            //    msg5.Content = "成功";
            //}

            return result;
        }
        finally
        {
            System.Threading.Thread.Sleep(500);
        }
    }
    /// <summary>
    /// 设置后台参数
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic BackParameterSetting(dynamic item)
    {
        Result result = new Result(true);
        try
        {
            item.ClearRealTimeMsgs();

            TextParameter parameter0;
            try
            {
                parameter0 = item.Parameters[0] as TextParameter;
            }
            catch
            {
                result.AddTestErrMsgs(ErrMsg._10001);//添加错误信息
                return result;
            }

            RealTimeMsg msg112 = new RealTimeMsg($"获取{parameter0.Value}设备实际类型");
            item.AddRealTimeMsgs(msg112);

            string type;
            if (!item.GetDevice("P21").GetDevType(out type))
            {
                result.AddTestErrMsgs(new ErrMsg(20001, "获取设备实际类型失败"));
                return result;
            }
            msg112.Content = type;

            RealTimeMsg msg1122 = new RealTimeMsg($"获取{parameter0.Value}发货信息");
            item.AddRealTimeMsgs(msg1122);
            string jsonData = DBService.GetDevicesSpecificationBySN_Old(parameter0.Value.Trim());
            msg1122.Content = jsonData;
            JArray dataArray = null;
            bool _822specialty = false;

            //if (string.IsNullOrEmpty(jsonData))
            //{
            //    msg1122.Content += "没有查到发货信息";
            //}
            //try
            //{
            //    dataArray = (JArray)JsonConvert.DeserializeObject(jsonData);
            //    bool.TryParse(dataArray[13].ToString(), out _822specialty);
            //}
            //catch
            //{
            //    msg1122.Content += "发货信息解析失败";
            //}
            bool.TryParse(item.Root.DUT["Is822Specialty"],out _822specialty);
            RealTimeMsg msg11223 = new RealTimeMsg($"获取{parameter0.Value}MES信息");
            item.AddRealTimeMsgs(msg11223);
            var typevalue = Helper.GetSNType(parameter0.Value)?.Trim();
            msg11223.Content = typevalue;

            if (string.IsNullOrWhiteSpace(typevalue))
            {
                item.Root.IsRunning = false;
                return result.AddTestErrMsgs(new ErrMsg(000001, "提示：当前编号在系统中不存在，请确认扫描的编号是否正确。"));
            }


            if (item.Root.DUT.IsSpecialty)
            {
                RealTimeMsg msg1 = new RealTimeMsg("验证泵真空能力百分比");
                item.AddRealTimeMsgs(msg1);
                double value;
                double stdValue;
                double currentValue;
                if (!item.GetDevice("P21").GetControlPanelModelParameter(out stdValue, out currentValue))
                {
                    result.SetConclusion("获取泵真空能力失败", ErrMsg._201011);
                }
                else
                {
                    double BumpValue = 0.905;
                    if (typevalue.ToUpper().Contains("AL"))
                        BumpValue = 0.3;
                    else if (typevalue.ToUpper().Contains("D"))
                        BumpValue = 0.95;
                    else if (typevalue.ToUpper().Contains("B"))
                    {
                        BumpValue = 0.95;
                        typevalue = "ConST811A-BP";
                    }

                    DUT dut = item.Root.DUT;
                    if (dut.DeviceSalesType.Contains("气象") || dut.OrderMode.Contains("气象"))
                    {
                        BumpValue = 0.95;
                        typevalue = "ConST811A-BP";
                    }

                    msg1.Content = ($"订单机型{dut.DeviceSalesType}，真空能力标准值:{BumpValue}，当前泵真空能力值:{currentValue}");
                    if (BumpValue != currentValue)
                    {
                        bool key = ScriptHelper.OpenInfoConfirmWindow(item, "当前泵真空能力值与标准初始化值不一致。 手动确认是否通过？，，是：手动通过  否：测试失败");
                        if (key)
                        { 
                            return result;
                        }
                        result.SetConclusion("泵真空能力与机型不符，需要到计量室进行重新配置", ErrMsg._201011);
                    }
                }

                RealTimeMsg msg2 = new RealTimeMsg("根据控制板类型,设置泵高压能力,BP=130kPa,DP=850kPa,LLP=125.5kPa,MP=7610kPa HP=10600kPa -->");
                RealTimeMsg msg_controlversion = new RealTimeMsg("当前控制板版本");
                string controllerVersion;
                if (!item.GetDevice("P21").GetVersion_Controller(out controllerVersion))
                {
                    result.AddTestErrMsgs(new ErrMsg(20003, "获取控制板版本失败"));
                    return result;
                }
                msg_controlversion.Content = $"{controllerVersion}";
                item.AddRealTimeMsgs(msg2);
                item.AddRealTimeMsgs(msg_controlversion);
                if (!item.GetDevice("P21").SetPositiveModelParameter(out value, controllerVersion))
                {
                    result.SetConclusion("设置泵正压能力失败", ErrMsg._201011);
                    msg2.Content = "失败";
                }
                else
                {
                    msg2.Content = value.ToString() + "kPa";
                }
            }


            RealTimeMsg msg3 = new RealTimeMsg("禁用可切换控0策略");
            item.AddRealTimeMsgs(msg3);
            if (!item.GetDevice("P21").SetControlFeatureConfig("SupportControlZeroStrategyChange", "0"))
            {
                result.SetConclusion("禁用可切换控0策略失败", ErrMsg._201011);
                msg3.Content = "失败";
            }
            else
            {
                msg3.Content = "成功";
            }
            //RealTimeMsg msg4 = new RealTimeMsg("设置是否支持压力切换");
            //item.AddRealTimeMsgs(msg4);
            //if (!item.GetDevice("P21").SetChangePressType())
            //{
            //    result.SetConclusion("设置是否支持压力切换失败", ErrMsg._201011);
            //    msg4.Content = "失败";
            //}
            //else
            //{
            //    msg4.Content = "成功";
            //}
            if (item.Root.DUT.IsSpecialty)
            {
                //单模块不进行量程限制
                if (item.GetDevice("P21").IsDoubleRange())
                {
                    RealTimeMsg msg5 = new RealTimeMsg("上限模块量程限制");
                    item.AddRealTimeMsgs(msg5);
                    //先读取量程模块限制，不符合要求后进行修改
                    ModelLimitSetting setting;
                    if (!item.GetDevice("P21").GetPressureModelLimitInfo(out setting))
                    {
                        //result.SetConclusion("获取上限模块量程限制失败", ErrMsg._201011);
                    }
                    msg5.Content = string.Format("({0}~{1})kPa", setting.LowerValue, setting.UpperValue);
                    ModelLimitSetting limitSetting;
                    if (!item.GetDevice("P21").CheckPressureLimitIsCorrect(setting, out limitSetting))
                    {

                        PressureRange highRange = new PressureRange();
                        if (!item.GetDevice("P21").GetHighPressureModelRange(out highRange))
                        {
                            result.AddTestErrMsgs(new ErrMsg(20001, "获取模块量程失败"));
                        }
                        PressureRange lowRange = new PressureRange();
                        if (!item.GetDevice("P21").GetLowPressureModelRange(out lowRange))
                        {
                            result.AddTestErrMsgs(new ErrMsg(20001, "获取模块量程失败"));
                        }
                        double low = highRange.UpperValue < lowRange.UpperValue ? highRange.UpperValue : lowRange.UpperValue;

                        Math.Round(low * 0.95, 0);
                        limitSetting.LowerValue = Math.Round(low * 0.95, 0);

                        if (!item.GetDevice("P21").SetAllPressureModelLimitInfo(limitSetting))
                        {
                            result.SetConclusion("设置上限模块量程限制失败", ErrMsg._201011);
                            msg5.Content += string.Format("({0}~{1})kPa 失败", limitSetting.LowerValue, limitSetting.UpperValue);
                        }
                        else
                        {
                            msg5.Content += string.Format("({0}~{1})kPa 成功", limitSetting.LowerValue, limitSetting.UpperValue);
                        }
                    }
                }
            }
            //bool? key = ScriptHelper.OpenInfoConfirmWindow(item, "系统参数初始化设置完成，是否重新启动设备！", 0, 30);

            //if (key == true)
            //{
            item.GetDevice("P21").SetReboot();
            item.GetDevice("P21").Close();
            item.GetDevice("P21").SetCommConfigEmpty();
            System.Threading.Thread.Sleep(2000);
            RealTimeMsg msg11 = new RealTimeMsg("设备正在重新启动");
            item.AddRealTimeMsgs(msg11);
            DateTime startTime = DateTime.Now;
            while (true)
            {
                if ((DateTime.Now - startTime).TotalSeconds >= 30)
                {
                    break;
                }
                System.Threading.Thread.Sleep(1000);
                msg11.ContentRunning();
            }
            startTime = DateTime.Now;
            while (!item.GetDevice("P21").Open())
            {
                if ((DateTime.Now - startTime).TotalSeconds >= 30)
                {
                    msg11.Content = "设备通讯重连超时，请检查通讯线连接";
                    result.AddTestErrMsgs(new ErrMsg(20001, "设备通讯重连超时，请检查通讯线连接"));
                    return result;
                }
                System.Threading.Thread.Sleep(2000);
                msg11.ContentRunning();
            }
            msg11.Name = "设备重新启动";
            msg11.Content = "成功,请确认相关配置已经生效。";
            //}

            return result;
        }
        finally
        {
            System.Threading.Thread.Sleep(500);
        }
    }
    /// <summary>
    /// 811A出厂前WIFI测试
    /// </summary>
    /// <param name="testItem"></param>
    /// <returns></returns>
    public dynamic WiFiFunctionTest(dynamic testItem)
    {
        try
        {
            Result<TextData> result = new Result<TextData>(true);
            result.Data = new TextData("测试结果");

            //获取参数
            if (testItem.Parameters == null)
            {
                result.AddTestErrMsgs(ErrMsg._10001);//添加错误信息
                return result;
            }
            TextParameter ssid = testItem.Parameters[0] as TextParameter;
            TextParameter encryptionMode = testItem.Parameters[1] as TextParameter;
            TextParameter password = testItem.Parameters[2] as TextParameter;

            testItem.ClearRealTimeMsgs();
            RealTimeMsg msg0 = new RealTimeMsg("验证当前连接是否为WiFi连接通信");
            testItem.AddRealTimeMsgs(msg0);
            CommType commType = testItem.GetDevice("P21").GetCommType();
            if (commType == CommType.WLAN)
            {
                msg0.Content = "当前WiFi连接，通信正常！";
                result.Data.Value = "WiFi测试通过";
                return result;
            }
            msg0.Content = "当前不是WiFi网连接，开始测试！";

            RealTimeMsg msg = new RealTimeMsg("获取WiFi功能是否开放");
            testItem.AddRealTimeMsgs(msg);
            bool wifiFunState = false;
            if (!testItem.GetDevice("P21").GetWLANFunctionState(out wifiFunState))
            {
                result.AddTestErrMsgs(new ErrMsg(20003, "获取wifi功能状态失败"));
                return result;
            }
            msg.Name = "WiFi功能状态";
            msg.Content = wifiFunState ? "Open" : "Close";
            if (!wifiFunState)
            {
                RealTimeMsg msgWifiFunc = new RealTimeMsg("当前WiFi功能未开启,WiFi测试将终止");
                testItem.AddRealTimeMsgs(msgWifiFunc);
                Thread.Sleep(1000);
                bool? key = ScriptHelper.OpenInfoConfirmWindow(testItem, "获取WiFi功能失败，请手动确认测试项。\r\n点击“确定”完成测试，测试项标记为通过。点击“取消”，测试失败。", 30, 0);
                if (key == true)
                {
                    result.Data.Value = "WiFi测试通过，操作员手动通过";
                    return result;
                }
                else
                {
                    result.AddTestErrMsgs(new ErrMsg(30003, "获取wifi功能失败，测试失败"));
                    result.Data.Value = "WiFi测试失败";
                    return result;
                }

                //bool? key = ScriptHelper.OpenInfoConfirmWindow(testItem, "该设备WiFi功能被关闭！请操作员确认订单是否有WiFi功能。\r\n点击“确定”完成测试，测试项标记为通过。点击“取消”将开放WiFi功能，继续WiFi功能测试。", 30, 0);
                //if (key == true)
                //{
                //    result.Data.Value = "WiFi测试操作员手动通过";
                //    RealTimeMsg msgwifi = new RealTimeMsg("WiFi测试手动通过！");
                //    result.SetConclusion("WiFi测试手动通过");

                //    return result;
                //}

                //RealTimeMsg msg8 = new RealTimeMsg("正在开放wifi功能");
                //testItem.AddRealTimeMsgs(msg8);
                //bool isOpen = testItem.GetDevice("P21").OpenWLANFunction();
                //if (!isOpen)
                //{
                //    result.AddTestErrMsgs(new ErrMsg(20003, "打开WiFi功能失败"));
                //    return result;
                //}
                //msg8.Content = isOpen ? "已开放" : "未开放";
            }

            System.Threading.Thread.Sleep(500);


            RealTimeMsg msg1 = new RealTimeMsg("获取WiFi开关状态");
            testItem.AddRealTimeMsgs(msg1);
            bool wifiState = false;
            if (!testItem.GetDevice("P21").GetWifiState(out wifiState))
            {
                result.AddTestErrMsgs(new ErrMsg(20001, "获取WiFi开关状态失败"));
                return result;
            }
            msg1.Name = "WiFi状态";
            msg1.Content = wifiState ? "Open" : "Close";
            if (!wifiState)
            {
                RealTimeMsg msg3 = new RealTimeMsg("正在打开WiFi");
                testItem.AddRealTimeMsgs(msg3);

                bool isOpen = testItem.GetDevice("P21").SetWifiOpen();
                msg3.Name = "打开WiFi";
                msg3.Name = isOpen ? "已打开" : "未打开";
                if (!isOpen)
                {
                    result.AddTestErrMsgs(new ErrMsg(20001, "打开WiFi失败"));
                    return result;
                }
            }
            System.Threading.Thread.Sleep(500);

            RealTimeMsg msg2 = new RealTimeMsg("获取WiFi地址(MAC)");
            testItem.AddRealTimeMsgs(msg2);

            string returnValue = string.Empty;
            if (!testItem.GetDevice("P21").GetWiFiAddress(out returnValue))
            {
                result.AddTestErrMsgs(new ErrMsg(20001, "获取WiFi地址(MAC)失败！"));
                return result;
            }

            msg2.Name = "WiFi地址(MAC)";
            msg2.Content = result.Data.Value = returnValue;

            if (result.Data.Value.Length <= 0)
            {
                result.AddTestErrMsgs(new ErrMsg(30003, "Wifi物理地址(MAC)不存在"));
                return result;
            }


            while (true)
            {
                RealTimeMsg msg10 = new RealTimeMsg("连接" + ssid.Value);
                testItem.AddRealTimeMsgs(msg10);
                testItem.GetDevice("P21").ConnectWifiToHotspot(ssid.Value, encryptionMode.Value, password.Value);
                System.Threading.Thread.Sleep(5000);
                msg10.Content = "完成";

                RealTimeMsg msg11 = new RealTimeMsg("获取WIFI连接状态");
                testItem.AddRealTimeMsgs(msg11);
                string state = "";
                for (int i = 0; i < 60; i++)
                {
                    System.Threading.Thread.Sleep(1000);
                    msg11.ContentRunning();
                    if (testItem.GetDevice("P21").GetConnectWifiState(out state) && state != "ConnectFailed ")
                    {
                        break;
                    }
                }
                if (testItem.GetDevice("P21").GetConnectWifiState(out state) && state != "ConnectFailed ")
                {
                    msg11.Name = "WIFI地址(IP)";
                    string ipaddress = "";
                    if (!testItem.GetDevice("P21").GetWifiIPAddress(out ipaddress))
                    {
                        result.AddTestErrMsgs(new ErrMsg(20001, "获取WIFI地址失败！"));
                        return result;
                    }
                    if (ipaddress != "" && ipaddress != "0.0.0.0")
                    {
                        msg11.Content = result.Data.Value = ipaddress;
                        break;
                    }
                    else
                        msg11.Content = "重新连接WiFi";

                }
                else
                {
                    result.AddTestErrMsgs(new ErrMsg(30001, "WIFI连接失败！"));
                    return result;
                }
            }
            
            return result;
        }
        finally
        {
            testItem.GetDevice("P21").SetWifiClose();
            Thread.Sleep(500);
            //testItem.GetDevice("P21").CloseWLANFunction();
        }
    }
    /// <summary>
    /// 出厂前蓝牙测试
    /// </summary>
    /// <param name="item"></param>
    /// <returns></returns>
    public dynamic BLEFunctionTest(dynamic item)
    {
        Result<TextData> result = new Result<TextData>(true);
        result.Data = new TextData("蓝牙状态");

        item.ClearRealTimeMsgs();

        RealTimeMsg msg12 = new RealTimeMsg("打开蓝牙");
        item.AddRealTimeMsgs(msg12);
        //if (!item.GetDevice("P21").OpenBlueTooth())
        //{
        //    result.AddTestErrMsgs(new ErrMsg(30003, "指令通讯异常，打开蓝牙失败"));
        //    return result;
        //}
        //msg12.Content = "√";

        //System.Threading.Tasks.Task.Delay(2000).Wait();

        RealTimeMsg msg1 = new RealTimeMsg("获取蓝牙状态");
        item.AddRealTimeMsgs(msg1);
        OpenCloseState state = OpenCloseState.UnKnown;
        if (!item.GetDevice("P21").GetBlueToothState(out state))
        {
            bool? key = ScriptHelper.OpenInfoConfirmWindow(item, "获取蓝牙状态失败，请操作员确认订单是否有蓝牙功能。\r\n点击“确定”完成测试，测试项标记为通过。点击“取消”，测试失败。", 30, 0);
            if (key == true)
            {
                msg1.Content = "获取蓝牙状态失败";
                result.Data.Value = "蓝牙测试通过，操作员手动通过";
                return result;
            }
            else
            {
                result.AddTestErrMsgs(new ErrMsg(30003, "指令通讯异常，获取蓝牙状态失败"));
                return result;
            }            
        }
        result.Data.Value = state.ToString();
        msg1.Name = "蓝牙状态";
        msg1.Content = result.Data.Value;

        RealTimeMsg msg121 = new RealTimeMsg("蓝牙名称");
        item.AddRealTimeMsgs(msg121);
        if (!item.GetDevice("P21").GetBlueToothName(out string BLEName))
        {
            result.AddTestErrMsgs(new ErrMsg(30003, "指令通讯异常，打开蓝牙失败"));
            return result;
        }
        msg12.Content = BLEName;


        RealTimeMsg msg123 = new RealTimeMsg("关闭蓝牙");
        item.AddRealTimeMsgs(msg123);
        if (!item.GetDevice("P21").CloseBlueTooth())
        {
            result.AddTestErrMsgs(new ErrMsg(30003, "指令通讯异常，打开蓝牙失败"));
            return result;
        }
        msg123.Content = "√";

        return result;
    }
