    public static class Util
    {
        /// <summary>
        /// 毫秒转时间
        /// </summary>
        /// <param name="l">毫秒</param>
        /// <returns></returns>LeakTestComposition_Low_DP
        public static string FormatLongToTimeStr(long l)
        {
            TimeSpan st = TimeSpan.FromTicks(l);
            return string.Format("{0}:{1}:{2}", st.Hours, st.Minutes, st.Seconds);
        }
        /// <summary>
        /// 毫秒转时间
        /// </summary>
        /// <param name="ts"></param>
        /// <returns></returns>
        public static string FormatLongToTimeStr(TimeSpan ts)
        {
            return string.Format("{0}:{1}:{2}", ts.Hours, ts.Minutes, ts.Seconds);
        }
        /// <summary>
        /// 新泄露测试公式
        /// </summary>
        /// <param name="deviceModel">P21设备型号</param>
        /// <param name="position">泄露位置</param>
        /// <param name="pressureChange">压力变化量(单位默认kPa)</param>
        /// <param name="time">泄露时间(单位默认秒)</param>
        /// <param name="atm">当前环境大气压(默认从设备大气压传感器读)</param>
        /// <returns></returns>
        public static double LeakTestValueFormula(LeakDeviceModel deviceModel, LeakPosition position, double pressureChange, double time, double atm)
        {
            //Q=Ve*△P/P0*60/T
            //Q为体积流量
            //当前计算得出Q单位是ml/min
            Volume vol = new Volume(deviceModel);
            if (atm == 0 || time == 0)
            {
                return double.NaN;
            }
            switch (position)
            {
                case LeakPosition.PositiveExport:
                    return (vol.PositiveExportVolume * pressureChange * 60) / (atm * time);
                case LeakPosition.NegativeExport:
                    return (vol.NegativeExportVolume * pressureChange * 60) / (atm * time);
                case LeakPosition.PositiveSource:
                    return (vol.PositiveSourceVolume * pressureChange * 60) / (atm * time);
                case LeakPosition.NegativeSource:
                    return (vol.NegativeSourceVolume * pressureChange * 60) / (atm * time);
                default:
                    return double.NaN;
            }
        }

    }
    /// <summary>
    /// 泄露位置
    /// </summary>
    public enum LeakPosition
    {
        /// <summary>
        /// 正压输出端
        /// </summary>
        PositiveExport = 0,
        /// <summary>
        /// 负压输出端
        /// </summary>
        NegativeExport = 1,
        /// <summary>
        /// 正压气源
        /// </summary>
        PositiveSource = 2,
        /// <summary>
        /// 负压气源
        /// </summary>
        NegativeSource = 3,
    }
    /// <summary>
    /// 泄露设备型号
    /// </summary>
    public enum LeakDeviceModel
    {
        /// <summary>
        /// 表压、差压和微差压设备测试泄露的容积一致
        /// </summary>
        MP_DP_LLP = 0,
        /// <summary>
        /// 高精度、气象版的设备测试泄露的容积一致
        /// </summary>
        HMP = 1
    }
    /// <summary>
    /// 不同型号P21设备容积
    /// </summary>
    public class Volume
    {
        /// <summary>
        /// 构造函数
        /// </summary>
        /// <param name="model">设备型号</param>
        public Volume(LeakDeviceModel model)
        {
            switch (model)
            {
                case LeakDeviceModel.MP_DP_LLP:
                    _PositiveExportVolume = 13.5;
                    _NegativeExportVolume = 15.5;
                    _PositiveSourceVolume = 11.82;
                    _NegativeSourceVolume = 11.82;
                    break;
                case LeakDeviceModel.HMP:
                    _PositiveExportVolume = 13.5;
                    _NegativeExportVolume = 13.5;
                    _PositiveSourceVolume = 11.82;
                    _NegativeSourceVolume = 11.82;
                    break;
            }
        }
